async function createOrgEvent(client: any, body: any) {
  const { title, event_date, event_end, event_type, description, visible_to_trades } = body
  if (!title || !event_date || !event_type) throw new Error('title, event_date, and event_type required')
  if (!['public_holiday', 'company_day'].includes(event_type)) throw new Error('event_type must be public_holiday or company_day')

  const { data, error } = await client.from('org_events').insert({
    org_id: DEFAULT_ORG_ID,
    title,
    event_date,
    event_end: event_end || null,
    event_type,
    description: description || null,
    visible_to_trades: visible_to_trades !== false,
  }).select().single()

  if (error) throw error
  return data
}

async function deleteOrgEvent(client: any, body: any) {
  const id = body.id || body.event_id
  if (!id) throw new Error('id required')

  const { error } = await client.from('org_events').delete().eq('id', id).eq('org_id', DEFAULT_ORG_ID)
  if (error) throw error
  return { ok: true }
}

async function createJobAction(client: any, body: any) {
  const { title, description, job_number, job_id, due_date, due_time, priority, source, category, sub_category } = body
  if (!title) throw new Error('title required')

  // If job_number provided but no job_id, look up the job
  let resolvedJobId = job_id || null
  let resolvedJobNumber = job_number || null
  let clientName: string | null = null

  if (job_number && !job_id) {
    const { data: job } = await client.from('jobs')
      .select('id, job_number, client_name, type')
      .eq('org_id', DEFAULT_ORG_ID)
      .eq('job_number', job_number)
      .maybeSingle()
    if (job) {
      resolvedJobId = job.id
      resolvedJobNumber = job.job_number
      clientName = job.client_name
    }
  } else if (job_id) {
    const { data: job } = await client.from('jobs')
      .select('job_number, client_name, type')
      .eq('id', job_id)
      .maybeSingle()
    if (job) {
      resolvedJobNumber = job.job_number
      clientName = job.client_name
    }
  }

  // Infer category from job type + title if not provided
  let cat = category || 'general_ops'
  let subCat = sub_category || 'tasks'
  if (!category && resolvedJobNumber) {
    if (resolvedJobNumber.startsWith('SWF-')) cat = 'fencing'
    else if (resolvedJobNumber.startsWith('SWP-')) cat = 'patio'
    else if (resolvedJobNumber.startsWith('SWMS-')) cat = 'makesafes'
  }
  if (!sub_category && title) {
    const t = title.toLowerCase()
    if (t.includes('invoice') || t.includes('payment') || t.includes('chase') || t.includes('deposit')) subCat = 'invoices'
    else if (t.includes('material') || t.includes('order') || t.includes('supplier') || t.includes('ampelite') || t.includes('steel')) subCat = 'materials'
    else if (t.includes('schedule') || t.includes('reschedule') || t.includes('assign')) subCat = 'scheduling'
    else if (t.includes('doc') || t.includes('work order') || t.includes('wo ') || t.includes('council')) subCat = 'docs'
  }

  const row = {
    org_id: DEFAULT_ORG_ID,
    job_id: resolvedJobId,
    job_number: resolvedJobNumber,
    client_name: clientName || body.client_name || null,
    title,
    description: description || null,
    due_date: due_date || null,
    due_time: due_time || null,
    priority: priority || 'normal',
    source: source || 'manual',
    category: cat,
    sub_category: subCat,
  }

  const { data, error } = await client.from('job_actions').insert(row).select().single()
  if (error) throw error
  return data
}

async function updateJobAction(client: any, body: any) {
  const actionId = body.action_id || body.id
  if (!actionId) throw new Error('action_id required')

  const updates: any = { updated_at: new Date().toISOString() }
  if (body.status === 'done') {
    updates.status = 'done'
    updates.completed_at = new Date().toISOString()
  } else if (body.status === 'dismissed') {
    updates.status = 'dismissed'
    updates.dismissed_at = new Date().toISOString()
  } else if (body.status) {
    updates.status = body.status
  }
  if (body.due_date !== undefined) updates.due_date = body.due_date
  if (body.due_time !== undefined) updates.due_time = body.due_time
  if (body.priority) updates.priority = body.priority
  if (body.title) updates.title = body.title

  const { data, error } = await client.from('job_actions')
    .update(updates)
    .eq('id', actionId)
    .select()
    .single()
  if (error) throw error
  return data
}

async function generateWorkOrderDoc(client: any, body: any) {
  const jId = body.job_id || body.jobId
  if (!jId) throw new ApiError('job_id required', 400)

  const { data: job, error: jobErr } = await client.from('jobs')
    .select('id, job_number, type, client_name, client_phone, client_email, site_address, site_suburb, scope_json, pricing_json, created_at')
    .eq('id', jId).single()
  if (jobErr || !job) throw new ApiError('Job not found', 404)
  if (job.type !== 'fencing') throw new ApiError('Work order doc only supported for fencing jobs', 400)

  const sj = job.scope_json?.job
  if (!sj?.runs?.length) throw new ApiError('No fencing scope data on this job', 400)

  // Get media for site photos
  const { data: media } = await client.from('job_media')
    .select('label, storage_url, thumbnail_url, phase')
    .eq('job_id', jId)
  const sitePhotos = (media || []).filter((m: any) => m.phase !== 'receipt')

  // ── Constants (from fence designer) ──
  const POST_LOOKUP: Record<number, {ret:number,post:number}[]> = {
    1200:[{ret:0,post:2400},{ret:150,post:2400},{ret:300,post:2400},{ret:450,post:2400},{ret:600,post:2400}],
    1500:[{ret:0,post:2400},{ret:150,post:2400},{ret:300,post:2400},{ret:450,post:2700},{ret:600,post:2700}],
    1800:[{ret:0,post:2400},{ret:150,post:2700},{ret:300,post:2700},{ret:450,post:3000},{ret:600,post:3000}],
    2100:[{ret:0,post:2700},{ret:150,post:3000},{ret:300,post:3000},{ret:450,post:3000},{ret:600,post:3000}]
  }
  const SUPPLIER_PW: Record<string, number> = { RNR:2380, Metroll:2365, Lysaght:2360, Stratco:2350 }
  const CP = {
    panelKit1800_2400:185, panelKit1800_2700:210, panelKit1800_3000:235,
    panelKit1500_2400:165, panelKit1200_2400:145, panelKit2100_2700:230, panelKit2100_3000:255,
    plinth:28, patioTube:45, gateKitPed:320, gateKitDbl:580, gatePost:85,
    concrete:9.50, tekBox:18, labourPerM:35, delivery:250
  }
  const ACCESS_RATE: Record<string,number> = { easy:0, moderate:0.10, difficult:0.20 }

  function lookupPost(sh: number, ret: number) {
    const t = POST_LOOKUP[sh] || POST_LOOKUP[1800]
    const e = t.find(x => x.ret === ret)
    if (e) return e.post
    const req = sh + ret + 600
    return req <= 2400 ? 2400 : req <= 2700 ? 2700 : 3000
  }

  const esc = (s: string) => (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')
  const fmt = (n: number) => n.toLocaleString('en-AU', { minimumFractionDigits: 2, maximumFractionDigits: 2 })

  // ── Collect data ──
  const removal = sj.removal || {}
  const access = removal.access || 'easy'
  const accessRate = ACCESS_RATE[access] || 0
  const panelWidthMm = SUPPLIER_PW[sj.supplier] || 2365
  let totalMetres = 0, totalPanels = 0, totalPosts = 0, totalPlinths = 0, totalPatioTubes = 0
  const postGroups: Record<string, {sheetH:number, postH:number, count:number}> = {}
  const runDetails: any[] = []

  for (const run of sj.runs) {
    const panels = run.panels || []
    const panelCount = panels.length
    totalMetres += run.length || 0
    totalPanels += panelCount
    totalPosts += panelCount + 1
    let runPlinths = 0, panelsWithPatio = 0
    const panelDetails: any[] = []
    for (let idx = 0; idx < panels.length; idx++) {
      const p = panels[idx]
      const slopePl = p.slopePlinths || 0
      const manualPl = p.retaining / 150
      const totalPl = Math.min(4, slopePl + manualPl)
      const totalRet = totalPl * 150
      runPlinths += totalPl
      const postH = lookupPost(p.height, totalRet)
      const patio = totalPl >= 3 && totalPl <= 4
      if (patio) panelsWithPatio++
      const key = `${p.height}_${postH}`
      if (!postGroups[key]) postGroups[key] = { sheetH: p.height, postH, count: 0 }
      postGroups[key].count++
      panelDetails.push({ num: idx+1, height: p.height, retaining: totalRet, totalH: p.height+totalRet, postH, patio, stepMm: p.stepMm||0 })
    }
    const patioTubes = panelsWithPatio > 0 ? panelsWithPatio + 1 : 0
    totalPlinths += runPlinths
    totalPatioTubes += patioTubes
    const hasRetaining = panels.some((p: any) => (p.slopePlinths||0) + (p.retaining/150) > 0)
    runDetails.push({ name: run.name, length: run.length||0, panelCount, plinths: runPlinths, patioTubes, hasRetaining, panels: panelDetails })
  }
  if (sj.runs.length > 1) totalPosts -= (sj.runs.length - 1)

  let gatePosts = 0
  const gateItems: string[] = []
  for (const g of (sj.gates || [])) {
    const gp = g.type === 'double' ? 4 : 2
    gatePosts += gp
    gateItems.push(g.type === 'double' ? `Double swing gate ${g.width||''}mm` : `Pedestrian gate ${g.width||900}mm`)
  }
  const allPosts = totalPosts + gatePosts
  const concreteBags = Math.ceil(allPosts * 2 * 1.1 / 2) * 2
  const tekBoxes = totalPanels > 0 ? Math.max(1, Math.ceil(totalPanels / 4)) : 0

  // Post breakdown
  const heightCounts: Record<number,number> = {}
  for (const r of runDetails) for (const p of r.panels) heightCounts[p.postH] = (heightCounts[p.postH]||0) + 1
  const postBreakdown = Object.keys(heightCounts).sort().map(h => `${heightCounts[Number(h)]} @ ${h}mm`).join(', ')

  // Internal costs
  let internalCost = 0
  for (const g of Object.values(postGroups)) {
    let uc = CP.panelKit1800_2400
    if (g.sheetH===1200) uc=CP.panelKit1200_2400
    else if (g.sheetH===1500) uc=CP.panelKit1500_2400
    else if (g.sheetH===1800) { uc = g.postH<=2400?CP.panelKit1800_2400:g.postH<=2700?CP.panelKit1800_2700:CP.panelKit1800_3000 }
    else if (g.sheetH===2100) { uc = g.postH<=2700?CP.panelKit2100_2700:CP.panelKit2100_3000 }
    internalCost += g.count * uc
  }
  internalCost += totalPlinths*CP.plinth + totalPatioTubes*CP.patioTube + concreteBags*CP.concrete + tekBoxes*CP.tekBox
  for (const g of (sj.gates||[])) internalCost += g.type==='double'?(CP.gateKitDbl+4*CP.gatePost):(CP.gateKitPed+2*CP.gatePost)
  const labourBase = totalMetres * CP.labourPerM
  const internalLabour = labourBase * (1 + accessRate)
  const totalCostBase = internalCost + internalLabour + CP.delivery
  const pricing = sj._pricing_json || job.pricing_json || {}
  const quoteTotalExGST = pricing.totalExGST || (pricing.totalIncGST ? pricing.totalIncGST / 1.1 : 0)
  const margin = quoteTotalExGST - totalCostBase

  const dateStr = sj.date || job.created_at
  const fmtDate = dateStr ? new Date(dateStr).toLocaleDateString('en-AU', { day: 'numeric', month: 'short', year: 'numeric' }) : ''

  // ── Build HTML ──
  const LOGO = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 490 79.55" style="height:28px;width:auto;"><defs><style>.c1{fill:#fff}.c3{fill:rgba(255,255,255,0.6)}</style></defs><path class="c1" d="M85.11,46.94c.24,1.73,.73,3.02,1.44,3.88,1.31,1.56,3.56,2.34,6.74,2.34,1.91,0,3.45-.21,4.64-.62,2.26-.79,3.38-2.25,3.38-4.39,0-1.25-.55-2.22-1.66-2.9-1.11-.67-2.86-1.26-5.26-1.77l-4.1-.9c-4.03-.89-6.8-1.86-8.3-2.9-2.55-1.75-3.83-4.48-3.83-8.19,0-3.39,1.25-6.21,3.74-8.45s6.16-3.36,11-3.36c4.04,0,7.48,1.06,10.33,3.17,2.85,2.11,4.35,5.18,4.48,9.21h-7.6c-.14-2.28-1.16-3.89-3.05-4.85-1.26-.63-2.83-.95-4.71-.95-2.09,0-3.76,.41-5,1.23-1.25,.82-1.87,1.97-1.87,3.44,0,1.35,.61,2.36,1.84,3.03,.79,.45,2.47,.97,5.03,1.57l6.64,1.57c2.91,.69,5.09,1.6,6.55,2.75,2.26,1.78,3.38,4.36,3.38,7.73s-1.34,6.33-4.01,8.62c-2.67,2.29-6.45,3.43-11.33,3.43s-8.9-1.13-11.76-3.38c-2.86-2.25-4.28-5.35-4.28-9.28h7.55Z"/><path class="c1" d="M130.99,31.2c1.95,.87,3.57,2.26,4.84,4.14,1.15,1.66,1.89,3.59,2.23,5.79,.2,1.29,.28,3.14,.24,5.56h-20.39c.11,2.81,1.09,4.78,2.93,5.91,1.12,.7,2.46,1.05,4.04,1.05,1.67,0,3.02-.43,4.06-1.28,.57-.46,1.07-1.1,1.51-1.93h7.47c-.2,1.66-1.1,3.35-2.71,5.06-2.51,2.72-6.02,4.08-10.53,4.08-3.73,0-7.01-1.15-9.86-3.44-2.85-2.3-4.27-6.03-4.27-11.21,0-4.85,1.28-8.57,3.86-11.16,2.57-2.59,5.91-3.88,10.01-3.88,2.44,0,4.63,.44,6.58,1.31Zm-10.95,6.32c-1.03,1.07-1.68,2.51-1.95,4.33h12.61c-.13-1.94-.78-3.42-1.95-4.42s-2.61-1.51-4.34-1.51c-1.88,0-3.34,.53-4.37,1.6Z"/><polygon class="c1" points="53.4 30.35 53.4 22.29 31.41 8.51 8.87 22.26 8.87 34.53 45.59 42.34 45.59 52.83 38.55 52.83 31.39 45.47 24.15 52.83 16.68 52.83 16.68 39 8.87 37.4 8.87 60.64 27.43 60.64 31.36 56.65 35.25 60.64 53.4 60.64 53.4 36.01 16.68 28.21 16.68 26.65 31.35 17.69 45.59 26.61 45.59 31.95 53.4 33.41 53.4 30.35"/><rect fill="#F15A29" x="8.96" y="62.99" width="44.53" height="7.77"/><text class="c3" x="406" y="52" font-family="Helvetica Neue,Helvetica,Arial,sans-serif" font-size="21" font-weight="400" letter-spacing="0.5">Group</text></svg>'

  // CSS
  const css = `*{box-sizing:border-box}body{font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;color:#293C46;margin:0;padding:0;font-size:13px;line-height:1.5}.page{max-width:820px;margin:0 auto;padding:0 40px 40px}.header-band{background:#293C46;padding:0;margin:0}.header-accent{height:4px;background:#F15A29}.header-inner{max-width:820px;margin:0 auto;padding:16px 40px;display:flex;align-items:center;justify-content:space-between}.header-meta{text-align:right;color:#fff}.header-meta .ref{font-size:13px;font-weight:700}.header-meta .date{font-size:11px;opacity:0.7;margin-top:2px}.doc-title{padding:16px 0 12px;border-bottom:3px solid #F15A29;margin-bottom:24px}.doc-title h1{font-size:22px;margin:0;color:#293C46;text-transform:uppercase;letter-spacing:1px}.section{margin-bottom:22px}.section h2{font-size:13px;text-transform:uppercase;letter-spacing:0.8px;font-weight:700;color:#293C46;margin:0 0 8px 0;padding:6px 0 6px 10px;border-left:3px solid #F15A29;background:#f0f4f7}.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px 24px;margin-bottom:14px}.info-grid .label{font-weight:700;font-size:10px;text-transform:uppercase;color:#4C6A7C;letter-spacing:0.5px}.info-grid .value{font-size:13px}table{width:100%;border-collapse:collapse;margin-bottom:14px;font-size:12px}th{background:#293C46;color:#fff;padding:8px 10px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:0.5px;font-weight:700}td{padding:7px 10px;border-bottom:1px solid #e5e7eb}tr:nth-child(even) td{background:#f8fafb}.text-right{text-align:right}.total-row td{font-weight:700;border-top:2px solid #293C46;background:#fff !important}.checklist{padding-left:20px}.checklist li{margin-bottom:5px;font-size:12px}.patio-flag{color:#F15A29;font-weight:700}.confidential{background:#fef2f2;border:2px solid #dc2626;padding:3px 10px;display:inline-block;font-size:10px;font-weight:700;color:#dc2626;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px}.footer{border-top:1px solid #c8c8c8;padding-top:12px;margin-top:30px;text-align:center;font-size:10px;color:#4C6A7C;line-height:1.6}@media print{body{padding:0}.page{padding:0 20px 20px}.header-inner{padding:12px 20px}.no-print{display:none !important}.header-band,.header-accent,th,.section h2{-webkit-print-color-adjust:exact;print-color-adjust:exact}}.print-btn{position:fixed;top:12px;right:12px;padding:10px 20px;background:#F15A29;color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:700;font-size:14px;box-shadow:0 2px 8px rgba(0,0,0,0.15);z-index:100}`

  // Runs HTML
  let runsHtml = ''
  for (const r of runDetails) {
    runsHtml += `<div class="section"><h2>${esc(r.name)} (${r.panelCount} panels, ${r.length}m)`
    if (r.patioTubes > 0) runsHtml += ` <span class="patio-flag">[${r.patioTubes} patio tubes]</span>`
    runsHtml += '</h2>'
    if (r.hasRetaining) {
      runsHtml += '<table><thead><tr><th>Panel</th><th>Fence</th><th>Ret.</th><th>Total</th><th>Post</th><th>Notes</th></tr></thead><tbody>'
      for (const p of r.panels) {
        let notes = ''
        if (p.patio) notes += '<span class="patio-flag">PATIO TUBE</span> '
        if (p.stepMm !== 0) notes += (p.stepMm < 0 ? '\u2193' : '\u2191') + Math.abs(p.stepMm) + 'mm'
        runsHtml += `<tr><td>P${p.num}</td><td>${p.height}mm</td><td>${p.retaining}mm</td><td>${p.totalH}mm</td><td>${p.postH}mm</td><td>${notes}</td></tr>`
      }
      runsHtml += '</tbody></table>'
    } else {
      const pH = r.panels[0]?.postH || 2400, sH = r.panels[0]?.height || 1800
      runsHtml += `<p style="padding-left:12px;">P1\u2013P${r.panelCount}: ${sH}mm fence, 0mm retaining | Post height: ${pH}mm</p>`
    }
    runsHtml += '</div>'
  }

  // Gates
  const gatesHtml = gateItems.length > 0 ? gateItems.map(g => `<p style="padding-left:12px;">${esc(g)} \u2014 90\u00D790mm SHS gate posts</p>`).join('') : '<p style="padding-left:12px;">None</p>'

  // Scope checklist
  const scopeList = ['Install COLORBOND\u00AE fencing per specification', 'Set all posts in concrete (2 bags/post)']
  if (totalPlinths > 0) scopeList.push(`Install ${totalPlinths} retaining plinths`)
  if (totalPatioTubes > 0) scopeList.push(`Install ${totalPatioTubes} patio tubes at retained sections`)
  if (removal.removalRequired && removal.existingFenceType) scopeList.push(`Remove existing ${removal.existingFenceType} fencing (${removal.existingFenceLength||0}m)`)
  for (const g of gateItems) scopeList.push(g)
  scopeList.push('Site clean-up and rubbish removal')

  // Site plan
  const sitePlan = sj._latlng?.lat ? `<img src="https://maps.googleapis.com/maps/api/staticmap?center=${sj._latlng.lat},${sj._latlng.lng}&zoom=19&size=800x400&maptype=satellite&key=AIzaSyCVNUaGS6k6MBG6_-MbCyiIGUajnzHU7DM" style="width:100%;border-radius:4px">` : ''

  // Photos
  let photosHtml = ''
  if (sitePhotos.length > 0) {
    photosHtml = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px">'
    for (const m of sitePhotos) {
      const src = m.thumbnail_url || m.storage_url
      photosHtml += `<div style="text-align:center"><img src="${esc(src)}" style="width:100%;max-height:200px;object-fit:cover;border-radius:4px"><div style="font-size:10px;color:#666;margin-top:2px">${esc(m.label||'')}</div></div>`
    }
    photosHtml += '</div>'
  }

  // Cost breakdown
  const costHtml = `<table><thead><tr><th>Item</th><th class="text-right">Cost</th></tr></thead><tbody>
<tr><td>Materials (panels, posts, plinths, concrete, fixings)</td><td class="text-right">$${fmt(internalCost)}</td></tr>
<tr><td>Labour base (${totalMetres.toFixed(1)}m @ $${CP.labourPerM}/m${accessRate>0?' + '+(accessRate*100)+'% access':''})</td><td class="text-right">$${fmt(internalLabour)}</td></tr>
<tr><td>Delivery</td><td class="text-right">$${fmt(CP.delivery)}</td></tr>
<tr class="total-row"><td>Total cost</td><td class="text-right">$${fmt(totalCostBase)}</td></tr>
<tr><td>Quote total (excl. GST)</td><td class="text-right">$${fmt(quoteTotalExGST)}</td></tr>
<tr style="font-weight:700"><td>Margin</td><td class="text-right">$${fmt(margin)}</td></tr>
</tbody></table>`

  // Assemble
  const jn = job.job_number || sj.ref || ''
  let html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Work Order \u2014 ${esc(jn)}</title><style>${css}</style></head><body>`
  html += '<button class="print-btn no-print" onclick="window.print()">Print / PDF</button>'
  html += `<div class="header-accent"></div><div class="header-band"><div class="header-inner"><div class="header-logo">${LOGO}</div><div class="header-meta"><div class="ref">${esc(jn)}</div><div class="date">${fmtDate}</div></div></div></div>`
  html += '<div class="page">'
  html += `<div class="doc-title"><h1>Work Order \u2014 ${esc(jn)}</h1></div>`
  html += `<div class="section"><div class="info-grid"><div><span class="label">Client</span><br><span class="value">${esc(job.client_name||sj.client)}</span></div><div><span class="label">Job Ref</span><br><span class="value">${esc(jn)}</span></div><div><span class="label">Address</span><br><span class="value">${esc(job.site_address||sj.address)}</span></div><div><span class="label">Date</span><br><span class="value">${fmtDate}</span></div><div><span class="label">Phone</span><br><span class="value">${esc(job.client_phone||sj.phone)}</span></div><div><span class="label">Email</span><br><span class="value">${esc(job.client_email||sj.email)}</span></div><div><span class="label">Scoper</span><br><span class="value">${esc(sj.scoper||'')}</span></div><div><span class="label">Access</span><br><span class="value">${esc(access)}</span></div></div></div>`
  if (sitePlan) html += `<div class="section"><h2>Site Plan</h2>${sitePlan}</div>`
  html += `<div class="section"><h2>Fence Specification</h2><div class="info-grid"><div><span class="label">Supplier</span><br><span class="value">${esc(sj.supplier||'')}</span></div><div><span class="label">Profile</span><br><span class="value">${esc(sj.profile||'')}</span></div><div><span class="label">Colour</span><br><span class="value">${esc(sj.colour||'')}</span></div><div><span class="label">Panel Width</span><br><span class="value">${panelWidthMm}mm</span></div></div></div>`
  html += runsHtml
  html += `<div class="section"><h2>Gates</h2>${gatesHtml}</div>`
  html += `<div class="section"><h2>Summary</h2><div class="info-grid"><div><span class="label">Total Length</span><br><span class="value">${totalMetres.toFixed(1)}m</span></div><div><span class="label">Panels</span><br><span class="value">${totalPanels}</span></div><div><span class="label">Posts</span><br><span class="value">${totalPosts} (${postBreakdown})</span></div><div><span class="label">Gate Posts</span><br><span class="value">${gatePosts} \u00D7 90\u00D790mm SHS</span></div><div><span class="label">Plinths</span><br><span class="value">${totalPlinths}</span></div><div><span class="label">Patio Tubes</span><br><span class="value">${totalPatioTubes}</span></div><div><span class="label">Concrete</span><br><span class="value">${concreteBags} bags</span></div><div><span class="label">Tek Screws</span><br><span class="value">${tekBoxes} boxes</span></div></div></div>`
  html += `<div class="section"><h2>Scope of Work</h2><ul class="checklist">${scopeList.map(s => `<li>${s}</li>`).join('')}</ul></div>`
  html += `<div class="section"><h2>Safety &amp; Compliance</h2><ul class="checklist"><li>Dial Before You Dig check completed: <strong>___</strong></li><li>PPE: steel-cap boots, gloves, safety glasses, ear protection</li><li>First aid kit on site</li>${removal.existingFenceType==='asbestos'?'<li style="color:#dc2626;font-weight:700">ASBESTOS: Licensed removal required. Do NOT break sheets.</li>':''}<li>No overhead power lines within 3m of work area confirmed: <strong>___</strong></li></ul></div>`
  html += `<div class="section"><h2>Completion Requirements</h2><ul class="checklist"><li>QC photos of every post alignment and panel fit</li><li>Client walkthrough and sign-off</li><li>Tradify job completion sign-off</li><li>All rubbish removed from site</li></ul></div>`
  if (sj.siteNotes) html += `<div class="section"><h2>Site Notes</h2><p style="padding-left:12px;">${esc(sj.siteNotes).replace(/\n/g,'<br>')}</p></div>`
  if (photosHtml) html += `<div class="section"><h2>Site Photos</h2>${photosHtml}</div>`
  html += `<div class="section" style="margin-top:30px"><span class="confidential">Confidential \u2014 Internal Use Only</span><h2 style="border-left:none;background:none;padding-left:0">Cost Breakdown</h2>${costHtml}</div>`
  html += '<div class="footer">SecureWorks WA Pty Ltd | ABN 64 689 223 416<br>fencing@secureworkswa.com.au | 0489 267 772<br>Fully Licensed | Quality Guaranteed</div>'
  html += '</div></body></html>'

  // ── Upload to storage ──
  const bucket = 'job-documents'
  try { await client.storage.createBucket(bucket, { public: true }) } catch { /* exists */ }

  const fileName = `WO-${jn}.html`
  const path = `${jId}/${Date.now()}-${fileName}`
  const encoded = new TextEncoder().encode(html)

  const { error: uploadErr } = await client.storage.from(bucket).upload(path, encoded, { contentType: 'text/html; charset=utf-8', upsert: true })
  if (uploadErr) throw new Error('Storage upload failed: ' + uploadErr.message)

  const { data: urlData } = client.storage.from(bucket).getPublicUrl(path)
  const publicUrl = urlData.publicUrl

  // ── Create job_documents record (or update existing) ──
  // Check if one already exists for this job
  const { data: existing } = await client.from('job_documents')
    .select('id').eq('job_id', jId).eq('type', 'work_order').eq('file_name', fileName).limit(1)

  let docId: string
  if (existing && existing.length > 0) {
    await client.from('job_documents').update({ storage_url: publicUrl, version: 2 }).eq('id', existing[0].id)
    docId = existing[0].id
  } else {
    const { data: newDoc, error: docErr } = await client.from('job_documents')
      .insert({ job_id: jId, type: 'work_order', file_name: fileName, storage_url: publicUrl, visible_to_trades: true, version: 1, metadata: {} })
      .select('id').single()
    if (docErr) throw new Error('Document record failed: ' + docErr.message)
    docId = newDoc.id
  }

  return { document_id: docId, url: publicUrl, file_name: fileName }
}

async function deleteMedia(client: any, body: any) {
  const mediaId = body.mediaId || body.media_id
  if (!mediaId) throw new Error('mediaId required')

  const { data: media, error: fetchErr } = await client
    .from('job_media')
    .select('id, job_id, storage_url, label, phase')
    .eq('id', mediaId)
    .single()

  if (fetchErr) throw fetchErr
  if (!media) throw new Error('Media not found')

  // Delete from storage
  if (media.storage_url) {
    try {
      const bucket = 'job-photos'
      const urlParts = media.storage_url.split(`/storage/v1/object/public/${bucket}/`)
      if (urlParts.length > 1) {
        await client.storage.from(bucket).remove([urlParts[1]])
      }
    } catch (e) {
      console.log('[ops-api] Storage delete failed (non-blocking):', (e as Error).message)
    }
  }

  const { error: delErr } = await client.from('job_media').delete().eq('id', mediaId)
  if (delErr) throw delErr

  await client.from('job_events').insert({
    job_id: media.job_id,
    event_type: 'media_deleted',
    detail_json: { media_id: mediaId, label: media.label, phase: media.phase },
  })

  logBusinessEvent(client, {
    event_type: 'media.deleted',
    entity_type: 'job_media',
    entity_id: mediaId,
    job_id: media.job_id,
    payload: { label: media.label, phase: media.phase },
    metadata: { operator: body.operator_email || null },
  })

  return { success: true }
}

async function jumpCouncilStep(client: any, body: any) {
  const { submission_id, target_step_index } = body
  if (!submission_id || target_step_index == null) throw new Error('submission_id and target_step_index required')

  const { data: sub } = await client.from('council_submissions')
    .select('id, job_id, steps, current_step_index')
    .eq('id', submission_id)
    .single()
  if (!sub) throw new Error('Submission not found')

  const steps = sub.steps || []
  const target = Number(target_step_index)
  if (target < 0 || target >= steps.length) throw new Error('target_step_index out of range')

  const now = new Date().toISOString()

  // Steps before target -> complete (skipped gaps only for Development Approval)
  for (let i = 0; i < target; i++) {
    if (steps[i].status === 'complete' || steps[i].status === 'skipped') {
      // Already complete/skipped -> leave as is
    } else if (steps[i].name === 'Development Approval' && steps[i].status === 'pending') {
      // Development Approval skipped only if never touched (still pending)
      steps[i].status = 'skipped'
      steps[i].started_at = null
      steps[i].completed_at = null
    } else {
      steps[i].status = 'complete'
      if (!steps[i].completed_at) steps[i].completed_at = now
      if (!steps[i].started_at) steps[i].started_at = now
    }
  }

  // Target step -> in_progress
  steps[target].status = 'in_progress'
  if (!steps[target].started_at) steps[target].started_at = now
  steps[target].completed_at = null

  // Steps after target -> pending (reset)
  for (let i = target + 1; i < steps.length; i++) {
    steps[i].status = 'pending'
    steps[i].started_at = null
    steps[i].completed_at = null
  }

  const overallStatus = target === 0 && steps.length > 1 ? 'in_progress' : steps.every((s: any) => s.status === 'complete') ? 'complete' : 'in_progress'

  await client.from('council_submissions').update({
    steps,
    current_step_index: target,
    overall_status: overallStatus,
    updated_at: now,
  }).eq('id', submission_id)

  const { data: job } = await client.from('jobs').select('job_number').eq('id', sub.job_id).maybeSingle()

  logBusinessEvent(client, {
    event_type: 'council.step_jumped',
    entity_type: 'council_submission',
    entity_id: submission_id,
    job_id: job?.job_number || sub.job_id,
    payload: { target_step: target, step_name: steps[target].name, overall_status: overallStatus },
  })

  return { success: true, overall_status: overallStatus, current_step_index: target, steps }
}

// ── Geocoding helper (Nominatim, free, no API key) ──
async function geocodeAddress(address: string, suburb?: string): Promise<{ lat: number, lng: number } | null> {
  try {
    const query = (address || '') + (suburb ? ', ' + suburb : '') + ', Western Australia'
    const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=1&countrycodes=au`
    const resp = await fetch(url, {
      headers: { 'User-Agent': 'SecureWorks-OpsAPI/1.0 (admin@secureworkswa.com.au)' }
    })
    if (!resp.ok) return null
    const results = await resp.json()
    if (results && results.length > 0) {
      return { lat: parseFloat(results[0].lat), lng: parseFloat(results[0].lon) }
    }
    return null
  } catch (e) {
    console.log('[ops-api] geocode failed (non-blocking):', (e as Error).message)
    return null
  }
}

async function geocodeAndUpdateJob(client: any, jobId: string, address: string, suburb?: string) {
  try {
    const coords = await geocodeAddress(address, suburb)
    if (coords) {
      await client.from('jobs').update({ site_lat: coords.lat, site_lng: coords.lng }).eq('id', jobId)
    }
  } catch (e) {
    console.log('[ops-api] geocode update failed (non-blocking):', (e as Error).message)
  }
}

async function geocodeJob(client: any, body: any) {
  const jId = body.jobId || body.job_id
  if (!jId) throw new Error('jobId required')
  const { data: job } = await client.from('jobs').select('id, site_address, site_suburb, site_lat, site_lng').eq('id', jId).single()
  if (!job) throw new Error('Job not found')
  const coords = await geocodeAddress(job.site_address, job.site_suburb)
  if (!coords) return { ok: false, message: 'Could not geocode address: ' + (job.site_address || '') }
  await client.from('jobs').update({ site_lat: coords.lat, site_lng: coords.lng }).eq('id', jId)
  return { ok: true, lat: coords.lat, lng: coords.lng }
}

// Bulk geocode all make-safe jobs missing coordinates
async function geocodeMissingMakesafes(client: any) {
  const { data: jobs } = await client.from('jobs')
    .select('id, site_address, site_suburb')
    .eq('type', 'makesafe')
    .is('site_lat', null)
    .not('site_address', 'is', null)
    .limit(20)
  if (!jobs || jobs.length === 0) return { ok: true, geocoded: 0 }
  let geocoded = 0
  for (const j of jobs) {
    const coords = await geocodeAddress(j.site_address, j.site_suburb)
    if (coords) {
      await client.from('jobs').update({ site_lat: coords.lat, site_lng: coords.lng }).eq('id', j.id)
      geocoded++
    }
    // Nominatim rate limit: 1 req/sec
    await new Promise(r => setTimeout(r, 1100))
  }
  return { ok: true, geocoded, total: jobs.length }
}

// Scoped-routine redirect (decision scoped-routine-key-2026-06-17): when the make-safe
// automation routine calls create_makesafe_job, it must NOT create a live job. Instead
// we record its proposal as a make-safe intake DRAFT so the human approve gate still
// applies. Takes the SAME body shape as createMakesafeJob and writes a
// makesafe_intake_drafts row (never a jobs row). Status mirrors the P0-C completeness
// logic: a complete proposal lands as 'needs_review' (ready for the human tick), an
// incomplete one as 'draft'. A synthetic graph_message_id is minted because a routine
// proposal has no source email; it is namespaced so it can never collide with a real
// ingested email id and the create_intake_draft dedup still works.
async function createMakesafeDraftFromProposal(client: any, body: any) {
  const {
    client_name, site_address, suburb, site_suburb, phone, mobile, email,
    requesting_company_slug, requesting_company_name, external_ref, description,
    makesafe_type, job_type_detail, makesafe_type_detail,
    safety_requirements, special_instructions, attachments_json,
  } = body

  if (!client_name || !site_address) throw new Error('client_name and site_address required')

  const attachments = parseJsonArray(attachments_json)
  // Same required-field set the approve gate enforces (P0-C parity): a draft missing any
  // of these is not yet tickable, so it lands as 'draft' rather than 'needs_review'.
  const missingRequired = (
    (!requesting_company_slug && !requesting_company_name) ||
    !external_ref ||
    !client_name ||
    !site_address ||
    attachments.length === 0
  )

  // Synthetic, collision-proof message id for a routine proposal (no source email).
  const syntheticMessageId = `routine-proposal:${crypto.randomUUID()}`

  // The drafts table has NO makesafe_type column and confidence is constrained to
  // high/medium/low, so we stash the proposed make-safe type in extraction_json (which
  // approveIntakeDraft's choose() reads via extraction[key]) and record confidence as
  // 'low' (a routine proposal always needs the human review).
  const resolvedMakesafeType = makesafe_type || job_type_detail || makesafe_type_detail || null

  const { data, error } = await client.from('makesafe_intake_drafts').insert({
    org_id: DEFAULT_ORG_ID,
    mailbox: 'routine@makesafe.internal',
    graph_message_id: syntheticMessageId,
    received_at: new Date().toISOString(),
    requesting_company_slug: requesting_company_slug || null,
    requesting_company_name: requesting_company_name || null,
    external_ref: external_ref || null,
    client_name: client_name || null,
    client_phone: phone || mobile || null,
    client_email: email || null,
    site_address: site_address || null,
    site_suburb: site_suburb || suburb || null,
    description: description || null,
    safety_requirements: safety_requirements || null,
    special_instructions: special_instructions || null,
    confidence: 'low',
    missing_fields: [],
    extraction_json: { makesafe_type: resolvedMakesafeType, source: 'routine_proposal' },
    attachments_json: attachments,
    status: missingRequired ? 'draft' : 'needs_review',
  }).select().single()

  if (error) throw error
  return { ok: true, draft: data, redirected: true, note: 'routine proposal recorded as an intake draft for human approval; no live job created' }
}

async function createMakesafeJob(client: any, body: any) {
  const {
    client_name, site_address, suburb, phone, mobile, email,
    requesting_company_slug, requesting_company_name, external_ref, description,
    makesafe_type, job_type_detail, makesafe_type_detail,
    safety_requirements, special_instructions,
    pdf_base64, external_links,
    builder_email_text_for_trade, builder_email_subject, builder_email_received_at,
    makesafe_job_family, makesafe_job_family_label,
    builder_claim_ref, builder_work_order_number, builder_po_number,
    suppress_manager_notification,
  } = body

  if (!client_name || !site_address) throw new Error('client_name and site_address required')

  // Look up requesting company
  let companyData: any = null
  if (requesting_company_slug) {
    const { data: co } = await client.from('makesafe_companies')
      .select('*').eq('slug', requesting_company_slug).maybeSingle()
    companyData = co
  }

  // Generate job number through the shared database helper once the make-safe
  // contract migration is applied. Fallback preserves the previous SWMS-26001
  // behaviour for review/test environments that have not run the migration yet.
  let jobNumber: string | null = null
  try {
    const { data: jnData } = await client.rpc('next_job_number', { job_type: 'makesafe' })
    const candidate = String(jnData || '')
    if (candidate.toUpperCase().startsWith('SWMS-')) {
      jobNumber = candidate
    } else if (candidate) {
      console.log('[ops-api] next_job_number(makesafe) returned non-SWMS prefix; falling back:', candidate)
    }
  } catch (e) {
    console.log('[ops-api] next_job_number(makesafe) failed; falling back:', (e as Error)?.message)
  }
  if (!jobNumber) {
    const { data: lastJob } = await client.from('jobs')
      .select('job_number')
      .ilike('job_number', 'SWMS-%')
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle()
    let nextNum = 26001
    if (lastJob?.job_number) {
      const num = parseInt(lastJob.job_number.replace('SWMS-', ''), 10)
      if (!isNaN(num)) nextNum = num + 1
    }
    jobNumber = `SWMS-${nextNum}`
  }

  // Build metadata
  const reviewedCompanyName = requesting_company_name || companyData?.name || null
  const reviewedMakeSafeType = makesafe_type || job_type_detail || makesafe_type_detail || null
  const reviewedSafety = safety_requirements || companyData?.safety_requirements || null
  const reviewedSpecialInstructions = special_instructions || companyData?.special_instructions || null
  const reviewedJobFamily = makesafe_job_family || _classifyMakeSafeJobFamily(external_ref || null, description || reviewedMakeSafeType || null, null)
  const reviewedJobFamilyLabel = makesafe_job_family_label || _makeSafeJobFamilyLabel(reviewedJobFamily)

  const metadata: any = {
    requesting_company: companyData ? { slug: companyData.slug, name: companyData.name } : reviewedCompanyName ? { slug: requesting_company_slug || null, name: reviewedCompanyName } : null,
    external_ref: external_ref || null,
    builder_claim_ref: builder_claim_ref || null,
    builder_work_order_number: builder_work_order_number || null,
    builder_po_number: builder_po_number || null,
    makesafe_type: reviewedMakeSafeType,
    job_type_detail: reviewedMakeSafeType,
    invoice_email: companyData?.invoice_email || null,
    special_instructions: reviewedSpecialInstructions,
    safety_requirements: reviewedSafety,
    external_links: external_links || null,
    builder_email_text_for_trade: builder_email_text_for_trade || null,
    builder_email_subject: builder_email_subject || null,
    builder_email_received_at: builder_email_received_at || null,
    makesafe_job_family: reviewedJobFamily,
    makesafe_job_family_label: reviewedJobFamilyLabel,
  }

  // Create the job
  const { data: job, error: jobErr } = await client.from('jobs').insert({
    org_id: DEFAULT_ORG_ID,
    type: 'makesafe',
    status: 'accepted',
    client_name,
    client_phone: phone || mobile || null,
    client_email: email || null,
    site_address,
    site_suburb: suburb || null,
    job_number: jobNumber,
    notes: description || null,
    metadata,
  }).select().single()

  if (jobErr) throw jobErr

  // Geocode address (fire-and-forget, non-blocking)
  geocodeAndUpdateJob(client, job.id, site_address, suburb).catch(() => {})

  // Make-safe overlay details: keeps requesting-company refs, substatus,
  // safety notes, report handoff and invoice notes out of patio/fencing scope.
  try {
    await client.from('makesafe_job_details').insert({
      job_id: job.id,
      requesting_company_id: companyData?.id || null,
      requesting_company_slug: companyData?.slug || requesting_company_slug || null,
      requesting_company_name: reviewedCompanyName,
      external_ref: external_ref || null,
      substatus: 'company_contact_required',
      safety_requirements: reviewedSafety,
      special_instructions: reviewedSpecialInstructions,
      external_links: external_links || companyData?.external_links || [],
      billing_rules: companyData?.billing_rules || {},
      // BE-2: report-family jobs persist their report_type token at creation
      // (family 'roof_report' -> 'roof_report', 'assessment_report_quote' ->
      // 'assessment_report'; null for non-report families). Previously only
      // jobs.metadata.makesafe_job_family was written, so family-detected
      // report jobs 409'd the portal-done marker and hid from send-time
      // report-type logic. Same value convention as approveIntakeDraft.
      report_type: _reportTypeForJobFamily(reviewedJobFamily),
    })
  } catch (e: any) {
    // Non-blocking until the migration is deployed everywhere. The base job
    // remains visible and the PR/migration note makes this gap explicit.
    console.log('[ops-api] makesafe_job_details insert skipped:', e?.message)
  }

  // If PDF provided, upload to storage and create job_documents record
  if (pdf_base64) {
    try {
      const pdfBuffer = Uint8Array.from(atob(pdf_base64), c => c.charCodeAt(0))
      const pdfPath = `${job.id}/work-order-${jobNumber}.pdf`
      const adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)
      const { error: upErr } = await adminClient.storage
        .from('job-documents')
        .upload(pdfPath, pdfBuffer, { contentType: 'application/pdf', upsert: true })
      if (!upErr) {
        const { data: urlData } = adminClient.storage.from('job-documents').getPublicUrl(pdfPath)
        await client.from('job_documents').insert({
          job_id: job.id,
          type: 'work_order',
          file_name: `work-order-${jobNumber}.pdf`,
          storage_url: pdfPath,
          pdf_url: urlData?.publicUrl || null,
          visible_to_trades: true,
        })
      }
    } catch (e: any) {
      console.log('[ops-api] PDF upload failed for makesafe:', e?.message)
    }
  }

  // Log job event
  await client.from('job_events').insert({
    job_id: job.id,
    event_type: 'makesafe_created',
    detail_json: { job_number: jobNumber, requesting_company: companyData?.name || null, external_ref },
  })

  // M3b U2a (D4a, gate G3): text the make-safe manager(s) that a new make-safe
  // exists. Shaun is no-texts by choice, and dispatcher
  // role) is naturally excluded by the manager lookup's phone + non-dispatcher
  // gates. The legacy suppress_notifications flag remains intentionally ignored.
  // Deterministic intake has its own narrow suppress_manager_notification input
  // because that mission owns no communications. Other creation paths are unchanged.
  // Non-blocking; notifyVerticalManagersSms never throws.
  if (suppress_manager_notification !== true) {
    const msSite = `${site_address || ''}${suburb ? ', ' + suburb : ''}`.trim()
    const msText = [
      `New make-safe: ${jobNumber} - ${client_name || 'Client'}`.trim(),
      msSite ? `Site: ${msSite}` : '',
      reviewedCompanyName ? `Builder: ${reviewedCompanyName}` : '',
      external_ref ? `Ref: ${external_ref}` : '',
      `Open in Trade: https://secureworks-group.github.io/secureworks-ux/trade.html#job/${job.id}`,
    ].filter(Boolean).join('\n')
    await notifyVerticalManagersSms(client, 'makesafe', msText)
  }

  return { ok: true, job }
}
// Test-only export alias (mirrors the `_`-prefixed convention for the other make-safe helpers).
export const _createMakesafeJob = createMakesafeJob

// ══════════════════════════════════════════════════════════════
// Make-Safe Slices 2-7 — API endpoints
// ══════════════════════════════════════════════════════════════

// ── Slice 2: list requesting companies ──
async function listMakesafeCompanies(client: any) {
  const { data, error } = await client.from('makesafe_companies')
    .select('*')
    .eq('active', true)
    .order('name')
  if (error) throw error
  return { companies: data || [] }
}

// ── Slice 2: update make-safe overlay details ──
async function updateMakesafeDetails(client: any, body: any) {
  const { job_id, jobId } = body
  const jId = job_id || jobId
  if (!jId) throw new Error('job_id required')

  const allowed = [
    'requesting_company_id', 'requesting_company_slug', 'requesting_company_name',
    'external_ref', 'substatus', 'safety_requirements', 'special_instructions',
    'external_links', 'billing_rules', 'invoice_notes',
    'company_contacted_at', 'report_received_at', 'report_sent_at', 'invoice_ready_at',
  ]
  const updates: Record<string, any> = { updated_at: new Date().toISOString() }
  for (const key of allowed) {
    if (body[key] !== undefined) updates[key] = key === 'substatus' ? requireValidMakesafeSubstatus(body[key]) : body[key]
  }

  const { data, error } = await client.from('makesafe_job_details')
    .update(updates)
    .eq('job_id', jId)
    .select()
    .single()
  if (error) throw error
  return { ok: true, details: data }
}

const RECONCILE_MAKESAFE_FAMILIES = new Set([
  'assessment_report_quote',
  'roof_report',
  'temp_fence_makesafe',
  'general_makesafe',
])

// Privileged exact correction for a reviewed live card. Unlike the additive
// backfill, this action may replace an incorrect non-null family, but only when
// the caller supplies the family it observed before the write. It preserves all
// other metadata, keeps report_type in sync, changes no stage/substatus, and
// emits an audit event. The routine key cannot reach this action.
async function updateMakesafeJobFamily(client: any, body: any) {
  const jId = body?.job_id || body?.jobId
  const family = cleanReviewedString(body?.makesafe_job_family || body?.family)
  const expectedBefore = cleanReviewedString(body?.expected_before_family || body?.expectedBeforeFamily)
  if (!jId || !family) throw new ApiError('job_id and makesafe_job_family required', 400)
  if (!expectedBefore) throw new ApiError('expected_before_family required', 400)
  if (!RECONCILE_MAKESAFE_FAMILIES.has(family)) {
    throw new ApiError(`invalid makesafe_job_family '${family}'`, 400)
  }

  const { data: job, error: jobErr } = await client.from('jobs')
    .select('id, job_number, type, status, metadata').eq('id', jId).single()
  if (jobErr || !job) throw jobErr || new ApiError('job not found', 404)
  if (job.type !== 'makesafe') throw new ApiError('job is not a make-safe', 409)
  const beforeMetadata = parseJsonObject(job.metadata)
  const beforeFamily = cleanReviewedString(beforeMetadata.makesafe_job_family)
  if (beforeFamily !== expectedBefore) {
    throw new ApiError(`family drift: expected '${expectedBefore}', found '${beforeFamily || 'null'}'`, 409)
  }

  const { data: detail, error: detailErr } = await client.from('makesafe_job_details')
    .select('job_id, report_type, substatus').eq('job_id', jId).single()
  if (detailErr || !detail) throw detailErr || new ApiError('make-safe details not found', 404)
  const nextReportType = _reportTypeForJobFamily(family)
  const nowIso = new Date().toISOString()
  const nextMetadata = {
    ...beforeMetadata,
    makesafe_job_family: family,
    makesafe_job_family_label: _makeSafeJobFamilyLabel(family),
  }
  const { error: updateJobErr } = await client.from('jobs')
    .update({ metadata: nextMetadata, updated_at: nowIso }).eq('id', jId)
  if (updateJobErr) throw updateJobErr
  const { error: updateDetailErr } = await client.from('makesafe_job_details')
    .update({ report_type: nextReportType, updated_at: nowIso }).eq('job_id', jId)
  if (updateDetailErr) {
    await client.from('jobs')
      .update({ metadata: beforeMetadata, updated_at: new Date().toISOString() })
      .eq('id', jId)
      .then(() => {}).catch(() => {})
    throw updateDetailErr
  }

  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'makesafe_job_family_corrected',
    detail_json: {
      before_family: beforeFamily,
      after_family: family,
      before_report_type: detail.report_type || null,
      after_report_type: nextReportType,
      substatus_unchanged: detail.substatus || null,
      changed_at: nowIso,
      reason: cleanReviewedString(body?.reason) || 'reviewed source work-order correction',
    },
  }).then(() => {}).catch(() => {})

  return {
    ok: true,
    job_id: jId,
    job_number: job.job_number || null,
    before: { makesafe_job_family: beforeFamily, report_type: detail.report_type || null, substatus: detail.substatus || null },
    after: { makesafe_job_family: family, report_type: nextReportType, substatus: detail.substatus || null },
  }
}
export const _updateMakesafeJobFamily = updateMakesafeJobFamily

const INSURANCE_CONVERSION_CLASSES: Record<string, string> = {
  patio_repair: 'Patio Insurance Repair',
  fencing_repair: 'Fencing Insurance Repair',
  rapid_repair: 'Rapid Insurance Repair',
  restoration: 'Restoration Insurance Work',
}

// Captain-reviewed pipeline correction. The original job, job number, evidence,
// assignment, invoices and status stay in place; only the owning pipeline/type
// and explicit insurance classification change. This removes non-make-safe work
// from the make-safe board without archiving or losing the live obligation.
async function convertMakesafeToInsurance(client: any, body: any) {
  const jId = body?.job_id || body?.jobId
  const expectedBeforeType = cleanReviewedString(body?.expected_before_type || body?.expectedBeforeType)
  const classification = cleanReviewedString(body?.insurance_job_type || body?.classification)
  if (!jId || !expectedBeforeType || !classification) {
    throw new ApiError('job_id, expected_before_type and insurance_job_type required', 400)
  }
  if (expectedBeforeType !== 'makesafe') {
    throw new ApiError("expected_before_type must be 'makesafe'", 400)
  }
  const label = INSURANCE_CONVERSION_CLASSES[classification]
  if (!label) throw new ApiError(`invalid insurance_job_type '${classification}'`, 400)

  const { data: job, error: jobErr } = await client.from('jobs')
    .select('id, job_number, type, status, metadata').eq('id', jId).single()
  if (jobErr || !job) throw jobErr || new ApiError('job not found', 404)
  if (job.type !== expectedBeforeType) {
    throw new ApiError(`job type drift: expected '${expectedBeforeType}', found '${job.type || 'null'}'`, 409)
  }
  const { data: detail, error: detailErr } = await client.from('makesafe_job_details')
    .select('job_id, external_ref, substatus, report_type').eq('job_id', jId).single()
  if (detailErr || !detail) throw detailErr || new ApiError('make-safe details not found', 404)

  const beforeMetadata = parseJsonObject(job.metadata)
  const nowIso = new Date().toISOString()
  const conversion = {
    from_job_type: job.type,
    to_job_type: 'insurance',
    insurance_job_type: classification,
    insurance_job_type_label: label,
    captain_ruling: cleanReviewedString(body?.captain_ruling) || null,
    reason: cleanReviewedString(body?.reason) || null,
    converted_at: nowIso,
    source_job_number: job.job_number || null,
    source_external_ref: detail.external_ref || null,
  }
  const nextMetadata = {
    ...beforeMetadata,
    insurance_job_type: classification,
    insurance_job_type_label: label,
    pipeline_conversion: conversion,
  }
  const { data: updated, error: updateErr } = await client.from('jobs')
    .update({ type: 'insurance', metadata: nextMetadata, updated_at: nowIso })
    .eq('id', jId)
    .eq('type', expectedBeforeType)
    .select('id, job_number, type, status, metadata')
    .single()
  if (updateErr) throw updateErr

  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'makesafe_converted_to_insurance',
    detail_json: {
      ...conversion,
      job_status_unchanged: job.status || null,
      substatus_preserved: detail.substatus || null,
      prior_makesafe_job_family: beforeMetadata.makesafe_job_family || null,
    },
  }).then(() => {}).catch(() => {})

  return {
    ok: true,
    job_id: jId,
    job_number: updated.job_number || null,
    before: {
      type: job.type,
      status: job.status || null,
      makesafe_job_family: beforeMetadata.makesafe_job_family || null,
      substatus: detail.substatus || null,
    },
    after: {
      type: updated.type,
      status: updated.status || null,
      insurance_job_type: updated.metadata?.insurance_job_type || null,
      insurance_job_type_label: updated.metadata?.insurance_job_type_label || null,
      substatus: detail.substatus || null,
    },
  }
}
export const _convertMakesafeToInsurance = convertMakesafeToInsurance

type MakesafeFamilyBackfillCandidate = {
  job_id: string
  job_number: string | null
  external_ref: string | null
  stage: string | null
  status: string | null
  substatus: string | null
  current_family: string | null
  inferred_family: string
  inferred_label: string
  notes_excerpt: string
  link_count: number
}

type ActiveBackfillMakeSafeJobFamily =
  | 'assessment_report_quote'
  | 'roof_report'
  | 'temp_fence_makesafe'
  | 'general_makesafe'

function inferMakesafeFamilyForActiveBackfill(args: {
  notes?: string | null
  metadata?: any
  detail?: any
}): ActiveBackfillMakeSafeJobFamily | null {
  const metadata = parseJsonObject(args.metadata)
  const detail = args.detail || {}
  const text = [
    metadata?.makesafe_type,
    metadata?.job_type_detail,
    metadata?.scope,
    metadata?.scope_json,
    detail?.report_type,
    args.notes,
  ].map((v) => {
    if (v == null) return ''
    if (typeof v === 'string') return v
    try { return JSON.stringify(v) } catch (_) { return String(v) }
  }).filter(Boolean).join('\n').toLowerCase()

  // Match the agreed four-family model. This deliberately does not classify
  // physical roof make-safe, ceiling collapse, board-up, structural, asbestos,
  // watertight, etc. as their own family; if those rows lack canonical metadata
  // they remain exceptions/general work until explicitly reviewed.
  if (/(temp(?:orary)?\s*fenc|fenc(?:e|ing)?\s*(collect|pickup|pick\s*up|retriev)|collect\s+.*fenc|pick\s*up\s+.*fenc|pickup\s+.*fenc|retriev\w*\s+.*fenc)/i.test(text)) {
    return 'temp_fence_makesafe'
  }
  if (/\b(roof\s+(report|assessment\s*report|inspection\s*report)|report\s+.*\broof\b|prime\s+roof\s+report|single\s+storey\s+roof\s+report|two\s+storey\s+roof\s+report|cause\s+of\s+damage\/point\s+of\s+water\s+entry)\b/i.test(text)) {
    return 'roof_report'
  }
  if (/\b(assessment\s*(report)?|assess\s+and\s+quote|inspect\s+and\s+(provide\s+)?quote|inspection\s+and\s+assessment|contractor\s+(inspection|assessment)|quote\s*(request|link|report)?|quotation|scope\s+of\s+works?)\b/i.test(text)) {
    return 'assessment_report_quote'
  }
  return null
}

function buildMakesafeFamilyBackfillCandidates(
  jobs: any[],
  detailsMap: Record<string, any>,
  stageMap: Record<string, string>,
): MakesafeFamilyBackfillCandidate[] {
  const out: MakesafeFamilyBackfillCandidate[] = []
  for (const job of (jobs || [])) {
    const metadata = parseJsonObject(job?.metadata)
    const currentFamily = metadata?.makesafe_job_family ? String(metadata.makesafe_job_family) : null
    if (currentFamily) continue
    const detail = detailsMap[job.id] || null
    const inferred = inferMakesafeFamilyForActiveBackfill({
      notes: job?.notes || null,
      metadata,
      detail,
    })
    if (!inferred) continue
    out.push({
      job_id: job.id,
      job_number: job.job_number || null,
      external_ref: detail?.external_ref || metadata?.external_ref || null,
      stage: stageMap[job.id] || null,
      status: job.status || null,
      substatus: normalizeMakesafeSubstatus(detail?.substatus) || null,
      current_family: currentFamily,
      inferred_family: inferred,
      inferred_label: _makeSafeJobFamilyLabel(inferred),
      notes_excerpt: String(job?.notes || '').slice(0, 160),
      link_count: Array.isArray(detail?.external_links)
        ? detail.external_links.length
        : (Array.isArray(metadata?.external_links) ? metadata.external_links.length : 0),
    })
  }
  return out
}

function normalizeBackfillJobNumberFilter(value: any): Set<string> | null {
  const raw = Array.isArray(value)
    ? value
    : (typeof value === 'string' ? value.split(/[,\s]+/) : [])
  const normalized = raw
    .map((v) => String(v || '').trim().toUpperCase())
    .filter(Boolean)
  return normalized.length ? new Set(normalized) : null
}

function filterMakesafeFamilyBackfillCandidatesForScope(
  candidates: MakesafeFamilyBackfillCandidate[],
  body: any,
): MakesafeFamilyBackfillCandidate[] {
  const includeJobNumbers = normalizeBackfillJobNumberFilter(body?.job_numbers)
  const excludeJobNumbers = normalizeBackfillJobNumberFilter(body?.exclude_job_numbers)
  return candidates.filter((candidate) => {
    const jobNumber = String(candidate.job_number || '').trim().toUpperCase()
    if (includeJobNumbers && !includeJobNumbers.has(jobNumber)) return false
    if (excludeJobNumbers && excludeJobNumbers.has(jobNumber)) return false
    return true
  })
}

export const _inferMakesafeFamilyForActiveBackfillForTest = inferMakesafeFamilyForActiveBackfill
export const _buildMakesafeFamilyBackfillCandidatesForTest = buildMakesafeFamilyBackfillCandidates
export const _filterMakesafeFamilyBackfillCandidatesForScopeForTest = filterMakesafeFamilyBackfillCandidatesForScope

async function backfillMakesafeJobFamilies(client: any, body: any) {
  const dryRun = body?.dry_run !== false
  const expectedCount = body?.expected_count === undefined || body?.expected_count === null
    ? null
    : Number(body.expected_count)
  const allowedFamilies = new Set([
    'assessment_report_quote',
    'roof_report',
    'temp_fence_makesafe',
    'general_makesafe',
  ])

  const { data: jobs, error: jobsErr } = await client.from('jobs')
    .select('id, job_number, status, notes, metadata, created_at')
    .eq('type', 'makesafe')
    .not('status', 'in', '("cancelled","archived","lost","invoiced","completed")')
    .is('completed_at', null)
    .order('created_at', { ascending: false })
  if (jobsErr) throw jobsErr

  const jobIds = (jobs || []).map((j: any) => j.id)
  const details = jobIds.length
    ? await _fetchAllByJobIdChunked(
      client,
      'makesafe_job_details',
      'job_id, external_ref, substatus, report_type, external_links',
      jobIds,
    )
    : []
  const detailsMap: Record<string, any> = {}
  for (const d of (details || [])) detailsMap[d.job_id] = d

  const stageMap: Record<string, string> = {}
  const pipeline = await makesafePipeline(client, new URLSearchParams())
  for (const rows of Object.values(pipeline?.columns || {}) as any[]) {
    for (const row of (rows || [])) {
      if (row?.id) stageMap[row.id] = row.board_stage || row.stage || ''
    }
  }

  const allCandidates = buildMakesafeFamilyBackfillCandidates(jobs || [], detailsMap, stageMap)
    .filter((c) => allowedFamilies.has(c.inferred_family))
  const candidates = filterMakesafeFamilyBackfillCandidatesForScope(allCandidates, body)

  if (expectedCount !== null && candidates.length !== expectedCount) {
    return {
      ok: false,
      dry_run: dryRun,
      error: `expected_count mismatch: expected ${expectedCount}, got ${candidates.length}`,
      expected_count: expectedCount,
      candidate_count: candidates.length,
      unfiltered_candidate_count: allCandidates.length,
      candidates,
    }
  }

  const result: any = {
    ok: true,
    dry_run: dryRun,
    candidate_count: candidates.length,
    unfiltered_candidate_count: allCandidates.length,
    candidates,
    updated: [] as any[],
    skipped: [] as any[],
  }
  if (dryRun) return result

  for (const c of candidates) {
    const job = (jobs || []).find((j: any) => j.id === c.job_id)
    const metadata = parseJsonObject(job?.metadata)
    if (metadata?.makesafe_job_family) {
      result.skipped.push({ ...c, reason: 'family became non-null before write' })
      continue
    }
    const nextMetadata = {
      ...metadata,
      makesafe_job_family: c.inferred_family,
      makesafe_job_family_label: c.inferred_label,
    }
    const { data: updated, error } = await client.from('jobs')
      .update({ metadata: nextMetadata, updated_at: new Date().toISOString() })
      .eq('id', c.job_id)
      .eq('type', 'makesafe')
      .not('status', 'in', '("cancelled","archived","lost","invoiced","completed")')
      .select('id, job_number, status, metadata')
      .single()
    if (error) throw error
    result.updated.push({
      job_id: updated.id,
      job_number: updated.job_number,
      status: updated.status,
      makesafe_job_family: updated.metadata?.makesafe_job_family || null,
      makesafe_job_family_label: updated.metadata?.makesafe_job_family_label || null,
    })
  }

  return result
}

// ── Slice 2: move substatus forward with timestamp tracking ──
const MAKESAFE_BOARD_STAGE_LABELS: Record<string, string> = {
  new: 'New',
  allocated: 'Allocated',
  // Trade report received but the close-out pack has NOT yet been drafted
  // (no rendered report doc / no draft invoice). Sits between Allocated and
  // Report Ready so admin can see what is waiting to be drafted.
  trade_report_in: 'Trade Report In',
  report_ready: 'Report Ready',
  completed: 'Completed This Week',
  archive: 'Archive',
  // M-F: manually-cancelled make-safes (builder recalled / reallocated / sent in
  // error). Fed by a SEPARATE bounded query (last 90 days) — never inflates the
  // active board's `total`. Ops renders it as a collapsible column.
  cancelled: 'Cancelled',
}
const MAKESAFE_BOARD_STAGES = Object.keys(MAKESAFE_BOARD_STAGE_LABELS)
const MAKESAFE_VALID_SUBSTATUSES = [
  'company_contact_required', 'company_contact_done',
  'waiting_on_trade_report', 'admin_to_send_report',
  'ready_to_invoice', 'complete',
]

export function _normalizeMakesafeSubstatus(substatus: string | null | undefined): string | null {
  if (!substatus) return null
  const trimmed = String(substatus).trim()
  if (trimmed === 'pending_allocation') return 'company_contact_required'
  return trimmed || null
}

function normalizeMakesafeSubstatus(substatus: string | null | undefined): string | null {
  return _normalizeMakesafeSubstatus(substatus)
}

function requireValidMakesafeSubstatus(substatus: string | null | undefined): string {
  const normalized = normalizeMakesafeSubstatus(substatus)
  if (!normalized) throw new Error('substatus required')
  if (!MAKESAFE_VALID_SUBSTATUSES.includes(normalized)) {
    throw new Error('Invalid substatus: ' + substatus + '. Allowed: ' + MAKESAFE_VALID_SUBSTATUSES.join(', '))
  }
  return normalized
}

function hasActiveMakesafeInvoice(invoice: any): boolean {
  return !!invoice && !['VOIDED', 'DELETED'].includes(String(invoice.status || '').toUpperCase())
}

function perthYmd(date: Date): { y: number; m: number; d: number } | null {
  if (Number.isNaN(date.getTime())) return null
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Australia/Perth',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date)
  const val = (type: string) => Number(parts.find((p) => p.type === type)?.value || 0)
  const y = val('year')
  const m = val('month')
  const d = val('day')
  return y && m && d ? { y, m, d } : null
}

function utcMidnight(parts: { y: number; m: number; d: number }): number {
  return Date.UTC(parts.y, parts.m - 1, parts.d)
}

export function _isMakesafeCompletedThisWeek(completedAt: string | null | undefined, nowIso?: string): boolean {
  // Unknown completion dates stay visible as Completed This Week rather than
  // disappearing into Archive. Ops can then fix the missing timestamp manually.
  if (!completedAt) return true
  const completedParts = perthYmd(new Date(completedAt))
  const nowParts = perthYmd(nowIso ? new Date(nowIso) : new Date())
  if (!completedParts || !nowParts) return true
  const nowDayStart = utcMidnight(nowParts)
  const day = new Date(nowDayStart).getUTCDay()
  const daysSinceMonday = (day + 6) % 7
  const weekStart = nowDayStart - daysSinceMonday * 86400000
  const weekEnd = weekStart + 7 * 86400000
  const completedDayStart = utcMidnight(completedParts)
  return completedDayStart >= weekStart && completedDayStart < weekEnd
}

// Canonical complete-vs-archive split: completed within the last 7 days stays in
// `completed`, older rolls to `archive`. Replaces the old Perth-calendar-week
// rule so a make-safe completed late in a week is not archived the next Monday.
// Unknown/unparseable completion dates stay in `completed` (same fallback as the
// week rule) so ops can fix the missing timestamp rather than losing the card.
// nowMs minus completedMs uses a strict 7x86400000ms window (>= 7 days archives).
export function _isMakesafeCompletedWithin7Days(completedAt: string | null | undefined, nowIso?: string): boolean {
  if (!completedAt) return true
  const completedMs = new Date(completedAt).getTime()
  const nowMs = nowIso ? new Date(nowIso).getTime() : Date.now()
  if (Number.isNaN(completedMs) || Number.isNaN(nowMs)) return true
  return nowMs - completedMs < 7 * 86400000
}

function makesafeCompletedAt(job: any, detail: any, invoice: any): string | null {
  return invoice?.invoice_date || invoice?.created_at || detail?.invoice_ready_at || job?.completed_at || job?.updated_at || null
}

// MLB (ML Builders / Major Loss Builders) identity. SWMS is a hard close-out
// requirement only for MLB-company make-safes, not universally. We detect MLB
// defensively from slug, company name, or the builder reference prefix because
// the canonical company slug is not hard-coded here (see PR notes for review).
export function _isMakesafeMlbCompany(detail: any, job: any): boolean {
  const slug = String(
    detail?.requesting_company_slug || detail?.makesafe_companies?.slug || job?.metadata?.requesting_company?.slug || ''
  ).toLowerCase()
  const name = String(
    detail?.requesting_company_name || detail?.makesafe_companies?.name || job?.metadata?.requesting_company?.name || ''
  ).toLowerCase()
  const ref = String(detail?.external_ref || job?.metadata?.external_ref || '').toUpperCase()
  if (slug.includes('mlb') || slug.includes('ml-builders') || slug.includes('major-loss')) return true
  if (name.includes('ml builders') || name.includes('major loss')) return true
  if (/\bMLB[-\s]?\d/.test(ref)) return true
  return false
}

// B4 (Wave 0): Western Building / Builderwest identity. Mirrors _isMakesafeMlbCompany.
// Western Building and Builderwest are the same operator group for make-safe purposes —
// they use the MLB-style hire card and require a SWMS like MLB.
// Slug slugs: 'builderwest', 'western-building'. Ref prefixes: 'BWCWA', 'WB'.
export function _isMakesafeWesternCompany(detail: any, job: any): boolean {
  const slug = String(
    detail?.requesting_company_slug || detail?.makesafe_companies?.slug || job?.metadata?.requesting_company?.slug || ''
  ).toLowerCase()
  const name = String(
    detail?.requesting_company_name || detail?.makesafe_companies?.name || job?.metadata?.requesting_company?.name || ''
  ).toLowerCase()
  const ref = String(detail?.external_ref || job?.metadata?.external_ref || '').toUpperCase()
  if (slug.includes('builderwest') || slug.includes('western-building')) return true
  if (name.includes('builderwest') || name.includes('western building')) return true
  if (ref.startsWith('BWCWA') || /\bWB[-\s]?\d/.test(ref)) return true
  return false
}

// Close-out doc gate. A make-safe may only resolve to completed/archive once its
// invoice + report PDFs are attached. SWMS is additionally required for MLB jobs.
// Returns the set of docs that are still missing (empty => gate satisfied).
export function _makesafeMissingCloseoutDocs(
  docs: { has_invoice_doc?: boolean; has_report_doc?: boolean; has_swms_doc?: boolean } | null | undefined,
  requiresSwms: boolean,
  isReportJob?: boolean,
): string[] {
  const d = docs || {}
  const missing: string[] = []
  if (!d.has_invoice_doc) missing.push('invoice')
  // Report jobs require ONLY the invoice — no SecureWorks report PDF is produced.
  if (!isReportJob && !d.has_report_doc) missing.push('report')
  if (requiresSwms && !d.has_swms_doc) missing.push('swms')
  return missing
}

// ─────────────────────────────────────────────────────────────────────────
// SHARED surfacing predicate — single source of truth for the board derivation
// (_deriveMakesafeBoardStage / enrichMakesafeBoardJob) AND the report-drafts
// cockpit feed (makesafeReportDrafts). Both must agree on:
//   - sentClosed: the pack genuinely went out the door (never re-surface it).
//   - readyForReview: a draft is rendered + draft invoice exists, awaiting send.
//   - resumeNotSent: an authorised-but-not-sent pack to RESUME (never a fresh send).
//   - tradeReportIn: report received but NOT yet drafted.
// This is the SAFE predicate from the adversarial review. It only ever reads /
// derives — it authorises nothing, sends nothing, charges nothing.
//
// `pack` is the makesafe_report_packs row for the job (status + report_doc_id).
// A non-null report_doc_id (written by makesafeRenderReport) means a report
// draft was rendered. The pack `status` column distinguishes sent vs not.
export interface MakesafeReportPackLike {
  status?: string | null
  report_doc_id?: string | null
  invoice_doc_id?: string | null
  swms_doc_id?: string | null
  review_state?: string | null
  sent_at?: string | null
}
export interface MakesafeSurfacing {
  normalizedSub: string | null
  hasSubmittedReport: boolean
  hasReportDoc: boolean
  invoiceIsDraft: boolean
  invoiceAuthorisedLive: boolean
  sentClosed: boolean
  // gateSoftenSent: the TRUSTWORTHY sent signal that may soften the hard
  // close-out doc-gate. NARROWER than sentClosed: it excludes a bare
  // MAKESAFE_PACK_SENT marker (packSent) on its own, because that marker alone
  // (with a DRAFT/unauthorised invoice) is TRIAGE-only and must NOT relax the
  // gate (preserves the existing 2.3 guardrail). It is true for a durable pack
  // sent-status or detail.report_sent_at — both proof the close-out actually went
  // out. sentClosed (which DOES include bare packSent) still governs SURFACING
  // (never re-show a packSent job as a fresh ready-to-send draft).
  gateSoftenSent: boolean
  readyForReview: boolean
  resumeNotSent: boolean
  tradeReportIn: boolean
}

// pack statuses that mean the pack was actually sent / closed (never re-surface).
const MAKESAFE_PACK_SENT_STATUSES = ['sent', 'sent_marker_failed', 'sent_not_closed', 'close_failed']

// CHIP-TRUTH (audit F5): the TRUSTWORTHY "sent to builder" signal for the board's
// SENT chip. TRUE only when there is a REAL send record:
//   - the MAKESAFE_PACK_SENT | main marker note (packSent), or
//   - the durable makesafe_report_packs row is in a sent/closed status.
// It deliberately EXCLUDES detail.report_sent_at, which updateMakesafeSubstatus
// stamps on the move to ready_to_invoice (admin marking the report ready to
// invoice) — NOT necessarily at send time — so it is not proof of a send. It also
// does NOT use the board stage: today the SENT chip greened for EVERY
// completed/archive card as a column proxy (makesafeReportStatus -> 'processed'),
// asserting "sent" with no record behind it. Fail-closed: unknown -> not sent.
export function _makesafeSentToBuilder(
  packSent: boolean | undefined,
  pack: MakesafeReportPackLike | null | undefined,
): boolean {
  const packStatus = String(pack?.status || '').toLowerCase()
  return packSent === true || MAKESAFE_PACK_SENT_STATUSES.includes(packStatus)
}

export function _deriveMakesafeSurfacing(
  job: any,
  detail: any,
  report: any,
  invoice: any,
  docs: { has_invoice_doc?: boolean; has_report_doc?: boolean; has_swms_doc?: boolean } | null | undefined,
  packSent: boolean | undefined,
  pack: MakesafeReportPackLike | null | undefined,
): MakesafeSurfacing {
  const normalizedSub = normalizeMakesafeSubstatus(detail?.substatus)
  const hasSubmittedReport = !!report || !!detail?.report_received_at ||
    normalizedSub === 'admin_to_send_report' || normalizedSub === 'ready_to_invoice'
  const packStatus = String(pack?.status || '').toLowerCase()

  // A rendered report draft artifact exists: either makesafeRenderReport wrote a
  // report_doc_id onto the pack, or job_documents already carry a report PDF.
  const hasReportDoc = !!(pack && pack.report_doc_id) || docs?.has_report_doc === true

  const invoiceStatusUpper = String(invoice?.status || '').toUpperCase()
  const invoiceIsLive = hasActiveMakesafeInvoice(invoice)
  const invoiceIsDraft = invoiceIsLive && invoiceStatusUpper === 'DRAFT'
  const invoiceAuthorisedLive = invoiceIsLive &&
    ['AUTHORISED', 'SUBMITTED', 'PAID'].includes(invoiceStatusUpper)

  // gateSoftenSent — the signal trustworthy enough to SOFTEN the hard close-out
  // doc-gate (let a job complete despite a missing doc). This is the UNSAFE
  // direction, so it is the NARROWEST: a durable pack sent-status ONLY. It
  // deliberately EXCLUDES detail.report_sent_at, because updateMakesafeSubstatus
  // stamps report_sent_at on the move to ready_to_invoice (admin marking the
  // report ready to invoice) — NOT necessarily when the pack was actually
  // emailed. Trusting it here could let an un-sent invoiced job with a missing
  // close-out doc bypass the gate. A durable pack status (sent / sent_not_closed
  // / sent_marker_failed / close_failed) only exists after the irreversible send
  // step, so it is safe gate-softening evidence. (Adversarial review finding 3.)
  const gateSoftenSent = MAKESAFE_PACK_SENT_STATUSES.includes(packStatus)

  // sentClosed — the pack demonstrably went to the builder. ANY of:
  //   - the MAKESAFE_PACK_SENT | main marker note (packSent)
  //   - detail.report_sent_at stamped (the close-out send timestamp)
  //   - the durable pack row is in a sent/closed status
  // Governs SURFACING only (never re-surface a packSent job as ready-to-send) —
  // this is the SAFE direction (excluding a job from the send queue can't cause
  // a double-send), so it can trust report_sent_at where gateSoftenSent cannot.
  const sentClosed = packSent === true ||
    !!detail?.report_sent_at ||
    MAKESAFE_PACK_SENT_STATUSES.includes(packStatus)

  // readyForReview — a genuine drafted-not-sent pack awaiting the human send:
  // not sent, in the admin_to_send_report substatus, with a submitted report, a
  // rendered report artifact AND a DRAFT invoice (the two close-out artifacts).
  const readyForReview = !sentClosed &&
    normalizedSub === 'admin_to_send_report' &&
    hasSubmittedReport &&
    hasReportDoc &&
    invoiceIsDraft

  // resumeNotSent — the irreversible authorise happened but the send did not.
  // Resume re-sends; it must NEVER re-authorise and must NEVER read as a fresh
  // ready-for-review draft. Surfaces in report_ready as a resume.
  const resumeNotSent = !sentClosed &&
    packStatus === 'authorised_not_sent' &&
    invoiceAuthorisedLive

  // tradeReportIn — the trade report has come in (substatus admin_to_send_report)
  // but the close-out pack is NOT yet drafted (no rendered report doc / no draft
  // invoice) and it is not already sent. Scoped to the admin_to_send_report
  // substatus so it can NEVER hijack a job already in the invoiced/complete
  // close-out regime (those keep the existing invoiceDone + hard doc-gate path).
  const tradeReportIn = normalizedSub === 'admin_to_send_report' &&
    hasSubmittedReport && !readyForReview && !resumeNotSent && !sentClosed

  return {
    normalizedSub,
    hasSubmittedReport,
    hasReportDoc,
    invoiceIsDraft,
    invoiceAuthorisedLive,
    sentClosed,
    gateSoftenSent,
    readyForReview,
    resumeNotSent,
    tradeReportIn,
  }
}

export function _deriveMakesafeBoardStage(
  job: any,
  detail: any,
  assignments: any[] = [],
  report?: any,
  invoice?: any,
  nowIso?: string,
  docs?: { has_invoice_doc?: boolean; has_report_doc?: boolean; has_swms_doc?: boolean } | null,
  packSent?: boolean,
  pack?: MakesafeReportPackLike | null,
): string {
  const normalizedSub = normalizeMakesafeSubstatus(detail?.substatus)
  const jobStatus = String(job?.status || '').toLowerCase()
  // M-F: a cancelled make-safe always derives to the Cancelled column, regardless
  // of any sent/report/invoice evidence it carried (report-then-cancel is allowed).
  // EARLY return — before the `new` default and every other branch below.
  if (jobStatus === 'cancelled' || jobStatus === 'canceled') return 'cancelled'
  // Canonically archived jobs stay archived even when their historical detail or
  // assignment rows are sparse. Never let an archive card fall back to New.
  if (jobStatus === 'archived') return 'archive'
  const hasAssignments = assignments.length > 0
  const hasSubmittedReport = !!report || !!detail?.report_received_at || normalizedSub === 'admin_to_send_report' || normalizedSub === 'ready_to_invoice'
  const invoiceDone = hasActiveMakesafeInvoice(invoice) || jobStatus === 'invoiced' || normalizedSub === 'complete'

  const surf = _deriveMakesafeSurfacing(job, detail, report, invoice, docs, packSent, pack)

  // A job is "verified sent" when the reporting skill has written the
  // MAKESAFE_PACK_SENT | main marker note AND the invoice is actually
  // authorised (not just draft). This is the only signal that softens the
  // hard doc-gate below — and it is a TRIAGE input here, never the sole
  // driver: it only relaxes the gate when the invoice is authorised and the
  // substatus is complete (the pack genuinely went out the door).
  const invoiceAuthorised = hasActiveMakesafeInvoice(invoice) &&
    ['AUTHORISED', 'SUBMITTED', 'PAID'].includes(String(invoice?.status || '').toUpperCase())
  // verifiedSent softens the hard close-out doc-gate. Original signal: pack_sent
  // marker + authorised invoice + substatus complete. Now ALSO satisfied by the
  // TRUSTWORTHY gateSoftenSent signal (a DURABLE pack status sent/sent_not_closed/
  // sent_marker_failed/close_failed ONLY) so a sent-but-not-fully-closed pack
  // (e.g. sent_not_closed) does NOT get re-held in report_ready by a missing doc —
  // it already went out the door and must resolve to completed/archive.
  // gateSoftenSent deliberately EXCLUDES a bare packSent marker AND
  // detail.report_sent_at (the latter is stamped at the ready_to_invoice move, not
  // at send time, so it is not safe gate-softening evidence — adversarial #3).
  const verifiedSent = (packSent === true && invoiceAuthorised && normalizedSub === 'complete') ||
    surf.gateSoftenSent

  // Canonical MakeSafe command flow:
  // Intake drafts live outside this board until approved.
  // New -> Allocated -> Trade Report In -> Report Ready -> Completed (<=7 days)
  //   -> Archive (>7 days).
  // `ready_to_invoice` is a legacy/admin substatus and now stays actionable in
  // Report Ready unless an invoice/complete signal proves the MakeSafe is done.
  //
  // DRAFTED-NOT-SENT / RESUME WIN over the invoiceDone short-circuit, but ONLY
  // when the pack has NOT been sent+closed. This fixes Ferndale: an invoiced
  // job (status=invoiced, sub=admin_to_send_report) carrying a DRAFT invoice +
  // rendered report previously short-circuited to completed/archive (because a
  // DRAFT invoice counts as an active invoice) and vanished. It must instead
  // surface in report_ready for the human to send. A genuinely sent+closed job
  // (surf.sentClosed) falls through to the close-out doc gate below exactly as
  // before — we never re-surface a sent pack.
  if (!surf.sentClosed) {
    // resume an authorised-but-not-sent pack — surfaces as report_ready (a
    // resume), never re-sends, never re-authorises.
    if (surf.resumeNotSent) return 'report_ready'
    // a drafted-not-sent pack (rendered report + DRAFT invoice) awaiting send.
    if (surf.readyForReview) return 'report_ready'
    // report received but NOT yet drafted -> the new Trade Report In column.
    if (surf.tradeReportIn) return 'trade_report_in'
  }
  if (invoiceDone) {
    // Close-out doc gate. Two regimes:
    //  - VERIFIED-SENT job (pack_sent marker + authorised invoice + substatus
    //    complete): the pack demonstrably went to the builder, so any still-
    //    missing docs are a SOFT docs_warning (surfaced by enrichMakesafeBoardJob),
    //    NOT a hard hold. The job derives to completed/archive. This clears the
    //    Tapping/Bassendean/Stirling/Marangaroo class where the pack was sent but
    //    the PDF was never re-attached to the job.
    //  - NOT-verified-sent job: the HARD doc-gate stays. An un-sent job is never
    //    completed without its invoice + report (+ SWMS for MLB) attached — hold
    //    it in report_ready. (When no docs map is supplied, preserve the prior
    //    ungated behaviour for callers that don't load job_documents.)
    if (!verifiedSent && docs !== undefined && docs !== null) {
      // B4 (Wave 0): Western Building also requires SWMS (same rule as MLB).
      const missing = _makesafeMissingCloseoutDocs(docs, _isMakesafeMlbCompany(detail, job) || _isMakesafeWesternCompany(detail, job), !!(detail?.report_type))
      if (missing.length > 0) return 'report_ready'
    }
    return _isMakesafeCompletedWithin7Days(makesafeCompletedAt(job, detail, invoice), nowIso) ? 'completed' : 'archive'
  }
  if (hasSubmittedReport || jobStatus === 'complete') return 'report_ready'
  if (hasAssignments || normalizedSub === 'waiting_on_trade_report' || normalizedSub === 'company_contact_done' || jobStatus === 'scheduled' || jobStatus === 'in_progress') return 'allocated'
  return 'new'
}

function deriveMakesafeBoardStage(
  job: any,
  detail: any,
  assignments: any[] = [],
  report?: any,
  invoice?: any,
  docs?: { has_invoice_doc?: boolean; has_report_doc?: boolean; has_swms_doc?: boolean } | null,
  packSent?: boolean,
  pack?: MakesafeReportPackLike | null,
): string {
  return _deriveMakesafeBoardStage(job, detail, assignments, report, invoice, undefined, docs, packSent, pack)
}

function makesafeAge(createdAt: string | null | undefined, boardStage: string) {
  const timestamp = createdAt ? new Date(createdAt).getTime() : NaN
  const ageHours = Number.isFinite(timestamp) ? Math.max(0, Math.round((Date.now() - timestamp) / 3600000)) : 0
  const ageDays = Math.floor(ageHours / 24)
  const health = boardStage === 'completed' ? 'closed' : ageHours < 24 ? 'green' : ageHours < 48 ? 'yellow' : 'red'
  return { age_hours: ageHours, age_days: ageDays, health }
}

function firstByJobId(rows: any[] | null | undefined): Record<string, any> {
  const map: Record<string, any> = {}
  for (const row of (rows || [])) {
    if (row?.job_id && !map[row.job_id]) map[row.job_id] = row
  }
  return map
}

// Re-attendance (M-C) + U2-S1: shared cycle boundary lives in
// makesafe_cycle_evidence.ts so board and audit cannot diverge.
function currentCycleReportMap(
  rows: any[] | null | undefined,
  detailsMap: Record<string, any>,
): Record<string, any> {
  return cycleEvidenceReportMap(rows, detailsMap)
}

function makesafeCrew(assignments: any[] = []) {
  const names = assignments.map((a: any) => a?.users?.name).filter(Boolean)
  const uniqueNames = Array.from(new Set(names))
  const crewNames = assignments.map((a: any) => a?.crew_name).filter(Boolean)
  const uniqueCrews = Array.from(new Set(crewNames))
  const firstDate = assignments.map((a: any) => a?.scheduled_date).filter(Boolean).sort()[0] || null
  const labelBase = uniqueCrews.length > 0 ? uniqueCrews.join(', ') : uniqueNames.length > 0 ? uniqueNames.join(', ') : 'Unassigned'
  return {
    crew_label: firstDate && labelBase !== 'Unassigned' ? `${labelBase} — ${firstDate}` : labelBase,
    crew_members: uniqueNames,
  }
}

function makesafeReportStatus(boardStage: string, detail: any, report: any): string {
  if (boardStage === 'completed' || boardStage === 'archive') return 'processed'
  if (boardStage === 'report_ready' || report || detail?.report_received_at) return 'ready_for_reporting_skill'
  return 'waiting_on_trade_report'
}

function makesafeInvoiceStatus(boardStage: string, invoice: any): string {
  if (hasActiveMakesafeInvoice(invoice)) {
    const status = String(invoice.status || '').toUpperCase()
    if (status === 'PAID') return 'paid'
    if (status === 'AUTHORISED' || status === 'SUBMITTED') return 'invoiced'
    return status.toLowerCase() || 'invoiced'
  }
  if (boardStage === 'completed' || boardStage === 'archive') return 'invoiced'
  if (boardStage === 'report_ready') return 'report_ready'
  return 'not_ready'
}

// Build the per-job close-out doc booleans from this job's job_documents rows.
// has_wo: a work order doc; has_report_doc / has_invoice_doc / has_swms_doc.
//
// CHIP-TRUTH (audit F6): PREFER the typed job_documents.type over the filename
// heuristic. The reporting skill now writes TYPED rows — an invoice as
// type='invoice' named 'INV-0776.pdf', the report as type='makesafe_report',
// the SWMS as type='swms'. A filename-only match therefore both:
//   - MISSES real typed docs (INV-0776.pdf has no 'invoice' substring, so the
//     invoice read as missing — stranding 8 fully-packed MLB jobs and failing
//     the send preflight's close-out doc gate); and
//   - can FAKE a doc from a mistyped 'general' file whose NAME happens to match.
// Rule, per row:
//   - a MEANINGFUL type (present and not 'general') is AUTHORITATIVE — the row
//     counts ONLY for that kind, never via filename.
//   - an ABSENT or 'general' type FALLS BACK to the filename heuristic (legacy
//     rows the skill has not re-typed yet).
// Fail-closed: an unknown/other type counts for no kind; empty docs -> all false.
function makesafeDocBooleans(docRows: any[] | null | undefined) {
  const rows = docRows || []
  const isFallbackType = (t: string) => t === '' || t === 'general'
  const nameOf = (d: any) => String(d?.file_name || '').toLowerCase()
  const typeOf = (d: any) => String(d?.type || '').toLowerCase()
  // SWMS filename fallback must NOT catch the make-safe job-number prefix
  // `SWMS-NNNNN`, which appears in most attached filenames. Match "swms" only
  // when it is not the job-number token (not immediately followed by hyphen+digit).
  const swmsInName = (name: string) => /swms(?![-\s]?\d)/i.test(name)
  // A row counts for `canonicalType` when its type IS that type, or when the row
  // is untyped/'general' and the filename fallback matches.
  const has = (canonicalType: string, nameMatches: (name: string) => boolean) =>
    rows.some((d: any) => {
      const t = typeOf(d)
      if (t === canonicalType) return true
      if (isFallbackType(t)) return nameMatches(nameOf(d))
      return false
    })
  return {
    // has_wo stays type-only (no legacy filename WO fallback) — never inferred
    // from a filename to avoid a stray 'general' file spoofing a work order.
    has_wo: rows.some((d: any) => typeOf(d) === 'work_order'),
    has_report_doc: has('makesafe_report', (n) => n.includes('make safe report')),
    has_invoice_doc: has('invoice', (n) => n.includes('invoice')),
    has_swms_doc: has('swms', (n) => swmsInName(n)),
  }
}
// Test-only export for the chip-truth doc-boolean derivation.
export const _makesafeDocBooleansForTest = makesafeDocBooleans

function docCreatedAtMs(doc: any): number {
  const t = doc?.created_at ? new Date(doc.created_at).getTime() : NaN
  return Number.isFinite(t) ? t : 0
}

function bestMakesafeDocByType(docRows: any[] | null | undefined, type: string, preferredId?: string | null) {
  const docs = (docRows || []).filter((d: any) => String(d?.type || '') === type)
  if (preferredId) {
    const preferred = docs.find((d: any) => d?.id === preferredId)
    if (preferred) return preferred
  }
  docs.sort((a: any, b: any) =>
    (Number(b?.version || 1) - Number(a?.version || 1)) ||
    (docCreatedAtMs(b) - docCreatedAtMs(a)) ||
    String(a?.file_name || '').localeCompare(String(b?.file_name || '')) ||
    String(a?.id || '').localeCompare(String(b?.id || ''))
  )
  return docs[0] || null
}

function selectMakesafePackDocs(docRows: any[] | null | undefined, pack?: any | null) {
  return {
    reportDoc: bestMakesafeDocByType(docRows, 'makesafe_report', pack?.report_doc_id || null),
    invoiceDoc: bestMakesafeDocByType(docRows, 'invoice', pack?.invoice_doc_id || null),
    swmsDoc: bestMakesafeDocByType(docRows, 'swms', pack?.swms_doc_id || null),
    workOrderDoc: bestMakesafeDocByType(docRows, 'work_order', null),
    serviceReportDoc:
      bestMakesafeDocByType(docRows, 'service_report', null) ||
      bestMakesafeDocByType(docRows, 'client_reference', null),
  }
}

const MAKESAFE_MLB_REPORT_RECIPIENT = 'makesafes@mlbuilders.com.au'

function knownMakesafeReportRecipient(args: {
  companySlug?: string | null
  companyName?: string | null
  externalRef?: string | null
}): string | null {
  const slug = String(args.companySlug || '').trim().toLowerCase()
  const name = String(args.companyName || '').trim().toLowerCase()
  const ref = String(args.externalRef || '').trim().toUpperCase()
  if (
    slug === 'mlb' ||
    /^MLB[-\s]?\d+/.test(ref) ||
    name === 'ml builders' ||
    name === 'major loss builders'
  ) return MAKESAFE_MLB_REPORT_RECIPIENT
  return null
}

function resolveMakesafeReportRecipient(args: {
  companyReportRecipient?: string | null
  companyInvoiceEmail?: string | null
  detailInvoiceEmail?: string | null
  companySlug?: string | null
  companyName?: string | null
  externalRef?: string | null
}): string | null {
  const configured = resolveRecipientEmail({
    companyReportRecipient: args.companyReportRecipient,
    companyInvoiceEmail: args.companyInvoiceEmail,
    detailInvoiceEmail: args.detailInvoiceEmail,
  })
  if (configured) return configured
  // Data backstop for known builder work-orders inboxes. This is deliberately
  // NOT a fallback to invoice_email or arbitrary job metadata: it preserves the
  // exact-recipient gate while letting legacy MLB rows send after the vetted
  // report-recipient address was split out of the wiki into Supabase.
  return knownMakesafeReportRecipient(args)
}

// The marker note the reporting skill writes on a successful make-safe pack send
// (send_makesafe_email.py) rides the job_events note stream as
// `MAKESAFE_PACK_SENT | <kind: main|photo> | ...`. The board only treats the
// `main` pack as a verified send; the `photo` follow-up does not count. The
// detector + writer live in makesafe_send_pack.ts (the single source of truth,
// imported above) — this file keeps NO private copy, so the two sides can never
// drift on the marker shape (the class of the SWMS-26832 false OUTSTANDING-TO-SEND).

// ── Paginated, id-chunked .in() reader (money-safety) ────────────────────────
// PostgREST caps a single response at 1000 rows. A make-safe job set can carry
// FAR more than 1000 job_events notes or job_documents rows across its history,
// so a single unpaginated .in() read SILENTLY TRUNCATES — dropping (e.g.) a
// MAKESAFE_PACK_SENT marker that happens to sort beyond row 1000. A dropped
// marker makes a SENT job look unsent and re-surface as ready-to-send. This
// helper paginates by ROWS via .range() AND chunks the id list by the shared
// encoded-URL budget (with a <=200 count backstop), keeping each URL under budget
// and walking past the first 1000 response rows. It merges the pages returned by
// those range reads; concurrent-writer OFFSET semantics are a separate concern.
//
// `applyFilters(query)` lets the caller add column predicates (e.g.
// .eq('event_type','note')); the helper owns the .in() chunking + .range()
// pagination so callers never re-implement the cap-safe loop. The shared reader
// labels and throws each query error instead of converting that failed read into
// an empty row set. A successful empty read still means no matching rows.
//
// STABLE ORDER (required, not optional): .range() is LIMIT/OFFSET, and Postgres
// guarantees NO ordering between two separate LIMIT/OFFSET queries unless the
// ORDER BY is a TOTAL order. Without a unique sort key a chunk that spills past
// one page can return a row on neither page — e.g. a job_documents `work_order`
// row silently dropped, so a card with its WO filed reads has_wo=false. The
// reader therefore always appends a unique tie-breaker column, AFTER any
// caller-supplied ordering (so the caller's sort stays primary and this only
// breaks its ties). Every table read through here has an `id` PK except the ones
// keyed BY the job id, listed below.
const MAKESAFE_JOB_KEYED_TABLES = new Set(['makesafe_job_details', 'makesafe_card_story'])
const MAKESAFE_PAGE_SIZE = 1000
async function _fetchAllByJobIdChunked(
  client: any,
  table: string,
  select: string,
  jobIds: string[],
  applyFilters?: (q: any) => any,
  idColumn = 'job_id',
): Promise<any[]> {
  // One row per job and no separate `id` column, so the join column IS the
  // unique key; ordering by `id` there would be a PostgREST 400.
  const stableKey = MAKESAFE_JOB_KEYED_TABLES.has(table) ? idColumn : 'id'
  return await _fetchAllRowsInChunks<any>(
    jobIds,
    (idBatch) => {
      let query = client.from(table).select(select).in(idColumn, idBatch)
      if (applyFilters) query = applyFilters(query)
      return query.order(stableKey, { ascending: true })
    },
    `${table} (${idColumn} join)`,
  )
}
// Test-only export for the cap-safe chunked reader (proves >1000-row pagination).
export const _fetchAllByJobIdChunkedForTest = _fetchAllByJobIdChunked

// Build a job_id -> boolean map of which jobs carry a verified MAKESAFE_PACK_SENT
// | main marker note (or the documented legacy bundled-coverage note — SWMS-26832
// — via the shared triage predicate, so a bundled-covered card no longer shows a
// false OUTSTANDING-TO-SEND). PAGINATED + id-chunked read over job_events for the
// candidate job set (was a single unpaginated .in() that truncated at 1000 rows
// and could drop a sent-marker beyond the cap, re-surfacing a SENT job). The
// EXISTS-style reduction happens in JS over EVERY returned note row. Triage flag
// only — see the guardrail in _deriveMakesafeBoardStage / enrichMakesafeBoardJob.
async function buildPackSentMap(client: any, jobIds: string[]): Promise<Record<string, boolean>> {
  const map: Record<string, boolean> = {}
  if (!jobIds.length) return map
  const events = await _fetchAllByJobIdChunked(
    client,
    'job_events',
    'job_id, event_type, detail_json',
    jobIds,
    // The shared reader owns the stable `id` tie-breaker that keeps .range()
    // pagination from skipping a row (which could drop a MAKESAFE_PACK_SENT
    // marker and re-surface a sent job). (Adversarial review #5.)
    (q) => q.eq('event_type', 'note'),
  )
  for (const ev of (events || [])) {
    if (ev?.job_id && _sendPackIsPackSentTriageEvent(ev)) map[ev.job_id] = true
  }
  return map
}
// Test-only export for the cap-safe pack-sent map builder.
export const _buildPackSentMapForTest = buildPackSentMap

function enrichMakesafeBoardJob(j: any, detail: any, assignments: any[] = [], report?: any, invoice?: any, docRows?: any[] | null, packSent?: boolean, pack?: MakesafeReportPackLike | null) {
  // Only engage the close-out doc gate when the caller actually loaded
  // job_documents. Callers that pass nothing keep the prior (ungated) behaviour.
  const docFlags = docRows !== undefined ? makesafeDocBooleans(docRows) : null
  // U2-S1: one shared cycle boundary for assignments/pack/sent/docs before stage
  // derivation. On reattend, unscoped prior-cycle evidence fails closed; invoice
  // remains visible but cannot close the current attendance.
  const scoped = projectCycleScopedEvidence({
    detail,
    reports: report ? [report] : [],
    assignments,
    docs: docRows || [],
    pack: pack || null,
    packSent: packSent === true,
    // Without a loaded pack-cycle junction row, reattend never trusts job-global
    // pack/sent as current-cycle readiness (fail closed). First attendance keeps
    // legacy packCycleBound=true so existing sent behaviour is preserved.
    packCycleBound: !hasReattendBoundary(detail),
    attendanceCycleId: detail?.attendance_cycle_id ?? null,
  })
  const scopedAssignments = scoped.assignments
  const scopedReport = scoped.serviceReport
  const scopedPack = scoped.pack
  const scopedPackSent = packSent === undefined ? undefined : scoped.packSent
  // Suppress closeout drivers (invoiceDone / sentClosed) on reattend while
  // still exposing invoice_status for commercial warning visibility.
  const invoiceForStage = scoped.allowCloseoutFromEvidence ? invoice : null
  const boardStage = deriveMakesafeBoardStage(
    j,
    detail,
    scopedAssignments,
    scopedReport,
    invoiceForStage,
    docFlags,
    scopedPackSent,
    scopedPack,
  )
  const age = makesafeAge(j.created_at, boardStage)
  const crew = makesafeCrew(scopedAssignments)
  const requestingCompany = detail?.requesting_company_name || detail?.makesafe_companies?.name || j.metadata?.requesting_company?.name || null
  const requestingCompanySlug = detail?.requesting_company_slug || detail?.makesafe_companies?.slug || j.metadata?.requesting_company?.slug || null
  // Surface which docs are still missing for the close-out gate. Only meaningful
  // once a job is otherwise ready to complete (an active invoice / complete
  // signal); we compute it whenever a docs map was supplied so the board can
  // explain why an invoiced job is still sitting in Report Ready (hard hold) or
  // has gone to completed with a soft docs_warning (verified-sent).
  let missingDocs: string[] = []
  let invoiceDone = false
  if (docFlags && scoped.allowCloseoutFromEvidence) {
    invoiceDone = hasActiveMakesafeInvoice(invoice) ||
      String(j?.status || '').toLowerCase() === 'invoiced' ||
      normalizeMakesafeSubstatus(detail?.substatus) === 'complete'
    if (invoiceDone) {
      // B4 (Wave 0): Western Building also requires SWMS (same rule as MLB).
      missingDocs = _makesafeMissingCloseoutDocs(docFlags, _isMakesafeMlbCompany(detail, j) || _isMakesafeWesternCompany(detail, j), !!(detail?.report_type))
    }
  }
  // Verified-sent reconciles the same way the board stage derives it: the
  // MAKESAFE_PACK_SENT marker is TRIAGE only and never softens the gate on its
  // own — it must coincide with an authorised invoice + substatus complete OR
  // the trustworthy gateSoftenSent signal (durable pack status / report_sent_at).
  const surf = _deriveMakesafeSurfacing(
    j,
    detail,
    scopedReport,
    invoiceForStage,
    docFlags,
    scopedPackSent,
    scopedPack,
  )
  const invoiceAuthorised = scoped.allowCloseoutFromEvidence &&
    hasActiveMakesafeInvoice(invoice) &&
    ['AUTHORISED', 'SUBMITTED', 'PAID'].includes(String(invoice?.status || '').toUpperCase())
  const verifiedSent = (scopedPackSent === true && invoiceAuthorised &&
    normalizeMakesafeSubstatus(detail?.substatus) === 'complete') || surf.gateSoftenSent

  // Split the missing-docs signal:
  //  - HARD docs_missing: the un-sent job is held in report_ready by the gate.
  //  - SOFT docs_warning: the verified-sent job completed, but a doc is still not
  //    attached — surfaced for the audit/board, NOT a hold. pack_sent is shown
  //    next to both so the model reconciles it against has_*_doc itself.
  const hardMissing = missingDocs.length > 0 && !verifiedSent
  const softWarning = missingDocs.length > 0 && verifiedSent
  // Doc flags for reattend: do not advertise prior-cycle report docs as present.
  const scopedDocFlags = docFlags
    ? {
      ...docFlags,
      has_report_doc: scoped.hasReportDoc || scoped.hasReportDocTyped,
    }
    : null
  return {
    ...j,
    makesafe_details: detail,
    substatus: normalizeMakesafeSubstatus(detail?.substatus) || null,
    board_stage: boardStage,
    board_label: MAKESAFE_BOARD_STAGE_LABELS[boardStage],
    intake_at: j.created_at,
    age_hours: age.age_hours,
    age_days: age.age_days,
    health: age.health,
    requesting_company: requestingCompany,
    requesting_company_name: requestingCompany,
    requesting_company_slug: requestingCompanySlug,
    builder_company: requestingCompany,
    external_ref: detail?.external_ref || j.metadata?.external_ref || null,
    // Re-attendance marker (M-C): reattend_count is the visit counter (0 = first
    // attendance only). is_reattend lets the board/reporting skill flag a card
    // that has been sent back to the trade on the SAME work order.
    reattend_count: Number(detail?.reattend_count || 0),
    is_reattend: Number(detail?.reattend_count || 0) > 0,
    last_reattend_at: detail?.last_reattend_at || null,
    cycle_number: scoped.cycle_number,
    // U2-S1 additive correlation-spine fields (non-breaking).
    attendance_cycle_id: scoped.attendance_cycle_id,
    cycle_attribution_flags: scoped.cycle_attribution_flags,
    readiness_revision: scoped.readiness_revision,
    commercial_warning: scoped.commercial_warning,
    // M-F cancel attribution (null on live cards; populated on Cancelled-column cards).
    cancel_reason: detail?.cancel_reason || null,
    cancel_note: detail?.cancel_note || null,
    cancelled_by: detail?.cancelled_by || null,
    cancelled_at: detail?.cancelled_at || null,
    assignments: scopedAssignments,
    assigned_trade: scopedAssignments.length > 0 ? scopedAssignments[0]?.users?.name || null : null,
    assigned_trade_phone: scopedAssignments.length > 0 ? scopedAssignments[0]?.users?.phone || null : null,
    crew_label: crew.crew_label,
    crew_members: crew.crew_members,
    report_status: makesafeReportStatus(boardStage, detail, scopedReport),
    invoice_status: makesafeInvoiceStatus(boardStage, invoice),
    // Server-only inputs for the computed status completion-time fallback. The
    // canonical projection consumes them but neither trade nor ops payloads expose
    // raw invoice records. On reattend, suppress closeout status for the engine.
    invoice_raw_status: scoped.allowCloseoutFromEvidence ? (invoice?.status || null) : null,
    invoice_date: scoped.allowCloseoutFromEvidence ? (invoice?.invoice_date || null) : null,
    invoice_created_at: scoped.allowCloseoutFromEvidence ? (invoice?.created_at || null) : null,
    // sent_to_builder (audit F5): the honest SENT-chip signal. TRUE only with a
    // real send record (pack-sent marker OR durable pack sent-status) — NEVER a
    // bare completed/archive column proxy. Completed cards with no send record
    // read as not-sent, not green. Fail-closed (unknown -> false).
    sent_to_builder: _makesafeSentToBuilder(scopedPackSent, scopedPack),
    // Canonical board seam: retain the non-financial report/pack facts so both
    // projections can consume the same server-owned row without re-deriving.
    report: scopedReport ? {
      status: scopedReport.status || null,
      submitted_at: scopedReport.submitted_at || scopedReport.created_at || null,
      created_at: scopedReport.created_at || null,
      cycle_number: scopedReport.cycle_number ?? scoped.cycle_number,
      attendance_cycle_id: scopedReport.attendance_cycle_id ?? scoped.attendance_cycle_id,
    } : null,
    report_pack: scopedPack ? {
      status: scopedPack.status || null,
      report_doc_id: scopedPack.report_doc_id || null,
      invoice_doc_id: scopedPack.invoice_doc_id || null,
      swms_doc_id: scopedPack.swms_doc_id || null,
      review_state: scopedPack.review_state || null,
      sent_at: scopedPack.sent_at || null,
    } : null,
    ...(scopedDocFlags || {}),
    // pack_sent is only meaningful (defined) when the caller loaded the marker.
    ...(packSent !== undefined ? { pack_sent: scopedPackSent === true } : {}),
    docs_missing: hardMissing,
    missing_docs: hardMissing ? missingDocs : undefined,
    docs_warning: softWarning,
    warning_docs: softWarning ? missingDocs : undefined,
  }
}
// Test-only export for the board-job enrichment (chip-truth wiring).
export const _enrichMakesafeBoardJobForTest = enrichMakesafeBoardJob

async function updateMakesafeSubstatus(client: any, body: any) {
  const { job_id, jobId, substatus } = body
  const jId = job_id || jobId
  if (!jId || !substatus) throw new Error('job_id and substatus required')
  const nextSubstatus = requireValidMakesafeSubstatus(substatus)

  const updates: Record<string, any> = {
    substatus: nextSubstatus,
    updated_at: new Date().toISOString(),
  }
  // Auto-set timestamps based on substatus transition
  const now = new Date().toISOString()
  if (nextSubstatus === 'company_contact_done') updates.company_contacted_at = now
  if (nextSubstatus === 'admin_to_send_report') updates.report_received_at = now
  if (nextSubstatus === 'ready_to_invoice') updates.report_sent_at = now
  if (nextSubstatus === 'complete') updates.invoice_ready_at = now

  const { data, error } = await client.from('makesafe_job_details')
    .update(updates)
    .eq('job_id', jId)
    .select()
    .single()
  if (error) throw error

  // ── M3d U2b: advancing a make-safe INTO a finished substatus closes the job's
  // still-open crew assignments (finished make-safe work -> assignment complete).
  // Non-finished substatuses map to null and no-op. Non-blocking helper.
  const _msCloseMode = _closeAsForMakesafeSubstatus(nextSubstatus)
  if (_msCloseMode) await closeOpenAssignmentsForJob(client, jId, _msCloseMode)

  // Log event (fire-and-forget). A PostgREST insert builder is thenable but has no `.catch`
  // method, so `.insert(...).catch(...)` throws "catch is not a function" AFTER the update above
  // has already committed — surfacing a spurious 500 on an otherwise-successful substatus change
  // (and silently defeating advanceMakesafeSubstatusOnInvoice). Convert to the .then().catch()
  // form (matches the established fire-and-forget idiom elsewhere in this file).
  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'makesafe_substatus_changed',
    detail_json: { substatus: nextSubstatus, changed_at: updates.updated_at },
  }).then(() => {}).catch(() => {})

  return { ok: true, details: data }
}
// Test-only export alias (mirrors the `_`-prefixed convention for the other make-safe helpers).
export const _updateMakesafeSubstatus = updateMakesafeSubstatus

// ── B4 (makesafe-report-types): "Report completed on builder portal" marker ──
// Dedicated action per the adversarial review (reuse of submitMakesafeReport was
// REJECTED — it requires photos, writes a job_service_reports row treated as a
// REAL report by board/audit paths, and would re-engage the close-out doc gate).
//
// This marker writes STATE + EVENT ONLY:
//   - makesafe_job_details.substatus = 'admin_to_send_report'
//   - makesafe_job_details.report_received_at = now()
//   - optional external_links MERGE (append, dedupe by url — never replace) of a
//     provided builder portal URL
//   - one job_events row
// It NEVER writes job_service_reports or job_documents, NEVER renders a report,
// NEVER creates/authorises an invoice, NEVER sends anything, NEVER notifies.
//
// Restriction is SERVER-DERIVED: the PERSISTED makesafe_job_details.report_type
// must be set. A client-supplied "invoice-only"/report-type flag is never
// trusted (reviewer BLOCKER: a normal make-safe must not be able to masquerade
// as a report-type and skip its real report).
//
// Idempotent: a job already at admin_to_send_report / ready_to_invoice /
// complete returns ok with zero writes and zero events (mirrors the
// allocate_job dedupe style) — and, importantly, a repeat call can never
// REGRESS a job that has already advanced past admin_to_send_report.
//
// NOT in ROUTINE_ALLOWED_ACTIONS: the routine key is refused by the dispatch
// default-deny; callable by the privileged api_key / trade JWT paths like the
// adjacent make-safe actions (no new authz machinery).
const _PORTAL_DONE_ALREADY_SUBSTATUSES = ['admin_to_send_report', 'ready_to_invoice', 'complete']

async function markMakesafePortalReportDone(client: any, body: any) {
  const jId = body.job_id || body.jobId
  if (!jId) throw new ApiError('job_id required', 400)

  // FIX 5a: same URL hygiene as builder-email link extraction (entity-decode,
  // trailing-punctuation strip, http(s)-only) — reuse cleanUrl, no parallel regex.
  const rawPortalUrl = String(body.portal_url || body.portalUrl || '').trim()
  const portalUrl = rawPortalUrl ? (_cleanBuilderLinkUrl(rawPortalUrl) || null) : null
  if (rawPortalUrl && !portalUrl) {
    throw new ApiError('portal_url must be a valid http(s) URL', 400)
  }

  // Append-only merge of the portal link into external_links (array of
  // {label, url, kind, source} objects — see makesafe_email_links.ts). Returns
  // null when there is nothing to write (no URL supplied, or already present by
  // case-insensitive URL); existing entries are always preserved.
  const mergePortalLink = (existing: any): any[] | null => {
    if (!portalUrl) return null
    const links = Array.isArray(existing) ? existing : []
    const urlKey = portalUrl.toLowerCase()
    if (links.some((l: any) => String(l?.url || '').toLowerCase() === urlKey)) return null
    return [
      ...links,
      { label: 'Builder Portal', url: portalUrl, kind: 'builder_portal', source: 'portal_done_marker' },
    ]
  }

  const { data: detail, error } = await client.from('makesafe_job_details')
    .select('job_id, substatus, report_type, external_links, report_received_at, cycle_number, portal_verified_at, portal_verified_cycle')
    .eq('job_id', jId)
    .maybeSingle()
  if (error) throw error
  if (!detail) {
    throw new ApiError('no makesafe_job_details row for this job — mark_makesafe_portal_report_done only applies to make-safe jobs', 404)
  }

  // Server-side report-type restriction (never a client-supplied flag). Two
  // PERSISTED server-read sources qualify:
  //   1. makesafe_job_details.report_type (intake approval writes this), or
  //   2. jobs.metadata.makesafe_job_family being a report family — BE-2: the
  //      createMakesafeJob path historically wrote the family on the jobs row
  //      but omitted report_type on the details insert, so a family-detected
  //      report job showed the portal button yet 409'd here. Family acceptance
  //      SELF-HEALS report_type onto the detail row (in the same update below)
  //      so send-time report-type logic sees it from then on.
  // Body-supplied report_type / is_report_type flags are IGNORED either way.
  let reportType = String(detail.report_type || '').trim() || null
  let healReportType: string | null = null
  if (!reportType) {
    const { data: jobRow } = await client.from('jobs')
      .select('id, metadata').eq('id', jId).maybeSingle()
    const persistedFamily = parseJsonObject(jobRow?.metadata)?.makesafe_job_family || null
    const familyType = _reportTypeForJobFamily(persistedFamily)
    if (familyType) {
      reportType = familyType
      healReportType = familyType
    }
  }
  if (!reportType) {
    throw new ApiError('mark_makesafe_portal_report_done is restricted to report-type jobs: neither makesafe_job_details.report_type nor a report-family jobs.metadata.makesafe_job_family is set for this job. A normal make-safe must submit its real report.', 409)
  }

  // W2-C (item 14): this marker is the SINGLE writer of a recorded portal-locked
  // verification. Calling it means a human/agent saw the portal form locked (or an
  // agent run captured locked=true via capture_portal_evidence.py). Stamp the
  // verification cycle-scoped so a later reopen/re-attend (cycle bump) forces a
  // fresh verification. The item-14 guard (substatus advance + draft invoice) then
  // requires portal_verified_cycle == cycle_number before automation may proceed.
  const currentCycle = Number(detail.cycle_number ?? 1)
  const alreadyVerifiedThisCycle = !!detail.portal_verified_at &&
    Number(detail.portal_verified_cycle) === currentCycle
  const nowIso = new Date().toISOString()
  const verifySignal = String(body.portal_signal || body.portalSignal || '').trim() ||
    'operator-confirmed portal locked'
  const verifyActor = body.operator_email || body.user_email || body.operator || 'portal_done_marker'
  // The verification stamp, applied on both the advance path and the graf-recovery
  // idempotent path (see below). Only written when not already verified this cycle.
  const verificationStamp = {
    portal_verified_at: nowIso,
    portal_verified_cycle: currentCycle,
    portal_verified_signal: verifySignal,
    portal_verified_by: verifyActor,
  }

  // Idempotent repeat: already marked (or already further along) → no substatus
  // change, no report_received_at, no event. FIX 4: a job can reach
  // admin_to_send_report via update_makesafe_substatus BEFORE the marker delivers
  // the portal URL — a supplied portal_url is still link-merged.
  // W2-C graf-recovery: a report-type card that "graf" (JARVIS/GHL) advanced to
  // admin_to_send_report / ready_to_invoice WITHOUT verification would otherwise be
  // permanently blocked by the item-14 guard (it can never advance/invoice, and
  // it's past the substatuses the main path writes). So the idempotent path ALSO
  // records the verification when this cycle is not yet verified — that is exactly
  // the "trade finally submitted; agent captured locked" recovery.
  const currentSubstatus = normalizeMakesafeSubstatus(detail.substatus)
  if (currentSubstatus && _PORTAL_DONE_ALREADY_SUBSTATUSES.includes(currentSubstatus)) {
    const idempotentLinks = mergePortalLink(detail.external_links)
    const idemUpdate: Record<string, any> = {}
    if (idempotentLinks) idemUpdate.external_links = idempotentLinks
    if (!alreadyVerifiedThisCycle) Object.assign(idemUpdate, verificationStamp)
    if (Object.keys(idemUpdate).length > 0) {
      idemUpdate.updated_at = nowIso
      const { error: linkErr } = await client.from('makesafe_job_details')
        .update(idemUpdate)
        .eq('job_id', jId)
      if (linkErr) throw linkErr
      if (!alreadyVerifiedThisCycle) {
        await client.from('job_events').insert({
          job_id: jId,
          event_type: 'makesafe_portal_verified',
          detail_json: {
            substatus: currentSubstatus,
            report_type: reportType,
            cycle_number: currentCycle,
            portal_verified_signal: verifySignal,
            builder_portal_url: portalUrl,
            recovery_of_pre_verified_advance: true,
            changed_at: nowIso,
            operator: verifyActor,
          },
        }).then(() => {}).catch(() => {})
      }
    }
    return {
      ok: true,
      already_done: true,
      substatus: currentSubstatus,
      portal_link_added: !!idempotentLinks,
      verification_recorded: !alreadyVerifiedThisCycle,
    }
  }

  const updates: Record<string, any> = {
    substatus: 'admin_to_send_report',
    report_received_at: nowIso,
    updated_at: nowIso,
    // W2-C: record the portal-locked verification for the current cycle.
    ...verificationStamp,
  }
  // BE-2 self-heal: accepted via the persisted job family -> persist the
  // report_type token on the detail row in this same state update.
  if (healReportType) updates.report_type = healReportType

  // external_links JSONB MERGE, not replace (reviewer MINOR: other links must
  // survive) — shared append-only merge, same rules as the idempotent path.
  const mergedLinks = mergePortalLink(detail.external_links)
  if (mergedLinks) updates.external_links = mergedLinks

  const { data: updated, error: upErr } = await client.from('makesafe_job_details')
    .update(updates)
    .eq('job_id', jId)
    .select()
    .single()
  if (upErr) throw upErr

  // ── M3d U2b: the portal-done marker advances the make-safe to a finished
  // substatus (admin_to_send_report) — close its still-open crew assignments.
  // Only the real-advance path reaches here (the idempotent repeat returned
  // above). Non-blocking.
  await closeOpenAssignmentsForJob(client, jId, 'complete')

  // One event row, fire-and-forget with the .then().catch() idiom (same as
  // updateMakesafeSubstatus — a PostgREST insert builder has no bare .catch).
  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'makesafe_portal_report_done',
    detail_json: {
      substatus: 'admin_to_send_report',
      report_on_portal: true,
      report_type: reportType,
      report_type_healed_from_family: !!healReportType,
      builder_portal_url: portalUrl,
      // W2-C: the recorded portal-locked verification (cycle-scoped).
      portal_verified: true,
      portal_verified_cycle: currentCycle,
      portal_verified_signal: verifySignal,
      changed_at: nowIso,
      operator: verifyActor,
    },
  }).then(() => {}).catch(() => {})

  return { ok: true, already_done: false, verification_recorded: true, details: updated }
}
// Test-only export alias (mirrors the `_`-prefixed convention above).
export const _markMakesafePortalReportDone = markMakesafePortalReportDone

// ════════════════════════════════════════════════════════════
// W2-C (M-E1) PORTAL-TRUTH GUARD + RECHECK QUEUE — items 7 + 14.
//
// Item 14 ("graf"): 8+ roof-report cards carried ready_to_invoice and/or auto-cut
// Xero DRAFT invoices while their primeeco portal form was never submitted. The
// invariant enforced here: no AUTOMATED path advances a report-type card to a
// report-complete substatus, or drafts its invoice, without a recorded
// portal-locked verification (mark_makesafe_portal_report_done) for the current
// cycle. Server-side lock detection is deliberately NOT built — the portal is a
// client-rendered SPA behind a private share-token login (feasibility proven
// 2026-07-07); the deterministic detector is the skill's capture_portal_evidence.py
// run agent-side, whose result the marker records.
// ════════════════════════════════════════════════════════════

// Load the portal-verification state for a make-safe job. isReportType mirrors the
// marker's rule (persisted report_type OR a report-family jobs.metadata), so a
// family-detected report card is guarded even before report_type self-heals.
async function loadMakesafePortalVerification(
  client: any,
  jobId: string,
): Promise<PortalVerificationState & { reportType: string | null }> {
  const { data: detail } = await client.from('makesafe_job_details')
    .select('report_type, cycle_number, portal_verified_at, portal_verified_cycle')
    .eq('job_id', jobId)
    .maybeSingle()
  let reportType = String(detail?.report_type || '').trim() || null
  if (!reportType) {
    const { data: jobRow } = await client.from('jobs')
      .select('metadata').eq('id', jobId).maybeSingle()
    const fam = parseJsonObject(jobRow?.metadata)?.makesafe_job_family || null
    reportType = _reportTypeForJobFamily(fam) || null
  }
  return {
    isReportType: !!reportType,
    reportType,
    currentCycle: Number(detail?.cycle_number ?? 1),
    verifiedAt: detail?.portal_verified_at ?? null,
    verifiedCycle: detail?.portal_verified_cycle ?? null,
  }
}
export const _loadMakesafePortalVerification = loadMakesafePortalVerification

// Item-14 guard for a substatus advance. No-op unless the job is a report-type
// card advancing to a report-complete substatus without a current-cycle
// verification. Called from the update_makesafe_substatus DISPATCH (the external
// entry point) — the internal advanceMakesafeSubstatusOnInvoice / send-pack
// patches call updateMakesafeSubstatus directly and so are intentionally NOT
// re-gated here (they only run post-send, after verification, mirroring the
// existing ROUTINE_FORBIDDEN_SUBSTATUSES dispatch guard).
async function assertMakesafePortalVerifiedForAdvance(
  client: any,
  jobId: string | null | undefined,
  nextSubstatus: string | null | undefined,
): Promise<void> {
  if (!jobId) return
  const norm = normalizeMakesafeSubstatus(nextSubstatus)
  const state = await loadMakesafePortalVerification(client, jobId)
  if (!_substatusAdvanceNeedsPortalVerification(norm, state.isReportType)) return
  if (_portalVerificationSatisfied(state)) return
  throw new ApiError(
    `portal-truth guard (item 14): cannot advance report-type job ${jobId} to '${norm}' — ` +
    `no portal-locked verification recorded for cycle ${state.currentCycle}. Confirm the ` +
    `builder portal is submitted (capture_portal_evidence.py -> locked) and record it via ` +
    `mark_makesafe_portal_report_done first.`,
    409,
  )
}
export const _assertMakesafePortalVerifiedForAdvance = assertMakesafePortalVerifiedForAdvance

// Item-14 guard for a DRAFT invoice. No-op for non-report make-safes (they draft
// normally). A report-type card must carry a current-cycle portal-locked
// verification before any draft invoice is cut — this is the direct kill for the
// "graf" class (DRAFT invoices minted before the portal report was submitted).
async function assertMakesafePortalVerifiedForDraftInvoice(
  client: any,
  jobId: string | null | undefined,
): Promise<void> {
  if (!jobId) return
  const state = await loadMakesafePortalVerification(client, jobId)
  if (!state.isReportType) return
  if (_portalVerificationSatisfied(state)) return
  throw new ApiError(
    `portal-truth guard (item 14): refusing to draft an invoice for report-type job ${jobId} — ` +
    `no portal-locked verification recorded for cycle ${state.currentCycle}. Verify the portal ` +
    `is submitted and record it via mark_makesafe_portal_report_done before invoicing.`,
    409,
  )
}
export const _assertMakesafePortalVerifiedForDraftInvoice = assertMakesafePortalVerifiedForDraftInvoice

// ════════════════════════════════════════════════════════════
// M-G FIX 1 — physical make-safe REPORT-IN guard
// ────────────────────────────────────────────────────────────
// The portal guard above owns report-type cards. Its physical twin: a NON-report
// make-safe must have OUR trade report filed in our system before it can advance
// to a report-complete substatus or have its invoice cut. Proof = a submitted/
// approved job_service_reports row for the CURRENT cycle OR a typed job_documents
// 'makesafe_report' row (the dual definition makesafeAudit uses at :11072/:10032).
// isReportType mirrors loadMakesafePortalVerification (report_type OR report-family
// metadata); isMakesafe = a makesafe_job_details row exists, so the guard no-ops
// for ordinary patio/fence invoicing.
async function loadMakesafeReportIn(
  client: any,
  jobId: string,
): Promise<ReportInState> {
  const { data: detail } = await client.from('makesafe_job_details')
    .select('report_type, cycle_number')
    .eq('job_id', jobId)
    .maybeSingle()
  const isMakesafe = !!detail
  let reportType = String(detail?.report_type || '').trim() || null
  if (isMakesafe && !reportType) {
    const { data: jobRow } = await client.from('jobs')
      .select('metadata').eq('id', jobId).maybeSingle()
    const fam = parseJsonObject(jobRow?.metadata)?.makesafe_job_family || null
    reportType = _reportTypeForJobFamily(fam) || null
  }
  const currentCycle = Number(detail?.cycle_number ?? 1)
  let hasCurrentCycleReport = false
  let hasReportDoc = false
  // Only physical make-safes need the report-in proof computed.
  if (isMakesafe && !reportType) {
    const { data: reports } = await client.from('job_service_reports')
      .select('status, cycle_number').eq('job_id', jobId)
    hasCurrentCycleReport = (reports || []).some((r: any) =>
      ['submitted', 'approved'].includes(String(r?.status || '').toLowerCase()) &&
      Number(r?.cycle_number ?? 1) === currentCycle)
    if (!hasCurrentCycleReport) {
      const { data: docs } = await client.from('job_documents')
        .select('type').eq('job_id', jobId)
      hasReportDoc = (docs || []).some(
        (d: any) => String(d?.type || '').toLowerCase() === 'makesafe_report')
    }
  }
  return { isMakesafe, isReportType: !!reportType, currentCycle, hasCurrentCycleReport, hasReportDoc }
}
export const _loadMakesafeReportIn = loadMakesafeReportIn

// Report-in guard for a substatus advance on a PHYSICAL make-safe. No-op for
// non-make-safe jobs, report-type cards (portal guard owns them), and pre-report
// substatuses. Called from the update_makesafe_substatus DISPATCH beside the
// item-14 portal guard.
async function assertMakesafeReportInForAdvance(
  client: any,
  jobId: string | null | undefined,
  nextSubstatus: string | null | undefined,
): Promise<void> {
  if (!jobId) return
  const norm = normalizeMakesafeSubstatus(nextSubstatus)
  const state = await loadMakesafeReportIn(client, jobId)
  if (!_substatusAdvanceNeedsReportIn(norm, state)) return
  if (_reportInSatisfied(state)) return
  throw new ApiError(
    `report-in guard (M-G FIX 1): cannot advance physical make-safe job ${jobId} to '${norm}' — ` +
    `no submitted/approved trade report for cycle ${state.currentCycle} and no typed makesafe_report ` +
    `document filed. File the crew report (submit_makesafe_report) before advancing.`,
    409,
  )
}
export const _assertMakesafeReportInForAdvance = assertMakesafeReportInForAdvance

// Report-in guard for INVOICE creation on a PHYSICAL make-safe, wired into
// createInvoice() (the reachable choke point every skill invoice passes through).
// No-op for non-make-safe jobs (ordinary invoicing) and report-type cards (the
// portal-verified guard covers those, also wired at createInvoice).
async function assertMakesafeReportInForInvoice(
  client: any,
  jobId: string | null | undefined,
): Promise<void> {
  if (!jobId) return
  const state = await loadMakesafeReportIn(client, jobId)
  if (!state.isMakesafe || state.isReportType) return
  if (_reportInSatisfied(state)) return
  throw new ApiError(
    `report-in guard (M-G FIX 1): refusing to invoice physical make-safe job ${jobId} — ` +
    `no submitted/approved trade report for cycle ${state.currentCycle} and no typed makesafe_report ` +
    `document filed. File the crew report (submit_makesafe_report) before invoicing.`,
    409,
  )
}
export const _assertMakesafeReportInForInvoice = assertMakesafeReportInForInvoice

// ── Honest fallback: portal-recheck queue (agent-side runs consume) ──
// Shared scan: active report-type cards with a portal link, not verified this
// cycle. The queue read formats them for capture_portal_evidence.py; the enqueue
// cron stamps a rate-limited recheck marker on them.
const PORTAL_RECHECK_DETAIL_SELECT =
  'job_id, external_ref, substatus, cycle_number, external_links, report_type, ' +
  'portal_verified_at, portal_verified_cycle, portal_recheck_requested_at, portal_recheck_count'

async function scanPortalRecheckCards(client: any): Promise<Array<{
  detail: any; job: any; currentCycle: number; portalLinks: ReturnType<typeof _extractPortalLinks>
}>> {
  const { data: details, error } = await client.from('makesafe_job_details')
    .select(PORTAL_RECHECK_DETAIL_SELECT)
    .not('report_type', 'is', null)
  if (error) throw error
  const rows = (details || []).filter((d: any) => d?.job_id)
  const jobIds = rows.map((d: any) => d.job_id)
  const jobs = await _fetchAllByJobIdChunked(
    client, 'jobs', 'id, job_number, status, site_address, client_name', jobIds,
    undefined, 'id',
  )
  const jobsById: Record<string, any> = {}
  for (const j of jobs) jobsById[j.id] = j
  const out: Array<{ detail: any; job: any; currentCycle: number; portalLinks: ReturnType<typeof _extractPortalLinks> }> = []
  for (const d of rows) {
    const job = jobsById[d.job_id]
    if (!job) continue
    const currentCycle = Number(d.cycle_number ?? 1)
    const eligible = _portalRecheckEligible({
      jobStatus: job.status,
      isReportType: true,
      externalLinks: d.external_links,
      currentCycle,
      verifiedAt: d.portal_verified_at ?? null,
      verifiedCycle: d.portal_verified_cycle ?? null,
    })
    if (!eligible) continue
    out.push({ detail: d, job, currentCycle, portalLinks: _extractPortalLinks(d.external_links) })
  }
  return out
}

// READ: the portal-recheck queue an agent run consumes. capture_links is shaped
// for capture_portal_evidence.py links.json ([{ref,url,role,label}]). No writes.
async function makesafePortalRecheckQueue(client: any, params: URLSearchParams) {
  const rawLimit = Number(params.get('limit') || '100')
  const limit = Number.isFinite(rawLimit) ? Math.max(1, Math.min(500, Math.floor(rawLimit))) : 100
  const cards = await scanPortalRecheckCards(client)
  const queue = cards.slice(0, limit).map(({ detail, job, currentCycle, portalLinks }) => {
    const ref = detail.external_ref || job.job_number || detail.job_id
    return {
      job_id: detail.job_id,
      job_number: job.job_number || null,
      external_ref: detail.external_ref || null,
      report_type: detail.report_type || null,
      substatus: normalizeMakesafeSubstatus(detail.substatus),
      cycle_number: currentCycle,
      site_address: job.site_address || null,
      portal_recheck_requested_at: detail.portal_recheck_requested_at || null,
      portal_recheck_count: Number(detail.portal_recheck_count || 0),
      portal_links: portalLinks,
      // Ready to write straight to capture_portal_evidence.py's links.json.
      capture_links: portalLinks.map((l) => ({ ref, url: l.url, role: l.role, label: l.label })),
    }
  })
  return { ok: true, count: cards.length, returned: queue.length, queue, generated_at: new Date().toISOString() }
}
export const _makesafePortalRecheckQueue = makesafePortalRecheckQueue

// WRITE (cron): stamp a rate-limited recheck marker on eligible cards so the queue
// carries a durable "recheck due since / how many times" signal even between agent
// runs. Idempotent within the cadence window (min_interval_hours, default 6).
// Stamps markers only — never advances substatus, never drafts, never sends.
async function makesafePortalRecheckEnqueue(client: any, body: any) {
  const rawInterval = Number(body?.min_interval_hours ?? body?.minIntervalHours ?? 6)
  const minIntervalHours = Number.isFinite(rawInterval) ? Math.max(0, Math.min(168, rawInterval)) : 6
  const minIntervalMs = minIntervalHours * 3600_000
  const rawMax = Number(body?.max_enqueue ?? body?.maxEnqueue ?? 200)
  const maxEnqueue = Number.isFinite(rawMax) ? Math.max(1, Math.min(500, Math.floor(rawMax))) : 200
  const now = Date.now()
  const nowIso = new Date(now).toISOString()
  const cards = await scanPortalRecheckCards(client)
  let enqueued = 0
  let skippedRecent = 0
  for (const { detail } of cards) {
    if (!_portalRecheckDue(detail.portal_recheck_requested_at, now, minIntervalMs)) {
      skippedRecent++
      continue
    }
    if (enqueued >= maxEnqueue) break
    const { error: upErr } = await client.from('makesafe_job_details').update({
      portal_recheck_requested_at: nowIso,
      portal_recheck_count: Number(detail.portal_recheck_count || 0) + 1,
      portal_recheck_reason: 'report-type card with portal link, not verified this cycle',
      updated_at: nowIso,
    }).eq('job_id', detail.job_id)
    if (upErr) throw upErr
    enqueued++
  }
  return {
    ok: true,
    enqueued,
    skipped_recent: skippedRecent,
    eligible: cards.length,
    min_interval_hours: minIntervalHours,
    enqueued_at: nowIso,
  }
}
export const _makesafePortalRecheckEnqueue = makesafePortalRecheckEnqueue

// ── Slice 3: dedicated make-safe pipeline ──
async function makesafePipeline(client: any, params: URLSearchParams, restrictJobIds?: string[]) {
  // The canonical board endpoint requests history=all so archived/cancelled
  // cards remain searchable. The legacy makesafe_pipeline response preserves its
  // existing active + 90-day-cancelled window until its consumer migrates.
  const allHistory = params.get('history') === 'all'
  // Optional server-authorised scope: when present, BOTH the active and cancelled
  // job queries are constrained to this id set so an allocated-only caller never
  // loads make-safes it can't see. A caller passing an empty set gets nothing.
  const restrict = Array.isArray(restrictJobIds) ? restrictJobIds : null
  if (restrict && restrict.length === 0) {
    return { columns: { new: [], allocated: [], trade_report_in: [], report_ready: [], completed: [], archive: [], cancelled: [] }, stage_labels: MAKESAFE_BOARD_STAGE_LABELS, total: 0 }
  }
  // T4 — full-history load. The old `.limit(200)` hid older completed/archived
  // make-safes from the archive column. Paginate the jobs query so the board
  // shows the COMPLETE history; T1's row-paginated dependent reads keep this
  // money-safe even as the job set (and its events/docs) grows past the cap.
  const jobsRaw: any[] = []
  {
    let offset = 0
    for (let guard = 0; guard < 1000; guard++) {
      let activeQuery = client.from('jobs')
        .select('id, job_number, type, status, client_name, client_phone, client_email, site_address, site_suburb, site_lat, site_lng, notes, metadata, created_at, updated_at, completed_at')
        .eq('type', 'makesafe')
        .not('status', 'in', allHistory ? '("cancelled","lost")' : '("cancelled","archived","lost")')
      if (restrict) activeQuery = activeQuery.in('id', restrict)
      const { data, error } = await activeQuery
        .order('created_at', { ascending: false })
        .order('id', { ascending: false })
        .range(offset, offset + MAKESAFE_PAGE_SIZE - 1)
      if (error) throw error
      const batch = data || []
      jobsRaw.push(...batch)
      if (batch.length < MAKESAFE_PAGE_SIZE) break
      offset += MAKESAFE_PAGE_SIZE
    }
  }
  const jobs = jobsRaw

  // Fetch all makesafe_job_details for these jobs
  const jobIds = (jobs || []).map((j: any) => j.id)
  let detailsMap: Record<string, any> = {}
  let reportMap: Record<string, any> = {}
  let invoiceMap: Record<string, any> = {}
  // docsMap: per-job array of job_documents rows, used for the close-out gate.
  let docsMap: Record<string, any[]> = {}
  // packMap: the durable makesafe_report_packs row (status + report_doc_id) used
  // by the shared surfacing predicate (drafted-not-sent / resume / sent-closed).
  let packMap: Record<string, MakesafeReportPackLike> = {}
  if (jobIds.length > 0) {
    // T1 — id-chunked (details list is one-per-job so row count ~= job count,
    // but chunk the .in() anyway so a multi-thousand-job set can't exceed the
    // PostgREST id-list/row caps).
    const details = await _fetchAllByJobIdChunked(
      client,
      'makesafe_job_details',
      '*, makesafe_companies:requesting_company_id(slug, name)',
      jobIds,
    )
    for (const d of (details || [])) {
      detailsMap[d.job_id] = d
    }

    // T1 — job_service_reports + xero_invoices + job_documents + report_packs.
    // job_documents ROW count can exceed 1000 across full history, so it MUST be
    // row-paginated (not just id-chunked). The chunked helper does both. We keep
    // the original predicate/order via applyFilters.
    const [reports, invoices, docs, packs] = await Promise.all([
      _fetchAllByJobIdChunked(
        client,
        'job_service_reports',
        'job_id, status, submitted_at, created_at, cycle_number, attendance_cycle_id, cycle_attribution',
        jobIds,
        (q) => q.neq('status', 'draft').order('submitted_at', { ascending: false }),
      ),
      _fetchAllByJobIdChunked(
        client,
        'xero_invoices',
        'job_id, status, invoice_type, invoice_number, reference, amount_due, total, invoice_date, created_at',
        jobIds,
        (q) => q.eq('invoice_type', 'ACCREC')
          .not('status', 'in', '("VOIDED","DELETED")')
          .order('invoice_date', { ascending: false }),
      ),
      _fetchAllByJobIdChunked(
        client,
        'job_documents',
        'job_id, type, file_name',
        jobIds,
      ),
      _fetchAllByJobIdChunked(
        client,
        'makesafe_report_packs',
        'job_id, pack_kind, status, report_doc_id, invoice_doc_id, swms_doc_id, sent_at',
        jobIds,
      ),
    ])
    reportMap = currentCycleReportMap(reports || [], detailsMap)
    invoiceMap = firstByJobId(invoices || [])
    for (const doc of (docs || [])) {
      if (!doc?.job_id) continue
      if (!docsMap[doc.job_id]) docsMap[doc.job_id] = []
      docsMap[doc.job_id].push(doc)
    }
    for (const p of (packs || [])) {
      if (!p?.job_id) continue
      // 'main' is the close-out pack; only the main pack drives board surfacing.
      if ((p.pack_kind || 'main') === 'main') packMap[p.job_id] = p
    }
  }

  // Fetch assignments for these jobs
  let assignMap: Record<string, any[]> = {}
  // packSentMap: which jobs carry a verified MAKESAFE_PACK_SENT | main marker.
  let packSentMap: Record<string, boolean> = {}
  if (jobIds.length > 0) {
    // T1 — assignments can be multiple per job; id-chunk + row-paginate.
    const assigns = await _fetchAllByJobIdChunked(
      client,
      'job_assignments',
      'id, job_id, user_id, scheduled_date, start_time, status, role, crew_name, travel_started_at, arrived_at, started_at, clocked_on_at, completed_at, attendance_cycle_id, cycle_attribution, users:user_id(id, name, phone)',
      jobIds,
      (q) => q.neq('status', 'cancelled').order('scheduled_date', { ascending: true }),
    )
    for (const a of (assigns || [])) {
      if (!assignMap[a.job_id]) assignMap[a.job_id] = []
      assignMap[a.job_id].push(a)
    }
    packSentMap = await buildPackSentMap(client, jobIds)
  }

  const columns: Record<string, any[]> = {
    new: [],
    allocated: [],
    trade_report_in: [],
    report_ready: [],
    completed: [],
    archive: [],
    // M-F: init the Cancelled bucket BEFORE any push (a missing key would throw on
    // columns[stage].push). Fed by the separate bounded query below.
    cancelled: [],
  }

  for (const j of (jobs || [])) {
    const enriched = enrichMakesafeBoardJob(j, detailsMap[j.id] || null, assignMap[j.id] || [], reportMap[j.id], invoiceMap[j.id], docsMap[j.id] || [], packSentMap[j.id] === true, packMap[j.id] || null)
    columns[enriched.board_stage].push(enriched)
  }

  // ── M-F: Cancelled column — a SEPARATE bounded query (D3 = last 90 days). ──
  // The main jobs query above KEEPS its `.not('status','in',("cancelled",...))`
  // exclusion, so cancelled jobs never touch `total` (which is the ACTIVE board
  // count). We fetch recently-cancelled make-safes independently and enrich them
  // (the derive short-circuits to `cancelled` on status, so no report/invoice/doc
  // dependent reads are needed — only the detail row for reason/who/date). Window
  // is bounded by jobs.updated_at (the cancel write stamps updated_at = the cancel
  // time) and cards are ordered by cancelled_at (fallback updated_at).
  const CANCELLED_WINDOW_DAYS = 90
  const cancelledSinceIso = new Date(Date.now() - CANCELLED_WINDOW_DAYS * 86_400_000).toISOString()
  const cancelledRaw: any[] = []
  {
    let offset = 0
    for (let guard = 0; guard < 100; guard++) {
      let cancelledQuery = client.from('jobs')
        .select('id, job_number, type, status, client_name, client_phone, client_email, site_address, site_suburb, site_lat, site_lng, notes, metadata, created_at, updated_at, completed_at')
        .eq('type', 'makesafe')
        .eq('status', 'cancelled')
      if (restrict) cancelledQuery = cancelledQuery.in('id', restrict)
      if (!allHistory) cancelledQuery = cancelledQuery.gte('updated_at', cancelledSinceIso)
      const { data, error } = await cancelledQuery
        .order('updated_at', { ascending: false })
        .order('id', { ascending: false })
        .range(offset, offset + MAKESAFE_PAGE_SIZE - 1)
      if (error) throw error
      const batch = data || []
      cancelledRaw.push(...batch)
      if (batch.length < MAKESAFE_PAGE_SIZE) break
      offset += MAKESAFE_PAGE_SIZE
    }
  }
  if (cancelledRaw.length > 0) {
    const cancelledIds = cancelledRaw.map((j: any) => j.id)
    const cancelledDetailsMap: Record<string, any> = {}
    const cds = await _fetchAllByJobIdChunked(
      client,
      'makesafe_job_details',
      '*, makesafe_companies:requesting_company_id(slug, name)',
      cancelledIds,
    )
    for (const d of (cds || [])) cancelledDetailsMap[d.job_id] = d
    // Retain assignment ownership on cancelled cards so the trade projection can
    // keep an allocated-only trade's OWN worked-then-cancelled make-safes in their
    // Archive. Cancelling a make-safe closes its open assignments to 'cancelled',
    // so we deliberately load every status here (not .neq('status','cancelled')).
    // tradeSafe still filters the per-card payload to the viewer's own assignment,
    // so another trade's allocation is never exposed.
    const cancelledAssignMap: Record<string, any[]> = {}
    const cancelledAssigns = await _fetchAllByJobIdChunked(
      client,
      'job_assignments',
      'id, job_id, user_id, scheduled_date, start_time, status, role, crew_name, travel_started_at, arrived_at, started_at, clocked_on_at, completed_at, users:user_id(id, name, phone)',
      cancelledIds,
      (q) => q.order('scheduled_date', { ascending: true }),
    )
    for (const a of (cancelledAssigns || [])) {
      if (!a?.job_id) continue
      if (!cancelledAssignMap[a.job_id]) cancelledAssignMap[a.job_id] = []
      cancelledAssignMap[a.job_id].push(a)
    }
    const cancelledCards = cancelledRaw.map((j: any) =>
      enrichMakesafeBoardJob(j, cancelledDetailsMap[j.id] || null, cancelledAssignMap[j.id] || [], undefined, undefined, undefined, undefined, null))
    // Order by cancelled_at (fallback updated_at) — freshest cancel first.
    cancelledCards.sort((a: any, b: any) =>
      String(b.cancelled_at || b.updated_at || '').localeCompare(String(a.cancelled_at || a.updated_at || '')))
    for (const card of cancelledCards) columns.cancelled.push(card)
  }

  // `total` reflects the ACTIVE board only (cancelled fed separately, above).
  return { columns, stage_labels: MAKESAFE_BOARD_STAGE_LABELS, total: (jobs || []).length }
}

// Server-owned scope for allocated-only trades: the make-safe job ids they are
// assigned to. Scoped to type='makesafe' at the source (inner join) so patio /
// fencing / other-type assignments never bloat the restrict IN-list passed into
// the canonical loader. Cancelled-status assignments are retained on purpose:
// cancelling a make-safe job closes its open assignments to 'cancelled', so a
// trade's own worked-then-cancelled make-safes would otherwise never load into
// their Archive. Returned ids feed the canonical loader so the full make-safe
// history is never loaded for a caller who can only see their own jobs.
// Row-paginated for the cap, and — like every other paginated make-safe read —
// terminated on a UNIQUE key. job_id is NOT unique in job_assignments (a job
// carries one row per assigned user/date), so ordering by job_id alone is not a
// total order: a trade whose make-safe assignment set spills past one page could
// have rows tied on job_id land on neither page, dropping that job id from the
// restrict set and vanishing their own card from their board. `id` is the PK.
async function loadMakesafeAssignedJobIds(client: any, userId: string): Promise<string[]> {
  const ids = new Set<string>()
  let offset = 0
  for (let guard = 0; guard < 100; guard++) {
    const { data, error } = await client.from('job_assignments')
      .select('job_id, jobs:job_id!inner(type)')
      .eq('user_id', userId)
      .eq('jobs.type', 'makesafe')
      .order('job_id', { ascending: true })
      .order('id', { ascending: true })
      .range(offset, offset + MAKESAFE_PAGE_SIZE - 1)
    if (error) throw error
    const batch = data || []
    for (const a of batch) if (a?.job_id) ids.add(a.job_id)
    if (batch.length < MAKESAFE_PAGE_SIZE) break
    offset += MAKESAFE_PAGE_SIZE
  }
  return Array.from(ids)
}
// Test-only export for the allocated-only trade scope read. It is the one
// .range()-paginated make-safe read the audit/board page-order guard cannot see
// (neither stub issues it), so it carries its own page-stability regression.
export const _loadMakesafeAssignedJobIdsForTest = loadMakesafeAssignedJobIds

// One audience-independent read. makesafePipeline remains the stage authority;
// this loader adds only presentation facts (contacts/actions, report photo count,
// notes and intake lineage) using cap-safe reads. Ops and trade projections are
// generated from the returned rows, never from separate queries or client logic.
async function loadCanonicalMakesafeBoard(
  client: any,
  opts?: { restrictToJobIds?: string[] },
): Promise<any[]> {
  const restrictToJobIds = opts?.restrictToJobIds
  // Allocated-only callers pass an explicit, already-authorised id set. An empty
  // set means "no visible make-safes" — return without loading any history.
  if (restrictToJobIds && restrictToJobIds.length === 0) return []
  const pipeline = await makesafePipeline(client, new URLSearchParams('history=all'), restrictToJobIds)
  const baseRows: any[] = []
  const seen = new Set<string>()
  for (const stage of MAKESAFE_BOARD_STAGES) {
    for (const row of (pipeline?.columns?.[stage] || [])) {
      if (!row?.id || seen.has(row.id)) continue
      seen.add(row.id)
      baseRows.push(row)
    }
  }
  const jobIds = baseRows.map((row) => row.id)
  if (jobIds.length === 0) return []

  // These reads are business-meaningful. _fetchAllByJobIdChunked checks every
  // PostgREST error and paginates every 1000 rows, so empty means genuinely empty.
  const [notes, photos, contacts] = await Promise.all([
    _fetchAllByJobIdChunked(
      client,
      'job_events',
      'id, job_id, user_id, event_type, detail_json, created_at, users:user_id(name)',
      jobIds,
      (q) => q.eq('event_type', 'note'),
    ),
    _fetchAllByJobIdChunked(
      client,
      'job_media',
      'id, job_id, type, phase',
      jobIds,
      (q) => q.eq('type', 'photo').eq('phase', 'completion'),
    ),
    _fetchAllByJobIdChunked(
      client,
      'job_contacts',
      'job_id, client_name, client_phone, is_primary, contact_label, status',
      jobIds,
      (q) => q.eq('status', 'active'),
    ),
  ])

  // The status-holds table is an additive shadow overlay that can legitimately lag
  // the edge function in a preview database. Holds only decorate the board with
  // reason-coded badges, so tolerate a missing table and log loudly rather than
  // failing the entire operator-facing make-safe board on that overlay.
  let holds: any[] = []
  try {
    holds = await _fetchAllByJobIdChunked(
      client,
      'makesafe_status_holds',
      'id, job_id, cycle_number, reason_code, note, held_by, created_at, lifted_at, attendance_cycle_id, cycle_attribution',
      jobIds,
      (q) => q.order('created_at', { ascending: false }),
    )
  } catch (error) {
    console.error('[ops-api] makesafe_board status holds read unavailable:', (error as Error).message)
  }

  // The intake-case migration is shadow-first and can legitimately lag an edge
  // function in a preview database. Claim/ref grouping below remains canonical;
  // log loudly rather than failing the entire operational board on that additive
  // lineage overlay.
  let intakeCases: any[] = []
  try {
    intakeCases = await _fetchAllByJobIdChunked(
      client,
      'makesafe_intake_cases',
      'id, job_id, lineage_id, parent_case_id, parent_relation, cycle, updated_at',
      jobIds,
      (q) => q.order('cycle', { ascending: false }),
    )
  } catch (error) {
    console.error('[ops-api] makesafe_board intake lineage read unavailable:', (error as Error).message)
  }

  // The cutover ledger is append-only and display-only. Migration-first deploy
  // remains required, but a missing preview table must not take down the board.
  let statusApplications: any[] = []
  try {
    statusApplications = await _fetchAllByJobIdChunked(
      client,
      'makesafe_board_status_current',
      'id, run_key, job_id, source_status, before_status, after_status, evidence_ref, applied_by, applied_at',
      jobIds,
      (q) => q.order('applied_at', { ascending: false }),
    )
  } catch (error) {
    console.error('[ops-api] makesafe_board status application read unavailable:', (error as Error).message)
  }

  const notesByJobId: Record<string, any[]> = {}
  for (const note of notes) {
    const body = note?.detail_json?.text ?? note?.detail_json?.note ?? ''
    if (!note?.job_id || noteIsSystemMarker(body)) continue
    if (!notesByJobId[note.job_id]) notesByJobId[note.job_id] = []
    notesByJobId[note.job_id].push(note)
  }
  const photoCountByJobId: Record<string, number> = {}
  for (const photo of photos) {
    if (photo?.job_id) photoCountByJobId[photo.job_id] = (photoCountByJobId[photo.job_id] || 0) + 1
  }
  const contactsByJobId: Record<string, any[]> = {}
  for (const contact of contacts) {
    if (!contact?.job_id) continue
    if (!contactsByJobId[contact.job_id]) contactsByJobId[contact.job_id] = []
    contactsByJobId[contact.job_id].push(contact)
  }
  const intakeCaseByJobId: Record<string, any> = {}
  for (const intakeCase of intakeCases) {
    if (intakeCase?.job_id && !intakeCaseByJobId[intakeCase.job_id]) {
      intakeCaseByJobId[intakeCase.job_id] = intakeCase
    }
  }
  const statusApplicationsByJobId: Record<string, any> = {}
  for (const application of statusApplications) {
    if (application?.job_id && !statusApplicationsByJobId[application.job_id]) {
      statusApplicationsByJobId[application.job_id] = application
    }
  }
  const holdsByJobId: Record<string, any> = {}
  // Match the computed-status read model's cycle authority (detail-first) so holds
  // recorded on cycle>1 attach as badges even when the base pipeline row carries no
  // top-level cycle_number: read_model uses detail?.cycle_number ?? base?.cycle_number.
  const cycleByJobId = new Map(baseRows.map((row) => [
    row.id,
    Number(row?.makesafe_details?.cycle_number ?? row?.cycle_number ?? 1),
  ]))
  for (const hold of holds) {
    if (hold?.lifted_at) continue
    const currentCycle = cycleByJobId.get(hold?.job_id) || 1
    if (hold?.job_id && Number(hold?.cycle_number || 1) === currentCycle && !holdsByJobId[hold.job_id]) {
      holdsByJobId[hold.job_id] = hold
    }
  }

  return buildCanonicalMakesafeRows(baseRows, {
    notesByJobId,
    photoCountByJobId,
    contactsByJobId,
    intakeCaseByJobId,
    holdsByJobId,
    statusApplicationsByJobId,
  })
}

function makesafeStatusReviewCards(rows: any[]) {
  return (rows || []).map((row: any) => ({
    id: row.id,
    job_number: row.job_number || null,
    substatus: row.substatus || null,
    // The canonical stage includes only captain-applied display transitions. Raw
    // substatus remains available separately and is never rewritten by cutover.
    declared_status: row.canonical_stage || 'new',
    computation: {
      status: row.computed_status,
      job_type: row.computed_status_job_type,
      reasons: row.computed_status_reasons || [],
      missing: row.computed_status_missing || [],
      hold: row.computed_status_hold || null,
    },
    report_received_at: row.computed_status_evidence?.report_received_at || null,
    has_submitted_service_report:
      row.computed_status_evidence?.has_submitted_service_report === true,
    has_current_portal_capture:
      row.computed_status_evidence?.has_current_portal_capture === true,
  }))
}

function makesafeStatusDisagreementsFromRows(rows: any[]) {
  return buildMakesafeDisagreementList(makesafeStatusReviewCards(rows))
}

function makesafeStatusCanaryFromRows(rows: any[]) {
  return checkMakesafeStatusCanary(makesafeStatusReviewCards(rows))
}

async function persistMakesafeStatusShadow(client: any, rows: any[]): Promise<{
  ok: boolean
  refreshed: number
  error?: string
}> {
  if (!client || typeof client.rpc !== 'function') {
    return { ok: false, refreshed: 0, error: 'Supabase RPC client unavailable' }
  }
  const payload = (rows || []).map((row: any) => ({
    job_id: row.id,
    computed_status: row.computed_status,
    reasons: row.computed_status_reasons || [],
    missing: row.computed_status_missing || [],
    computed_at: row.computed_status_at || new Date().toISOString(),
  }))
  if (payload.length === 0) return { ok: true, refreshed: 0 }
  const { data, error } = await client.rpc('refresh_makesafe_status_shadow', {
    p_rows: payload,
  })
  if (error) {
    const message = error?.message || String(error)
    console.error('[ops-api] makesafe status shadow refresh failed:', message)
    return { ok: false, refreshed: 0, error: message }
  }
  return { ok: true, refreshed: Number(data || 0) }
}

async function persistMakesafeStatusApplications(
  client: any,
  args: {
    runKey: string
    appliedBy: string
    evidenceRef: string
    transitions: MakesafeStatusApplication[]
  },
): Promise<{ ok: boolean; applied: any[]; error?: string }> {
  if (!client || typeof client.rpc !== 'function') {
    return { ok: false, applied: [], error: 'Supabase RPC client unavailable' }
  }
  if (args.transitions.length === 0) return { ok: true, applied: [] }
  const { data, error } = await client.rpc('apply_makesafe_board_status', {
    p_run_key: args.runKey,
    p_applied_by: args.appliedBy,
    p_evidence_ref: args.evidenceRef,
    p_rows: args.transitions,
  })
  if (error) {
    const message = error?.message || String(error)
    console.error('[ops-api] makesafe status application failed:', message)
    return { ok: false, applied: [], error: message }
  }
  const applied = Array.isArray(data) ? data : (data?.applied || [])
  return { ok: true, applied }
}

async function loadMakesafeStatusApplicationRun(client: any, runKey: string): Promise<any[]> {
  const { data, error } = await client.from('makesafe_board_status_applications')
    .select('id, run_key, job_id, job_number, source_status, before_status, after_status, computed_at, computed_reasons, computed_missing, evidence_ref, applied_by, applied_at')
    .eq('run_key', runKey)
    .order('id', { ascending: true })
  if (error) throw error
  return data || []
}

// Test-only exports. Production routes call the same functions.
export const _makesafePipelineForTest = makesafePipeline
export const _loadCanonicalMakesafeBoardForTest = loadCanonicalMakesafeBoard
export const _makesafeStatusDisagreementsFromRowsForTest = makesafeStatusDisagreementsFromRows
export const _makesafeStatusCanaryFromRowsForTest = makesafeStatusCanaryFromRows
export const _persistMakesafeStatusShadowForTest = persistMakesafeStatusShadow
export const _persistMakesafeStatusApplicationsForTest = persistMakesafeStatusApplications

// Test-only export for the close-out doc-attach path (typed + idempotent).
export const _attachMakesafeDocumentForTest = attachMakesafeDocument

// Test-only exports for the item-11 live-Graph attachment fallback.
export const _pickGraphAttachmentForTest = pickGraphAttachment
export const _resolveMailboxCandidatesForTest = resolveMailboxCandidates
export const _attachEmailAttachmentToJobForTest = attachEmailAttachmentToJob

// ── sw_makesafe_audit: compact pipeline reader (jobs[] + known_refs[]) ──
// Retires the per-job sw_job_detail loop in the intake-audit + close-out-audit
// skills. One server-side aggregate; the skills drill sw_job_detail only into a
// single already-flagged job. See harness/.../sw-makesafe-audit-tool-spec.md.

// Reference normaliser — mirrors the Python invoice_utils._norm (strip, lower,
// drop all whitespace) AND drops hyphens so spaced/dashed/compact variants of the
// SAME ref collapse to one key: 'AJBR 67713' == 'AJBR-67713' == 'AJBR67713' ->
// 'ajbr67713' (BLOCKER B pt2). This keeps the DRAFT idempotency key + the dup-scan
// robust to hyphen/space variants of the same external_ref. The >=5-char substring
// tier still works on this normalised (hyphen/space-free) form.
function _makesafeNormRef(s: any): string {
  return String(s ?? '').trim().toLowerCase().replace(/[\s-]+/g, '')
}

// Normalise every invoice row's reference ONCE per read, index-aligned with
// invoiceRows. The whole-board audit resolves invoices for EVERY job against
// EVERY ACCREC invoice, so normalising inside the per-job loop costs
// jobs x invoices regex passes (500 x ~3000 = 1.5M) on an edge function with a
// ~2s CPU budget — and makesafeStoryRecompute re-runs the whole audit. Hoisting
// it leaves only cheap string compares in the loop; the resolver still
// normalises on demand when no prepared list is supplied, so every caller
// (including the tests) behaves identically either way.
function _prepareMakesafeInvoiceRefs(invoiceRows: any[]): string[] {
  return (invoiceRows || []).map((inv: any) => _makesafeNormRef(inv?.reference))
}

// AUDIT-MODE invoice resolution (item 2.4). Returns the FULL mapped invoice list
// for a job INCLUDING VOIDED/DELETED, each row tagged with status + match_tier,
// so the audit's duplicate + void-history checks can fire (Erskine / Sorrento).
// This is the OPPOSITE of the create-invoice dup-guard, which deliberately
// collapses to a single live winner (fail-safe). Tiers, highest-trust first:
//   job_id           — invoice.job_id === job.id
//   reference        — norm(invoice.reference) === norm(external_ref)
//   reference_substr — norm(external_ref) is a substring of norm(reference)
//                      (>=5 chars so short tokens can't false-match)
// A given invoice is tagged with the FIRST (highest) tier it matches; an invoice
// matching no tier for this job is not returned for this job.
function _resolveMakesafeJobInvoices(
  invoiceRows: any[],
  jobId: string | null | undefined,
  externalRef: string | null | undefined,
  normalizedRefs?: string[],
): Array<{ status: string | null; invoice_number: string | null; reference: string | null; match_tier: string; voided: boolean }> {
  const nref = _makesafeNormRef(externalRef)
  const out: Array<any> = []
  const rows = invoiceRows || []
  for (let i = 0; i < rows.length; i++) {
    const inv = rows[i]
    let tier: string | null = null
    if (jobId && inv?.job_id === jobId) {
      tier = 'job_id'
    } else if (nref) {
      const invRef = normalizedRefs?.[i] ?? _makesafeNormRef(inv?.reference)
      if (invRef && invRef === nref) tier = 'reference'
      else if (nref.length >= 5 && invRef && invRef.includes(nref)) tier = 'reference_substring'
    }
    if (!tier) continue
    const status = inv?.status != null ? String(inv.status) : null
    out.push({
      status,
      invoice_number: inv?.invoice_number ?? null,
      reference: inv?.reference ?? null,
      match_tier: tier,
      voided: ['VOIDED', 'DELETED'].includes(String(status || '').toUpperCase()),
    })
  }
  return out
}
