// Consumer contract (uncapped jobs[] + required-query error handling) is owned
// by docs/makesafe-board-read-model-v1.md, "Audit read".
async function makesafeAudit(client: any, params: URLSearchParams) {
  const since = params.get('since')
  const statusFilter = params.get('status')
  const companyFilter = params.get('company')

  // ── jobs[] ── one compact row per make-safe job ──
  // Paginate the jobs matching the request instead of silently capping at 500.
  // This removes the fixed row limit; it does not claim broader U2 state-model
  // parity or turn a successful empty dependent read into an error.
  const jobs = await _fetchAllRows<any>(() => {
    let query = client.from('jobs')
      .select('id, job_number, type, status, site_lat, site_lng, metadata, created_at')
      .eq('type', 'makesafe')
      .order('created_at', { ascending: false })
      .order('id', { ascending: false })
    if (since) query = query.gte('created_at', since)
    if (statusFilter) query = query.eq('status', statusFilter)
    return query
  }, 'makesafe_audit jobs')

  const jobIds = (jobs || []).map((j: any) => j.id)
  let detailsMap: Record<string, any> = {}
  let docsMap: Record<string, any[]> = {}
  let reportSet: Set<string> = new Set()
  let invoiceRows: any[] = []
  // GAP-4 — pack_sent (notes-based MAKESAFE_PACK_SENT marker, via buildPackSentMap)
  // and pipeline_item_sent_status (the sync-system verdict from pipeline_items,
  // joined on the target job) surfaced on each audit jobs[] row.
  let packSentMap: Record<string, boolean> = {}
  let pipelineSentStatusMap: Record<string, string> = {}
  if (jobIds.length > 0) {
    // Every job-scoped join uses the shared encoded-URL-budgeted, row-paginated
    // reader. A reported query error rejects Promise.all and therefore the whole
    // request instead of being mapped to empty facts. A successful empty result
    // remains an empty result; this path adds no per-job completeness checksum.
    const [details, docs, reports, loadedInvoiceRows, psMap, pisMap] = await Promise.all([
      _fetchAllByJobIdChunked(
        client,
        'makesafe_job_details',
        // reattend_count + cycle_number feed currentCycleReportMap so a prior
        // visit's report cannot falsify current-cycle has_report_record /
        // pack_effectively_sent on a reattendance card (board already gates this).
        'job_id, external_ref, requesting_company_name, requesting_company_slug, substatus, reattend_count, cycle_number, makesafe_companies:requesting_company_id(slug, name)',
        jobIds,
      ),
      _fetchAllByJobIdChunked(
        client,
        'job_documents',
        'job_id, type, file_name',
        jobIds,
      ),
      _fetchAllByJobIdChunked(
        client,
        'job_service_reports',
        // cycle_number is required for the current-cycle report filter below.
        'job_id, status, cycle_number',
        jobIds,
        (q) => q.neq('status', 'draft'),
      ),
      // AUDIT path: pull ALL ACCREC invoices INCLUDING VOIDED/DELETED (item
      // 2.4) so duplicate, reference-only and void-history checks can fire.
      // Paginate this required global join too and reject its query errors.
      // invoice_date is DAY-granularity and non-unique, so it cannot order
      // .range() pages on its own — dozens of invoices share a date and a tie
      // straddling row 1000 could land on neither page, blanking a real
      // invoice_status. `id` (the PK) breaks the tie without disturbing the
      // newest-first contract _resolveLiveMakesafeInvoice relies on.
      _fetchAllRows<any>(
        () => client.from('xero_invoices')
          .select('job_id, status, invoice_number, reference, invoice_type, invoice_date')
          .eq('invoice_type', 'ACCREC')
          .order('invoice_date', { ascending: false })
          .order('id', { ascending: false }),
        'makesafe_audit xero_invoices',
      ),
      // GAP-4 — reuse the existing buildPackSentMap (batch job_events query).
      buildPackSentMap(client, jobIds),
      // GAP-4 — sync-system sent verdict per job (pipeline_items.sent_status).
      _buildPipelineSentStatusMap(client, jobIds),
    ])
    for (const d of details) detailsMap[d.job_id] = d
    for (const doc of docs) {
      if (!doc?.job_id) continue
      if (!docsMap[doc.job_id]) docsMap[doc.job_id] = []
      docsMap[doc.job_id].push(doc)
    }
    // Same cycle boundary as the board path (currentCycleReportMap): when
    // reattend_count > 0 only the current cycle's non-draft service report counts.
    // Legacy / reopen-only cards (reattend_count 0 or absent) keep any-cycle
    // first-match behaviour so single-visit rows stay byte-compatible.
    const currentReports = currentCycleReportMap(reports || [], detailsMap)
    for (const jobId of Object.keys(currentReports)) reportSet.add(jobId)
    invoiceRows = loadedInvoiceRows
    packSentMap = {}
    for (const job of (jobs || [])) {
      if (isLegacyMakesafeCard(detailsMap[job.id])) packSentMap[job.id] = psMap[job.id] === true
    }
    pipelineSentStatusMap = pisMap
  }

  // One normalisation pass over the whole invoice read, reused by every job's
  // resolution below (the per-job loop then does string compares only).
  const invoiceRefKeys = _prepareMakesafeInvoiceRefs(invoiceRows)

  // Annotated `any[]` because the paginated job read now yields a concretely
  // typed array: without this the story_* fields attached further down (after
  // the makesafe_job_story join) would not type-check against the inferred
  // object literal shape. Runtime shape is unchanged.
  let jobRows: any[] = (jobs || []).map((j: any) => {
    const detail = detailsMap[j.id] || null
    const docFlags = makesafeDocBooleans(docsMap[j.id] || [])
    // A filed close-out report can show up two ways: (a) a job_service_reports
    // row (legacy / submit_makesafe_report path), or (b) a typed
    // job_documents row of type 'makesafe_report' (the M3 attach path used by
    // the reporting/close-out skill via attach_makesafe_document). The skill
    // files the report as a typed doc and never writes a job_service_reports
    // row, so the audit must count the typed doc too — otherwise every report
    // the skill produces reads as missing. See sw-makesafe-audit-tool-spec.md.
    const hasReportDocTyped = isLegacyMakesafeCard(detail) && (docsMap[j.id] || []).some(
      (d: any) => String(d?.type || '').toLowerCase() === 'makesafe_report',
    )
    const company = detail?.requesting_company_name || detail?.makesafe_companies?.name ||
      j.metadata?.requesting_company?.name || null
    const externalRef = detail?.external_ref || j.metadata?.external_ref || null
    const rawSub = detail?.substatus ?? null
    // W2-D (invoice-bleed fix) — resolve THIS card's invoice fields STRICTLY by
    // job_id. _resolveMakesafeJobInvoices still tags every match's tier; we split
    // its output so ref/substring-matched rows (a SIBLING card sharing external_ref,
    // or an invoice whose job_id link is missing) can NEVER masquerade as this
    // card's own invoice. Proven bleed: MLB-25387 / MLB-25911 / MLB-26072 (sibling
    // INV-0844) and MLB-26122 (sibling PAID INV-0851 shown on an uninvoiced roof-
    // report card). Two cards sharing a builder ref used to both inherit the one
    // invoice's status/number, so an uninvoiced card read as PAID at a glance and
    // batch tooling built on this compact read described invoice state wrongly.
    const allMatched = _resolveMakesafeJobInvoices(invoiceRows, j.id, externalRef, invoiceRefKeys)
    // Own = job_id-linked only (incl. voided/deleted for void-history, item 2.4).
    // Drives every scalar invoice field below.
    const invoices = allMatched.filter((i) => i.match_tier === 'job_id')
    // Ref/substring-matched but NOT job_id-linked. Surfaced under an explicitly
    // named field (sibling_invoices) so no consumer mistakes it for the card's own
    // — fails OBVIOUS, not silent: an auditor still SEES an invoice exists under
    // the shared ref, but it never contaminates invoice_status / invoice_no /
    // live_invoice_*. Empty in the common case; non-empty flags a genuine sibling
    // claim or a broken job_id link.
    const siblingInvoices = allMatched.filter((i) => i.match_tier !== 'job_id')
    // invoice_status / invoice_no = comma-joined DISTINCT over the JOB-LINKED set
    // (a duplicate on THIS job still SHOWS; a sibling's invoice never does). Both
    // null when this card has no job_id-linked invoice — uninvoiced reads as
    // uninvoiced.
    const distinctStatuses = Array.from(new Set(invoices.map((i) => i.status).filter(Boolean)))
    const distinctNumbers = Array.from(new Set(invoices.map((i) => i.invoice_number).filter(Boolean)))
    // M3 marker-integrity: the SINGLE current LIVE invoice, resolved from the
    // job-linked set only, preferring PAID/AUTHORISED over any non-void status.
    // Voided/replaced numbers (and any baked sent-marker text) never win — this is
    // the one downstream should read as "the invoice we actually sent".
    const liveInvoice = _resolveLiveMakesafeInvoice(invoices)
    // M-G FIX 5 — pack_effectively_sent: retire the stale "outstanding-to-send" false
    // positive on a job that is already PAID with its docs filed (AJBR-67205 class), WITHOUT
    // overwriting pack_sent (the close-out doc-gate relies on the raw marker). A PAID invoice
    // is reachable without our pack ever being emailed (Xero collects on any authorised
    // invoice; deposits rank PAID), so the skill treats this as a DISTINCT "paid-filed —
    // confirm sent" verdict, never a silent "sent". Report side uses the audit's dual
    // definition (typed makesafe_report doc OR a job_service_reports row). Deposit invoices
    // (ACCRECDEPOSIT) cannot false-trigger this: the invoice query above is ACCREC-only, so a
    // paid deposit never enters `invoices` and can never resolve as the live PAID invoice here.
    const packEffectivelySent = isLegacyMakesafeCard(detail) && (
      (packSentMap[j.id] === true) ||
      (String(liveInvoice?.status || '').toUpperCase() === 'PAID' &&
        (docFlags.has_report_doc || hasReportDocTyped || reportSet.has(j.id)) &&
        docFlags.has_invoice_doc)
    )
    const hasReportDoc = isLegacyMakesafeCard(detail) && docFlags.has_report_doc
    return {
      job_id: j.id,
      job_number: j.job_number,
      external_ref: externalRef,
      company,
      job_status: j.status,
      substatus: rawSub, // RAW, not normalised — board-truth check needs to SEE the stale alias
      substatus_legacy: rawSub === 'pending_allocation',
      geocoded: j.site_lat != null && j.site_lng != null,
      has_wo: docFlags.has_wo,
      has_report_doc: hasReportDoc,
      has_invoice_doc: docFlags.has_invoice_doc,
      has_swms_doc: docFlags.has_swms_doc,
      has_report_record: reportSet.has(j.id) || hasReportDocTyped,
      invoice_status: distinctStatuses.length ? distinctStatuses.join(',') : null,
      invoice_no: distinctNumbers.length ? distinctNumbers.join(',') : null,
      // M3 — current LIVE (non-voided) invoice resolved by job link, AUTHORISED-first.
      live_invoice_no: liveInvoice?.invoice_number ?? null,
      live_invoice_status: liveInvoice?.status ?? null,
      // GAP-4 — notes-based pack-sent marker (triage) + the sync-system verdict.
      pack_sent: isLegacyMakesafeCard(detail) && packSentMap[j.id] === true,
      // M-G FIX 5 — pack_sent OR (PAID + report doc + invoice doc). Consumed by the
      // skill's outstanding verdict() to retire a stale "outstanding" on a paid+filed job
      // as a DISTINCT "paid-filed — confirm sent" state (not folded into "sent").
      pack_effectively_sent: packEffectivelySent,
      pipeline_item_sent_status: pipelineSentStatusMap[j.id] ?? null,
      // Per-row mapped invoice list — JOB-LINKED only (incl. voided/deleted for
      // void-history, item 2.4). Ref-matched-but-not-job-linked rows are moved to
      // sibling_invoices so this board-truth read never bleeds a sibling's invoice
      // onto an uninvoiced card (W2-D).
      invoices,
      // Ref/substring-matched invoices NOT linked to this job by job_id (empty in
      // the common case). Explicitly separate so no consumer treats them as this
      // card's own; a non-empty value flags a broken job_id link or a genuine
      // sibling claim under a shared builder ref (W2-D).
      sibling_invoices: siblingInvoices,
    }
  })

  // Optional company filter (slug or name substring on the make-safe company).
  if (companyFilter) {
    const cf = companyFilter.toLowerCase()
    const matchById: Record<string, boolean> = {}
    for (const j of (jobs || [])) {
      const d = detailsMap[j.id] || null
      const slug = String(d?.requesting_company_slug || d?.makesafe_companies?.slug || '').toLowerCase()
      const name = String(d?.requesting_company_name || d?.makesafe_companies?.name || '').toLowerCase()
      matchById[j.id] = slug.includes(cf) || name.includes(cf)
    }
    jobRows = jobRows.filter((r: any) => matchById[r.job_id])
  }

  // ── known_refs[] ── tiny ref index for the intake audit ──
  // Union of (a) make-safe jobs and (b) intake drafts. The job's source_email_id
  // comes from the originating intake draft (joined on approved_job_id) — jobs do
  // not currently carry the email id themselves (see PR notes). Drafts contribute
  // {ref, email, job_number: null, substatus: null}.
  const knownRefs: Array<{ external_ref: string | null; source_email_id: string | null; job_number: string | null; substatus: string | null }> = []
  // Drafts: needs_review or draft (not yet a job). Both sides of the known-ref
  // union are required audit truth, so paginate and reject instead of silently
  // returning an incomplete reference index on a query error or row cap. Both
  // reads order by the `id` PK: an unordered .range() page pair can drop a row
  // once either side outgrows one page, and a dropped draft ref reads as an
  // unknown ref (duplicate intake) on the audit side.
  const drafts = await _fetchAllRows<any>(
    () => client.from('makesafe_intake_drafts')
      .select('external_ref, graph_message_id, internet_message_id, status, approved_job_id')
      .in('status', ['needs_review', 'draft'])
      .order('id', { ascending: true }),
    'makesafe_audit pending intake drafts',
  )
  const draftEmailByJob: Record<string, string | null> = {}
  // Also map approved drafts -> their job, to recover each job's source_email_id.
  const approvedDrafts = await _fetchAllRows<any>(
    () => client.from('makesafe_intake_drafts')
      .select('graph_message_id, internet_message_id, approved_job_id')
      .eq('status', 'approved')
      .order('id', { ascending: true }),
    'makesafe_audit approved intake drafts',
  )
  for (const d of (approvedDrafts || [])) {
    if (d?.approved_job_id) draftEmailByJob[d.approved_job_id] = d.graph_message_id || d.internet_message_id || null
  }
  for (const r of jobRows) {
    knownRefs.push({
      external_ref: r.external_ref,
      source_email_id: draftEmailByJob[r.job_id] ?? null,
      job_number: r.job_number,
      substatus: r.substatus,
    })
  }
  for (const d of (drafts || [])) {
    knownRefs.push({
      external_ref: d.external_ref ?? null,
      source_email_id: d.graph_message_id || d.internet_message_id || null,
      job_number: null,
      substatus: null,
    })
  }

  // W3-A (M-E hybrid loop) — surface the cheap-pass story verdict + freshness on
  // each jobs[] row, and the recheck-queue depth at the top level, so the board
  // banner + standing fix-list can render truth-freshness. ADDITIVE ONLY: every
  // field above is unchanged; a card with no story row reads null (no cheap-pass
  // concern / cleanly closed). This read never writes anything.
  const auditJobIds = jobRows.map((r: any) => r.job_id).filter(Boolean)
  const storyRows = auditJobIds.length
    ? await _fetchAllByJobIdChunked(
      client,
      'makesafe_card_story',
      'job_id, story_verdict, needs_agent, recheck_enqueued, evidence_gaps, blockers, computed_at',
      auditJobIds,
    )
    : []
  const storyByJob: Record<string, any> = {}
  for (const s of (storyRows || [])) if (s?.job_id) storyByJob[s.job_id] = s
  const verdictCounts: Record<string, number> = {}
  let needsAgentCount = 0
  let latestComputedAt: string | null = null
  for (const s of (storyRows || [])) {
    const v = String(s?.story_verdict || 'UNKNOWN')
    verdictCounts[v] = (verdictCounts[v] || 0) + 1
    if (s?.needs_agent) needsAgentCount++
    if (s?.computed_at && (latestComputedAt === null || s.computed_at > latestComputedAt)) {
      latestComputedAt = s.computed_at
    }
  }
  for (const r of jobRows) {
    const s = storyByJob[r.job_id] || null
    r.story_verdict = s?.story_verdict ?? null
    r.story_computed_at = s?.computed_at ?? null
    r.story_needs_agent = s?.needs_agent === true
    r.story_evidence_gaps = Array.isArray(s?.evidence_gaps) ? s.evidence_gaps : []
    r.story_blockers = Array.isArray(s?.blockers) ? s.blockers : []
  }

  // Recheck-queue depth: report-type cards stamped for an agent portal re-check
  // (portal_recheck_requested_at set) that are still UNVERIFIED (portal_verified_at
  // null). This auxiliary COUNT stays non-fatal, but failure/unsupported count is
  // surfaced as null (unknown), never the truthful numeric value 0.
  let recheckQueueDepth: number | null = null
  try {
    const { count, error: depthErr } = await client.from('makesafe_job_details')
      .select('job_id', { count: 'exact', head: true })
      .not('report_type', 'is', null)
      .not('portal_recheck_requested_at', 'is', null)
      .is('portal_verified_at', null)
    if (depthErr) {
      console.error('makesafe_audit recheck_queue_depth failed', depthErr)
    } else if (typeof count === 'number') {
      recheckQueueDepth = count
    } else {
      console.error('makesafe_audit recheck_queue_depth count unavailable')
    }
  } catch (depthErr) {
    console.error('makesafe_audit recheck_queue_depth failed', depthErr)
  }

  return {
    generated_at: new Date().toISOString(),
    jobs: jobRows,
    known_refs: knownRefs,
    // W3-A truth-freshness surface (additive).
    recheck_queue_depth: recheckQueueDepth,
    story: {
      computed_at: latestComputedAt,
      verdict_counts: verdictCounts,
      needs_agent: needsAgentCount,
      total: (storyRows || []).length,
    },
  }
}
export const _makesafeAuditForTest = makesafeAudit

// ════════════════════════════════════════════════════════════
// W3-A (M-E hybrid loop) — the CHEAP PASS + the admin@ Sent-Items mirror.
//
// The cheap pass computes, for ACTIVE make-safe cards, the backend-honest story
// verdict from the W2-D invoice partition + the admin@ Sent mirror + job markers +
// Xero-by-job, and persists it to makesafe_card_story. Cards whose expensive legs
// (the primeeco portal, a full live-mailbox sweep) are still needed FAIL CLOSED to
// UNVERIFIED-needs-agent and are stamped into the EXISTING W2-C recheck queue
// (reused columns; never a second queue). MARKER/READ ONLY — never advances a
// substatus, drafts/creates an invoice, sends, or SMSs (item-14 guard is law).
// ════════════════════════════════════════════════════════════

// Terminal statuses that are NOT active (cancelled stays IN so a cancelled-with-
// evidence card can raise CANCELLED-CONFLICT).
const STORY_ACTIVE_DEAD_STATUSES = new Set([
  'archived', 'lost', 'deleted', 'duplicate', 'duplicated', 'void', 'voided',
])
// Sent-mirror lookback for the send-attribution scan (bounded; make-safe sends are
// weeks old at most, and the 90-day mirror floor bounds the store anyway).
const STORY_SENT_LOOKBACK_DAYS = 120

interface StoryRecomputeOpts {
  staleHours?: number
  nowIso?: string
  sentLookbackDays?: number
  minIntervalHours?: number // W2-C recheck rate-limit reuse (default 6, matches the cron)
  makesafeAudit?: (client: any, params: URLSearchParams) => Promise<any>
}

async function makesafeStoryRecompute(client: any, opts: StoryRecomputeOpts = {}) {
  const nowIso = opts.nowIso ?? new Date().toISOString()
  const nowMs = Date.parse(nowIso)
  const staleMs = (opts.staleHours ?? 24) * 3600_000
  const minIntervalMs = (opts.minIntervalHours ?? 6) * 3600_000
  const auditFn = opts.makesafeAudit ?? makesafeAudit

  // 1) W2-D partition: one compact row per make-safe job (invoice by job_id, sibling
  //    bleed split out, pack_sent marker, pipeline sent status, doc booleans).
  const audit = await auditFn(client, new URLSearchParams())
  const allJobs: any[] = audit?.jobs || []
  const activeJobs = allJobs.filter(
    (j) => !STORY_ACTIVE_DEAD_STATUSES.has(String(j.job_status || '').toLowerCase()),
  )
  const jobIds = activeJobs.map((j) => j.job_id).filter(Boolean)

  // 2) portal / report-type state per card (report_type, cycle, links, verify, recheck).
  const details = jobIds.length
    ? await _fetchAllByJobIdChunked(
      client, 'makesafe_job_details',
      'job_id, report_type, cycle_number, external_links, portal_verified_at, ' +
        'portal_verified_cycle, portal_recheck_requested_at, portal_recheck_count, ' +
        'cancel_reason',
      jobIds,
    )
    : []
  const detailByJob: Record<string, any> = {}
  for (const d of (details || [])) if (d?.job_id) detailByJob[d.job_id] = d

  // 3) admin@ Sent mirror rows (bounded window) for backend send-attribution.
  const sentSinceIso = new Date(
    nowMs - (opts.sentLookbackDays ?? STORY_SENT_LOOKBACK_DAYS) * 86_400_000,
  ).toISOString()
  const sentRows = await _fetchAllRows(
    () => client.from('emails')
      .select('post_id, subject, body_preview, body_content, to_recipients, has_attachments, received_at')
      .eq('mailbox', _ADMIN_SENT_MAILBOX).eq('folder', _SENT_FOLDER).gte('received_at', sentSinceIso)
      // post_id is the emails PK; the paginated read must end on a unique key or
      // a .range() page pair can drop a Sent row (a real send reads as unsent).
      .order('post_id', { ascending: true }),
    'story sent-mirror read',
  )

  // 4) prior story rows (the delta rule).
  const priorRows = jobIds.length
    ? await _fetchAllByJobIdChunked(
      client, 'makesafe_card_story', 'job_id, story_verdict, signal_fingerprint, computed_at', jobIds,
    )
    : []
  const priorByJob: Record<string, any> = {}
  for (const p of (priorRows || [])) if (p?.job_id) priorByJob[p.job_id] = p

  let computed = 0, skipped = 0, closedCleared = 0, enqueued = 0
  const verdictCounts: Record<string, number> = {}
  const countVerdict = (v: string) => { verdictCounts[v] = (verdictCounts[v] || 0) + 1 }

  for (const j of activeJobs) {
    const detail = detailByJob[j.job_id] || {}
    const sub = normalizeMakesafeSubstatus(j.substatus)
    const jobStatusLc = String(j.job_status || '').toLowerCase()
    const cancelled = jobStatusLc === 'cancelled' || jobStatusLc === 'canceled' ||
      sub === 'cancelled' || sub === 'canceled'

    // Xero STRICTLY by job_id (W2-D): audit.invoices are job-linked only (incl voided).
    const jobInvoices: any[] = Array.isArray(j.invoices) ? j.invoices : []
    const paid = jobInvoices.some((i) => !i.voided && String(i.status || '').toUpperCase() === 'PAID')
    const invoiceBuilt = !!j.live_invoice_no
    const siblingInvoices: any[] = Array.isArray(j.sibling_invoices) ? j.sibling_invoices : []
    const siblingBleed = siblingInvoices.some((i) => !i.voided)

    // Send attribution over the admin@ Sent mirror (ref# + job-linked invoice numbers).
    const refNum = _refNumberOf(j.external_ref)
    const invoiceNos = String(j.invoice_no || '').split(',').map((s: string) => s.trim()).filter(Boolean)
    const tokens = [refNum, ...invoiceNos].filter(Boolean)
    const sentHits = tokens.length
      ? (sentRows as _SentRow[]).filter((row) => _sentRowAttributesToJob(row, tokens))
      : []
    const adminSentAttributed = sentHits.length > 0
    let sentHitLatest: string | null = null
    for (const h of sentHits as any[]) {
      if (h.received_at && (sentHitLatest === null || h.received_at > sentHitLatest)) sentHitLatest = h.received_at
    }

    const isReportType = !!detail.report_type
    const currentCycle = Number(detail.cycle_number ?? 1)
    const portalVerifiedThisCycle = !!detail.portal_verified_at &&
      Number(detail.portal_verified_cycle) === currentCycle
    const hasPortalLink = _extractPortalLinks(detail.external_links).length > 0
    const attended = ['in_progress', 'complete', 'completed', 'invoiced'].includes(jobStatusLc) ||
      j.has_report_record === true

    const ev: _CardEvidence = {
      jobStatus: j.job_status ?? null,
      substatus: sub,
      cancelled,
      // M-F: a MANUAL cancel (cancel_reason set) is a clean CANCELLED, never a conflict.
      cancelReasonSet: !!detail.cancel_reason,
      adminSentAttributed,
      packSentMarker: j.pack_sent === true,
      pipelineVerifiedSent: String(j.pipeline_item_sent_status || '') === 'verified_sent',
      paid,
      invoiceBuilt,
      siblingBleed,
      attended,
      hasReportDoc: j.has_report_doc === true || j.has_report_record === true,
      hasInvoiceDoc: j.has_invoice_doc === true,
      woReceived: j.has_wo === true,
      isReportType,
      portalVerifiedThisCycle,
      hasPortalLink,
    }
    const prior = priorByJob[j.job_id] || null

    // Cleanly-closed cards carry no fix-list row: clear any stale prior row and skip.
    if (_isCleanlyClosed(ev)) {
      if (prior) {
        const { error: delErr } = await client.from('makesafe_card_story').delete().eq('job_id', j.job_id)
        if (delErr) throw delErr
        closedCleared++
      }
      continue
    }

    const positiveSend = ev.adminSentAttributed || ev.packSentMarker || ev.pipelineVerifiedSent
    const invoiceKey = `${j.invoice_no || ''}~${j.live_invoice_status || ''}`
    const fingerprint = _computeSignalFingerprint({
      substatus: sub, jobStatus: j.job_status ?? null, cancelled, positiveSend,
      paid, invoiceBuilt, siblingBleed, attended, hasReportDoc: ev.hasReportDoc,
      woReceived: ev.woReceived, portalVerifiedThisCycle,
      sentHitCount: sentHits.length, sentHitLatest, invoiceKey,
    })

    // Delta rule: recompute only on a changed cheap signal or > staleness.
    if (!_shouldRecompute(prior?.signal_fingerprint, prior?.computed_at, fingerprint, nowMs, staleMs)) {
      skipped++
      if (prior?.story_verdict) countVerdict(prior.story_verdict)
      continue
    }

    const result = _computeStoryVerdict(ev)
    countVerdict(result.verdict)

    // Stamp the EXISTING W2-C recheck queue for cards needing an agent PORTAL leg
    // (reused eligibility + columns + rate-limit; marker only). Non-portal
    // needs-agent cards surface via the verdict alone (no second queue).
    let recheckEnqueued = false
    if (
      result.needs_agent &&
      _portalRecheckEligible({
        jobStatus: j.job_status, isReportType: true, externalLinks: detail.external_links,
        currentCycle, verifiedAt: detail.portal_verified_at ?? null,
        verifiedCycle: detail.portal_verified_cycle ?? null,
      }) &&
      _portalRecheckDue(detail.portal_recheck_requested_at, nowMs, minIntervalMs)
    ) {
      const { error: stampErr } = await client.from('makesafe_job_details').update({
        portal_recheck_requested_at: nowIso,
        portal_recheck_count: Number(detail.portal_recheck_count || 0) + 1,
        portal_recheck_reason: 'cheap-pass: report-type card, unverified this cycle, no backend send proof',
        updated_at: nowIso,
      }).eq('job_id', j.job_id)
      if (stampErr) throw stampErr
      recheckEnqueued = true
      enqueued++
    }

    const { error: upErr } = await client.from('makesafe_card_story').upsert({
      job_id: j.job_id,
      story_verdict: result.verdict,
      evidence_gaps: result.evidence_gaps,
      blockers: result.blockers,
      signals: {
        cancelled, positive_send: positiveSend, admin_sent_attributed: adminSentAttributed,
        pack_sent_marker: ev.packSentMarker, pipeline_verified_sent: ev.pipelineVerifiedSent,
        paid, invoice_built: invoiceBuilt, sibling_bleed: siblingBleed, attended,
        has_report_doc: ev.hasReportDoc, wo_received: ev.woReceived,
        is_report_type: isReportType, portal_verified_this_cycle: portalVerifiedThisCycle,
        has_portal_link: hasPortalLink, sent_hit_count: sentHits.length, substatus: sub,
      },
      needs_agent: result.needs_agent,
      recheck_enqueued: recheckEnqueued,
      external_ref: j.external_ref ?? null,
      signal_fingerprint: fingerprint,
      computed_at: nowIso,
      updated_at: nowIso,
    }, { onConflict: 'job_id' })
    if (upErr) throw upErr
    computed++
  }

  return {
    ok: true,
    active: activeJobs.length,
    computed,
    skipped,
    closed_cleared: closedCleared,
    enqueued,
    verdict_counts: verdictCounts,
    computed_at: nowIso,
  }
}
export const _makesafeStoryRecomputeForTest = makesafeStoryRecompute

// WIRING: the admin@ Sent-Items mirror action. Builds the real Graph traversal
// (shared app-only token + graphFetch) and hands it to the pure mirror. Read-of-
// Graph, write-to-emails only — no send, no substatus, no invoice.
async function makesafeSentMirrorAction(client: any, body: any) {
  const backfillDays = Number(body?.backfill_days) || undefined
  return await _makesafeSentMirror(client, {
    backfillDays,
    fetchSentMessages: (sinceIso: string) =>
      _fetchAdminSentMessages(sinceIso, { getGraphToken: _getGraphToken, graphFetch: _graphFetch }),
  })
}
export const _makesafeSentMirrorActionForTest = makesafeSentMirrorAction

// ── Slice 5: make-safe completion report ──
async function submitMakesafeReport(client: any, body: any) {
  const {
    job_id, jobId, userId, user_id,
    arrival_time, damage_description, damage_cause,
    work_done, materials_used, labour_hours, trade_count,
    access_issues, follow_up_required, invoice_notes,
    job_type, job_type_detail, makesafe_type_detail,
    status: reportStatus,
  } = body
  const jId = job_id || jobId
  const uId = userId || user_id || null
  if (!jId) throw new Error('job_id required')
  await assertMakesafeJob(client, jId)

  // Re-attendance (M-C): each report is scoped to the job's current work cycle.
  // A re-attend (reattend_makesafe) increments makesafe_job_details.cycle_number,
  // so this submit stores a NEW report row for the new cycle rather than
  // overwriting the prior visit's report. Legacy/single-visit jobs default to
  // cycle 1 and behave exactly as before (the existing-report lookup below is
  // scoped to the same cycle, so a prior-cycle submitted report never blocks the
  // second visit's submission and is never overwritten).
  const { data: cycleDetail } = await client.from('makesafe_job_details')
    .select('cycle_number, substatus').eq('job_id', jId).maybeSingle()
  const currentCycle = (cycleDetail as { cycle_number?: number } | null)?.cycle_number ?? 1
  const detailSubstatus = (cycleDetail as { substatus?: string } | null)?.substatus || null

  const reportFields: Record<string, any> = {
    cycle_number: currentCycle,
    checklist_json: {
      arrival_time: arrival_time || '',
      damage_description: damage_description || '',
      job_type: job_type || '',
      job_type_detail: job_type_detail || makesafe_type_detail || '',
      makesafe_type_detail: makesafe_type_detail || job_type_detail || '',
      damage_cause: damage_cause || '',
      work_done: work_done || '',
      materials_used: materials_used || [],
      labour_hours: labour_hours || 0,
      trade_count: trade_count || 1,
      access_issues: access_issues || '',
      follow_up_required: follow_up_required || false,
      invoice_notes: invoice_notes || '',
    },
    notes: work_done || null,
    status: reportStatus || 'submitted',
    submitted_by: uId,
    submitted_at: (reportStatus || 'submitted') === 'submitted' ? new Date().toISOString() : null,
  }

  // Check for an existing report FOR THIS CYCLE only (cycle-scoped so a prior
  // visit's submitted/approved report is never treated as a duplicate here).
  const { data: existing } = await client.from('job_service_reports')
    .select('id, status').eq('job_id', jId).eq('cycle_number', currentCycle).limit(1).maybeSingle()

  const submittingFinal = (reportStatus || 'submitted') === 'submitted'
  // A report already persisted as 'submitted' whose board sync completed (detail
  // already advanced to the finished substatus) is a genuine duplicate submit and
  // is still rejected. But one saved as 'submitted' whose board never advanced —
  // a prior call that failed a post-save step (auto-assignment, board substatus,
  // event log) and returned 500 — is NOT a duplicate: it is a stuck card. Rather
  // than dead-ending the retry with 'Report already submitted', we resume and
  // re-run the idempotent sync steps below to finish the job.
  // A card can legitimately advance past the report-in substatus (to
  // ready_to_invoice or complete) while its report row is still 'submitted'
  // (board advancement never flips the report to 'approved'). Treat the whole
  // finished-substatus set as board-sync-complete so a duplicate submit is
  // rejected rather than resumed — a resume re-writes substatus back to
  // admin_to_send_report and would regress an already-advanced card.
  const FINISHED_SUBSTATUSES = ['admin_to_send_report', 'ready_to_invoice', 'complete']
  const boardSyncComplete = FINISHED_SUBSTATUSES.includes(detailSubstatus || '')
  const resumingSubmitted = submittingFinal &&
    existing?.status === 'submitted' && !boardSyncComplete
  if (submittingFinal) {
    // Captain D1: a final report is always attributable. Trade JWT dispatch
    // supplies this server-side; privileged callers must supply an actor too.
    if (!uId) throw new ApiError('user_id required for final MakeSafe report attribution', 400)
    if (existing?.status === 'submitted' && boardSyncComplete) throw new Error('Report already submitted')
    const { data: mediaRows, error: mediaErr } = await client.from('job_media')
      .select('phase')
      .eq('job_id', jId)
      .eq('type', 'photo')
      .limit(200)
    if (mediaErr) throw mediaErr
    const photoCount = (mediaRows || []).length
    if (photoCount < 5) {
      throw new ApiError(`MakeSafe report needs at least 5 photos (found ${photoCount})`, 400)
    }
  }

  let report
  if (existing) {
    if (existing.status === 'approved') throw new Error('Report already approved')
    if (resumingSubmitted) {
      // Preserve the original submission (submitted_by/submitted_at) on a resume
      // and just re-read the row; the sync steps below are what still need to run.
      const { data, error } = await client.from('job_service_reports')
        .select().eq('id', existing.id).single()
      if (error) throw error
      report = data
    } else {
      const { data, error } = await client.from('job_service_reports')
        .update(reportFields).eq('id', existing.id).select().single()
      if (error) throw error
      report = data
    }
  } else {
    const { data, error } = await client.from('job_service_reports')
      .insert({ job_id: jId, ...reportFields }).select().single()
    if (error) throw error
    report = data
  }

  // Auto-update makesafe substatus + job status on report submission
  let boardSync: any = null
  let eventSync: any = null
  const warnings: string[] = []
  if (submittingFinal) {
    const syncAt = new Date().toISOString()

    // Captain D1: allocation never gates report-in. When a genuine final report
    // arrives on a card with no assignment row at all, record the submitter as
    // the completed lead so the crew ledger tells the same operational story.
    // Existing assignments are never replaced or duplicated.
    const { data: assignmentRows, error: assignmentReadErr } = await client
      .from('job_assignments')
      .select('id')
      .eq('job_id', jId)
      .limit(1)
    if (assignmentReadErr) {
      throw new ApiError(`MakeSafe report saved but submitter assignment check failed: ${assignmentReadErr.message || assignmentReadErr}`, 500)
    }
    let autoAssignment: any = null
    if ((assignmentRows || []).length === 0) {
      const { data: insertedAssignment, error: assignmentInsertErr } = await client
        .from('job_assignments')
        .insert({
          job_id: jId,
          user_id: uId,
          role: 'lead_installer',
          status: 'complete',
          completed_at: syncAt,
          notes: `Auto-assigned from final MakeSafe report submission (cycle ${currentCycle})`,
        })
        .select('id, user_id, status')
        .single()
      if (assignmentInsertErr) {
        throw new ApiError(`MakeSafe report saved but submitter auto-assignment failed: ${assignmentInsertErr.message || assignmentInsertErr}`, 500)
      }
      autoAssignment = insertedAssignment
    }

    const { data: detailSync, error: detailSyncErr } = await client.from('makesafe_job_details')
      .update({
        substatus: 'admin_to_send_report',
        report_received_at: syncAt,
        invoice_notes: invoice_notes || null,
        updated_at: syncAt,
      })
      .eq('job_id', jId)
      .select('job_id, substatus, report_received_at')
      .maybeSingle()
    if (detailSyncErr) {
      throw new ApiError(`MakeSafe report saved but board sync failed: ${detailSyncErr.message || detailSyncErr}`, 500)
    }
    if (!detailSync) {
      throw new ApiError('MakeSafe report saved but board sync failed: makesafe detail row missing', 500)
    }
    // ── M3d U2b: submitting the final make-safe report advances substatus to a
    // finished value (admin_to_send_report) — close its still-open crew
    // assignments. Guarded by submittingFinal above. Non-blocking.
    await closeOpenAssignmentsForJob(client, jId, 'complete')
    boardSync = {
      ok: true,
      substatus: detailSync.substatus || 'admin_to_send_report',
      report_received_at: detailSync.report_received_at || syncAt,
      auto_assignment: autoAssignment ? {
        id: autoAssignment.id,
        user_id: autoAssignment.user_id || uId,
        status: autoAssignment.status || 'complete',
        attribution: 'final_makesafe_report_submitter',
      } : null,
    }

    // Do not mark the job final complete/invoiced here. The MakeSafe ops board
    // derives its report_ready stage from substatus=admin_to_send_report above.
    try {
      // On a resume, an earlier attempt may already have logged this event; skip
      // re-inserting so retries stay idempotent instead of duplicating history.
      let priorEvent = false
      if (resumingSubmitted) {
        const { data: existingEvent } = await client.from('job_events')
          .select('id')
          .eq('job_id', jId)
          .eq('event_type', 'makesafe_report_submitted')
          .eq('detail_json->>cycle_number', String(currentCycle))
          .limit(1)
          .maybeSingle()
        priorEvent = !!existingEvent
      }
      if (priorEvent) {
        eventSync = { ok: true, skipped: 'already_logged' }
      } else {
        const { error: eventErr } = await client.from('job_events').insert({
          job_id: jId,
          user_id: uId,
          event_type: 'makesafe_report_submitted',
          detail_json: {
            report_id: report.id,
            labour_hours,
            trade_count,
            materials_used,
            auto_assignment_id: autoAssignment?.id || null,
            auto_assigned_submitter: !!autoAssignment,
            assignment_attribution: autoAssignment ? 'final_makesafe_report_submitter' : null,
            cycle_number: currentCycle,
          },
        })
        if (eventErr) {
          eventSync = { ok: false, error: eventErr.message || String(eventErr) }
          warnings.push('event_sync_failed')
        } else {
          eventSync = { ok: true }
        }
      }
    } catch (err) {
      eventSync = { ok: false, error: err instanceof Error ? err.message : String(err) }
      warnings.push('event_sync_failed')
    }
  }

  return { ok: true, report, board_sync: boardSync, event_sync: eventSync, warnings }
}
export const _submitMakesafeReportForTest = submitMakesafeReport
export const _recaptureIntakeDraftForTest = recaptureIntakeDraft

// ── Slice 6: make-safe map data ──
async function makesafeMap(client: any, params: URLSearchParams) {
  const filter = params.get('filter') || 'active' // active|today|unassigned|new|allocated|report_ready|completed|archive|waiting_report|on_road
  const tradeId = params.get('trade_id') || null

  let query = client.from('jobs')
    .select('id, job_number, type, status, client_name, client_phone, site_address, site_suburb, site_lat, site_lng, notes, metadata, created_at, updated_at, completed_at')
    .eq('type', 'makesafe')
    .not('status', 'in', '("cancelled","archived","lost")')
    .order('created_at', { ascending: false })
    .limit(300)

  const { data: jobs, error } = await query
  if (error) throw error

  const jobIds = (jobs || []).map((j: any) => j.id)
  if (jobIds.length === 0) return { jobs: [], no_location: [], stage_labels: MAKESAFE_BOARD_STAGE_LABELS }

  // Fetch details, assignments, reports, and invoices in parallel. These are
  // read-only enrichment queries for the map; write mutations remain untouched.
  const [detailsRes, assignsRes, reportsRes, invoicesRes] = await Promise.all([
    client.from('makesafe_job_details')
      .select('job_id, requesting_company_id, requesting_company_slug, requesting_company_name, external_ref, substatus, report_received_at, report_sent_at, invoice_ready_at, reattend_count, last_reattend_at, cycle_number, makesafe_companies:requesting_company_id(slug, name)')
      .in('job_id', jobIds),
    client.from('job_assignments')
      .select('job_id, user_id, scheduled_date, status, role, crew_name, travel_started_at, arrived_at, clocked_on_at, completed_at, users:user_id(name, phone)')
      .in('job_id', jobIds)
      .neq('status', 'cancelled')
      .order('scheduled_date', { ascending: true }),
    client.from('job_service_reports')
      .select('job_id, status, submitted_at, created_at, cycle_number')
      .in('job_id', jobIds)
      .neq('status', 'draft')
      .order('submitted_at', { ascending: false }),
    client.from('xero_invoices')
      .select('job_id, status, invoice_type, invoice_number, reference, amount_due, total, invoice_date, created_at')
      .in('job_id', jobIds)
      .eq('invoice_type', 'ACCREC')
      .not('status', 'in', '("VOIDED","DELETED")')
      .order('invoice_date', { ascending: false }),
  ])

  const detailsMap: Record<string, any> = {}
  for (const d of (detailsRes.data || [])) detailsMap[d.job_id] = d
  const assignMap: Record<string, any[]> = {}
  for (const a of (assignsRes.data || [])) {
    if (!assignMap[a.job_id]) assignMap[a.job_id] = []
    assignMap[a.job_id].push(a)
  }
  const reportMap = currentCycleReportMap(reportsRes.data || [], detailsMap)
  const invoiceMap = firstByJobId(invoicesRes.data || [])

  const today = new Date().toISOString().slice(0, 10)
  const enriched = (jobs || []).map((j: any) => {
    const assigns = assignMap[j.id] || []
    const todayAssigns = assigns.filter((a: any) => a.scheduled_date === today)
    const onRoad = todayAssigns.some((a: any) => a.travel_started_at && !a.completed_at)
    return {
      ...enrichMakesafeBoardJob(j, detailsMap[j.id] || null, assigns, reportMap[j.id], invoiceMap[j.id]),
      on_road: onRoad,
      has_location: !!(j.site_lat && j.site_lng),
    }
  })

  // Apply filters. Board-stage names are the primary filters; the older
  // waiting_report alias is kept for compatibility but is derived from the same
  // normalized board state rather than raw migration substatuses only.
  let filtered = enriched
  if (MAKESAFE_BOARD_STAGES.includes(filter)) filtered = enriched.filter((j: any) => j.board_stage === filter)
  if (filter === 'today') filtered = enriched.filter((j: any) => j.assignments.some((a: any) => a.scheduled_date === today))
  if (filter === 'unassigned') filtered = enriched.filter((j: any) => j.assignments.length === 0)
  if (filter === 'waiting_report') filtered = enriched.filter((j: any) => j.substatus === 'waiting_on_trade_report' || j.board_stage === 'allocated' || j.board_stage === 'trade_report_in' || j.board_stage === 'report_ready')
  if (filter === 'on_road') filtered = enriched.filter((j: any) => j.on_road)
  if (tradeId) filtered = filtered.filter((j: any) => j.assignments.some((a: any) => a.user_id === tradeId))

  const withLocation = filtered.filter((j: any) => j.has_location)
  const noLocation = filtered.filter((j: any) => !j.has_location)

  return { jobs: withLocation, no_location: noLocation, stage_labels: MAKESAFE_BOARD_STAGE_LABELS }
}

// ── Slice 7: list intake drafts ──
async function listIntakeDrafts(client: any, params: URLSearchParams) {
  // reopen_candidate is included by default so the board INTAKE column surfaces
  // "matches job X — reopen it?" items alongside normal new-WO drafts.
  const status = params.get('status') || 'draft,needs_review,reopen_candidate'
  const statuses = status.split(',').map((s: string) => s.trim())

  const { data, error } = await client.from('makesafe_intake_drafts')
    .select('*')
    .in('status', statuses)
    .order('received_at', { ascending: false })
    .limit(50)
  if (error) throw error
  const drafts = (data || []).map((draft: any) => enrichIntakeDraftForReview(draft))
  return { drafts }
}

function parseJsonObject(value: any): Record<string, any> {
  if (!value) return {}
  if (typeof value === 'object' && !Array.isArray(value)) return value
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value)
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {}
    } catch (_) { return {} }
  }
  return {}
}

function parseJsonArray(value: any): any[] {
  if (!value) return []
  if (Array.isArray(value)) return value
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value)
      return Array.isArray(parsed) ? parsed : []
    } catch (_) { return [] }
  }
  return []
}

function cleanReviewedString(value: any): string | null {
  const text = value == null ? '' : String(value).trim()
  return text || null
}

function intakeAttachmentName(attachment: any): string {
  return cleanReviewedString(attachment?.file_name || attachment?.name || attachment?.label) || ''
}

function attachmentNameLooksLikeWorkOrder(attachment: any): boolean {
  return /(^|[^a-z0-9])(w\/o|wo|works?[-_\s]*order|work[-_\s]*order)([^a-z0-9]|$)/i.test(intakeAttachmentName(attachment))
}

function attachmentNameLooksReportOnly(attachment: any): boolean {
  return /(^|[^a-z0-9])(report|assessment|photo[-_\s]*evidence|invoice)([^a-z0-9]|$)/i.test(intakeAttachmentName(attachment))
}

function hasWorkOrderAttachmentEvidence(attachments: any[]): boolean {
  const available = availableIntakeAttachments(attachments)
  if (available.some((a: any) => a?.is_work_order === true)) return true
  if (available.some((a: any) => attachmentNameLooksLikeWorkOrder(a) && !attachmentNameLooksReportOnly(a))) return true
  // Legacy rows from before WO designation often have exactly one servable PDF.
  // If it is not named like a report/invoice/photo-evidence document, treat it as
  // the work order evidence for auto-intake rather than stranding the card.
  return available.length === 1 && !attachmentNameLooksReportOnly(available[0])
}

// Clean, complete, high-confidence drafts advance by default (Captain Amendment 46).
// An explicit "false" remains a deployment brake; the DB auto_file_enabled switch and
// every field/duplicate/atomic-claim guard remain authoritative. No other value may
// silently park all eligible drafts.
function autoApproveCleanIntakeEnabled(): boolean {
  return Deno.env.get('MAKESAFE_AUTO_APPROVE_CLEAN_INTAKE') !== 'false'
}

// Intake item 5 — opt-in for the deterministic WO-PDF client-field fill. DEFAULT
// OFF: a fill can populate client_name/site_address and (when unambiguous + else
// clean) lift confidence to high, which makes a draft auto-approvable, so it must
// not switch on silently. When off, the fill code below never runs.
function pdfClientFillEnabled(): boolean {
  return Deno.env.get('MAKESAFE_INTAKE_PDF_CLIENT_FILL') === 'true'
}
export const _pdfClientFillEnabledForTest = pdfClientFillEnabled

// Builder DISPATCH BOILERPLATE — template lines that appear on EVERY work order from a
// builder, including pure report orders, so they are NOT evidence of any specific
// obligation (Marnin 2026-07-07: "that text is on every MLB WO... treat it as template
// noise, never obligation evidence"). Stripped before report/obligation evidence
// detection so a make-safe make-safe WO can't look like a report and a report WO can't
// look like a second make-safe. MLB is the dominant template; the phrases are generic
// enough to also neutralise the equivalent boilerplate other builders repeat.
const BUILDER_TEMPLATE_BOILERPLATE_RE: RegExp[] = [
  // MLB: "Upon completion of works you must provide before and after photos, and your
  // SWMS with your invoice." (+ close variants)
  /upon completion of works[^.]*?(?:swms|invoice)[^.]*\.?/gi,
  /you must provide before and after photos[^.]*\.?/gi,
  /(?:please\s+)?provide\s+before\s+and\s+after\s+photos[^.]*?(?:swms|invoice)[^.]*\.?/gi,
  /your\s+swms\s+with\s+your\s+invoice\.?/gi,
  // Generic safe-work-practice boilerplate that rides on many dispatch templates.
  /please undertake the job in a safe and professional manner[^.]*\.?/gi,
]

function stripBuilderTemplateBoilerplate(text: string | null | undefined): string {
  let out = String(text || '')
  for (const re of BUILDER_TEMPLATE_BOILERPLATE_RE) out = out.replace(re, ' ')
  return out.replace(/[ \t]{2,}/g, ' ').trim()
}
export const _stripBuilderTemplateBoilerplateForTest = stripBuilderTemplateBoilerplate

// The free text a draft/email carries, for report-evidence + combined-intake detection.
// Builder dispatch boilerplate is stripped first so template lines never read as
// obligation evidence.
function intakeReportEvidenceText(draft: any, extraction: any, attachments: any[]): string {
  const attachmentNames = (attachments || [])
    .map((a: any) => cleanReviewedString(a?.file_name || a?.name || a?.label))
    .filter(Boolean)
    .join('\n')
  const joined = [
    draft?.subject,
    draft?.body_preview,
    draft?.description,
    draft?.safety_requirements,
    draft?.special_instructions,
    extraction?.description,
    extraction?.scope,
    extraction?.notes,
    extraction?.job_type,
    extraction?.makesafe_type,
    extraction?.report_type,
    extraction?.builder_email_text_for_trade,
    attachmentNames,
  ].map((v) => cleanReviewedString(v)).filter(Boolean).join('\n')
  return stripBuilderTemplateBoilerplate(joined)
}

// Intake SPLIT retune (Marnin 2026-07-07): a make-safe + report is TWO cards ONLY when
// the email genuinely carries TWO work orders. "Every work order relates to ONE piece
// of work — one WO/PO number = one card, typed by the WO's stated scope. Two pieces of
// work at one property arrive as TWO work orders." So a single WO NEVER splits, no
// matter the wording; the split trigger requires two distinct PO numbers and/or two
// servable work-order PDFs.
function distinctWorkOrderSignals(
  text: string,
  attachments: any[],
): { poCount: number; woPdfCount: number } {
  const names = (attachments || [])
    .map((a: any) => cleanReviewedString(a?.file_name || a?.name || a?.label))
    .filter(Boolean)
    .join('\n')
  const hay = `${text || ''}\n${names}`
  // Distinct builder PO numbers (e.g. "MLB-26721PO-55622" -> 55622). Two POs = two WOs.
  // "PO Box 2143" (a footer address) can't match: PO must be immediately followed by a
  // separator/nothing and then the digits, never "PO <word>".
  const poNums = new Set<string>()
  for (const m of hay.matchAll(/PO[-#:]?\s?(\d{3,})/gi)) poNums.add(m[1])
  // Servable attachments that are named like a work order (two WO PDFs = two WOs).
  const woPdfCount = availableIntakeAttachments(attachments)
    .filter((a: any) => a?.is_work_order === true || attachmentNameLooksLikeWorkOrder(a))
    .length
  return { poCount: poNums.size, woPdfCount }
}

function emailCarriesMultipleWorkOrders(
  draftLike: any,
  extraction: any,
  attachments: any[],
): boolean {
  const text = [
    draftLike?.subject,
    draftLike?.body_preview,
    draftLike?.description,
    extraction?.builder_email_text_for_trade,
    extraction?.builder_work_order_number,
    extraction?.builder_po_number,
    extraction?.external_ref,
  ].map((v) => cleanReviewedString(v)).filter(Boolean).join('\n')
  const { poCount, woPdfCount } = distinctWorkOrderSignals(text, attachments)
  return poCount >= 2 || woPdfCount >= 2
}
export const _emailCarriesMultipleWorkOrdersForTest = emailCarriesMultipleWorkOrders

// POSITIVE report-only evidence: is there genuine proof this email carries a
// roof/assessment REPORT obligation (as opposed to a keyword-fallback false positive on
// a bare "roof" token)? Any one of:
//   (1) the model (body + PDF aware) COMMITTED a report-only type, or
//   (2) the subject/body carries EXPLICIT report-request wording ("roof report",
//       "make safe and report", "and provide a report"), or
//   (3) an attachment is explicitly a report/assessment document (named as such and not
//       named like a work order).
// This is the pivot for BOTH the wrong-type guard (no positive evidence + a WO PDF ->
// demote to general make-safe) and combined-intake detection (positive evidence + a WO
// PDF -> a make-safe that ALSO owes a report).
function hasPositiveReportOnlyEvidence(draft: any, extraction: any, attachments: any[]): boolean {
  if (_isReportOnlyType(_mappedModelReportType(extraction?.report_type) as any)) return true
  if (_textHasExplicitReportRequest(intakeReportEvidenceText(draft, extraction, attachments))) return true
  const available = availableIntakeAttachments(attachments)
  if (available.some((a: any) => attachmentNameLooksReportOnly(a) && !attachmentNameLooksLikeWorkOrder(a))) return true
  return false
}

// COMBINED make-safe + report — TWO cards from ONE email. RETUNED (Marnin 2026-07-07):
// this is legitimate ONLY when the email genuinely carries TWO work orders (two distinct
// PO numbers and/or two servable WO PDFs) where a report obligation is among them. A
// SINGLE work order is ONE card typed by its own scope, no matter the wording — a roof-
// report WO's own PDF is the roof-report order, not a separate make-safe, so a single WO
// must never be flagged combined (that produced the spurious make-safe twin on
// MLB-26721PO-55622). When it does fire it records extraction.secondary_obligation + a
// blocking missing_field; the split machinery (approveIntakeDraft) expands the two cards.
const COMBINED_OBLIGATION_MISSING_FIELD = 'combined_makesafe_and_report'
function flagCombinedIntakeObligation(
  draftLike: any,
  extraction: any,
  attachments: any[],
  missingFields: string[],
  draftReportType: string | null,
): { type: string } | null {
  // The trigger: genuinely TWO work orders in this one email. A single WO — even a
  // roof-report WO with a servable PDF — is never combined.
  if (!emailCarriesMultipleWorkOrders(draftLike, extraction, attachments)) return null
  if (!hasWorkOrderAttachmentEvidence(attachments)) return null
  if (!hasPositiveReportOnlyEvidence(draftLike, extraction, attachments)) return null
  const modelType = _mappedModelReportType(extraction?.report_type)
  const reportType = _isReportOnlyType(modelType as any)
    ? String(modelType)
    : (draftReportType && _isReportOnlyType(draftReportType) ? draftReportType : 'unknown_report')
  const obligation = {
    type: reportType,
    reason: COMBINED_OBLIGATION_MISSING_FIELD,
    detail: 'This email is a physical make-safe (servable work-order PDF present) that ALSO requests a roof/assessment report. The work order is the primary card; a SEPARATE report card is owed. Do not lose the second obligation.',
    detected_at: new Date().toISOString(),
  }
  if (extraction && typeof extraction === 'object') extraction.secondary_obligation = obligation
  if (!missingFields.includes(COMBINED_OBLIGATION_MISSING_FIELD)) missingFields.push(COMBINED_OBLIGATION_MISSING_FIELD)
  return obligation as any
}

// Intake item 3b — AUTO-SPLIT a combined make-safe + report into two cards.
// A combined obligation is SPLITTABLE (can auto-expand into two live cards on
// approval) only when its report type is UNAMBIGUOUS — a known report-only type
// (roof_report / assessment_report), not the 'unknown_report' fallback. An
// ambiguous combined obligation still goes to human review. Returns the report
// type to mint the second card as, or null when not splittable.
function combinedSplitObligation(extraction: any): { reportType: string } | null {
  const so = extraction?.secondary_obligation
  if (!so || typeof so !== 'object') return null
  if (cleanReviewedString(so.reason) !== COMBINED_OBLIGATION_MISSING_FIELD) return null
  const t = cleanReviewedString(so.type)
  if (t && _isReportOnlyType(t)) return { reportType: t }
  return null
}

function effectiveIntakeReportType(draft: any): string | null {
  const extraction = parseJsonObject(draft?.extraction_json)
  const attachments = parseJsonArray(draft?.attachments_json)
  const explicit = cleanReviewedString(draft?.report_type)
  if (explicit) {
    // WRONG-TYPE GUARD (intake hardening item 1): a stored roof/assessment report_type
    // is trusted verbatim EXCEPT when the draft ALSO carries a servable work-order PDF
    // and there is NO positive report-only evidence. That is the keyword-fallback trap:
    // classifyReportType fires on any "roof" substring when the model abstains, so a
    // physical roof make-safe (real WO PDF attached) gets mis-stored as roof_report and,
    // trusted verbatim here, is approved as a report-only card at ready_to_invoice with
    // its WO PDF NEVER attached. Demote to null (general make-safe) so the WO attaches.
    // With positive evidence the report type STICKS (a genuine report, possibly a
    // combined make-safe+report which the scanner flags as a secondary obligation).
    if (
      _isReportOnlyType(explicit) &&
      hasWorkOrderAttachmentEvidence(attachments) &&
      !hasPositiveReportOnlyEvidence(draft, extraction, attachments)
    ) {
      return null
    }
    return explicit
  }

  // Legacy rows can have body text that mentions "roof report" while the actual
  // attached document is a work order. Do not let fallback report classification
  // override clear WO evidence; otherwise clean intake never auto-promotes.
  if (hasWorkOrderAttachmentEvidence(attachments)) return null

  const text = intakeReportEvidenceText(draft, extraction, attachments)
  const classified = _classifyReportType(draft?.subject || null, text || null)
  return _isReportOnlyType(classified) ? classified : null
}

function enrichIntakeDraftForReview(draft: any): any {
  if (!draft) return draft
  const detected = effectiveIntakeReportType(draft)
  const hasStored = !!cleanReviewedString(draft.report_type)
  const extraction = parseJsonObject(draft.extraction_json)
  const pdfDocuments = parseJsonArray(extraction.work_order_pdf_text)
  const reportEnriched = {
    ...draft,
    report_type: draft.report_type || detected || null,
    detected_report_type: detected || null,
    report_type_source: detected ? (hasStored ? 'stored' : 'fallback_classifier') : (hasStored ? 'stored' : null),
    work_order_pdf_text: pdfDocuments,
    pdf_field_provenance: parseJsonObject(extraction.pdf_field_provenance),
    pdf_sourced_fields: parseJsonArray(extraction.pdf_sourced_fields),
    pdf_extraction_quarantine: pdfDocuments.filter((document: any) =>
      document?.status === 'quarantined'
    ),
  }
  const prefill = _deriveAjIntakePrefill({
    fromEmail: draft.from_email,
    subject: draft.subject,
    bodyText: extraction.builder_email_text_for_trade || draft.body_preview,
  })
  const applied = _applyAjIntakePrefill(extraction, prefill)
  if (!applied.filledFields.length) return reportEnriched

  const topLevelFields = [
    'external_ref',
    'client_name',
    'client_phone',
    'site_address',
    'site_suburb',
  ]
  const prefilled = { ...reportEnriched }
  for (const key of topLevelFields) {
    if (!cleanReviewedString(prefilled[key])) prefilled[key] = applied.extraction[key] || null
  }
  const filledMissingNames = new Set(applied.filledFields.map((key) => cleanMissingFieldName(key)))
  return {
    ...prefilled,
    extraction_json: applied.extraction,
    missing_fields: parseJsonArray(draft.missing_fields).filter(
      (field: any) => !filledMissingNames.has(cleanMissingFieldName(field)),
    ),
    deterministic_prefill_source: 'aj_labelled_email',
    deterministic_prefill_fields: applied.filledFields,
  }
}

const AUTO_APPROVE_ALLOWED_MISSING_FIELDS = new Set([
  'client_phone',
  'phone',
  'client_email',
  'email',
  'site_suburb',
  'suburb',
  'safety_requirements',
  'special_instructions',
  'portal_link',
])

function cleanMissingFieldName(value: any): string {
  return String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_')
}

function availableIntakeAttachments(attachments: any[]): any[] {
  return (attachments || []).filter((a: any) => a && !a.pdf_unavailable && (a.pdf_url || a.storage_url))
}

// ── D-a (Auto-Intake v2 M1): FAIL-LOUD extraction key preflight ──────────────
// v1's core sin was silence: when the ANTHROPIC_API_KEY was revoked, scanSesMakesafes
// skipped extraction with a bare console.log and kept producing empty drafts (missing
// portal links on 31 of 35 roof jobs) for weeks. v2 refuses to be silent: a dead/absent
// key degrades the WHOLE scan loud — every draft made this run is tagged with this
// marker (a BLOCKING missing field, so auto-file can never fire on a degraded draft),
// forced to needs_review, and a visible makesafe_intake_health banner is written.
const INTAKE_EXTRACTION_DOWN_MARKER = 'extraction_down_key_dead'

// Compatibility seam retained for the original dead-key tests. The complete policy is
// classifyExtractionFailure: usage-cap/config/request failures are terminal too, while
// rate-limit/network/5xx failures remain retryable.
function isAnthropicAuthFailure(err: unknown): boolean {
  return _classifyExtractionFailure(err).reason === 'auth_failed'
}

// D-d kill switch: read makesafe_cron_settings.auto_file_enabled (Captain D1 default
// TRUE). Fail-OPEN to true on a read error/missing row so a transient DB blip does not
// silently park all eligible drafts. The env switch is also default-on and disables
// only when explicitly set to "false".
async function isAutoFileEnabled(client: any): Promise<boolean> {
  try {
    const { data, error } = await client.from('makesafe_cron_settings')
      .select('auto_file_enabled').eq('id', true).maybeSingle()
    if (error) {
      console.warn('[ops-api] auto_file_enabled read failed; defaulting ON:', error.message)
      return true
    }
    if (!data || data.auto_file_enabled == null) return true
    return data.auto_file_enabled !== false
  } catch (e) {
    console.warn('[ops-api] auto_file_enabled read threw; defaulting ON:', (e as Error).message)
    return true
  }
}

// D-a: write the single-row makesafe_intake_health record every scan. Computes the
// ok<->degraded transition so degraded_since answers "how long has the key been dead".
// Best-effort: a health-write failure must never fail the scan itself.
async function writeIntakeHealth(client: any, input: {
  extractionStatus: 'ok' | 'degraded'
  degradedReason: string | null
  anyExtractionSucceeded: boolean
  // A confirmed durable item-local quarantine write this run. It is recovery proof for a
  // prior quarantine_persistence_failed degradation ONLY — never for a provider outage.
  quarantinePersistenceProven?: boolean
  draftsCreated: number
  autoFiled: number
  // M1.5 cost ledger for this scan (optional so callers that don't extract, e.g. the
  // group-post capture path, can omit it and leave the ledger untouched).
  cost?: {
    model_calls: number
    model_skips: number
    usage: {
      input_tokens: number
      output_tokens: number
      cache_read_input_tokens: number
      cache_creation_input_tokens: number
    }
  }
  // B5 SLA: this scan's email-received -> draft-created latency snapshot (seconds) +
  // the count of candidates deferred past the per-run scan budget. Optional +
  // pre-migration-safe: written into the FULL row only, so a pre-migration base-only
  // retry silently drops them (same posture as the M1.5 cost columns).
  sla?: {
    p50_sec: number
    p95_sec: number
    max_sec: number
    samples: number
  }
  cappedCandidates?: number
  // A3 dropped-WO breadcrumb for this scan (folded into the health row + the alarm).
  breadcrumb?: {
    insertConflictsHealed: number
    insertConflictsLive: number
    droppedAfterExtraction: number
    lastDroppedRef: string | null
  }
  // Empty-feed anomaly: the freshest inbound (non-own-domain) ses@ email this scan saw.
  // Lets the alarm detect a Graph mirror returning 200-with-nothing (no new mail).
  lastInboundEmailAt?: string | null
}): Promise<void> {
  try {
    const nowIso = new Date().toISOString()
    // H1: read the M1 BASE columns separately (always exist) so the fail-loud banner's
    // ok<->degraded transition is tracked even if the M1.5 ledger columns don't exist
    // yet. The cost totals are a SEPARATE best-effort read (may 400 pre-migration).
    const { data: prevBase } = await client.from('makesafe_intake_health')
      .select('extraction_status, degraded_reason, degraded_since, last_successful_extraction_at')
      .eq('id', true).maybeSingle()
    let prevCost: any = null
    if (input.cost) {
      const { data } = await client.from('makesafe_intake_health')
        .select('total_model_calls, total_model_skips, total_input_tokens, total_output_tokens, total_cache_read_tokens, total_cache_write_tokens')
        .eq('id', true).maybeSingle()
      prevCost = data || null // null pre-migration (columns absent) -> counters start at 0
    }
    // A3: prior lifetime breadcrumb totals (best-effort; null pre-migration -> start at 0).
    let prevBreadcrumb: any = null
    if (input.breadcrumb) {
      const { data } = await client.from('makesafe_intake_health')
        .select('total_insert_conflicts_healed, total_insert_conflicts_live, total_dropped_wo, dropped_wo_last_ref')
        .eq('id', true).maybeSingle()
      prevBreadcrumb = data || null
    }
    const wasDegraded = String(prevBase?.extraction_status || '') === 'degraded'
    // Degradation clears ONLY on observed successful extraction. A quiet scan is not
    // evidence a provider outage recovered; because failed/skipped source items stay
    // unmarked, the next scan supplies that proof without waiting for unrelated mail.
    // The one exception: a degradation caused ONLY by quarantine persistence has its own
    // recovery proof, because the permanently-request_invalid sources behind it can never
    // supply an extraction success. A confirmed durable quarantine write clears it.
    const persistenceRecoveryProven = !!input.quarantinePersistenceProven &&
      _degradedReasonIsPersistenceOnly(prevBase?.degraded_reason)
    const preservePriorDegraded = wasDegraded && !input.anyExtractionSucceeded &&
      !persistenceRecoveryProven && input.extractionStatus === 'ok'
    const effectiveStatus: 'ok' | 'degraded' = preservePriorDegraded ? 'degraded' : input.extractionStatus
    const effectiveReason = preservePriorDegraded
      ? (String(prevBase?.degraded_reason || '') || 'extraction_recovery_unproven')
      : input.degradedReason
    const isDegraded = effectiveStatus === 'degraded'
    // degraded_since: keep the existing start if still degraded; stamp now on a fresh
    // ok->degraded transition; clear when recovered.
    const degradedSince = isDegraded
      ? (wasDegraded && prevBase?.degraded_since ? prevBase.degraded_since : nowIso)
      : null
    const lastSuccess = input.anyExtractionSucceeded
      ? nowIso
      : (prevBase?.last_successful_extraction_at || null)
    // The M1 fail-loud banner — must be written on EVERY run, migration or not.
    const baseRow: any = {
      id: true,
      extraction_status: effectiveStatus,
      degraded_reason: isDegraded ? (effectiveReason || 'key_unset') : null,
      degraded_since: degradedSince,
      last_scan_at: nowIso,
      last_successful_extraction_at: lastSuccess,
      last_scan_drafts_created: input.draftsCreated,
      last_scan_auto_filed: input.autoFiled,
      updated_at: nowIso,
    }
    const row: any = { ...baseRow }
    // M1.5: write the last-scan snapshot + increment the lifetime running counters.
    if (input.cost) {
      const u = input.cost.usage
      const n = (v: any) => (Number.isFinite(Number(v)) ? Number(v) : 0)
      row.last_scan_model_calls = input.cost.model_calls
      row.last_scan_model_skips = input.cost.model_skips
      row.last_scan_input_tokens = u.input_tokens
      row.last_scan_output_tokens = u.output_tokens
      row.last_scan_cache_read_tokens = u.cache_read_input_tokens
      row.last_scan_cache_write_tokens = u.cache_creation_input_tokens
      row.last_scan_estimated_cost_usd = _usdCost(u)
      row.total_model_calls = n(prevCost?.total_model_calls) + input.cost.model_calls
      row.total_model_skips = n(prevCost?.total_model_skips) + input.cost.model_skips
      row.total_input_tokens = n(prevCost?.total_input_tokens) + u.input_tokens
      row.total_output_tokens = n(prevCost?.total_output_tokens) + u.output_tokens
      row.total_cache_read_tokens = n(prevCost?.total_cache_read_tokens) + u.cache_read_input_tokens
      row.total_cache_write_tokens = n(prevCost?.total_cache_write_tokens) + u.cache_creation_input_tokens
    }
    // B5 SLA: last-scan latency snapshot + capped-candidate count. In the FULL row
    // only (dropped by the base-only retry pre-migration). Written even on a quiet scan
    // (samples 0 -> all-zero) so the metric is always current.
    if (input.sla) {
      row.last_scan_latency_p50_sec = input.sla.p50_sec
      row.last_scan_latency_p95_sec = input.sla.p95_sec
      row.last_scan_latency_max_sec = input.sla.max_sec
      row.last_scan_latency_samples = input.sla.samples
    }
    if (typeof input.cappedCandidates === 'number') {
      row.last_scan_capped_candidates = input.cappedCandidates
    }
    // A3: dropped-WO breadcrumb. last_scan_* reset every run (0 on a clean scan so the
    // alarm clears); total_* accumulate for forensics. FULL row only (base fallback drops
    // them pre-migration, like the SLA/cost columns).
    if (input.breadcrumb) {
      const n = (v: any) => (Number.isFinite(Number(v)) ? Number(v) : 0)
      const b = input.breadcrumb
      row.last_scan_insert_conflicts_healed = b.insertConflictsHealed
      row.last_scan_insert_conflicts_live = b.insertConflictsLive
      row.last_scan_dropped_wo = b.droppedAfterExtraction
      row.total_insert_conflicts_healed = n(prevBreadcrumb?.total_insert_conflicts_healed) + b.insertConflictsHealed
      row.total_insert_conflicts_live = n(prevBreadcrumb?.total_insert_conflicts_live) + b.insertConflictsLive
      row.total_dropped_wo = n(prevBreadcrumb?.total_dropped_wo) + b.droppedAfterExtraction
      if (b.droppedAfterExtraction > 0 || b.insertConflictsLive > 0) {
        row.dropped_wo_last_at = nowIso
        row.dropped_wo_last_ref = b.lastDroppedRef || prevBreadcrumb?.dropped_wo_last_ref || null
      }
    }
    // Empty-feed anomaly: stamp the freshest inbound email this scan saw so the alarm can
    // detect a Graph mirror returning nothing. Only ADVANCES (never rewind on a quiet run).
    if (input.lastInboundEmailAt) {
      row.last_inbound_email_at = input.lastInboundEmailAt
    }
    // H1 (INVARIANT #5 — health must never go silently dark): supabase-js does NOT throw
    // on a PostgREST error; it returns {error}. In the window between merge->auto-deploy
    // and the hand-applied M1.5 migration, the ledger columns don't exist, so the FULL
    // upsert is rejected — which would silently drop the M1 fail-loud banner too. So
    // CHECK the error and RETRY with only the base M1 columns; a dead key in that window
    // must still be visible.
    const { error: upErr } = await client.from('makesafe_intake_health').upsert(row, { onConflict: 'id' })
    if (upErr) {
      console.warn('[ops-api] writeIntakeHealth full upsert failed (ledger columns likely pre-migration); retrying M1 base columns:', upErr.message)
      const { error: baseErr } = await client.from('makesafe_intake_health').upsert(baseRow, { onConflict: 'id' })
      if (baseErr) {
        console.error('[ops-api] writeIntakeHealth base upsert ALSO failed — health banner NOT written:', baseErr.message)
      }
    }
  } catch (e) {
    console.warn('[ops-api] writeIntakeHealth failed (non-fatal):', (e as Error).message)
  }
}

function shouldAutoApproveCleanIntake(input: {
  enabled?: boolean
  isReportCapture?: boolean
  tagReportType?: boolean
  reportType?: string | null
  confidence?: string | null
  missingFields?: any[]
  matchedCompany?: any
  externalRef?: string | null
  clientName?: string | null
  siteAddress?: string | null
  attachments?: any[]
  // Intake hardening: a cancellation must never auto-approve (it retracts a job, never
  // creates one); a combined make-safe+report email carries a SECOND obligation the
  // single-card auto-file would silently drop — both stay in the human queue.
  cancelled?: boolean
  combinedObligation?: boolean
  // Intake item 3b: an UNAMBIGUOUS combined obligation (known report type) may
  // auto-approve because approval now expands it into TWO cards instead of losing
  // the second obligation. An ambiguous combined obligation leaves this false and
  // still routes to human review.
  combinedSplittable?: boolean
}): { ok: boolean; reason: string } {
  if (input.enabled === false) return { ok: false, reason: 'disabled' }
  if (input.cancelled === true) return { ok: false, reason: 'cancelled_work_order' }
  if (input.combinedObligation === true && !input.combinedSplittable) {
    return { ok: false, reason: 'combined_makesafe_and_report_manual_review' }
  }

  const attachments = input.attachments || []
  const available = availableIntakeAttachments(attachments)
  if (available.length === 0) return { ok: false, reason: 'missing_work_order_pdf' }
  const hasUnavailablePdf = attachments.some((a: any) => a?.pdf_unavailable)
  if (hasUnavailablePdf) return { ok: false, reason: 'pdf_capture_needs_review' }
  const hasDesignatedWo = hasWorkOrderAttachmentEvidence(available)
  if (available.length > 1 && !hasDesignatedWo) return { ok: false, reason: 'multiple_pdfs_no_designated_work_order' }

  // A report-capture email with no WO PDF must stay manual. But if the email has
  // a servable/designated work-order PDF, the work order is the action: subject/body
  // words like "report" or "roof" should not strand clean intake in review.
  if (input.isReportCapture && !hasDesignatedWo) return { ok: false, reason: 'report_capture_manual_review' }
  if (input.tagReportType && !hasDesignatedWo) return { ok: false, reason: 'report_tagged_manual_review' }
  if (_isReportOnlyType(input.reportType) && !hasDesignatedWo) return { ok: false, reason: 'report_only_manual_review' }

  const confidence = String(input.confidence || '').trim().toLowerCase()
  if (confidence !== 'high') return { ok: false, reason: 'confidence_not_high' }

  const missing = (input.missingFields || []).map(cleanMissingFieldName).filter(Boolean)
  const blockingMissing = missing.filter((m) =>
    !AUTO_APPROVE_ALLOWED_MISSING_FIELDS.has(m) &&
    // The combined-obligation marker is not blocking when the obligation is
    // splittable — approval expands it into two cards (item 3b).
    !(input.combinedSplittable === true && m === COMBINED_OBLIGATION_MISSING_FIELD)
  )
  if (blockingMissing.length > 0) return { ok: false, reason: 'missing_fields:' + blockingMissing.join(',') }

  if (!input.matchedCompany?.slug && !input.matchedCompany?.name) return { ok: false, reason: 'missing_requesting_company' }
  if (!cleanReviewedString(input.externalRef)) return { ok: false, reason: 'missing_external_ref' }
  if (!cleanReviewedString(input.clientName)) return { ok: false, reason: 'missing_client_name' }
  if (!cleanReviewedString(input.siteAddress)) return { ok: false, reason: 'missing_site_address' }

  return { ok: true, reason: 'clean_high_confidence_work_order' }
}

function shouldAutoApproveCleanIntakeDraftRow(draft: any): { ok: boolean; reason: string } {
  const extraction = parseJsonObject(draft?.extraction_json)
  const attachments = parseJsonArray(draft?.attachments_json)
  const effectiveReportType = effectiveIntakeReportType(draft) || cleanReviewedString(draft?.report_type)

  // Defence in depth for legacy rows created before scan-time cancellation/combined
  // flagging existed: recompute both signals directly from the stored draft so the sweep
  // can never auto-promote a cancellation twin or a make-safe that also owes a report.
  const cancelled = _subjectIsCancellation(draft?.subject) ||
    /\b(?:has\s+(?:since\s+)?been\s+cancell?ed|work\s+orders?\s+(?:has|have)\s+(?:since\s+)?been\s+cancell?ed|please\s+(?:note|be\s+advised)[^.]*cancell?ed)\b/i
      .test(String(draft?.body_preview || ''))
  // RETUNE: the defence-in-depth recompute (for legacy rows without a stored
  // secondary_obligation) now also requires genuinely TWO work orders — a single
  // roof-report WO is not combined.
  const combinedObligation = !!(extraction?.secondary_obligation) ||
    (emailCarriesMultipleWorkOrders(draft, extraction, attachments) &&
      hasWorkOrderAttachmentEvidence(attachments) &&
      hasPositiveReportOnlyEvidence(draft, extraction, attachments))
  // item 3b: an unambiguous combined obligation is splittable (auto-expands into two cards).
  const combinedSplittable = combinedSplitObligation(extraction) !== null

  // NOTE: this is a PURE cleanliness check (no `enabled` passed). Whether auto-approval
  // is switched on at all is decided by the caller — the sweep action gates the default-on
  // MAKESAFE_AUTO_APPROVE_CLEAN_INTAKE flag once, so a braked flag still yields an
  // informative dry-run preview instead of masking every draft as 'disabled'.
  return shouldAutoApproveCleanIntake({
    reportType: effectiveReportType,
    confidence: draft?.confidence,
    missingFields: parseJsonArray(draft?.missing_fields),
    matchedCompany: {
      slug: cleanReviewedString(draft?.requesting_company_slug) || cleanReviewedString(extraction.requesting_company_slug),
      name: cleanReviewedString(draft?.requesting_company_name) || cleanReviewedString(extraction.requesting_company_name),
    },
    externalRef: cleanReviewedString(draft?.external_ref) || cleanReviewedString(extraction.external_ref),
    clientName: cleanReviewedString(draft?.client_name) || cleanReviewedString(extraction.client_name),
    siteAddress: cleanReviewedString(draft?.site_address) || cleanReviewedString(extraction.site_address),
    attachments,
    cancelled,
    combinedObligation,
    combinedSplittable,
  })
}

export const _combinedSplitObligationForTest = combinedSplitObligation
export const _effectiveIntakeReportTypeForTest = effectiveIntakeReportType
export const _shouldAutoApproveCleanIntakeForTest = shouldAutoApproveCleanIntake
// Intake hardening (items 1 + 3): exported so tests can exercise the positive-report
// evidence pivot, the combined make-safe+report flagger, and the default-on env brake.
export const _hasPositiveReportOnlyEvidenceForTest = hasPositiveReportOnlyEvidence
export const _flagCombinedIntakeObligationForTest = flagCombinedIntakeObligation
export const _autoApproveCleanIntakeEnabledForTest = autoApproveCleanIntakeEnabled
