// ── Slice 7: approve intake draft -> create job ──
async function autoApproveCleanIntakeDrafts(client: any, body: any = {}) {
  const rawLimit = Number(body.limit || body.max || 60)
  const limit = Math.max(1, Math.min(Number.isFinite(rawLimit) ? Math.floor(rawLimit) : 60, 100))
  const requestedDryRun = body.dry_run === true || body.dryRun === true
  // Both explicit brakes remain fail-safe. When either is disabled this sweep still
  // produces a preview, but it performs no live approvals.
  const enabled = autoApproveCleanIntakeEnabled() && await isAutoFileEnabled(client)
  const dryRun = requestedDryRun || !enabled
  const statuses = Array.isArray(body.statuses) && body.statuses.length
    ? body.statuses.map((s: any) => String(s || '').trim()).filter(Boolean)
    : ['needs_review', 'draft']

  const { data: drafts, error } = await client.from('makesafe_intake_drafts')
    .select('*')
    .in('status', statuses)
    .order('received_at', { ascending: true })
    .limit(limit)
  if (error) throw error

  const checked = drafts || []
  const autoApproved: any[] = []
  const eligible: any[] = []
  const skipped: any[] = []
  const failed: any[] = []

  for (const draft of checked) {
    const decision = shouldAutoApproveCleanIntakeDraftRow(draft)
    if (!decision.ok) {
      skipped.push({
        draft_id: draft?.id || null,
        external_ref: draft?.external_ref || null,
        reason: decision.reason,
      })
      continue
    }

    // Evidence that made THIS draft clean — logged with every auto-approval so an
    // unattended promotion is always auditable (mission requirement).
    const cleanEvidence = {
      confidence: draft?.confidence || null,
      report_type: effectiveIntakeReportType(draft),
      requesting_company: cleanReviewedString(draft?.requesting_company_slug) ||
        cleanReviewedString(draft?.requesting_company_name) || null,
      client_name_present: !!cleanReviewedString(draft?.client_name),
      site_address_present: !!cleanReviewedString(draft?.site_address),
      work_order_pdf: hasWorkOrderAttachmentEvidence(parseJsonArray(draft?.attachments_json)),
    }
    eligible.push({
      draft_id: draft?.id || null,
      external_ref: draft?.external_ref || null,
      reason: decision.reason,
      clean_evidence: cleanEvidence,
    })
    if (dryRun) continue

    try {
      const approved = await approveIntakeDraft(client, {
        draft_id: draft.id,
        approved_by: body.triggered_by || 'auto_intake_clean_gate',
        review_notes: 'Auto-approved clean make-safe intake from board sweep: high-confidence extraction, requesting company/ref/client/address present, and servable work-order PDF captured. Draft-only intake promotion; no invoice/send/authorise/close action.',
      })
      autoApproved.push({
        draft_id: draft.id,
        job_id: approved?.job?.id || null,
        // Item 3b: a combined draft splits into two live cards; log BOTH ids so an
        // unattended split is fully auditable.
        job_ids: approved?.job_ids || (approved?.job?.id ? [approved.job.id] : []),
        secondary_job_id: approved?.secondary_job?.id || null,
        split_combined: !!approved?.split_combined,
        external_ref: draft.external_ref || null,
        reason: decision.reason,
        clean_evidence: cleanEvidence,
      })
    } catch (e) {
      failed.push({
        draft_id: draft?.id || null,
        external_ref: draft?.external_ref || null,
        reason: decision.reason,
        error: e instanceof Error ? e.message : String(e),
      })
    }
  }

  return {
    ok: true,
    enabled,
    dry_run: dryRun,
    requested_dry_run: requestedDryRun,
    checked_count: checked.length,
    eligible_count: eligible.length,
    auto_approved: autoApproved,
    auto_approved_count: autoApproved.length,
    skipped_count: skipped.length,
    failed,
    failed_count: failed.length,
    skipped,
  }
}

// Item 3b — cross-link the two cards minted from one combined make-safe + report
// work order: a sibling pointer in each job's metadata (so the board can pair them)
// plus a job_events audit note on each. All writes are best-effort/non-blocking —
// a cross-link failure must never undo the (already-created) cards.
async function _crossLinkCombinedCards(
  client: any,
  primary: { id: string; number: string | null; role: string },
  secondary: { id: string; number: string | null; role: string },
): Promise<void> {
  const link = async (
    jobId: string,
    self: { id: string; number: string | null; role: string },
    sibling: { id: string; number: string | null; role: string },
  ) => {
    try {
      const { data: row } = await client.from('jobs').select('metadata').eq('id', jobId).maybeSingle()
      const md = parseJsonObject(row?.metadata)
      md.combined_sibling = {
        job_id: sibling.id,
        job_number: sibling.number,
        role: sibling.role,
        self_role: self.role,
        source: 'combined_makesafe_and_report',
      }
      await client.from('jobs').update({ metadata: md, updated_at: new Date().toISOString() }).eq('id', jobId)
    } catch (_) { /* non-blocking */ }
    try {
      await client.from('job_events').insert({
        job_id: jobId,
        event_type: 'makesafe.combined_split',
        detail_json: {
          sibling_job_id: sibling.id,
          sibling_job_number: sibling.number,
          sibling_role: sibling.role,
          self_role: self.role,
          note: `Auto-split from one combined make-safe + report work order. Sibling card: ${sibling.number || sibling.id} (${sibling.role}).`,
        },
      })
    } catch (_) { /* non-blocking */ }
  }
  await link(primary.id, primary, secondary)
  await link(secondary.id, secondary, primary)
}

function assertReviewedFamilyConsistency(
  reviewedFamily: string | null,
  effectiveReportType: string | null,
  splitObligation: boolean,
  primaryIsReportOnly: boolean,
): void {
  if (!reviewedFamily) return
  const reviewedFamilyReportType = _reportTypeForJobFamily(reviewedFamily)
  if (splitObligation) {
    if (reviewedFamilyReportType) {
      throw new ApiError(`reviewed makesafe_job_family '${reviewedFamily}' is a report family, but this draft auto-splits into a physical make-safe primary; the report family belongs to the secondary card`, 400)
    }
    return
  }
  if (reviewedFamilyReportType) {
    if (effectiveReportType !== reviewedFamilyReportType) {
      throw new ApiError(`reviewed makesafe_job_family '${reviewedFamily}' requires report_type '${reviewedFamilyReportType}', but the effective report_type is '${effectiveReportType || 'null'}'`, 400)
    }
    return
  }
  if (primaryIsReportOnly) {
    throw new ApiError(`reviewed makesafe_job_family '${reviewedFamily}' is a physical make-safe, but the effective report_type '${effectiveReportType}' is report-only`, 400)
  }
}
export const _assertReviewedFamilyConsistency = assertReviewedFamilyConsistency

async function loadExistingJobBindingForDraft(client: any, draft: any): Promise<{
  correction: any
  targetJob: any
  targetDetails: any
} | null> {
  const { data: correction, error: correctionError } = await client
    .from('makesafe_intake_source_authority_corrections')
    .select('org_id, source_post_id, target_job_id, correction_kind, expected_identity_key')
    .eq('org_id', draft.org_id)
    .eq('source_post_id', draft.graph_message_id)
    .eq('correction_kind', 'existing_job_binding')
    .maybeSingle()
  if (correctionError) {
    throw new Error(`existing_job_binding_reconciliation_required: correction lookup failed: ${correctionError.message || correctionError}`)
  }
  if (!correction) return null

  const [{ data: targetJob, error: jobError }, { data: targetDetails, error: detailsError }] = await Promise.all([
    client.from('jobs')
      .select('*')
      .eq('id', correction.target_job_id)
      .maybeSingle(),
    client.from('makesafe_job_details')
      .select('job_id, external_ref, requesting_company_slug, requesting_company_name, report_type, substatus')
      .eq('job_id', correction.target_job_id)
      .maybeSingle(),
  ])
  if (jobError || detailsError || !targetJob || !targetDetails) {
    throw new Error(
      `existing_job_binding_reconciliation_required: guarded target could not be loaded: ${
        jobError?.message || detailsError?.message || 'missing job/details'
      }`,
    )
  }
  return { correction, targetJob, targetDetails }
}

async function approveIntakeDraft(client: any, body: any) {
  const { draft_id, approved_by } = body
  if (!draft_id) throw new Error('draft_id required')

  // Load the draft for its field data (extraction/reviewed values below need draft.*).
  const { data: draft, error: dErr } = await client.from('makesafe_intake_drafts')
    .select('*').eq('id', draft_id).single()
  if (dErr || !draft) throw new Error('Draft not found')

  let extraction = parseJsonObject(draft.extraction_json)
  const ajPrefill = _deriveAjIntakePrefill({
    fromEmail: draft.from_email,
    subject: draft.subject,
    bodyText: extraction.builder_email_text_for_trade || draft.body_preview,
  })
  extraction = _applyAjIntakePrefill(extraction, ajPrefill).extraction
  const reviewed = parseJsonObject(body.reviewed_fields || body.reviewedFields || {})
  const reviewedReportType = cleanReviewedString(reviewed.report_type)
  if (reviewedReportType && !_isReportOnlyType(reviewedReportType)) {
    throw new ApiError(`reviewed report_type must be 'roof_report' or 'assessment_report', got '${reviewedReportType}'`, 400)
  }
  const reviewedFamily = cleanReviewedString(reviewed.makesafe_job_family)
  if (reviewedFamily && !RECONCILE_MAKESAFE_FAMILIES.has(reviewedFamily)) {
    throw new ApiError(`invalid reviewed makesafe_job_family '${reviewedFamily}'`, 400)
  }
  // A privileged reviewer may carry exact document evidence the degraded parser
  // could not read. That explicit report type wins over the stored fallback while
  // the existing automatic path remains unchanged when no override is supplied.
  const effectiveReportType = reviewedReportType || effectiveIntakeReportType(draft)
  const isReportOnlyDraft = _isReportOnlyType(effectiveReportType)
  // Item 3b — combined make-safe + report AUTO-SPLIT. When the draft carries an
  // UNAMBIGUOUS secondary report obligation, approval creates TWO cards: the PRIMARY
  // is the physical make-safe (WO PDF attached, normal workflow) and a SEPARATE
  // report-only card is minted below. So the primary is forced non-report-only here
  // even if the draft's own report_type is roof/assessment — otherwise the WO would
  // never attach and the physical make-safe would be lost.
  const splitObligation = combinedSplitObligation(extraction)
  const primaryIsReportOnly = splitObligation ? false : isReportOnlyDraft
  assertReviewedFamilyConsistency(reviewedFamily, effectiveReportType, !!splitObligation, primaryIsReportOnly)
  const choose = (key: string, fallback: any = null) => cleanReviewedString(reviewed[key]) || cleanReviewedString(draft[key]) || cleanReviewedString(extraction[key]) || cleanReviewedString(fallback)

  const approvedFields = {
    requesting_company_slug: choose('requesting_company_slug'),
    requesting_company_name: choose('requesting_company_name'),
    external_ref: choose('external_ref'),
    client_name: choose('client_name'),
    client_phone: choose('client_phone'),
    client_email: choose('client_email'),
    site_address: choose('site_address'),
    site_suburb: choose('site_suburb'),
    makesafe_type: choose('makesafe_type') || choose('job_type_detail') || choose('makesafe_type_detail'),
    description: choose('description') || choose('wo_summary') || cleanReviewedString(draft.body_preview),
    safety_requirements: choose('safety_requirements'),
    special_instructions: choose('special_instructions'),
  }

  const attachments = parseJsonArray(draft.attachments_json)
  // BUG 2 (CAPTURE): require a SERVABLE work-order PDF, not merely an attachments_json
  // entry. The intake scan now records a flagged entry (pdf_unavailable=true, null
  // URLs) when the re-upload to job-documents fails; that entry must NOT satisfy the
  // work_order_pdf requirement, or a make-safe job could be approved with no openable
  // WO document (the attach step below skips entries with no URL). Count only entries
  // with a usable pdf_url/storage_url and not flagged unavailable.
  const availableAttachments = (attachments || []).filter(
    (a: any) => a && !a.pdf_unavailable && (a.pdf_url || a.storage_url),
  )
  const missing: string[] = []
  if (!approvedFields.requesting_company_slug && !approvedFields.requesting_company_name) missing.push('requesting_company')
  if (!approvedFields.external_ref) missing.push('external_ref')
  if (!approvedFields.client_name) missing.push('client_name')
  if (!approvedFields.site_address) missing.push('site_address')
  if (!primaryIsReportOnly && availableAttachments.length === 0) missing.push('work_order_pdf')
  if (missing.length > 0) throw new Error('Cannot approve intake draft; missing required fields: ' + missing.join(', '))

  // On a combined split the primary is a PHYSICAL make-safe: don't inherit the
  // draft's roof/assessment family (that belongs to the secondary report card).
  const approvedJobFamily = reviewedFamily || (splitObligation
    ? _classifyMakeSafeJobFamily(
      draft?.subject || approvedFields.external_ref || '',
      [extraction?.builder_email_text_for_trade, approvedFields.description, approvedFields.makesafe_type].filter(Boolean).join('\n'),
      null,
    )
    : extraction?.makesafe_job_family || _classifyMakeSafeJobFamily(
    draft?.subject || approvedFields.external_ref || '',
    [
      extraction?.builder_email_text_for_trade,
      approvedFields.description,
      approvedFields.makesafe_type,
    ].filter(Boolean).join('\n'),
    effectiveReportType || null,
  ))
  const approvedJobFamilyKey = _normaliseDedupJobFamily(approvedJobFamily)

  // A guarded source correction means the operational job already exists. The
  // review gate must link this exact source to that job instead of running the
  // duplicate guard or minting another case. The inverse guard below proves the
  // source-derived AJ identity, reviewed values and one live target all agree.
  // Cancelled/void targets fail closed, so SWMS-261054 can never be revived.
  const existingJobBinding = await loadExistingJobBindingForDraft(client, draft)
  if (existingJobBinding) {
    _assertAjExistingJobBinding({
      correction: existingJobBinding.correction,
      draft,
      prefill: ajPrefill,
      approvedFields,
      approvedJobFamily,
      targetJob: existingJobBinding.targetJob,
      targetDetails: existingJobBinding.targetDetails,
    })

    const claimedAt = new Date().toISOString()
    const { data: claimed, error: claimErr } = await client.from('makesafe_intake_drafts')
      .update({ status: 'approved', updated_at: claimedAt })
      .eq('id', draft_id)
      .in('status', ['needs_review', 'draft'])
      .select()
    if (claimErr) throw claimErr
    if (!claimed || claimed.length === 0) {
      throw new Error('Draft is not in a reviewable state (needs_review/draft) - already approved, rejected, or superseded; concurrent approval blocked')
    }

    const { error: linkError } = await client.from('makesafe_intake_drafts').update({
      approved_job_id: existingJobBinding.targetJob.id,
      approved_at: claimedAt,
      approved_by: approved_by || null,
      review_notes: body.review_notes || body.reviewNotes ||
        `Linked by guarded source authority correction to existing ${existingJobBinding.targetJob.job_number}.`,
      requesting_company_slug: approvedFields.requesting_company_slug,
      requesting_company_name: approvedFields.requesting_company_name,
      external_ref: approvedFields.external_ref,
      client_name: approvedFields.client_name,
      client_phone: approvedFields.client_phone,
      client_email: approvedFields.client_email,
      site_address: approvedFields.site_address,
      site_suburb: approvedFields.site_suburb,
      description: approvedFields.description,
      safety_requirements: approvedFields.safety_requirements,
      special_instructions: approvedFields.special_instructions,
      report_type: effectiveReportType || draft.report_type || null,
      extraction_json: extraction,
      updated_at: claimedAt,
    }).eq('id', draft_id)
    if (linkError) {
      try {
        await client.from('makesafe_intake_drafts')
          .update({ status: 'needs_review', updated_at: new Date().toISOString() })
          .eq('id', draft_id)
      } catch (_) { /* best-effort; no job was created */ }
      throw linkError
    }

    return {
      ok: true,
      job: existingJobBinding.targetJob,
      draft_id,
      approved_fields: approvedFields,
      report_type: effectiveReportType || null,
      linked_existing_job: true,
      existing_job_binding_identity: existingJobBinding.correction.expected_identity_key,
      secondary_job: null,
      split_combined: false,
      job_ids: [existingJobBinding.targetJob.id],
    }
  }

  // Duplicate guard (Wave 0 H4): warn/block same external ref already live before
  // creating another job. Compare NORMALISED refs (the shared reconciler normaliser)
  // so "AJBR 67200", "AJBR-67200" and "AJBR67200" all collapse to one canonical key
  // rather than relying on near-exact ilike. When there is genuinely no match, this
  // is a no-op and distinct refs still pass.
  if (approvedFields.external_ref) {
    const prefixes = await loadRefPrefixes(client)
    const normTarget = canonicalExternalObligationRef(approvedFields.external_ref, prefixes)
    if (normTarget) {
      // makesafe_job_details is small (make-safe jobs only), so a bounded scan of
      // the refs already on live jobs is cheap and lets us match on normalised form.
      const approvedCompanyKey = canonicalCompanyDedupeKey(approvedFields.requesting_company_slug || approvedFields.requesting_company_name)
      const approvedWorkOrderIdentity = _workOrderIdentityKey(
        extraction?.builder_work_order_number,
        extraction?.builder_po_number,
      )
      // Shared PO-core boundary (mirrors readExistingObligationJobs): a distinct
      // explicit PO must never be false-blocked even when only ONE side proves a
      // WO/PO pair. The approved PO comes from the explicit fields; the existing
      // PO falls back to the composite recovery ref (MLB-26537PO-56922) when the
      // live job stored the PO only in external_ref, not in job metadata.
      const approvedPoCore = canonicalObligationPoCore(extraction?.builder_po_number)
        || canonicalObligationPoCore(extraction?.builder_work_order_number, true)
        || canonicalObligationPoCore(approvedFields.external_ref, true)
      const { data: candidates } = await client.from('makesafe_job_details')
        .select('job_id, external_ref, requesting_company_slug, requesting_company_name, report_type, jobs(job_number, client_name, site_address, status, metadata, notes)')
        .not('external_ref', 'is', null)
      const dup = (candidates || []).find((row: any) => {
        if (canonicalExternalObligationRef(row.external_ref, prefixes) !== normTarget) return false
        const existingCompanyKey = canonicalCompanyDedupeKey(row.requesting_company_slug || row.requesting_company_name)
        // Known-company approvals must only block against the same known company.
        // If either side lacks company metadata, fail open to the review queue
        // rather than silently suppress a different builder's same-number ref.
        if (!approvedCompanyKey || !existingCompanyKey || approvedCompanyKey !== existingCompanyKey) return false
        const existingJob = Array.isArray(row.jobs) ? row.jobs[0] : row.jobs
        // A cancelled/void/superseded job is a dead obligation; it must not block
        // a later genuine re-issue of the same claim/PO (mirrors the runtime
        // obligation dedupe boundary in makesafe_deterministic_intake_runtime.ts).
        if (['cancelled','canceled','void','voided','superseded'].includes(String(existingJob?.status || '').trim().toLowerCase())) return false
        const existingMetadata = parseJsonObject(existingJob?.metadata)
        const existingWorkOrderIdentity = _workOrderIdentityKey(
          existingMetadata.builder_work_order_number,
          existingMetadata.builder_po_number,
        )
        // PR 338/339 identity invariant: one claim/reference can carry multiple
        // distinct PO-backed instructions. A different proven WO/PO is not a
        // duplicate even when the display ref and family match.
        if (
          approvedWorkOrderIdentity && existingWorkOrderIdentity &&
          approvedWorkOrderIdentity !== existingWorkOrderIdentity
        ) return false
        const existingPoCore = canonicalObligationPoCore(existingMetadata.builder_po_number)
          || canonicalObligationPoCore(existingMetadata.builder_work_order_number, true)
          || canonicalObligationPoCore(row.external_ref, true)
        if (approvedPoCore && existingPoCore && approvedPoCore !== existingPoCore) return false
        const existingFamily = existingMetadata.makesafe_job_family || _classifyMakeSafeJobFamily(
          row.external_ref || '',
          [row.report_type, existingJob?.notes].filter(Boolean).join('\n'),
          row.report_type || null,
        )
        const existingFamilyKey = _normaliseDedupJobFamily(existingFamily)
        return !existingFamilyKey || existingFamilyKey === approvedJobFamilyKey
      })
      if (dup?.job_id) {
        const existingJob = Array.isArray(dup.jobs) ? dup.jobs[0] : dup.jobs
        throw new Error('Possible duplicate: ref ' + approvedFields.external_ref + ' already exists on ' + (existingJob?.job_number || dup.job_id) + ' for the same MakeSafe job family')
      }
    }
  }

  // Atomic claim (Wave 0 C3, TOCTOU): claim the draft BEFORE creating the job so two
  // concurrent approvals cannot both create a live job. The status CHECK constraint
  // (migration 20260602000001) only permits draft/needs_review/approved/rejected/
  // superseded -- there is NO 'approving' value -- so we claim DIRECTLY to 'approved'
  // gated on the current reviewable status, and drop the separate final status write
  // (the audit fields are still written below). A draft may legitimately be approved
  // from either 'needs_review' or 'draft', so the claim allows both (the narrowest
  // set that does not break the happy path); any other current status (approved,
  // approving-n/a, rejected, superseded) yields zero rows -> concurrent/invalid block.
  const { data: claimed, error: claimErr } = await client.from('makesafe_intake_drafts')
    .update({ status: 'approved', updated_at: new Date().toISOString() })
    .eq('id', draft_id)
    .in('status', ['needs_review', 'draft'])
    .select()
  if (claimErr) throw claimErr
  if (!claimed || claimed.length === 0) {
    throw new Error('Draft is not in a reviewable state (needs_review/draft) - already approved, rejected, or superseded; concurrent approval blocked')
  }

  // Failure-safety (Wave 0 C3 + auditor concern 2): everything from job creation
  // through the audit-field write runs inside this try. On failure we must avoid two
  // hazards: (a) stranding the claimed draft forever, and (b) creating an ORPHAN
  // double-create. The naive "always reset to needs_review on error" is unsafe: if
  // createMakesafeJob already inserted a LIVE job but a LATER step throws, resetting
  // the draft to needs_review would make it re-approvable and spawn a SECOND live job
  // for the same draft. So we track whether the job was created and branch:
  //   - job NOT yet created  -> safe to release the claim back to needs_review.
  //   - job ALREADY created  -> leave status 'approved', best-effort stamp the orphan
  //     job id (approved_job_id) so the row points at the real job for reconciliation,
  //     and do NOT re-queue it. A later step failing (audit update / doc attach) is
  //     non-fatal to the job itself; the job exists and the draft stays approved.
  let createdJobId: string | null = null
  try {
    // Create the make-safe job using reviewed/edited fields, not stale extraction data.
    // Preserve builder email source context for EVERY family so board/trade users can
    // see original instructions, links, and received timestamps after approval. For
    // report-only drafts, the same source links also support the report/quote workflow
    // and the job is advanced to ready_to_invoice below.
    const portalLinks = _normalizeReportExternalLinks(extraction)
    const sourceExternalLinks = portalLinks.length ? portalLinks : null
    const jobResult = await createMakesafeJob(client, {
      client_name: approvedFields.client_name,
      site_address: approvedFields.site_address,
      suburb: approvedFields.site_suburb,
      phone: approvedFields.client_phone,
      email: approvedFields.client_email,
      requesting_company_slug: approvedFields.requesting_company_slug,
      requesting_company_name: approvedFields.requesting_company_name,
      external_ref: approvedFields.external_ref,
      description: approvedFields.description,
      makesafe_type: approvedFields.makesafe_type,
      safety_requirements: approvedFields.safety_requirements,
      special_instructions: approvedFields.special_instructions,
      makesafe_job_family: approvedJobFamily,
      makesafe_job_family_label: _makeSafeJobFamilyLabel(approvedJobFamily),
      suppress_notifications: true,
      ...(sourceExternalLinks ? { external_links: sourceExternalLinks } : {}),
      builder_email_text_for_trade: extraction?.builder_email_text_for_trade || null,
      builder_email_subject: extraction?.builder_email_subject || draft?.subject || null,
      builder_email_received_at: extraction?.builder_email_received_at || draft?.received_at || null,
      builder_claim_ref: extraction?.builder_claim_ref || null,
      builder_work_order_number: extraction?.builder_work_order_number || null,
      builder_po_number: extraction?.builder_po_number || null,
      // Deterministic intake and privileged reconciliation own no communications.
      // The reviewed path must opt in explicitly; routine callers cannot reach the
      // approval route and therefore cannot abuse this suppression flag.
      suppress_manager_notification: body?.suppress_manager_notification === true ||
        extraction?.deterministic_intake === true,
    })
    // Record the live job id the instant it exists so the catch path can tell a
    // pre-insert failure (safe to re-queue) from a post-insert failure (orphan risk).
    createdJobId = jobResult?.job?.id || null

    // For report-only jobs: set report_type on makesafe_job_details and advance
    // substatus to ready_to_invoice (bypasses the report-production stage). A combined
    // split's PRIMARY is a physical make-safe (primaryIsReportOnly=false), so it skips
    // this and keeps the normal make-safe workflow; the report card is minted below.
    if (primaryIsReportOnly && createdJobId) {
      try {
        await client.from('makesafe_job_details').update({
          report_type: effectiveReportType,
          // Reconciliation of still-owed work starts unsubmitted. The legacy path
          // retains its current ready_to_invoice behaviour unless the privileged
          // caller explicitly supplies report_unsubmitted=true.
          ...(body?.report_unsubmitted === true ? {} : { substatus: 'ready_to_invoice' }),
          updated_at: new Date().toISOString(),
        }).eq('job_id', createdJobId)
      } catch (e: any) {
        console.log('[ops-api] approveIntakeDraft: report_type/substatus update non-blocking:', e?.message)
      }
    }

    // Link draft to created job and preserve the reviewed values on the draft audit
    // row. Status was already set to 'approved' by the atomic claim above, so this
    // update writes only the audit/linkage fields (no redundant status write).
    await client.from('makesafe_intake_drafts').update({
      approved_job_id: jobResult.job.id,
      approved_at: new Date().toISOString(),
      approved_by: approved_by || null,
      review_notes: body.review_notes || body.reviewNotes || 'Approved in Ops intake review gate after PDF/source comparison.',
      requesting_company_slug: approvedFields.requesting_company_slug,
      requesting_company_name: approvedFields.requesting_company_name,
      external_ref: approvedFields.external_ref,
      client_name: approvedFields.client_name,
      client_phone: approvedFields.client_phone,
      client_email: approvedFields.client_email,
      site_address: approvedFields.site_address,
      site_suburb: approvedFields.site_suburb,
      description: approvedFields.description,
      safety_requirements: approvedFields.safety_requirements,
      special_instructions: approvedFields.special_instructions,
      report_type: effectiveReportType || draft.report_type || null,
      updated_at: new Date().toISOString(),
    }).eq('id', draft_id)

    // Attach any PDF attachments from the original email as visible work orders.
    // Report-only jobs have no WO PDF — skip the attach loop for them. A combined
    // split attaches the WO to the physical make-safe primary here (and shares it
    // onto the report card below).
    if (!primaryIsReportOnly || body?.attach_work_order_for_report === true) {
      for (const att of attachments) {
        if (att.storage_url || att.pdf_url) {
          try {
            await client.from('job_documents').insert({
              job_id: jobResult.job.id,
              type: 'work_order',
              file_name: att.file_name || att.name || 'work-order.pdf',
              storage_url: att.storage_url || att.pdf_url,
              pdf_url: att.pdf_url || att.storage_url,
              visible_to_trades: true,
            })
          } catch (_) { /* non-blocking */ }
        }
      }
    }

    // ── Item 3b: mint the SECOND card (the report obligation) ────────────────
    // A combined make-safe + report is now expanded into TWO live cards instead of
    // holding for human review: the physical make-safe (created above) PLUS this
    // report-only card of the correct kind, sharing the same ref + WO PDF and
    // cross-linked. Non-fatal: the primary already exists, so a secondary failure is
    // logged and the primary stands (never a double-primary).
    let secondaryJob: any = null
    if (splitObligation && createdJobId) {
      try {
        const reportFamily = splitObligation.reportType === 'assessment_report'
          ? 'assessment_report_quote'
          : splitObligation.reportType
        const secondaryResult = await createMakesafeJob(client, {
          client_name: approvedFields.client_name,
          site_address: approvedFields.site_address,
          suburb: approvedFields.site_suburb,
          phone: approvedFields.client_phone,
          email: approvedFields.client_email,
          requesting_company_slug: approvedFields.requesting_company_slug,
          requesting_company_name: approvedFields.requesting_company_name,
          external_ref: approvedFields.external_ref,
          description: approvedFields.description,
          safety_requirements: approvedFields.safety_requirements,
          special_instructions: approvedFields.special_instructions,
          makesafe_job_family: reportFamily,
          makesafe_job_family_label: _makeSafeJobFamilyLabel(reportFamily),
          suppress_notifications: true,
          ...(sourceExternalLinks ? { external_links: sourceExternalLinks } : {}),
          builder_email_text_for_trade: extraction?.builder_email_text_for_trade || null,
          builder_email_subject: extraction?.builder_email_subject || draft?.subject || null,
          builder_email_received_at: extraction?.builder_email_received_at || draft?.received_at || null,
          builder_claim_ref: extraction?.builder_claim_ref || null,
          builder_work_order_number: extraction?.builder_work_order_number || null,
          builder_po_number: extraction?.builder_po_number || null,
          suppress_manager_notification: body?.suppress_manager_notification === true ||
            extraction?.deterministic_intake === true,
        })
        secondaryJob = secondaryResult?.job || null
        if (secondaryJob?.id) {
          // Report card carries its report_type. Do NOT auto-advance substatus — a
          // fresh report is unsubmitted; advancing to ready_to_invoice here would be
          // the exact unverified-advance hazard (request item 14). It starts at the
          // default company_contact_required and moves through the report workflow.
          try {
            await client.from('makesafe_job_details').update({
              report_type: splitObligation.reportType,
              updated_at: new Date().toISOString(),
            }).eq('job_id', secondaryJob.id)
          } catch (_) { /* non-blocking */ }
          // Share the WO PDF onto the report card for on-site context.
          for (const att of attachments) {
            if (att.storage_url || att.pdf_url) {
              try {
                await client.from('job_documents').insert({
                  job_id: secondaryJob.id,
                  type: 'work_order',
                  file_name: att.file_name || att.name || 'work-order.pdf',
                  storage_url: att.storage_url || att.pdf_url,
                  pdf_url: att.pdf_url || att.storage_url,
                  visible_to_trades: true,
                })
              } catch (_) { /* non-blocking */ }
            }
          }
          // Cross-link the pair (metadata sibling refs + a job_events note each) so
          // the board/trade view can see they came from one combined work order.
          await _crossLinkCombinedCards(
            client,
            { id: jobResult.job.id, number: jobResult.job.job_number, role: 'make_safe' },
            { id: secondaryJob.id, number: secondaryJob.job_number, role: splitObligation.reportType },
          )
        }
      } catch (splitErr) {
        console.error('[ops-api] approveIntakeDraft: combined split — secondary report card creation failed (primary stands):', (splitErr as Error).message)
      }
    }

    return {
      ok: true,
      job: jobResult.job,
      draft_id,
      approved_fields: approvedFields,
      report_type: effectiveReportType || null,
      // Item 3b: both card ids so the auto-approval evidence event can log the split.
      secondary_job: secondaryJob,
      split_combined: !!secondaryJob,
      job_ids: secondaryJob ? [jobResult.job.id, secondaryJob.id] : [jobResult.job.id],
    }
  } catch (postClaimErr) {
    if (!createdJobId) {
      // Pre-insert failure: no live job exists, so release the claim back to the
      // review queue. This is the only safe path to re-queue a draft.
      try {
        await client.from('makesafe_intake_drafts')
          .update({ status: 'needs_review', updated_at: new Date().toISOString() })
          .eq('id', draft_id)
      } catch (_) { /* best-effort; do not mask the original error */ }
    } else {
      // Post-insert failure: a LIVE job already exists. Do NOT re-queue (that would
      // double-create). Leave status 'approved' and best-effort point the draft at the
      // orphan job so reconciliation can find it. The job itself is fine; only a later
      // audit/attach step failed.
      try {
        await client.from('makesafe_intake_drafts')
          .update({ status: 'approved', approved_job_id: createdJobId, updated_at: new Date().toISOString() })
          .eq('id', draft_id)
      } catch (_) { /* best-effort; do not mask the original error */ }
    }
    throw postClaimErr
  }
}

// ── Slice 7: reject intake draft ──
async function rejectIntakeDraft(client: any, body: any) {
  const { draft_id, rejected_by, review_notes } = body
  if (!draft_id) throw new Error('draft_id required')

  const { data, error } = await client.from('makesafe_intake_drafts')
    .update({
      status: 'rejected',
      rejected_at: new Date().toISOString(),
      rejected_by: rejected_by || null,
      review_notes: review_notes || null,
      updated_at: new Date().toISOString(),
    })
    .eq('id', draft_id)
    .select()
    .single()
  if (error) throw error
  return { ok: true, draft: data }
}

// ── Slice 7: create intake draft (from agent/email parser) ──
async function createIntakeDraft(client: any, body: any) {
  const {
    mailbox, graph_message_id, internet_message_id, conversation_id,
    received_at, from_email, from_name, subject, body_preview,
    requesting_company_slug, requesting_company_name, external_ref,
    client_name, client_phone, client_email, site_address, site_suburb,
    description, safety_requirements, special_instructions,
    confidence, missing_fields, extraction_json, attachments_json,
  } = body

  if (!graph_message_id) throw new Error('graph_message_id required')

  const { data, error } = await client.from('makesafe_intake_drafts').insert({
    org_id: DEFAULT_ORG_ID,
    mailbox: mailbox || 'ses@secureworkswa.com.au',
    graph_message_id,
    internet_message_id: internet_message_id || null,
    conversation_id: conversation_id || null,
    received_at: received_at || new Date().toISOString(),
    from_email: from_email || null,
    from_name: from_name || null,
    subject: subject || null,
    body_preview: body_preview || null,
    requesting_company_slug: requesting_company_slug || null,
    requesting_company_name: requesting_company_name || null,
    external_ref: external_ref || null,
    client_name: client_name || null,
    client_phone: client_phone || null,
    client_email: client_email || null,
    site_address: site_address || null,
    site_suburb: site_suburb || null,
    description: description || null,
    safety_requirements: safety_requirements || null,
    special_instructions: special_instructions || null,
    confidence: confidence || 'low',
    missing_fields: missing_fields || [],
    extraction_json: extraction_json || {},
    attachments_json: attachments_json || [],
  }).select().single()

  if (error) throw error
  return { ok: true, draft: data }
}

// ── GAP-C: recapture_intake_draft ─────────────────────────────────────────────
// Mission: makesafe-wo-capture-recovery-2026-06-17
//
// Resolves a stale/rejected intake draft (usually created by the OLD user-mailbox
// path, which had a raw ~150-char graph_message_id that blew the storage key limit)
// to the GROUP-SYNC projection email, re-captures the WO PDF with the new unique
// key, and inserts a fresh reviewable draft.
//
// DRAFTS ONLY. Never calls approve / createMakesafeJob / invoice / send.
// NOT routine-callable (omitted from ROUTINE_ALLOWED_ACTIONS, default-deny fires).
// Privilege gate is identical to approve_intake_draft: api_key OR admin/owner JWT.
async function recaptureIntakeDraft(client: any, body: any, adminClientOverride?: any) {
  const { draft_id } = body
  if (!draft_id) throw new Error('draft_id required')

  // adminClientOverride is a test-only seam; production callers omit it and get
  // the service-role client (SUPABASE_URL/SERVICE_KEY are module consts, so a test
  // cannot supply them via env.set after import).
  const adminClient = adminClientOverride ?? createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)
  const SES_MAILBOX = _SES_MAILBOX

  // 1. Load the existing draft.
  const { data: draft, error: draftErr } = await client.from('makesafe_intake_drafts')
    .select('*').eq('id', draft_id).single()
  if (draftErr || !draft) throw new Error('Draft not found')

  // 2. Resolve the group email row.
  // If the draft was already created by the group-sync path (mailbox == ses@),
  // use its graph_message_id directly as the group post_id.
  // Otherwise (old user-mailbox path) resolve via normalised ref+company+received_at window.
  let groupPostId: string | null = null

  if (draft.mailbox === SES_MAILBOX && draft.graph_message_id) {
    // Already a group-sync draft. Verify the group post still exists in emails.
    const { data: emailRow } = await client.from('emails')
      .select('post_id').eq('post_id', draft.graph_message_id).maybeSingle()
    if (emailRow) groupPostId = emailRow.post_id
  }

  if (!groupPostId) {
    // OLD-path draft (user-mailbox graph_message_id) OR the direct lookup failed.
    // Bridge: find the group projection row by (normalised ref + company + received_at window +/- 2 days).
    const normRef = _normaliseDedupRef(draft.external_ref)
    const normCompany = _normaliseDedupCompany(draft.requesting_company_slug, draft.requesting_company_name)

    if (!normRef) {
      return {
        ok: true,
        recaptured: false,
        reason: 'no_ref_to_bridge',
        detail: 'The draft has no external_ref to search by. Cannot resolve group email row.',
      }
    }

    // Fetch group-sync candidates in a +/- 2-day window around the draft's received_at.
    const receivedAt = draft.received_at ? new Date(draft.received_at) : new Date()
    const windowStart = new Date(receivedAt.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString()
    const windowEnd = new Date(receivedAt.getTime() + 2 * 24 * 60 * 60 * 1000).toISOString()

    const { data: candidates } = await client.from('emails')
      .select('post_id, from_email, subject, received_at, has_attachments')
      .eq('mailbox', SES_MAILBOX)
      .is('pii_purged_at', null)
      .gte('received_at', windowStart)
      .lte('received_at', windowEnd)
      .order('post_id', { ascending: true })  // deterministic DB order; JS sort finalises

    // Bridge scoring: the external_ref match is MANDATORY (min score threshold = REF_SCORE).
    // A company-only match (no ref in subject) does NOT qualify — we must not bridge on
    // company + has_attachments alone (could pick any in-window email from the same sender).
    const REF_SCORE = 10  // score awarded when the ref appears in the subject
    const MIN_THRESHOLD = REF_SCORE  // bridge requires at minimum a ref match

    type GroupMatch = { email: any; score: number; deltaMs: number }
    const matches: GroupMatch[] = []
    for (const email of (candidates || [])) {
      let score = 0
      const subjectLower = (email.subject || '').toLowerCase()
      const normRefLower = normRef.toLowerCase()
      // Ref match is MANDATORY: the normalised ref OR the raw external_ref must appear in the subject.
      if (subjectLower.includes(normRefLower) ||
          (draft.external_ref && subjectLower.includes(draft.external_ref.toLowerCase()))) {
        score += REF_SCORE
      }
      // Ref match is required — do not score company/attachment-only candidates.
      if (score < MIN_THRESHOLD) continue
      // Bonus: company name/slug appears in the from_email (corroborating signal).
      if (normCompany && (email.from_email || '').toLowerCase().includes(normCompany)) {
        score += 5
      }
      // The email must have attachments to be a WO candidate.
      if (email.has_attachments) score += 2
      const delta = Math.abs(new Date(email.received_at).getTime() - receivedAt.getTime())
      matches.push({ email, score, deltaMs: delta })
    }

    if (matches.length > 0) {
      // Sort: (score desc, received_at proximity asc, post_id asc) — fully deterministic.
      matches.sort((a, b) =>
        b.score - a.score ||
        a.deltaMs - b.deltaMs ||
        (a.email.post_id < b.email.post_id ? -1 : a.email.post_id > b.email.post_id ? 1 : 0)
      )
      groupPostId = matches[0].email.post_id
    } else {
      // No candidate cleared the ref-match threshold — return B1-flag path.
      // Falls through to the !groupPostId block below.
    }
  }

  if (!groupPostId) {
    // No group email row found. Produce a B1-flag draft (visible, not silent no-op).
    const flagDraft = {
      org_id: DEFAULT_ORG_ID,
      mailbox: SES_MAILBOX,
      graph_message_id: `recapture:no_group_email:${draft_id}`,
      received_at: draft.received_at,
      from_email: draft.from_email,
      from_name: draft.from_name,
      subject: draft.subject,
      body_preview: draft.body_preview,
      requesting_company_slug: draft.requesting_company_slug,
      requesting_company_name: draft.requesting_company_name,
      external_ref: draft.external_ref,
      client_name: draft.client_name,
      client_phone: draft.client_phone,
      site_address: draft.site_address,
      site_suburb: draft.site_suburb,
      description: draft.description,
      confidence: draft.confidence || 'low',
      missing_fields: ['work_order_pdf', 'group_email_not_found'],
      extraction_json: draft.extraction_json || {},
      attachments_json: [{
        name: 'work-order',
        file_name: null,
        storage_url: null,
        pdf_url: null,
        pdf_unavailable: true,
        pdf_error: 'portal_link_or_oversize_needs_review',
        size: null,
      }],
      status: 'draft',
    }
    const { data: flagInserted, error: flagErr } = await client.from('makesafe_intake_drafts')
      .insert(flagDraft).select().single()
    if (flagErr) {
      console.log('[ops-api] recapture flag-draft insert failed:', flagErr.message)
    }
    return {
      ok: true,
      recaptured: false,
      reason: 'no_group_email_found',
      flag_draft_id: flagInserted?.id || null,
    }
  }

  // 3. Check if a LIVE draft already exists for this group post_id (idempotency).
  const { data: existingLive } = await client.from('makesafe_intake_drafts')
    .select('id, status')
    .eq('org_id', DEFAULT_ORG_ID)
    .eq('graph_message_id', groupPostId)
    .in('status', _LIVE_DRAFT_STATES as unknown as string[])
    .maybeSingle()
  if (existingLive) {
    return {
      ok: true,
      recaptured: false,
      reason: 'live_draft_exists',
      existing_draft_id: existingLive.id,
    }
  }

  // 3b. Refuse to create a duplicate draft when a live make-safe JOB already covers
  //     this ref (e.g. a human created the job directly via sw_create_makesafe_job,
  //     bypassing intake entirely). Attaching to the job is a human/General GATE-2
  //     recovery action — recapture must NOT auto-attach or create a redundant draft.
  if (draft.external_ref) {
    const normDraftRef = _normaliseDedupRef(draft.external_ref)
    const normDraftCompany = _normaliseDedupCompany(
      draft.requesting_company_slug,
      draft.requesting_company_name,
    )
    if (normDraftRef) {
      const { data: jobRows } = await client.from('makesafe_job_details')
        .select('job_id, external_ref, requesting_company_slug, requesting_company_name')
        .not('external_ref', 'is', null)
      for (const jobRow of (jobRows || [])) {
        if (!jobRow.external_ref || _normaliseDedupRef(jobRow.external_ref) !== normDraftRef) continue
        const normJobCompany = _normaliseDedupCompany(
          jobRow.requesting_company_slug,
          jobRow.requesting_company_name,
        )
        if (normDraftCompany && normJobCompany && normDraftCompany === normJobCompany) {
          return {
            ok: true,
            recaptured: false,
            reason: 'live_job_exists',
            existing_job_id: jobRow.job_id,
          }
        }
      }
    }
  }

  // 4. Capture PDFs from the group post's uploaded attachments (same logic as scanSesMakesafes).
  const recaptureAttachments: any[] = []
  try {
    const { data: attRows } = await client.from('email_attachments')
      .select('id, graph_attachment_id, name, content_type, storage_path, size_bytes')
      .eq('email_id', groupPostId)
      .eq('status', 'uploaded')

    const uploadedPdfRows = (attRows || []).filter((att: any) => {
      const isPdf = (att.content_type || '').includes('pdf') || (att.name || '').endsWith('.pdf')
      return isPdf && att.storage_path
    })

    const { selected: designatedWo, ordered: orderedPdfs } = _selectWorkOrderPdf(uploadedPdfRows)
    const keyHash = await _shortStorageKey(groupPostId)

    for (let attIdx = 0; attIdx < orderedPdfs.length; attIdx++) {
      const att = orderedPdfs[attIdx]
      try {
        const { data: blob, error: dlErr } = await adminClient.storage
          .from('makesafe-emails')
          .download(att.storage_path!)
        if (dlErr || !blob) {
          console.log('[ops-api] recapture PDF download failed:', dlErr?.message || 'no blob', att.storage_path)
          continue
        }
        const fileBuffer = new Uint8Array(await blob.arrayBuffer())
        const safeName = (att.name || 'work-order.pdf').replace(/[^a-zA-Z0-9._-]/g, '_').slice(-80)
        const keyComponent = _attachmentKeyComponent(att, attIdx)
        const storagePath = `makesafe-intake/${keyHash}-${keyComponent}/${safeName}`
        const { error: upErr } = await adminClient.storage
          .from('job-documents')
          .upload(storagePath, fileBuffer, { contentType: 'application/pdf', upsert: true })
        if (upErr) {
          console.log('[ops-api] recapture upload failed:', upErr.message, storagePath)
          recaptureAttachments.push({
            name: att.name,
            file_name: att.name,
            storage_url: null,
            pdf_url: null,
            pdf_unavailable: true,
            pdf_error: `upload_failed:${upErr.message}`.slice(0, 200),
            size: att.size_bytes,
            is_work_order: (att === designatedWo),
          })
          continue
        }
        const { data: urlData } = adminClient.storage.from('job-documents').getPublicUrl(storagePath)
        recaptureAttachments.push({
          name: att.name,
          file_name: att.name,
          storage_url: storagePath,
          pdf_url: urlData?.publicUrl || null,
          size: att.size_bytes,
          is_work_order: (att === designatedWo),
        })
      } catch (e) {
        console.log('[ops-api] recapture PDF re-upload failed:', (e as Error).message)
      }
    }
  } catch (e) {
    console.log('[ops-api] recapture attachment read failed:', (e as Error).message)
  }

  // 5. Determine status for the fresh draft.
  const recaptureAvailableCount = recaptureAttachments.filter(
    (a: any) => a && !a.pdf_unavailable && (a.pdf_url || a.storage_url),
  ).length
  const freshStatus = recaptureAvailableCount > 0 ? 'needs_review' : 'draft'

  // 6. Insert the fresh draft. Use graph_message_id = groupPostId so the
  //    UNIQUE(org_id, graph_message_id) constraint acts as the idempotency backstop.
  const freshDraft = {
    org_id: DEFAULT_ORG_ID,
    mailbox: SES_MAILBOX,
    graph_message_id: groupPostId,
    received_at: draft.received_at,
    from_email: draft.from_email,
    from_name: draft.from_name,
    subject: draft.subject,
    body_preview: draft.body_preview,
    requesting_company_slug: draft.requesting_company_slug,
    requesting_company_name: draft.requesting_company_name,
    external_ref: draft.external_ref,
    client_name: draft.client_name,
    client_phone: draft.client_phone,
    client_email: draft.client_email || null,
    site_address: draft.site_address,
    site_suburb: draft.site_suburb,
    description: draft.description,
    safety_requirements: draft.safety_requirements || null,
    special_instructions: null,
    confidence: draft.confidence || 'medium',
    missing_fields: recaptureAvailableCount > 0 ? [] : ['work_order_pdf'],
    extraction_json: draft.extraction_json || {},
    attachments_json: recaptureAttachments,
    status: freshStatus,
  }

  const { data: inserted, error: insErr } = await client.from('makesafe_intake_drafts')
    .insert(freshDraft).select().single()

  if (insErr) {
    // If it's a unique violation, a draft for this group post_id already exists (concurrent call).
    // Treat as idempotent success (no-op).
    if (insErr.code === '23505' || (insErr.message || '').includes('unique')) {
      return {
        ok: true,
        recaptured: false,
        reason: 'unique_constraint_live_draft_exists',
        group_post_id: groupPostId,
      }
    }
    throw new Error('recapture draft insert failed: ' + insErr.message)
  }

  // 7. Optionally mark the old draft as superseded (auditable but not required).
  // Keep it simple: the original rejected draft stays as-is (already rejected).
  // The new draft is the authoritative one going forward.

  return {
    ok: true,
    recaptured: true,
    new_draft_id: inserted?.id,
    group_post_id: groupPostId,
    attachments_count: recaptureAttachments.length,
    available_pdf_count: recaptureAvailableCount,
    status: freshStatus,
  }
}

// Wave 1: encode raw bytes -> base64 in 8192-byte chunks. A naive
// btoa(String.fromCharCode(...bytes)) blows the call stack on large PDFs because
// the whole array is spread into one fromCharCode call; chunking keeps each spread
// bounded. Mirrors the chunked-btoa pattern already used for quote-PDF email
// attachments elsewhere in this file.
function bytesToBase64(bytes: Uint8Array): string {
  let binary = ''
  const chunkSize = 8192
  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize))
  }
  return btoa(binary)
}

// BUG 2 (CAPTURE): the intake re-upload key used the raw graph_message_id, which is
// ~150 chars and contains '=', '+', '_' — pushing some keys past Storage's object-key
// constraints and silently failing the upload. Derive a SHORT, deterministic,
// Storage-safe key from the message id (first 24 hex of its SHA-256) so the same
// email always maps to the same object path and the key is always valid.
async function _shortStorageKey(input: string): Promise<string> {
  const buf = new TextEncoder().encode(String(input || ''))
  const digest = await crypto.subtle.digest('SHA-256', buf)
  const hex = Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, '0')).join('')
  return hex.slice(0, 24)
}

// ── Slice 7: scan SES make-safes for make-safe work orders ──
// Wave 1 (intake autopilot): SOURCE CHANGED. This no longer scans the Graph USER
// mailbox (users/admin@.../inbox). It now sources candidate work-order emails from
// the live GROUP-sync projection (the `emails` + `email_attachments` tables that
// monitor-ses-makesafes populates from the ses@ M365 group), reusing the SAME
// mailbox identity (ses@secureworkswa.com.au), paginated read, and inbound-
// contamination filter as makesafe_new_emails (GAP-1). Everything DOWNSTREAM is
// unchanged: company-pattern sender match, the subject pre-filter, dedup vs drafts
// (by graph_message_id == emails.post_id) + jobs (by external_ref), Haiku
// extraction, the isGenuineNewWorkOrder hard gate, the job-documents public
// re-upload, the draft status logic, and the insert + return shape — so the
// ops-dash cockpit keeps working with NO change. PDF bytes now come from the
// PRIVATE makesafe-emails bucket (where the group sync stored them) instead of a
// live Graph attachment download. The api-key-callable wiring is deliberately
// unchanged so the 5-min monitor cron can tail-call this. It may auto-promote
// only a strict clean/high-confidence normal WO; it still cannot send, authorise,
// invoice, close, allocate, or call approve_intake_draft directly.
// Shared make-safe extraction model + system prompt. Used by BOTH the scanner
// (scanSesMakesafes) and the admin reextract_intake_draft action so a re-extraction
// runs the SAME classifier with the SAME prompt as a fresh scan — zero drift.
const MAKESAFE_EXTRACTION_MODEL = 'claude-haiku-4-5-20251001'
const MAKESAFE_EXTRACTION_MAX_TOKENS = 900
const MAKESAFE_EXTRACTION_SYSTEM_PROMPT = `You extract make-safe work order details from emails and their attached PDF work orders for a Perth construction company.
Return JSON only: { "external_ref": "AJBR 66897" or null, "client_name": "...", "client_phone": "...", "site_address": "...", "site_suburb": "...", "description": "brief scope of work", "safety_requirements": "any safety notes" or null, "report_type": "roof_report"|"assessment_report"|"temp_fence"|"re_attend"|"general_makesafe"|"not_a_report", "portal_link": "https://..." or null, "portal_links": [{ "label": "Roof report link", "url": "https://...", "kind": "roof_report" }], "confidence": "high"|"medium"|"low", "missing_fields": ["field1", "field2"] }
Extract the company reference number (e.g. AJBR XXXXX, MLB-XXXXX), homeowner/client name, site address, phone number, and work description.
Check BOTH the email body AND any attached PDF work orders for these details. The PDF often contains client name, phone, and detailed scope that the email does not.
For report_type, COMMIT the single best classification of the work using the body AND the PDF: "roof_report" (roof report/inspection), "assessment_report" (assessment / assess-and-quote / scope of works), "temp_fence" (temporary fence collect/pickup), "re_attend" (return visit to an existing job), "general_makesafe" (a physical make-safe work order that is not primarily a report), or "not_a_report". Do not leave it blank; pick "general_makesafe" for an ordinary physical make-safe.
For MLB/Prime report-only emails, links in the email body are authoritative. Do not assume the attached work-order PDF contains the Prime/report URLs.
For portal_link: return the first/best https builder-portal URL in the email body. If multiple report/assessment/quote URLs appear, return all of them in portal_links with useful labels and kinds.
If the email is NOT a make-safe work order, set confidence to "low" and missing_fields to ["not_a_work_order"].`

// ── A1 — reextract_intake_draft (in-place re-extraction, immune to the unique key) ──
// ROOT CAUSE (wave2-reextract-diagnosis.json): the supersede-then-rescan recipe hits the
// (org_id, graph_message_id) UNIQUE key on re-insert and the error is swallowed, so a real
// WO never re-populates. This admin action re-runs the SAME extraction (template/model,
// PDF text, links, committed report_type) for a NAMED draft and UPDATEs the existing draft
// row IN PLACE (same id, same graph_message_id) — no INSERT, immune to the root cause, no
// marker interaction. A clean result may then auto-file through the existing gate exactly
// like a fresh scan. Refuses approved/rejected drafts.

// Pure guard: a reextract may run on an in-flight/parked draft but NEVER on a finalised one.
export function _assertDraftReextractable(status: string | null | undefined): void {
  const s = String(status ?? '').toLowerCase()
  if (s === 'approved' || s === 'rejected') {
    throw new ApiError(`reextract refused: draft is ${s} (only non-finalised drafts can be re-extracted)`, 409)
  }
}

// Re-run the SAME extraction pipeline the scanner uses for ONE email (template parse +
// Haiku on body + PDF text, PDF re-upload, subject parse, link merge, committed
// report_type + job family). Returns the recomputed field-set; the caller UPDATEs in place.
async function _reextractExtractFields(
  client: any,
  input: {
    graphMessageId: string
    postId: string
    fromEmail: string
    fromName: string
    subject: string
    body: string
    receivedAt: string | null
    hasAttachments: boolean
    senderPatterns: Array<{ slug: string; name: string; pattern: string }>
    parsingRulesBySlug: Map<string, any>
  },
): Promise<{
  extraction: any
  attachments: any[]
  confidence: string
  missingFields: string[]
  matchedCompany: { slug: string; name: string } | null
  draftReportType: string | null
  draftJobFamily: string
  availableWoCount: number
  isReportCapture: boolean
  extractionDegraded: boolean
  woGateOk: boolean
  woGateReason: string
}> {
  const { subject, fromEmail, fromName } = input
  // Admin/service client for the private-bucket download + public re-upload (created here
  // so the injectable test extractor path never triggers createClient with empty env).
  const adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)
  const rawEmailBody = input.body || ''
  const builderEmailTextForTrade = _stripEmailHtmlForTrade(rawEmailBody)
  const deterministicPortalLinks = _extractBuilderEmailLinks(rawEmailBody)
  const bodyPreview = (builderEmailTextForTrade || '').slice(0, 2000)
  const replyForwardRisk = _subjectHasReplyForwardPrefix(subject)

  // Match sender to company (same anchored-suffix logic as the scanner).
  let matchedCompany: { slug: string; name: string } | null = null
  const matchedSenderPattern = _findMatchingSenderCompany(fromEmail, input.senderPatterns)
  if (matchedSenderPattern) matchedCompany = { slug: matchedSenderPattern.slug, name: matchedSenderPattern.name }

  // PDF read from the PRIVATE makesafe-emails bucket + re-upload to PUBLIC job-documents,
  // identical attachments_json shape + WO designation as the scanner.
  const attachments: any[] = []
  const pdfBase64List: Array<{ name: string; base64: string }> = []
  if (input.hasAttachments) {
    try {
      const { data: attRows } = await client.from('email_attachments')
        .select('id, graph_attachment_id, name, content_type, storage_path, size_bytes')
        .eq('email_id', input.postId)
        .eq('status', 'uploaded')
      const uploadedPdfRows = (attRows || []).filter((att: any) => {
        const isPdf = (att.content_type || '').includes('pdf') || (att.name || '').endsWith('.pdf')
        return isPdf && att.storage_path
      })
      const { selected: designatedWo, ordered: orderedPdfs } = _selectWorkOrderPdf(uploadedPdfRows)
      const keyHash = await _shortStorageKey(input.graphMessageId)
      for (let attIdx = 0; attIdx < orderedPdfs.length; attIdx++) {
        const att = orderedPdfs[attIdx]
        try {
          const { data: blob, error: dlErr } = await adminClient.storage.from('makesafe-emails').download(att.storage_path!)
          if (dlErr || !blob) { console.log('[ops-api] reextract PDF download failed:', dlErr?.message || 'no blob', att.storage_path); continue }
          const fileBuffer = new Uint8Array(await blob.arrayBuffer())
          if (pdfBase64List.length < 2 && fileBuffer.length < 5000000) {
            pdfBase64List.push({ name: att.name ?? 'work-order.pdf', base64: bytesToBase64(fileBuffer) })
          }
          const safeName = (att.name || 'work-order.pdf').replace(/[^a-zA-Z0-9._-]/g, '_').slice(-80)
          const keyComponent = _attachmentKeyComponent(att, attIdx)
          const storagePath = `makesafe-intake/${keyHash}-${keyComponent}/${safeName}`
          const { error: upErr } = await adminClient.storage.from('job-documents')
            .upload(storagePath, fileBuffer, { contentType: 'application/pdf', upsert: true })
          if (upErr) {
            attachments.push({ name: att.name, file_name: att.name, storage_url: null, pdf_url: null, pdf_unavailable: true, pdf_error: `upload_failed:${upErr.message}`.slice(0, 200), size: att.size_bytes, is_work_order: (att === designatedWo) })
            continue
          }
          const { data: urlData } = adminClient.storage.from('job-documents').getPublicUrl(storagePath)
          attachments.push({ name: att.name, file_name: att.name, storage_url: storagePath, pdf_url: urlData?.publicUrl || null, size: att.size_bytes, is_work_order: (att === designatedWo) })
        } catch (e) { console.log('[ops-api] reextract PDF re-upload failed:', (e as Error).message) }
      }
    } catch (e) { console.log('[ops-api] reextract attachment read failed:', (e as Error).message) }
  }

  // Extraction: template-first when a full parse is available, else the Haiku model on
  // body + PDF text (SAME model + SAME system prompt as the scanner).
  let extraction: any = {}
  let confidence = 'low'
  let missingFields: string[] = []
  let extractionDegraded = false
  const ANTHROPIC_API_KEY = Deno.env.get('ANTHROPIC_API_KEY')
  const pdfTextModeEnabled = Deno.env.get('MAKESAFE_INTAKE_PDF_TEXT_MODE') !== 'false'
  const templateSlug = (matchedCompany?.slug || '').toLowerCase()

  const pdfTexts: string[] = []
  const pdfRawTexts: string[] = [] // item 5 — raw text layer for the client-block reader
  let pdfMode: 'text' | 'document' | 'none' = pdfBase64List.length ? 'document' : 'none'
  if (pdfBase64List.length && pdfTextModeEnabled) {
    let allText = true
    for (const pdf of pdfBase64List) {
      try {
        const bytes = Uint8Array.from(atob(pdf.base64), (c) => c.charCodeAt(0))
        const r = await _extractPdfText(bytes)
        if (r.mode === 'text') pdfTexts.push(`[${pdf.name}]\n${r.text}`)
        else allText = false
        if (r.rawText) pdfRawTexts.push(`[${pdf.name}]\n${r.rawText}`)
      } catch (_) { allText = false }
    }
    const combinedLen = pdfTexts.join('\n').length
    pdfMode = (allText && pdfTexts.length === pdfBase64List.length && combinedLen >= _PDF_TEXT_MIN_CHARS) ? 'text' : 'document'
  }
  const combinedPdfText = pdfTexts.join('\n')

  const templateResult = _parseWithTemplate(input.parsingRulesBySlug.get(templateSlug), {
    subject, body: builderEmailTextForTrade || bodyPreview, pdfText: combinedPdfText,
  })

  if (templateResult?.model_skipped) {
    const f = templateResult.fields
    extraction = {
      external_ref: f.external_ref || null, client_name: f.client_name || null, client_phone: f.client_phone || null,
      site_address: f.site_address || null, site_suburb: f.site_suburb || null, description: f.description || null,
      safety_requirements: f.safety_requirements || null,
    }
    confidence = templateResult.confidence
    missingFields = []
  } else if (ANTHROPIC_API_KEY) {
    try {
      const { default: Anthropic } = await import('https://esm.sh/@anthropic-ai/sdk@0.39.0')
      const anthropic = new Anthropic({ apiKey: ANTHROPIC_API_KEY })
      const userContent: any[] = [{ type: 'text', text: `From: ${fromName} <${fromEmail}>\nSubject: ${subject}\nBody: ${bodyPreview}` }]
      if (pdfMode === 'text') {
        for (const t of pdfTexts) userContent.push({ type: 'text', text: `[Work order PDF text]\n${t}` })
      } else {
        for (const pdf of pdfBase64List) {
          userContent.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: pdf.base64 } })
          userContent.push({ type: 'text', text: `[Attached PDF: ${pdf.name}]` })
        }
      }
      const resp = await anthropic.messages.create({
        model: MAKESAFE_EXTRACTION_MODEL,
        max_tokens: MAKESAFE_EXTRACTION_MAX_TOKENS,
        system: [{ type: 'text', cache_control: { type: 'ephemeral' }, text: MAKESAFE_EXTRACTION_SYSTEM_PROMPT }],
        messages: [{ role: 'user', content: userContent }],
      })
      const text = resp.content[0].type === 'text' ? resp.content[0].text : ''
      const jsonMatch = text.match(/\{[\s\S]*\}/)
      if (jsonMatch) {
        extraction = JSON.parse(jsonMatch[0])
        confidence = extraction.confidence || 'low'
        missingFields = extraction.missing_fields || []
      }
    } catch (e) {
      // Dead/absent key or transient failure -> degrade (do not make the draft worse).
      extractionDegraded = true
      console.error('[ops-api] reextract model call failed:', (e as Error).message)
    }
  } else {
    extractionDegraded = true
  }

  // Universal deterministic subject parse (authoritative ref; address only fills gaps).
  const subjectFields = _parseSubjectFields(subject)
  const refDecision = _resolveSubjectRef(replyForwardRisk, subjectFields.external_ref, extraction.external_ref || null)
  if (refDecision.external_ref) extraction.external_ref = refDecision.external_ref
  if (refDecision.subject_ref_hint) extraction.subject_ref_hint = refDecision.subject_ref_hint
  if (!replyForwardRisk) {
    if (!cleanReviewedString(extraction.site_address) && subjectFields.site_address) extraction.site_address = subjectFields.site_address
    if (!cleanReviewedString(extraction.site_suburb) && subjectFields.site_suburb) extraction.site_suburb = subjectFields.site_suburb
  }
  const ajPrefill = _deriveAjIntakePrefill({
    fromEmail,
    subject,
    bodyText: builderEmailTextForTrade || bodyPreview,
  })
  const ajApplied = _applyAjIntakePrefill(extraction, ajPrefill)
  extraction = ajApplied.extraction
  if (ajApplied.filledFields.length) {
    const filled = new Set(ajApplied.filledFields.map((field) => cleanMissingFieldName(field)))
    missingFields = missingFields.filter((field: string) => !filled.has(cleanMissingFieldName(field)))
  }

  // Item 5 — deterministic WO-PDF client-field fill (opt-in, default OFF). Same
  // policy as the live scan: fill only null client fields from a single unambiguous
  // WO-PDF client block so a re-extracted MLB draft can reach clean. See scan path.
  if (pdfClientFillEnabled()) {
    const clientText = combinedPdfText || pdfRawTexts.join('\n')
    if (clientText) {
      const fill = _decidePdfClientFill(clientText, {
        clientName: cleanReviewedString(extraction.client_name) || null,
        clientPhone: cleanReviewedString(extraction.client_phone) || null,
        siteAddress: cleanReviewedString(extraction.site_address) || null,
        confidence,
        missingFields,
        externalRefPresent: !!cleanReviewedString(extraction.external_ref),
        matchedCompanyPresent: !!(matchedCompany?.slug || matchedCompany?.name),
      })
      if (fill.applied) {
        for (const f of fill.filledFields) extraction[f] = fill.fill[f]
        extraction.pdf_sourced_fields = [
          ...(Array.isArray(extraction.pdf_sourced_fields) ? extraction.pdf_sourced_fields : []),
          ...fill.filledFields,
        ]
        missingFields = fill.missingFields
        confidence = fill.confidence
      }
    }
  }

  if (extractionDegraded) {
    extraction.extraction_degraded = true
    if (!missingFields.includes(INTAKE_EXTRACTION_DOWN_MARKER)) missingFields.push(INTAKE_EXTRACTION_DOWN_MARKER)
    confidence = 'low'
  }

  // Item 4 — also mine portal/report links from the recovered WO PDF text (reextract parity with scan).
  const attachmentPortalLinks = _extractBuilderEmailLinks(null, combinedPdfText || pdfRawTexts.join('\n'))
  const mergedPortalLinks = _mergeDeterministicAndClaudeLinks([...deterministicPortalLinks, ...attachmentPortalLinks], extraction)
  if (mergedPortalLinks.length) {
    extraction.portal_links = mergedPortalLinks
    extraction.portal_link = extraction.portal_link || mergedPortalLinks[0]?.url || null
  }
  if (builderEmailTextForTrade) {
    extraction.builder_email_text_for_trade = builderEmailTextForTrade
    extraction.builder_email_subject = subject || null
    extraction.builder_email_received_at = input.receivedAt || null
  }

  const availableWoCount = attachments.filter((a: any) => a && !a.pdf_unavailable && (a.pdf_url || a.storage_url)).length

  // Report-capture derivation + report_type/family (same helpers as the scanner).
  const woGate = _isGenuineNewWorkOrder(subject, fromEmail, availableWoCount)
  const isReportCapture = woGate.kind === 'report'
  const tagReportType = isReportCapture || (woGate as any).reportSubjectPattern === true
  if ((isReportCapture || tagReportType) && !matchedCompany?.slug) {
    const refPrefixMatch = subject.match(/\b(mlb|wb|bw|bwc|bwcwa|kba)-?\s*\d+/i)
    const derivedSlug = _slugFromRefPrefix(refPrefixMatch?.[1] ?? null)
    if (derivedSlug) matchedCompany = { slug: derivedSlug, name: derivedSlug }
  }
  let draftReportType: string | null = null
  if (tagReportType) draftReportType = _resolveCommittedReportType(extraction.report_type, subject, builderEmailTextForTrade || bodyPreview)
  const draftJobFamily = _classifyMakeSafeJobFamily(subject, [builderEmailTextForTrade, bodyPreview, extraction.description].filter(Boolean).join('\n'), draftReportType)
  extraction.makesafe_job_family = draftJobFamily
  extraction.makesafe_job_family_label = _makeSafeJobFamilyLabel(draftJobFamily)
  extraction.reextracted_at = new Date().toISOString()
  // Item 3: flag a combined make-safe + report so the reextracted draft never auto-files
  // a single card that drops the report obligation.
  flagCombinedIntakeObligation(
    { subject, body_preview: bodyPreview, description: extraction.description },
    extraction,
    attachments,
    missingFields,
    draftReportType,
  )

  return {
    extraction, attachments, confidence, missingFields, matchedCompany,
    draftReportType, draftJobFamily, availableWoCount, isReportCapture, extractionDegraded,
    woGateOk: woGate.ok, woGateReason: woGate.reason,
  }
}

// Admin action: re-extract a NAMED draft in place. deps.extractFields is injectable so the
// orchestration (load / refuse / update / auto-file / breadcrumb) is testable without the
// model or storage; production uses the real _reextractExtractFields.
export async function reextractIntakeDraft(
  client: any,
  body: any,
  deps?: { extractFields?: typeof _reextractExtractFields },
): Promise<any> {
  const draftId = body?.draft_id
  if (!draftId) throw new ApiError('draft_id required', 400)

  const { data: draft, error: dErr } = await client.from('makesafe_intake_drafts')
    .select('*').eq('id', draftId).single()
  if (dErr || !draft) throw new ApiError('Draft not found', 404)
  _assertDraftReextractable(draft.status)

  // Load the source email (post_id = the draft's graph_message_id) + companies for parsing.
  const { data: email } = await client.from('emails')
    .select('post_id, subject, body_content, body_preview, from_email, from_name, has_attachments, received_at')
    .eq('post_id', draft.graph_message_id)
    .maybeSingle()
  if (!email) throw new ApiError(`source email not found for graph_message_id ${draft.graph_message_id}`, 404)

  const { data: companies } = await client.from('makesafe_companies')
    .select('slug, name, sender_patterns, parsing_rules').eq('active', true)
  const senderPatterns: Array<{ slug: string; name: string; pattern: string }> = []
  const parsingRulesBySlug = new Map<string, any>()
  for (const co of (companies || [])) {
    for (const p of (co.sender_patterns || [])) senderPatterns.push({ slug: co.slug, name: co.name, pattern: String(p).toLowerCase() })
    if (co.slug && co.parsing_rules && typeof co.parsing_rules === 'object') parsingRulesBySlug.set(String(co.slug).toLowerCase(), co.parsing_rules)
  }

  const extractFields = deps?.extractFields || _reextractExtractFields
  const r = await extractFields(client, {
    graphMessageId: draft.graph_message_id,
    postId: email.post_id,
    fromEmail: email.from_email || draft.from_email || '',
    fromName: email.from_name || draft.from_name || '',
    subject: email.subject || draft.subject || '',
    body: email.body_content || email.body_preview || '',
    receivedAt: email.received_at || draft.received_at || null,
    hasAttachments: !!email.has_attachments,
    senderPatterns,
    parsingRulesBySlug,
  })

  const draftStatus = _computeIntakeDraftStatus({
    extractionDegraded: r.extractionDegraded,
    isReportCapture: r.isReportCapture,
    hasCompany: !!(r.matchedCompany?.slug || r.matchedCompany?.name),
    externalRef: r.extraction.external_ref || null,
    clientName: r.extraction.client_name || null,
    siteAddress: r.extraction.site_address || null,
    availableWoCount: r.availableWoCount,
  })

  // UPDATE the existing row IN PLACE — same id, same graph_message_id. No INSERT, immune
  // to the (org_id, graph_message_id) unique key that swallowed the original re-extraction.
  const update = {
    requesting_company_slug: r.matchedCompany?.slug || null,
    requesting_company_name: r.matchedCompany?.name || null,
    external_ref: r.extraction.external_ref || null,
    client_name: r.extraction.client_name || null,
    client_phone: r.extraction.client_phone || null,
    site_address: r.extraction.site_address || null,
    site_suburb: r.extraction.site_suburb || null,
    description: r.extraction.description || null,
    safety_requirements: r.extraction.safety_requirements || null,
    confidence: r.confidence,
    missing_fields: r.missingFields,
    extraction_json: r.extraction,
    attachments_json: r.attachments,
    report_type: r.draftReportType,
    status: draftStatus,
    review_notes: `Re-extracted in place ${new Date().toISOString()} (admin reextract_intake_draft). WO gate: ${r.woGateOk ? 'pass' : 'fail:' + r.woGateReason}.`,
    updated_at: new Date().toISOString(),
  }
  const { data: updated, error: upErr } = await client.from('makesafe_intake_drafts')
    .update(update).eq('id', draftId).select().single()
  if (upErr) throw new ApiError('reextract update failed: ' + upErr.message, 500)

  // Business_event breadcrumb (board trace for the recovery).
  try {
    await logBusinessEvent(client, {
      event_type: 'makesafe.intake_reextracted',
      source: 'app/makesafe-intake',
      entity_type: 'makesafe_ref',
      entity_id: String(r.extraction.external_ref || draft.graph_message_id),
      body_preview: `Re-extracted draft ${draftId}: ref ${r.extraction.external_ref || 'none'}, status ${draftStatus}`,
      payload: { draft_id: draftId, external_ref: r.extraction.external_ref || null, confidence: r.confidence, status: draftStatus, prior_status: draft.status, available_wo: r.availableWoCount },
      metadata: { mission: 'fix/makesafe-reextract-and-notify-2026-07-04' },
    })
  } catch { /* non-blocking */ }

  // Auto-file a clean, high-confidence result through the SAME gate the scanner uses.
  let autoFiled: any = null
  const autoFileEnabled = await isAutoFileEnabled(client)
  const autoDecision = shouldAutoApproveCleanIntake({
    enabled: autoFileEnabled && !r.extractionDegraded && autoApproveCleanIntakeEnabled(),
    isReportCapture: r.isReportCapture,
    tagReportType: r.draftReportType != null,
    reportType: r.draftReportType,
    confidence: r.confidence,
    missingFields: r.missingFields,
    matchedCompany: r.matchedCompany,
    externalRef: r.extraction.external_ref || null,
    clientName: r.extraction.client_name || null,
    siteAddress: r.extraction.site_address || null,
    attachments: r.attachments,
    cancelled: _subjectIsCancellation(draft?.subject ?? null),
    combinedObligation: !!(r.extraction?.secondary_obligation) ||
      (emailCarriesMultipleWorkOrders({ subject: draft?.subject ?? null, body_preview: draft?.body_preview ?? null }, r.extraction, r.attachments) &&
        hasWorkOrderAttachmentEvidence(r.attachments) &&
        hasPositiveReportOnlyEvidence({ subject: draft?.subject ?? null, body_preview: draft?.body_preview ?? null }, r.extraction, r.attachments)),
    combinedSplittable: combinedSplitObligation(r.extraction) !== null,
  })
  if (autoDecision.ok) {
    try {
      const approved = await approveIntakeDraft(client, {
        draft_id: draftId,
        approved_by: 'auto-intake-reextract',
        review_notes: 'Auto-filed after in-place re-extraction (reextract_intake_draft): high-confidence, required fields + servable WO PDF present.',
      })
      autoFiled = { job_id: approved?.job?.id || null, reason: autoDecision.reason }
    } catch (e) {
      autoFiled = { job_id: null, error: (e as Error).message, reason: autoDecision.reason }
    }
  }

  return {
    ok: true,
    draft_id: draftId,
    prior_status: draft.status,
    status: draftStatus,
    external_ref: r.extraction.external_ref || null,
    site_address: r.extraction.site_address || null,
    confidence: r.confidence,
    available_wo: r.availableWoCount,
    extraction_degraded: r.extractionDegraded,
    wo_gate: { ok: r.woGateOk, reason: r.woGateReason },
    auto_filed: autoFiled,
    draft: updated,
  }
}

// ── A2/A3 — scan-insert self-heal + dropped-WO breadcrumb ───────────────────────
// ROOT CAUSE (wave2-reextract-diagnosis.json): a genuine WO whose INSERT hit the
// (org_id, graph_message_id) UNIQUE key was SILENTLY dropped with only a console.log.
// This replaces that silent `continue` with:
//   * heal — the occupying row is a NON-LIVE shell (superseded/rejected): re-populate
//            it in place (same id, same graph_message_id, no new INSERT) so a released
//            email auto-recovers into its own slot. Returns the healed row.
//   * live_collision — the occupying row is LIVE (dedup failed upstream): DO NOT clobber
//            a live draft/job. Breadcrumb only.
//   * dropped — any other insert failure, or a heal UPDATE that itself fails: a real WO
//            would be lost. Breadcrumb so the alarm can fire; never a silent log again.
// Every outcome writes a business_event so a dropped/collided WO is visible on the board.
export async function _selfHealIntakeInsert(
  client: any,
  input: {
    draft: any
    insErr: any
    orgId: string
    graphMessageId: string
    externalRef: string | null
    subject: string
  },
): Promise<{ outcome: 'healed' | 'live_collision' | 'dropped'; row: any | null }> {
  const { draft, insErr, orgId, graphMessageId, externalRef, subject } = input
  const refOrId = externalRef || graphMessageId
  const isUniqueViolation = String(insErr?.code) === '23505' ||
    /duplicate key|unique constraint|already exists/i.test(insErr?.message || '')

  const dropBreadcrumb = async (reason: string) => {
    try {
      await logBusinessEvent(client, {
        event_type: 'makesafe.intake_wo_dropped',
        source: 'app/makesafe-intake',
        entity_type: 'makesafe_ref',
        entity_id: String(refOrId),
        body_preview: `Intake WO dropped (${reason}): ${subject}`,
        payload: { external_ref: externalRef, graph_message_id: graphMessageId, reason, error: (insErr?.message || '').slice(0, 300) },
        metadata: { mission: 'fix/makesafe-reextract-and-notify-2026-07-04' },
      })
    } catch { /* non-blocking breadcrumb */ }
  }

  if (!isUniqueViolation) {
    console.error('[ops-api] intake draft insert failed (WO DROPPED):', insErr?.message, '| ref', externalRef, '| subject', subject)
    await dropBreadcrumb('insert_error')
    return { outcome: 'dropped', row: null }
  }

  // 23505 on (org_id, graph_message_id): find the row occupying that slot.
  const { data: occ } = await client.from('makesafe_intake_drafts')
    .select('id, status')
    .eq('org_id', orgId)
    .eq('graph_message_id', graphMessageId)
    .maybeSingle()

  const action = occ?.id ? _decideInsertConflictAction(occ.status) : 'dropped'

  if (occ?.id && action === 'heal') {
    // Re-populate the non-live shell IN PLACE — immune to the unique key.
    const { data: healed, error: healErr } = await client.from('makesafe_intake_drafts')
      .update({
        received_at: draft.received_at,
        from_email: draft.from_email,
        from_name: draft.from_name,
        subject: draft.subject,
        body_preview: draft.body_preview,
        requesting_company_slug: draft.requesting_company_slug,
        requesting_company_name: draft.requesting_company_name,
        external_ref: draft.external_ref,
        client_name: draft.client_name,
        client_phone: draft.client_phone,
        client_email: draft.client_email,
        site_address: draft.site_address,
        site_suburb: draft.site_suburb,
        description: draft.description,
        safety_requirements: draft.safety_requirements,
        special_instructions: draft.special_instructions,
        confidence: draft.confidence,
        missing_fields: draft.missing_fields,
        extraction_json: draft.extraction_json,
        attachments_json: draft.attachments_json,
        report_type: draft.report_type,
        status: draft.status,
        updated_at: new Date().toISOString(),
      })
      .eq('id', occ.id)
      .select().single()
    if (healErr || !healed) {
      console.error('[ops-api] intake self-heal UPDATE failed (WO DROPPED):', healErr?.message, '| ref', externalRef)
      await dropBreadcrumb('heal_update_failed')
      return { outcome: 'dropped', row: null }
    }
    console.log('[ops-api] intake self-heal: re-populated', occ.status, 'shell in place for', refOrId)
    try {
      await logBusinessEvent(client, {
        event_type: 'makesafe.intake_insert_healed',
        source: 'app/makesafe-intake',
        entity_type: 'makesafe_ref',
        entity_id: String(refOrId),
        body_preview: `Intake insert self-healed (${occ.status} shell re-populated): ${subject}`,
        payload: { external_ref: externalRef, graph_message_id: graphMessageId, prior_status: occ.status, draft_id: occ.id },
        metadata: { mission: 'fix/makesafe-reextract-and-notify-2026-07-04' },
      })
    } catch { /* non-blocking breadcrumb */ }
    return { outcome: 'healed', row: healed }
  }

  if (occ?.id && action === 'live_collision') {
    console.error('[ops-api] intake insert LIVE collision (dedup miss?) — NOT clobbering live row:', refOrId, '| status', occ.status)
    try {
      await logBusinessEvent(client, {
        event_type: 'makesafe.intake_insert_live_collision',
        source: 'app/makesafe-intake',
        entity_type: 'makesafe_ref',
        entity_id: String(refOrId),
        body_preview: `Intake insert LIVE collision (dedup miss): ${subject}`,
        payload: { external_ref: externalRef, graph_message_id: graphMessageId, live_status: occ.status, live_draft_id: occ.id },
        metadata: { mission: 'fix/makesafe-reextract-and-notify-2026-07-04' },
      })
    } catch { /* non-blocking breadcrumb */ }
    return { outcome: 'live_collision', row: null }
  }

  // Unique violation but no occupying row found (race / RLS) — treat as a drop, loud.
  console.error('[ops-api] intake insert 23505 but no occupying row found (WO DROPPED):', refOrId)
  await dropBreadcrumb('unique_violation_no_row')
  return { outcome: 'dropped', row: null }
}

// Intake item 4 (nudge-email pattern) — land a nudge's portal links onto the EXISTING
// make-safe job it references, idempotently, instead of dropping them. A builder
// "please complete the report" nudge carries the report portal link but NO new WO PDF
// and references a ref that already has a live job; the scan otherwise silently skips
// it and the link is lost (recon proof SWMS-26632). Writes the canonical
// makesafe_job_details.external_links (+ the jobs.metadata alias the trade view/board
// read), ADD-only (never clobbers an operator edit; re-scanning the same nudge is a
// no-op). Returns the newly-added links. Throws on the canonical write so the caller
// can log; the caller keeps it non-blocking (a patch failure never breaks the scan).
async function _patchExistingJobExternalLinks(
  // deno-lint-ignore no-explicit-any -- supabase-js v2 untyped client (ops-api convention)
  client: any,
  jobId: string,
  incoming: any[],
): Promise<{ added: any[]; upgraded: any[] }> {
  if (!jobId || !Array.isArray(incoming) || incoming.length === 0) return { added: [], upgraded: [] }
  const { data: detail } = await client.from('makesafe_job_details')
    .select('external_links').eq('job_id', jobId).maybeSingle()
  // W3-F: also persist an in-place type upgrade (a re-scan sharpens a stored generic
  // builder_portal link to its specific kind) — not just a newly-added URL.
  const { links, added, upgraded } = _mergeIntoExternalLinks(detail?.external_links, incoming)
  if (added.length === 0 && upgraded.length === 0) return { added: [], upgraded: [] }
  const nowIso = new Date().toISOString()
  const { error: upErr } = await client.from('makesafe_job_details')
    .update({ external_links: links, updated_at: nowIso }).eq('job_id', jobId)
  if (upErr) throw new Error(`external_links patch failed: ${upErr.message}`)
  // Keep the jobs.metadata.external_links alias in sync (best-effort; canonical done).
  try {
    const { data: jobRow } = await client.from('jobs').select('metadata').eq('id', jobId).maybeSingle()
    const md = parseJsonObject(jobRow?.metadata)
    md.external_links = links
    await client.from('jobs').update({ metadata: md, updated_at: nowIso }).eq('id', jobId)
  } catch (_) { /* alias is best-effort */ }
  return { added, upgraded }
}

// ── M-A2 / W2-B: two-email late WO-PDF landing (orchestration) ─────────────────
// The scan calls this when a candidate carries a servable WO PDF but dedups against
// an EXISTING same-ref+company draft. It finds the SINGLE dirty draft the PDF belongs
// to (selectLatePdfLandingTarget — fail closed on ambiguity), lands the PDF + fills
// the client fields the announcement lacked (mergeLateWorkOrderPdfIntoDraft), UPDATEs
// the row IN PLACE (never an INSERT — immune to the (org_id, graph_message_id) unique
// key), and re-runs the UNCHANGED strict gate, auto-filing only when now clean AND the
// same env/DB/degraded brakes allow it. NEVER mints a duplicate card.
//
// deps.approve is injectable so the orchestration is testable without approveIntakeDraft.
async function landLateWorkOrderPdfOntoDraft(
  client: any,
  params: {
    candidate: _LatePdfCandidate
    autoFileEnabled: boolean
    extractionDegraded: boolean
    subject?: string | null
  },
  deps?: { approve?: typeof approveIntakeDraft },
): Promise<
  | { outcome: 'none' }
  | { outcome: 'ambiguous'; candidate_ids: string[] }
  | { outcome: 'landed'; draft_id: string; status: string; auto_filed: { job_id: string | null; reason: string } | null }
> {
  const approve = deps?.approve || approveIntakeDraft

  // Live drafts that could receive a late PDF (draft | needs_review only).
  const liveDrafts = await _fetchAllRows<any>(
    () => client.from('makesafe_intake_drafts')
      .select('id, status, external_ref, requesting_company_slug, requesting_company_name, attachments_json, extraction_json, missing_fields, client_name, client_phone, site_address, site_suburb, description, safety_requirements, confidence, report_type, subject')
      .eq('org_id', DEFAULT_ORG_ID)
      .in('status', ['draft', 'needs_review']),
    'makesafe_intake_drafts (late-pdf landing) read',
  )
  // Normalise each row's ref/identity/family the SAME way the dedup index does, so the
  // matcher sees the builder_claim_ref + WO/PO identity carried in extraction_json.
  const rows: _LatePdfDraftRow[] = (liveDrafts || []).map((d: any) => {
    const ex = parseJsonObject(d.extraction_json)
    const fam = ex.makesafe_job_family || _classifyMakeSafeJobFamily(
      d.subject || d.external_ref || '',
      [d.report_type, d.description].filter(Boolean).join('\n'),
      d.report_type || null,
    )
    return {
      ...d,
      external_ref: cleanReviewedString(ex.builder_claim_ref) || d.external_ref,
      makesafe_job_family: fam || null,
      builder_work_order_number: cleanReviewedString(ex.builder_work_order_number) || null,
      builder_po_number: cleanReviewedString(ex.builder_po_number) || null,
    }
  })

  const selection = _selectLatePdfLandingTarget(params.candidate, rows)
  if (selection.kind === 'none') return { outcome: 'none' }
  if (selection.kind === 'ambiguous') {
    const ids = selection.candidates.map((c) => c.id)
    try {
      await logBusinessEvent(client, {
        event_type: 'makesafe.intake_late_pdf_ambiguous',
        source: 'app/makesafe-intake',
        entity_type: 'makesafe_ref',
        entity_id: String(params.candidate.external_ref || params.candidate.graph_message_id || ''),
        body_preview: `Late WO PDF matched ${ids.length} dirty drafts for ref ${params.candidate.external_ref || 'unknown'}; failed closed for human review (no auto-land).`,
        payload: { external_ref: params.candidate.external_ref || null, candidate_draft_ids: ids, graph_message_id: params.candidate.graph_message_id || null },
        metadata: { mission: 'makesafe-system/W2-B-two-email-landing', reason: 'ambiguous_multiple_dirty_drafts' },
      })
    } catch { /* non-blocking breadcrumb */ }
    return { outcome: 'ambiguous', candidate_ids: ids }
  }

  // Exactly one target: merge + UPDATE in place.
  const target = selection.target
  const merge = _mergeLateWorkOrderPdfIntoDraft(target, params.candidate)
  const targetExtraction = parseJsonObject(target.extraction_json)
  const hasCompany = !!(cleanReviewedString(target.requesting_company_slug) || cleanReviewedString(target.requesting_company_name) ||
    cleanReviewedString(targetExtraction.requesting_company_slug) || cleanReviewedString(targetExtraction.requesting_company_name))
  const newStatus = _computeIntakeDraftStatus({
    extractionDegraded: params.extractionDegraded,
    isReportCapture: false,
    hasCompany,
    externalRef: cleanReviewedString(target.external_ref) || cleanReviewedString(merge.extraction_json.external_ref),
    clientName: merge.client_name,
    siteAddress: merge.site_address,
    availableWoCount: merge.available_wo_count,
  })

  const update = {
    attachments_json: merge.attachments_json,
    extraction_json: merge.extraction_json,
    missing_fields: merge.missing_fields,
    confidence: merge.confidence,
    client_name: merge.client_name,
    client_phone: merge.client_phone,
    site_address: merge.site_address,
    site_suburb: merge.site_suburb,
    description: merge.description,
    safety_requirements: merge.safety_requirements,
    status: newStatus,
    review_notes: `Late work-order PDF landed ${new Date().toISOString()} from a follow-up email (${params.candidate.graph_message_id || 'unknown post'}); attached to the existing draft, no duplicate card minted.`,
    updated_at: new Date().toISOString(),
  }
  const { data: updated, error: upErr } = await client.from('makesafe_intake_drafts')
    .update(update).eq('id', target.id).select().single()
  if (upErr) throw new Error('late-pdf landing update failed: ' + upErr.message)

  try {
    await logBusinessEvent(client, {
      event_type: 'makesafe.intake_late_pdf_landed',
      source: 'app/makesafe-intake',
      entity_type: 'makesafe_ref',
      entity_id: String(target.external_ref || params.candidate.external_ref || target.id),
      body_preview: `Landed late WO PDF on draft ${target.id} (ref ${target.external_ref || 'unknown'}); status ${newStatus}; filled ${merge.filled_fields.join(', ') || 'no'} field(s).`,
      payload: { draft_id: target.id, external_ref: target.external_ref || null, status: newStatus, filled_fields: merge.filled_fields, source_graph_message_id: params.candidate.graph_message_id || null },
      metadata: { mission: 'makesafe-system/W2-B-two-email-landing', reason: 'late_pdf_landed' },
    })
  } catch { /* non-blocking breadcrumb */ }

  // Re-run the UNCHANGED strict gate on the merged row; auto-file only if now clean
  // AND the same brakes (DB kill switch + default-on env brake + not degraded) allow it.
  let autoFiled: { job_id: string | null; reason: string } | null = null
  const decision = shouldAutoApproveCleanIntakeDraftRow(updated)
  const enabled = params.autoFileEnabled && !params.extractionDegraded && autoApproveCleanIntakeEnabled()
  if (enabled && decision.ok) {
    try {
      const approved = await approve(client, {
        draft_id: target.id,
        approved_by: 'auto-intake-late-pdf',
        review_notes: 'Auto-filed after a late work-order PDF landed on an existing intake draft (two-email MLB sequence): high-confidence, required fields + servable WO PDF now present. Draft-only intake promotion; no invoice/send/authorise/close action.',
      })
      autoFiled = { job_id: approved?.job?.id || null, reason: decision.reason }
    } catch (e) {
      autoFiled = { job_id: null, reason: `auto_file_error:${(e as Error).message}`.slice(0, 200) }
    }
  }
  return { outcome: 'landed', draft_id: target.id, status: newStatus, auto_filed: autoFiled }
}
export const _landLateWorkOrderPdfOntoDraftForTest = landLateWorkOrderPdfOntoDraft

async function scanSesMakesafes(client: any) {
  // Standing intake is deterministic unconditionally. The DB row supplies bounded
  // selection controls only; it can no longer select the retired paid-AI engine.
  const rollout = await _loadDeterministicRolloutControls(client)
  // Read the two existing auto-file brakes once. They may park a clean draft, but
  // they never turn off deterministic parsing, accounting or quarantine.
  const advanceDrafts = autoApproveCleanIntakeEnabled() && await isAutoFileEnabled(client)
  return await _runDeterministicIntake(client, {
    dryRun: false,
    selectionMode: rollout.selectionMode,
    days: 60,
    // Full-open still reads a bounded cursor page and commits at most maxCases.
    // Exact selection remains available only on explicit diagnostic actions.
    onlyUnscanned: false,
    maxCases: rollout.maxCases,
    allowSourcePostIds: rollout.sourcePostIds,
    allowInstructionKeys: rollout.instructionKeys,
    advanceDrafts,
    approveDraft: approveIntakeDraft,
  })
}

const REPORTING_INTAKE_ADVANCE_LIMIT = 100

async function runMakesafeReportingIntakePass(
  client: any,
  deps: {
    scan?: (client: any) => Promise<any>
    advance?: (client: any, body?: any) => Promise<any>
  } = {},
) {
  // One reporting run owns exactly one bounded scanner invocation. The follow-up
  // sweep advances only drafts that pass the same pure field gate and the same
  // approveIntakeDraft duplicate/atomic-claim guards as a human review-button click.
  const intake = await (deps.scan || scanSesMakesafes)(client)
  const advancement = await (deps.advance || autoApproveCleanIntakeDrafts)(client, {
    limit: REPORTING_INTAKE_ADVANCE_LIMIT,
    dry_run: false,
    triggered_by: 'ses-reporting-skill',
  })
  return {
    ok: true,
    trigger: 'ses-reporting-skill',
    bounded_intake_passes: 1,
    advancement_limit: REPORTING_INTAKE_ADVANCE_LIMIT,
    intake,
    advancement,
  }
}
export const _runMakesafeReportingIntakePassForTest = runMakesafeReportingIntakePass

// Retained only as historical/manual implementation evidence. No dispatch action,
// cron, reporting hook, or standing scanner can invoke this paid-AI engine.
async function retiredPaidAiIntakeImplementation(client: any) {

  // The group-sync projection keys ses@ mail under this mailbox (the canonical
  // value used by monitor-ses-makesafes + reconcile + the GAP reads).
  const SES_MAILBOX = _SES_MAILBOX

  // One admin/service client for both the private-bucket download and the public
  // re-upload below (hoisted out of the loop — was re-created per attachment).
  const adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)

  // Load known make-safe company sender patterns + per-builder template parsing rules
  // (M1.5: parsing_rules drives the deterministic template-parse cost lever).
  const { data: companies } = await client.from('makesafe_companies')
    .select('slug, name, sender_patterns, parsing_rules')
    .eq('active', true)
  const senderPatterns: Array<{ slug: string; name: string; pattern: string }> = []
  const parsingRulesBySlug = new Map<string, any>()
  for (const co of (companies || [])) {
    for (const p of (co.sender_patterns || [])) {
      senderPatterns.push({ slug: co.slug, name: co.name, pattern: p.toLowerCase() })
    }
    if (co.slug && co.parsing_rules && typeof co.parsing_rules === 'object') {
      parsingRulesBySlug.set(String(co.slug).toLowerCase(), co.parsing_rules)
    }
  }

  // Candidate window: last 7 days from the GROUP-sync projection (parity with the
  // old 7-day Graph window). Read the `emails` table for ses@, excluding PII-
  // tombstoned rows, paginated (PostgREST 1000-row cap) so a busy week isn't
  // silently truncated. Mirrors makesafe_new_emails (GAP-1) sourcing.
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()
  // Cost-leak fix: read the extract-at-most-once marker (makesafe_scanned_at) so an
  // already-scanned email is skipped before the model call. PRE-MIGRATION SAFE: if the
  // column doesn't exist yet (the code auto-deploys before the migration is hand-
  // applied), fall back to the base select and behave exactly as before (no marker).
  const EMAILS_BASE_COLS = 'post_id, mailbox, subject, body_preview, body_content, body_content_type, from_email, from_name, has_attachments, received_at, pii_purged_at'
  let scannedColumnAvailable = true
  let emailRows: any[]
  try {
    emailRows = await _fetchAllRows<any>(
      () => client.from('emails')
        .select(`${EMAILS_BASE_COLS}, makesafe_scanned_at`)
        .eq('mailbox', SES_MAILBOX)
        .is('pii_purged_at', null)
        .gte('received_at', sevenDaysAgo)
        .order('received_at', { ascending: false }),
      'emails (intake scan) read',
    )
  } catch (e) {
    scannedColumnAvailable = false
    console.warn('[ops-api] emails read with makesafe_scanned_at failed (pre-migration?); falling back to base select:', (e as Error).message)
    emailRows = await _fetchAllRows<any>(
      () => client.from('emails')
        .select(EMAILS_BASE_COLS)
        .eq('mailbox', SES_MAILBOX)
        .is('pii_purged_at', null)
        .gte('received_at', sevenDaysAgo)
        .order('received_at', { ascending: false }),
      'emails (intake scan) read (fallback)',
    )
  }

  // Map each emails row into the SAME shape the rest of the loop expects (it was
  // written against the Graph message shape: msg.id, msg.from.emailAddress.*,
  // msg.subject, msg.bodyPreview, msg.body.content, msg.hasAttachments).
  const mappedMessages = (emailRows || []).map((row: any) => ({
    id: row.post_id,
    internetMessageId: null,
    conversationId: null,
    from: { emailAddress: { address: row.from_email, name: row.from_name } },
    subject: row.subject,
    bodyPreview: row.body_preview,
    // Full body_content (HTML stripped below) gives better extraction than the
    // 500-char preview; fall back to preview then empty string.
    body: { content: row.body_content || row.body_preview || '' },
    receivedDateTime: row.received_at,
    hasAttachments: row.has_attachments,
    _post_id: row.post_id, // internal — used for the private-bucket attachment lookup
    _makesafe_scanned_at: row.makesafe_scanned_at ?? null, // extract-at-most-once marker
  }))

  // INBOUND-ONLY contamination filter (BEFORE sender/subject match): ses@ is a
  // GROUP that receives a COPY of every pack WE send, so the projection is ~79%
  // our own outbound mail. Drop any email whose sender is one of our own outbound
  // domains so the candidate set is the inbound, known-sender set (same approach
  // as makesafe_new_emails / GAP-1).
  const inboundMessages = mappedMessages.filter(
    (msg: any) => !_isOwnDomain(_deriveFromDomain(msg.from?.emailAddress?.address || null)),
  )

  // Empty-feed anomaly signal: the freshest INBOUND (non-own-domain) email this scan can
  // see. If the Graph mirror starts returning nothing, this stops advancing and the alarm
  // trips during business hours. Own outbound is excluded so our own sends can't mask it.
  let mostRecentInboundIso: string | null = null
  for (const m of inboundMessages) {
    const r = m.receivedDateTime || null
    if (r && (!mostRecentInboundIso || String(r) > mostRecentInboundIso)) mostRecentInboundIso = String(r)
  }

  // Filter to known make-safe senders (UNCHANGED logic, now over the inbound set)
  const matchedMessages = inboundMessages.filter((msg: any) => {
    const fromEmail = (msg.from?.emailAddress?.address || '').toLowerCase()
    const subject = (msg.subject || '').toLowerCase()
    // makesafe-inbound-filter — cheap SUBJECT pre-filter: drop the unambiguous
    // non-WO subjects (Photo Evidence / Report / Invoice / Correction / Crew
    // Report) BEFORE the expensive attachment read + Haiku call. RE/FW is a
    // downstream risk flag when work-order evidence exists, not a hard drop.
    // The hard isGenuineNewWorkOrder gate still runs before insert below.
    if (_subjectIsExcludedNonWorkOrder(msg.subject || '')) return false
    // Match if sender matches a known pattern OR subject contains work order keywords.
    // Sender matching is shared with monitor-ses-makesafes and uses anchored domain
    // suffix logic, not substring includes(), so lookalike domains cannot drift in.
    // The code-level watched-sender floor (item 11) adds Prime's notification
    // channel as a first-class sender so its WOs are candidates even without a DB
    // pattern; the isGenuineNewWorkOrder gate below still guards draft creation.
    const senderMatch = senderPatterns.some(sp => _senderMatchesPattern(fromEmail, sp.pattern))
    const floorMatch = _senderMatchesWatchedFloor(fromEmail)
    const subjectMatch = /work\s*order|make\s*safe|emergency|storm|urgent\s*(attend|repair)/i.test(subject)
    return senderMatch || floorMatch || (subjectMatch && (fromEmail.includes('.build') || fromEmail.includes('primeeco.tech')))
  })

  // Process a bounded number of UNPROCESSED candidates, not a blind "newest 50"
  // slice. Cheap duplicate checks still run across the full paged matched window.
  // The scan order interleaves oldest/newest matches before applying the budget
  // so a sustained flood of fresh mail cannot permanently starve older real work
  // orders that are still inside the seven-day candidate window.
  const fairMatchedMessages = _interleaveOldestNewestForFairScan(matchedMessages)
  const maxUnprocessedCandidates = Math.max(
    1,
    Number(Deno.env.get('MAKESAFE_INTAKE_SCAN_MAX_UNPROCESSED') || '200') || 200,
  )

  // BUG 1 — CROSS-PATH DEDUP. The OLD user-mailbox path and the NEW group-sync path
  // assign DIFFERENT graph_message_id values to the SAME work-order email, so a
  // graph_message_id-only check (the previous behaviour) re-drafts an email that was
  // already drafted by the other path. Build a single index over EVERY existing draft
  // in a live state (draft|needs_review|approved) — not just the candidate
  // graph_message_ids — plus existing make-safe jobs' external refs. A candidate is
  // skipped if it matches on graph_message_id OR internet_message_id OR
  // (normalised external_ref + requesting_company) OR an existing job's external_ref.
  // internet_message_id is null on the group-sync path (group posts don't expose it),
  // so (ref + company) is the workhorse cross-path key. See makesafe_intake_dedup.ts.
  const existingDrafts = await _fetchAllRows<any>(
    () => client.from('makesafe_intake_drafts')
      .select('graph_message_id, internet_message_id, external_ref, requesting_company_slug, requesting_company_name, status, report_type, subject, body_preview, description, extraction_json, from_email, received_at')
      .eq('org_id', DEFAULT_ORG_ID)
      .in('status', _LIVE_DRAFT_STATES as unknown as string[]),
    'makesafe_intake_drafts (dedup index) read',
  )
  // F1 (re-spam guard): also fetch rejected/superseded drafts so the cron does not
  // endlessly resurrect them. A normal scan candidate matching a rejected/superseded
  // ref+company is suppressed (reason='suppressed_rejected'). Only a targeted
  // recapture (force_recapture=true) can bypass this guard.
  const rejectedDrafts = await _fetchAllRows<any>(
    () => client.from('makesafe_intake_drafts')
      .select('graph_message_id, internet_message_id, external_ref, requesting_company_slug, requesting_company_name, status, received_at, extraction_json')
      .eq('org_id', DEFAULT_ORG_ID)
      .in('status', _SUPPRESSED_DRAFT_STATES as unknown as string[]),
    'makesafe_intake_drafts (rejected dedup index) read',
  )
  // Already-created jobs with a matching external ref (a live job already covers it).
  // Fetch job_id + jobs.status + requesting_company_slug so a job_external_ref hit:
  //   (a) is only surfaced as a reopen_candidate when the matched job is reopen-eligible
  //   (b) is keyed by normalised-ref + company slug to prevent cross-builder ref
  //       collisions (two builders can share a ref number like "67998"; without the
  //       company scope the map would overwrite one builder's job with the other's).
  const { data: existingJobs } = await client.from('makesafe_job_details')
    .select('job_id, external_ref, requesting_company_slug, report_type, jobs(status, metadata, notes)')
    .not('external_ref', 'is', null)
  // Build a (normalised-ref|company-slug|job-family) -> { jobId, status } lookup.
  const refToJobId = new Map<string, { jobId: string; status: string | null }>()
  const existingJobDedupRows: Array<{ external_ref: string | null; requesting_company_slug?: string | null; makesafe_job_family: string | null; builder_work_order_number?: string | null; builder_po_number?: string | null }> = []
  for (const j of (existingJobs || []) as Array<{ job_id: string; external_ref: string; requesting_company_slug: string | null; report_type?: string | null; jobs: { status: string; metadata?: any; notes?: string | null } | { status: string; metadata?: any; notes?: string | null }[] | null }>) {
    const nr = _normaliseDedupRef(j.external_ref)
    if (nr && j.job_id) {
      const jobsData = Array.isArray(j.jobs) ? j.jobs[0] : j.jobs
      const companyKey = (j.requesting_company_slug || '').toLowerCase()
      const jobMetadata = parseJsonObject(jobsData?.metadata)
      const jobFamily = jobMetadata.makesafe_job_family || _classifyMakeSafeJobFamily(
        j.external_ref || '',
        [j.report_type, jobsData?.notes].filter(Boolean).join('\n'),
        j.report_type || null,
      )
      const familyKey = _normaliseDedupJobFamily(jobFamily)
      const jobDedupRef = cleanReviewedString(jobMetadata.builder_claim_ref) || j.external_ref
      existingJobDedupRows.push({
        external_ref: jobDedupRef,
        requesting_company_slug: companyKey || null,
        makesafe_job_family: familyKey || null,
        builder_work_order_number: cleanReviewedString(jobMetadata.builder_work_order_number) || null,
        builder_po_number: cleanReviewedString(jobMetadata.builder_po_number) || null,
      })
      // Primary key: ref|company|family so one builder ref can have separate report/temp/general jobs.
      refToJobId.set(`${nr}|${companyKey}|${familyKey}`, { jobId: j.job_id, status: jobsData?.status ?? null })
      // Fallbacks for old jobs where company/family metadata is missing.
      refToJobId.set(`${nr}|${companyKey}|`, { jobId: j.job_id, status: jobsData?.status ?? null })
      if (!refToJobId.has(nr)) refToJobId.set(nr, { jobId: j.job_id, status: jobsData?.status ?? null })
    }
  }
  const existingDraftDedupRows = (existingDrafts || []).map((d: any) => {
    const extractionJson = parseJsonObject(d.extraction_json)
    const draftFamily = extractionJson.makesafe_job_family || _classifyMakeSafeJobFamily(
      d.subject || d.external_ref || '',
      [d.report_type, d.body_preview, d.description].filter(Boolean).join('\n'),
      d.report_type || null,
    )
    return {
      ...d,
      external_ref: cleanReviewedString(extractionJson.builder_claim_ref) || d.external_ref,
      makesafe_job_family: draftFamily || null,
      builder_work_order_number: cleanReviewedString(extractionJson.builder_work_order_number) || null,
      builder_po_number: cleanReviewedString(extractionJson.builder_po_number) || null,
    }
  })
  const rejectedDraftDedupRows = (rejectedDrafts || []).map((d: any) => {
    const extractionJson = parseJsonObject(d.extraction_json)
    return {
      ...d,
      external_ref: cleanReviewedString(extractionJson.builder_claim_ref) || d.external_ref,
      builder_work_order_number: cleanReviewedString(extractionJson.builder_work_order_number) || null,
      builder_po_number: cleanReviewedString(extractionJson.builder_po_number) || null,
    }
  })
  const dedupIndex = _buildIntakeDedupIndex(
    existingDraftDedupRows,
    existingJobDedupRows,
    rejectedDraftDedupRows,
  )

  const newDrafts: any[] = []
  let skippedDuplicates = 0
  let processedCandidates = 0
  let cappedCandidates = 0
  let skippedAiOnly = 0
  let skippedNotWorkOrderGate = 0
  let cancellationsDetected = 0
  let nudgeLinksAttached = 0 // item 4: portal links landed on an existing job from a nudge email
  let secondDeliverableDrafts = 0 // M-G D-3: distinct second WO for an active job, surfaced not dropped
  const skippedItems: any[] = []
  const autoApproved: any[] = []
  const autoApproveFailed: any[] = []
  // A2/A3 dropped-WO breadcrumb accumulators (folded into makesafe_intake_health after
  // the loop; the health alarm fires when live-collision + dropped > 0).
  let insertConflictsHealed = 0
  let insertConflictsLive = 0
  let droppedAfterExtraction = 0
  let lastDroppedRef: string | null = null
  // A5 arrival texts fired this scan (observability only).
  let arrivalTextsSent = 0
  // M1.5 cost ledger: per-scan running totals of model calls / template skips / tokens.
  let scanCostTotals = _emptyScanTotals()
  // Reliability slice: typed cycle outcome. Health may read OK after a partial success,
  // but never when every actual provider attempt failed. Terminal items are quarantined
  // after one automatic attempt and stay recoverable through reextract_intake_draft.
  let extractionAttempts = 0
  let extractionSuccesses = 0
  let terminalExtractionFailures = 0
  let retryableExtractionFailures = 0
  const extractionFailureReasons: ExtractionFailureReason[] = []
  let providerTerminalClassification: ExtractionFailureClassification | null = null
  let quarantinedItems = 0
  let itemLocalQuarantinedItems = 0
  const quarantinedEmailIds: string[] = []
  // An ITEM-LOCAL permanent failure must be bounded no matter WHICH exit its email takes
  // out of the loop — the work-order gate, any dedup/late-PDF skip, an insert failure or
  // a clean draft insert. Registering it here at classification time (rather than at each
  // `continue`) makes that structural: anything still pending after the loop never got a
  // durable draft, so it is flushed to a durable visible quarantine record and only then
  // marked scanned. Entries are dropped once a draft carries the evidence instead.
  const pendingItemLocalTerminals = new Map<string, {
    graphMessageId: string
    postId: string | null
    subject: string | null
    fromEmail: string | null
    receivedAt: string | null
    dropReason: string
    reason: ExtractionFailureReason
    message: string
  }>()
  let itemLocalQuarantinePersistFailures = 0
  // Per-draft auto-file truth. A global "auto_file_enabled:false" hides that some drafts
  // were created and eligible before a later failure, so report the actual split.
  let autoFileEligibleDrafts = 0
  let autoFileSuppressedDrafts = 0
  // Cost-leak fix: emails skipped because they were already extracted (marker set), and
  // the post_ids to STAMP as scanned this run (successful extraction/classification —
  // draft or not). Batch-marked at the end so each email is extracted at most once.
  let skippedAlreadyScanned = 0
  const scannedEmailIds: string[] = []

  // D-d kill switch (Captain D1 default TRUE): the DB flag decides whether the scan
  // may auto-file clean drafts this run. Read ONCE per scan.
  const autoFileEnabled = await isAutoFileEnabled(client)

  // A5 arrival-text config (recipients + kill switch). Read ONCE per scan; a genuine
  // new WO texts the owner crew once (fire-once via makesafe_notify_log).
  const notifySettings: _NotifySettings = await _loadNotifySettings(client)

  // M1.5 lever 1 kill switch: local PDF text extraction is ON by default; set
  // MAKESAFE_INTAKE_PDF_TEXT_MODE=false to force the document-block path with no
  // redeploy if the text path ever regresses extraction accuracy.
  const pdfTextModeEnabled = Deno.env.get('MAKESAFE_INTAKE_PDF_TEXT_MODE') !== 'false'

  // D-a FAIL-LOUD preflight. keyDegraded starts true when the key is UNSET (v1's exact
  // silent-death shape) and flips true the moment a classifier call fails auth (revoked
  // key). While degraded every draft is tagged, forced to needs_review, and never
  // auto-filed, and a visible makesafe_intake_health banner is written after the loop.
  const ANTHROPIC_API_KEY = Deno.env.get('ANTHROPIC_API_KEY')
  let keyDegraded = !ANTHROPIC_API_KEY
  let keyDegradedReason: string | null = ANTHROPIC_API_KEY ? null : 'key_unset'
  let anyExtractionSucceeded = false
  if (!ANTHROPIC_API_KEY) {
    providerTerminalClassification = {
      failureClass: 'terminal', reason: 'key_unset', quarantine: true, stopProviderLane: true,
    }
  }

  for (const msg of fairMatchedMessages) {
    // Cost-leak fix: EXTRACT-AT-MOST-ONCE. If this email was already scanned in a prior
    // run (marker set), skip it BEFORE the model call — this is what stops the ~4
    // non-work-order emails (no draft, so nothing for the draft-dedup to catch) being
    // re-extracted every 2-minute cycle. Cheap check, no cost.
    if (msg._makesafe_scanned_at) {
      skippedAlreadyScanned++
      skippedItems.push({ id: msg.id, subject: msg.subject || null, reason: 'already_scanned' })
      continue
    }
    // Cheap pre-extraction dedup on the ids AND the M1.5 D0 dual-capture content
    // fingerprint (sender + subject + received minute) — the fingerprint catches the
    // group-post / mailbox-fallback twin of the same email BEFORE the model call, so
    // the redundant capture path never costs a second Haiku call. The (ref + company)
    // check runs again AFTER extraction once we know the ref + matched company.
    const earlyDup = _isDuplicateIntake(
      {
        graph_message_id: msg.id,
        internet_message_id: msg.internetMessageId || null,
        from_email: msg.from?.emailAddress?.address || null,
        subject: msg.subject || null,
        received_at: msg.receivedDateTime || null,
        // H2: body feeds the fingerprint discriminator when no ref is parseable, so two
        // different ref-less jobs with an identical generic subject never collapse.
        body: msg.body?.content || msg.bodyPreview || null,
      },
      dedupIndex,
    )
    if (earlyDup) {
      skippedDuplicates++
      skippedItems.push({ id: msg.id, subject: msg.subject || null, reason: earlyDup })
      continue
    }
    if (processedCandidates >= maxUnprocessedCandidates) {
      cappedCandidates++
      skippedItems.push({
        id: msg.id,
        subject: msg.subject || null,
        reason: 'scan_budget_capped',
      })
      continue
    }
    processedCandidates++

    const fromEmail = msg.from?.emailAddress?.address || ''
    const fromName = msg.from?.emailAddress?.name || ''
    const subject = msg.subject || ''
    const replyForwardRisk = _subjectHasReplyForwardPrefix(subject)
    // Use full body for extraction (phone numbers and report links are often past
    // the 500-char preview cutoff). Keep a sanitized trade-readable copy for
    // report-only jobs; the email body is the source of truth for Prime/MLB links.
    const rawEmailBody = msg.body?.content || msg.bodyPreview || ''
    const builderEmailTextForTrade = _stripEmailHtmlForTrade(rawEmailBody)
    const deterministicPortalLinks = _extractBuilderEmailLinks(rawEmailBody)
    const bodyPreview = (builderEmailTextForTrade || String(msg.bodyPreview || '')).slice(0, 2000)

    // Match sender to company
    let matchedCompany: { slug: string; name: string } | null = null
    const matchedSenderPattern = _findMatchingSenderCompany(fromEmail, senderPatterns)
    if (matchedSenderPattern) {
      matchedCompany = { slug: matchedSenderPattern.slug, name: matchedSenderPattern.name }
    }

    // Read PDF attachments FIRST so we can feed them to Haiku.
    // Wave 1: bytes come from the PRIVATE makesafe-emails bucket (where the group
    // sync stored them) instead of a live Graph attachment download. Only rows
    // with status='uploaded' have servable bytes (the GAP-2 invariant). We then
    // RE-UPLOAD to the PUBLIC job-documents bucket at the SAME path pattern and
    // produce the IDENTICAL attachments_json shape, so the cockpit (which reads
    // attachments_json[].pdf_url) keeps working with no UI change.
    //
    // GAP-A (WO selection + unique key) — mission makesafe-wo-capture-recovery-2026-06-17.
    // We collect ALL uploaded PDF rows first, run selectWorkOrderPdf to designate
    // the WO and reorder (WO first), then iterate the ORDERED list. Each attachment
    // gets a UNIQUE storage key: makesafe-intake/<hash(msg.id)>-<keyComponent>/<safeName>
    // so two PDFs with the same/similar filename never overwrite each other.
    // The designated WO is fed to Haiku first (pdfBase64List ordering) and marked
    // is_work_order:true in attachments_json.
    //
    // GAP-B (B1 detect-and-flag) — same mission. After the uploaded-PDF capture,
    // if no servable PDF was produced AND the email passes a NEW-WO-subject check,
    // query email_attachments for needs_review rows with a qualifying WO-bytes reason
    // (pdf_no_inline_bytes_value_path_required / pdf_exceeds_inline_decode_cap /
    // pdf_magic_byte_validation_failed) OR a PDF-ish referenceAttachment/itemAttachment.
    // Push ONE flag entry so the draft is visible with an explicit reason, never silent.
    const attachments: any[] = []
    const pdfBase64List: Array<{ name: string; base64: string }> = []
    if (msg.hasAttachments) {
      try {
        // Read all uploaded PDF rows for this email.
        const { data: attRows, error: attErr } = await client.from('email_attachments')
          .select('id, graph_attachment_id, name, content_type, storage_path, size_bytes')
          .eq('email_id', msg._post_id)
          .eq('status', 'uploaded')
        if (attErr) {
          console.log('[ops-api] intake attachment lookup failed:', attErr.message)
        }

        // Filter to PDFs only (mirrors the original isPdf check).
        const uploadedPdfRows = (attRows || []).filter((att: any) => {
          const isPdf = (att.content_type || '').includes('pdf') || (att.name || '').endsWith('.pdf')
          return isPdf && att.storage_path
        })

        // GAP-A: designate the WO PDF and reorder (WO first, rest stable order).
        const { selected: designatedWo, ordered: orderedPdfs } = _selectWorkOrderPdf(uploadedPdfRows)

        // Pre-compute the per-message hash (used for all keys in this message).
        const keyHash = await _shortStorageKey(msg.id)

        for (let attIdx = 0; attIdx < orderedPdfs.length; attIdx++) {
          const att = orderedPdfs[attIdx]
          try {
            // Download the bytes from the PRIVATE makesafe-emails bucket.
            const { data: blob, error: dlErr } = await adminClient.storage
              .from('makesafe-emails')
              .download(att.storage_path!)
            if (dlErr || !blob) {
              console.log('[ops-api] PDF download failed for intake:', dlErr?.message || 'no blob', att.storage_path)
              continue
            }
            const fileBuffer = new Uint8Array(await blob.arrayBuffer())

            // GAP-A: feed the designated WO to Haiku FIRST; keep the <2 + <5MB cap.
            // Because orderedPdfs has the WO first, the WO naturally enters pdfBase64List
            // first (if it is small enough). Other PDFs follow in original stable order.
            if (pdfBase64List.length < 2 && fileBuffer.length < 5000000) {
              pdfBase64List.push({ name: att.name ?? 'work-order.pdf', base64: bytesToBase64(fileBuffer) })
            }

            // GAP-A: UNIQUE storage key per attachment.
            // Old key: makesafe-intake/<hash(msg.id)>/<safeName.slice(-80)>
            //   → two PDFs with the same/similar trailing filename overwrite each other.
            // New key: makesafe-intake/<hash(msg.id)>-<keyComponent(att)>/<safeName>
            //   → every attachment in an email gets its own prefix segment.
            const safeName = (att.name || 'work-order.pdf').replace(/[^a-zA-Z0-9._-]/g, '_').slice(-80)
            const keyComponent = _attachmentKeyComponent(att, attIdx)
            const storagePath = `makesafe-intake/${keyHash}-${keyComponent}/${safeName}`
            const { error: upErr } = await adminClient.storage
              .from('job-documents')
              .upload(storagePath, fileBuffer, { contentType: 'application/pdf', upsert: true })
            if (upErr) {
              // Upload failed — DO NOT record a pdf_url that would 404. Keep the
              // attachment in the list (it IS a real WO PDF we have private bytes
              // for) but flag it unavailable so the cockpit renders the fallback.
              console.log('[ops-api] intake job-documents upload failed:', upErr.message, storagePath)
              attachments.push({
                name: att.name,
                file_name: att.name,
                storage_url: null,
                pdf_url: null,
                pdf_unavailable: true,
                pdf_error: `upload_failed:${upErr.message}`.slice(0, 200),
                size: att.size_bytes,
                // GAP-A: mark which PDF is the designated work order.
                is_work_order: (att === designatedWo),
              })
              continue
            }
            const { data: urlData } = adminClient.storage.from('job-documents').getPublicUrl(storagePath)
            attachments.push({
              name: att.name,
              file_name: att.name,
              storage_url: storagePath,
              pdf_url: urlData?.publicUrl || null,
              size: att.size_bytes,
              // GAP-A: mark the designated WO so the cockpit and approveIntakeDraft
              // can surface the right PDF first. Backward-compatible (existing
              // cockpit ignores unknown keys).
              is_work_order: (att === designatedWo),
            })
          } catch (e) {
            console.log('[ops-api] PDF re-upload failed for intake:', (e as Error).message)
          }
        }
      } catch (e) {
        console.log('[ops-api] Attachment read failed:', (e as Error).message)
      }
    }

    // Extract fields using Claude (email body + PDF attachments)
    let extraction: any = {}
    let confidence = 'low'
    let missingFields: string[] = []
    // M1.5 cost-path bookkeeping. Recorded on the draft (extraction_json.cost /
    // pdf_mode / parser / model_called) and folded into the per-scan cost totals below.
    let pdfMode: 'text' | 'document' | 'none' = pdfBase64List.length ? 'document' : 'none'
    let extractionParser: 'template' | 'none' = 'none'
    let modelCalled = false
    let callUsage = { ..._ZERO_USAGE }
    // Cost-leak fix: per-email extraction signals -> scanMarkEligible decides whether to
    // stamp the scanned marker (extract-at-most-once). A dead/absent key or an
    // auth/transient failure leaves the email UNMARKED so it retries when the key
    // recovers (fail-loud backfill preserved).
    let emailTemplateParsed = false
    let emailModelValidResult = false
    let emailAuthFailed = false
    let emailTransientFailed = false
    let emailTerminalFailed = false
    // An item-local permanent failure (malformed request). No provider recovery fixes it,
    // so it is bounded after ONE attempt — but only once its durable draft exists.
    let emailItemLocalTerminal = false
    let emailFailureClassification: ExtractionFailureClassification | null = null
    const templateSlug = (matchedCompany?.slug || '').toLowerCase()

    // M1.5 LEVER 1 — local PDF text extraction. Pull the text layer out of each
    // captured WO PDF in Deno (deterministic, key-less). If EVERY PDF yields clean text
    // over the threshold, feed cheap text blocks to the model instead of the ~10x
    // document blocks; a scanned/low-text PDF falls back to the document path unchanged.
    const pdfTexts: string[] = []
    // Item 5 — also keep the RAW recovered text layer (even when it failed the
    // model-quality gate) so the deterministic client-block reader can run a
    // label-anchored parse on it. Never used for the model path.
    const pdfRawTexts: string[] = []
    if (pdfBase64List.length && pdfTextModeEnabled) {
      let allText = true
      for (const pdf of pdfBase64List) {
        try {
          const bytes = Uint8Array.from(atob(pdf.base64), (c) => c.charCodeAt(0))
          const r = await _extractPdfText(bytes)
          if (r.mode === 'text') pdfTexts.push(`[${pdf.name}]\n${r.text}`)
          else allText = false
          if (r.rawText) pdfRawTexts.push(`[${pdf.name}]\n${r.rawText}`)
        } catch (_) {
          allText = false
        }
      }
      const combinedLen = pdfTexts.join('\n').length
      pdfMode = (allText && pdfTexts.length === pdfBase64List.length && combinedLen >= _PDF_TEXT_MIN_CHARS)
        ? 'text'
        : 'document'
    }
    const combinedPdfText = pdfTexts.join('\n')

    // M1.5 LEVER 2 — per-builder deterministic template parse. Runs for every builder
    // that has parsing_rules (as a preview). Only when the builder is flipped
    // template_first AND every required field parses does it SKIP the model entirely.
    const templateResult = _parseWithTemplate(parsingRulesBySlug.get(templateSlug), {
      subject,
      body: builderEmailTextForTrade || bodyPreview,
      pdfText: combinedPdfText,
    })

    if (templateResult?.model_skipped && !keyDegraded) {
      // Full deterministic parse on a template-first builder — no classifier call.
      const f = templateResult.fields
      extraction = {
        external_ref: f.external_ref || null,
        client_name: f.client_name || null,
        client_phone: f.client_phone || null,
        site_address: f.site_address || null,
        site_suburb: f.site_suburb || null,
        description: f.description || null,
        safety_requirements: f.safety_requirements || null,
      }
      confidence = templateResult.confidence
      missingFields = []
      extractionParser = 'template'
      modelCalled = false
      anyExtractionSucceeded = true
      emailTemplateParsed = true
    } else if (ANTHROPIC_API_KEY && !keyDegraded) {
      // D-a: run the classifier ONLY while the key is healthy. If the key is unset the
      // guard is false from the first email; if it dies mid-run the catch flips
      // keyDegraded and every subsequent email skips the call (no silent spray).
      try {
        const { default: Anthropic } = await import('https://esm.sh/@anthropic-ai/sdk@0.39.0')
        const anthropic = new Anthropic({ apiKey: ANTHROPIC_API_KEY })

        // Build message content: email text + PDF (text blocks when the text layer was
        // extracted, else document blocks — same information, far fewer tokens on text).
        const userContent: any[] = [
          { type: 'text', text: `From: ${fromName} <${fromEmail}>\nSubject: ${subject}\nBody: ${bodyPreview}` },
        ]
        if (pdfMode === 'text') {
          for (const t of pdfTexts) {
            userContent.push({ type: 'text', text: `[Work order PDF text]\n${t}` })
          }
        } else {
          for (const pdf of pdfBase64List) {
            userContent.push({
              type: 'document',
              source: { type: 'base64', media_type: 'application/pdf', data: pdf.base64 },
            })
            userContent.push({ type: 'text', text: `[Attached PDF: ${pdf.name}]` })
          }
        }

        // M1.5 LEVER 3 — prompt caching. The static instruction prefix is marked
        // cache_control:ephemeral so repeat calls within the 5-minute TTL pay the
        // 0.1x cached-input rate. (Haiku 4.5's cache minimum is 4096 tokens, so this
        // only bites once the static prefix is large enough; the usage ledger below
        // captures cache_read/cache_creation tokens so the effect is measurable.)
        // Mark the call as made BEFORE awaiting so a transient throw is still counted
        // as a model call (not miscounted as a template skip) in the cost ledger.
        modelCalled = true
        extractionAttempts++
        const resp = await anthropic.messages.create({
          model: MAKESAFE_EXTRACTION_MODEL,
          max_tokens: MAKESAFE_EXTRACTION_MAX_TOKENS,
          system: [{
            type: 'text',
            cache_control: { type: 'ephemeral' },
            text: MAKESAFE_EXTRACTION_SYSTEM_PROMPT,
          }],
          messages: [{ role: 'user', content: userContent }],
        })
        callUsage = _readUsage(resp.usage)
        const text = resp.content[0].type === 'text' ? resp.content[0].text : ''
        const jsonMatch = text.match(/\{[\s\S]*\}/)
        if (jsonMatch) {
          extraction = JSON.parse(jsonMatch[0])
          confidence = extraction.confidence || 'low'
          missingFields = extraction.missing_fields || []
          anyExtractionSucceeded = true
          extractionSuccesses++
          emailModelValidResult = true
        } else {
          throw new Error('response parse failed: Anthropic returned no JSON object')
        }
      } catch (e) {
        const em = (e as Error).message || String(e)
        const failure = _classifyExtractionFailure(e)
        emailFailureClassification = failure
        extractionFailureReasons.push(failure.reason)
        extraction._extraction_error = em.slice(0, 200)
        extraction.extraction_failure = _extractionFailureState(failure, em)
        if (failure.failureClass === 'terminal') {
          terminalExtractionFailures++
          emailTerminalFailed = true
          emailAuthFailed = failure.reason === 'auth_failed'
          if (failure.stopProviderLane) {
            keyDegraded = true
            keyDegradedReason = failure.reason
            providerTerminalClassification = failure
          } else {
            emailItemLocalTerminal = true
          }
          console.error(`[ops-api] make-safe extraction TERMINAL ${failure.reason}; quarantining source item:`, em)
        } else {
          retryableExtractionFailures++
          emailTransientFailed = true
          console.error(`[ops-api] make-safe extraction RETRYABLE ${failure.reason}; kept for retry:`, em)
        }
      }
    }

    // Once a provider-wide terminal failure is known, later source items do not call the
    // provider. They receive the same visible quarantine state and are bounded too.
    if (!emailTemplateParsed && !emailModelValidResult && !emailFailureClassification && providerTerminalClassification) {
      emailFailureClassification = providerTerminalClassification
      emailTerminalFailed = true
      const em = keyDegradedReason === 'key_unset'
        ? 'ANTHROPIC_API_KEY is not configured'
        : `provider lane stopped after terminal ${providerTerminalClassification.reason}`
      extraction._extraction_error = em
      extraction.extraction_failure = _extractionFailureState(providerTerminalClassification, em)
    }

    // M1.5 cost ledger: stamp which path this email used + its token cost onto the
    // draft, and fold it into the per-scan totals. Only real extraction attempts
    // (template skip or a model call) are recorded — a dead-key draft is not a "skip".
    if (extractionParser === 'template' || modelCalled) {
      const emailCost = _emailCostRecord({
        model_called: modelCalled,
        pdf_mode: pdfMode,
        parser: extractionParser,
        usage: callUsage,
      })
      extraction.cost = emailCost
      extraction.pdf_mode = pdfMode
      extraction.parser = extractionParser
      extraction.model_called = modelCalled
      // When the model was called but a template parse also ran, keep a compact preview
      // so the Captain / golden-replay can compare before flipping this builder.
      if (templateResult && modelCalled) {
        extraction.template_preview = {
          full_parse: templateResult.full_parse,
          fields: templateResult.fields,
          missing_required: templateResult.missing_required,
        }
      }
      scanCostTotals = _accrueScanTotals(scanCostTotals, emailCost)
    }

    // M1.5 UNIVERSAL PRE-MODEL PARSE — runs for EVERY builder, EVERY path (template
    // skip / model call / dead-key). Live audit: subjects read "NEW WORK ORDER -
    // MLB-26499 18 Eagleglen Rise, Gidgegannup" yet every draft had external_ref/
    // site_address null. The deterministic subject ref is AUTHORITATIVE (exact, from
    // the builder's own subject, and it feeds the (external_ref, family) dedup key that
    // is degenerate while null); the address only fills what the model didn't produce,
    // so accuracy is same-or-better, never regressed.
    const subjectFields = _parseSubjectFields(subject)
    // M2: on a RE:/FW: reply the subject may quote ANOTHER job's ref; overriding the
    // model's ref would misroute the (ref, family) dedup key + job creation. resolveSubjectRef
    // makes the subject ref authoritative off a reply, and a HINT only on a reply. The
    // reply_forward_risk needs_review marker (added below) still fires either way.
    const refDecision = _resolveSubjectRef(replyForwardRisk, subjectFields.external_ref, extraction.external_ref || null)
    if (refDecision.external_ref) extraction.external_ref = refDecision.external_ref
    if (refDecision.subject_ref_hint) extraction.subject_ref_hint = refDecision.subject_ref_hint
    if (!replyForwardRisk) {
      if (!cleanReviewedString(extraction.site_address) && subjectFields.site_address) {
        extraction.site_address = subjectFields.site_address
      }
      if (!cleanReviewedString(extraction.site_suburb) && subjectFields.site_suburb) {
        extraction.site_suburb = subjectFields.site_suburb
      }
    }
    const ajPrefill = _deriveAjIntakePrefill({
      fromEmail,
      subject,
      bodyText: builderEmailTextForTrade || bodyPreview,
    })
    const ajApplied = _applyAjIntakePrefill(extraction, ajPrefill)
    extraction = ajApplied.extraction
    if (ajApplied.filledFields.length) {
      const filled = new Set(ajApplied.filledFields.map((field) => cleanMissingFieldName(field)))
      missingFields = missingFields.filter((field: string) => !filled.has(cleanMissingFieldName(field)))
    }

    // Item 5 — deterministic WO-PDF client-field fill (opt-in, default OFF). MLB
    // "NEW WORK ORDER" bodies carry the homeowner name/phone only in the WO PDF, so
    // the model/template leaves client_name/client_phone null and the draft can
    // never become clean. When enabled, read a single UNAMBIGUOUS client block from
    // the recovered WO PDF text and fill ONLY the null fields (tagged PDF-sourced);
    // an ambiguous / unreadable PDF fills nothing and stays manual.
    if (pdfClientFillEnabled()) {
      const clientText = combinedPdfText || pdfRawTexts.join('\n')
      if (clientText) {
        const fill = _decidePdfClientFill(clientText, {
          clientName: cleanReviewedString(extraction.client_name) || null,
          clientPhone: cleanReviewedString(extraction.client_phone) || null,
          siteAddress: cleanReviewedString(extraction.site_address) || null,
          confidence,
          missingFields,
          externalRefPresent: !!cleanReviewedString(extraction.external_ref),
          matchedCompanyPresent: !!(matchedCompany?.slug || matchedCompany?.name),
        })
        if (fill.applied) {
          for (const f of fill.filledFields) extraction[f] = fill.fill[f]
          extraction.pdf_sourced_fields = [
            ...(Array.isArray(extraction.pdf_sourced_fields) ? extraction.pdf_sourced_fields : []),
            ...fill.filledFields,
          ]
          missingFields = fill.missingFields
          confidence = fill.confidence
        }
      }
    }

    // Cost-leak fix: if this email got a valid extraction/classification, mark it
    // scanned — WHETHER OR NOT it becomes a draft below. This is the key fix: a
    // non-work-order email that the gate drops (no draft) is still marked here, so it is
    // never re-extracted. Placed BEFORE the gate-drop `continue`s. scanMarkEligible
    // returns false on every recoverable failure — auth, transient, provider-lane
    // quarantine or a dead/absent key — so those emails stay unmarked and retry when the
    // provider recovers (fail-loud backfill preserved). Cost is bounded by stopping the
    // lane, not by consuming items. An item-local permanent failure is the exception: it
    // is marked further down, only AFTER its durable draft exists.
    const thisEmailExtractionOk = _scanMarkEligible({
      templateParsed: emailTemplateParsed,
      modelValidResult: emailModelValidResult,
      authFailed: emailAuthFailed,
      transientFailed: emailTransientFailed,
      terminalQuarantined: emailTerminalFailed,
      itemLocalTerminalRecorded: false,
      keyDegradedOrAbsent: keyDegraded || !ANTHROPIC_API_KEY,
    })
    if (thisEmailExtractionOk && msg._post_id) {
      scannedEmailIds.push(msg._post_id)
    }
    // Provider-lane quarantine is visible but NOT scanned: the source item stays pending
    // so the next scan supplies recovery proof automatically once the lane is healthy.
    if (emailTerminalFailed) {
      quarantinedItems++
      if (emailItemLocalTerminal) itemLocalQuarantinedItems++
      if (msg._post_id) quarantinedEmailIds.push(msg._post_id)
    }

    // An ITEM-LOCAL permanent failure that an intake gate then DROPS never reaches the
    // draft insert, so without this it would hit the provider again every two minutes
    // forever. Register it the moment it is classified — every exit path below is then
    // covered by the post-loop flush, which persists the durable visible record first and
    // only marks the source scanned on a confirmed write.
    if (emailItemLocalTerminal) {
      pendingItemLocalTerminals.set(msg.id, {
        graphMessageId: msg.id,
        postId: msg._post_id || null,
        subject,
        fromEmail,
        receivedAt: msg.receivedDateTime || null,
        dropReason: 'gate_dropped_after_item_local_failure',
        reason: emailFailureClassification?.reason || 'request_invalid',
        message: String(extraction._extraction_error || ''),
      })
    }
    // Names the gate that dropped it, so the durable record carries the real reason
    // rather than the generic fallback. Purely descriptive: registration above is what
    // bounds the item.
    const recordItemLocalTerminalDrop = (dropReason: string) => {
      const pending = pendingItemLocalTerminals.get(msg.id)
      if (pending) pending.dropReason = dropReason
    }
    // Some exits DO write durable evidence (a draft minted or a late PDF landed on an
    // existing draft) and then continue before the common exit. That draft is the
    // durable record, so the item must leave the pending set — otherwise the post-loop
    // flush would emit a quarantine event asserting "no draft minted" for an email that
    // has one — while still being marked scanned so it stops re-hitting the provider.
    const resolveItemLocalTerminalWithDurableDraft = () => {
      if (!emailItemLocalTerminal) return
      if (!pendingItemLocalTerminals.delete(msg.id)) return
      if (msg._post_id && !scannedEmailIds.includes(msg._post_id)) scannedEmailIds.push(msg._post_id)
    }

    // D-a: tag EVERY draft made while the key is dead/unset so it is a loud
    // needs_review docket with an explicit marker, never a silent empty draft — and,
    // because the marker is a blocking missing field + confidence is forced low, it can
    // never be auto-filed.
    // Auto-file eligibility is PER DRAFT. Any draft whose enrichment failed or was
    // skipped after the lane degraded is review-only — including a retryable failure,
    // whose draft is just as unenriched as a terminal one.
    const draftExtractionDegraded = keyDegraded || !ANTHROPIC_API_KEY ||
      emailTerminalFailed || emailTransientFailed
    if (draftExtractionDegraded) {
      extraction.extraction_degraded = true
      extraction.extraction_degraded_reason = emailFailureClassification?.reason || keyDegradedReason || 'key_unset'
      if (!missingFields.includes(INTAKE_EXTRACTION_DOWN_MARKER)) {
        missingFields.push(INTAKE_EXTRACTION_DOWN_MARKER)
      }
      confidence = 'low'
    }

    // Item 4 — also mine portal/report links out of the recovered WO PDF text, not
    // just the email body, so a share link that only appears in the attachment still
    // reaches the job's external_links (and the trade view).
    const attachmentPortalLinks = _extractBuilderEmailLinks(null, combinedPdfText || pdfRawTexts.join('\n'))
    const mergedPortalLinks = _mergeDeterministicAndClaudeLinks([...deterministicPortalLinks, ...attachmentPortalLinks], extraction)
    if (mergedPortalLinks.length) {
      extraction.portal_links = mergedPortalLinks
      extraction.portal_link = extraction.portal_link || mergedPortalLinks[0]?.url || null
    }
    if (builderEmailTextForTrade) {
      extraction.builder_email_text_for_trade = builderEmailTextForTrade
      extraction.builder_email_subject = subject || null
      extraction.builder_email_received_at = msg.receivedDateTime || null
    }
    const builderIdentity = _extractBuilderWorkOrderIdentity({
      externalRef: extraction.external_ref || null,
      subject,
      bodyText: builderEmailTextForTrade || bodyPreview,
      attachmentNames: attachments.map((a: any) => a?.file_name || a?.name || null),
    })
    extraction = _mergeBuilderWorkOrderIdentity(extraction, builderIdentity)
    if (extraction.external_ref) {
      missingFields = missingFields.filter((f: string) => {
        const clean = String(f || '').trim().toLowerCase().replace(/[\s-]+/g, '_')
        return clean !== 'external_ref' && clean !== 'reference' && clean !== 'builder_ref'
      })
    }

    // BUG 2 (CAPTURE): `attachments` may now include an entry whose re-upload FAILED
    // (pdf_unavailable=true, null URLs). Such an entry is NOT a servable work-order
    // PDF. Count only AVAILABLE WO PDFs (a real pdf_url, not flagged unavailable) for
    // the gate + required-field logic, so an upload-failure can't (a) let an email
    // pass the WO gate on a non-existent PDF, or (b) mark a draft needs_review/approve-
    // ready when no WO PDF can actually be opened. The unavailable entry is still kept
    // in attachments_json (with its error) so the cockpit shows the graceful fallback.
    const availableWoCount = attachments.filter(
      (a: any) => a && !a.pdf_unavailable && (a.pdf_url || a.storage_url),
    ).length

    // Capture-first guard: Haiku can flag "not_a_work_order", but that must not be
    // the sole reason a deterministic builder work item disappears. If deterministic
    // evidence exists, keep the item in the normal hard gate path and mark it for
    // human review rather than silently continuing.
    const aiNotWorkOrder = missingFields.includes('not_a_work_order')
    const deterministicRefEvidence =
      /\b(ajbr|ajs|mlb|bwc|bwcwa|wb|kba)[-\s#]*\d{3,}\b/i.test(`${subject}\n${bodyPreview}`)
    const deterministicWorkOrderEvidence =
      availableWoCount > 0 ||
      _subjectLooksLikeNewWorkOrder(subject) ||
      mergedPortalLinks.length > 0 ||
      deterministicRefEvidence ||
      !!builderIdentity.builder_claim_ref ||
      !!builderIdentity.builder_work_order_number ||
      !!matchedCompany
    if (aiNotWorkOrder && !deterministicWorkOrderEvidence) {
      skippedAiOnly++
      skippedItems.push({
        id: msg.id,
        subject,
        reason: 'ai_not_a_work_order_no_deterministic_evidence',
      })
      recordItemLocalTerminalDrop('ai_not_a_work_order_no_deterministic_evidence')
      continue
    }
    if (aiNotWorkOrder) {
      missingFields = missingFields.filter((f: string) => f !== 'not_a_work_order')
      if (!missingFields.includes('ai_not_a_work_order_needs_review')) {
        missingFields.push('ai_not_a_work_order_needs_review')
      }
      extraction.classification_reason =
        'AI suggested not_a_work_order, but deterministic intake evidence was present; kept for review.'
    }
    if (replyForwardRisk) {
      if (!missingFields.includes('reply_forward_risk')) missingFields.push('reply_forward_risk')
      extraction.reply_forward_risk = true
    }

    // GAP-B (B1 detect-and-flag) — mission makesafe-wo-capture-recovery-2026-06-17.
    // If no servable PDF was captured AND the email passes a NEW-WO SUBJECT check,
    // look for qualifying needs_review attachments (portal link / over-cap / magic-
    // byte fail). If found, push ONE flag entry so the draft is visible with an
    // explicit reason, rather than silently missing the WO.
    //
    // False-positive bound (F4): ONLY flag when:
    //   1. availableWoCount === 0 (no servable PDF already captured)
    //   2. subject passes subjectLooksLikeNewWorkOrder (stronger than a bare keyword)
    //   3. a qualifying needs_review row exists (WO-bytes last_error or PDF-ish
    //      referenceAttachment/itemAttachment) — NOT every needs_review row
    //      (avoids SharePoint-signature false positives)
    if (availableWoCount === 0 && _subjectLooksLikeNewWorkOrder(subject)) {
      try {
        const { data: nrRows } = await client.from('email_attachments')
          .select('id, graph_attachment_id, name, content_type, size_bytes, status, attachment_kind, last_error')
          .eq('email_id', msg._post_id)
          .eq('status', 'needs_review')
        // WO_BYTES_ERRORS: reasons monitor-ses writes when it SAW a PDF but could NOT get
        // bytes (over-cap / portal link). These land as status='needs_review'.
        // NOTE: 'pdf_magic_byte_validation_failed' is written with status='failed'
        // (markAttachmentFailed), NOT 'needs_review', so the B1 query (status='needs_review')
        // can never match it. Remove it from this set to eliminate the dead branch (Codex F6).
        const WO_BYTES_ERRORS = new Set([
          'pdf_no_inline_bytes_value_path_required',
          'pdf_exceeds_inline_decode_cap',
        ])
        const qualifyingNr = (nrRows || []).find((nr: any) => {
          // A WO-bytes error: the sync saw a PDF but couldn't get bytes (over-cap / portal / magic fail)
          if (nr.last_error && WO_BYTES_ERRORS.has(nr.last_error)) return true
          // A referenceAttachment / itemAttachment with a PDF-ish name or content_type
          // (a WO delivered via a SharePoint/OneDrive link or Outlook forwarded item)
          const kind = nr.attachment_kind || ''
          const isPdfRef = (nr.name || '').toLowerCase().endsWith('.pdf') ||
            (nr.content_type || '').includes('pdf')
          if ((kind === 'referenceAttachment' || kind === 'itemAttachment') && isPdfRef) return true
          return false
        })
        if (qualifyingNr) {
          attachments.push({
            name: qualifyingNr.name || 'work-order',
            file_name: qualifyingNr.name || null,
            storage_url: null,
            pdf_url: null,
            pdf_unavailable: true,
            pdf_error: 'portal_link_or_oversize_needs_review',
            size: qualifyingNr.size_bytes || null,
          })
          console.log('[ops-api] intake B1 flag: qualifying needs_review attachment for WO-subject email', subject, qualifyingNr.last_error || qualifyingNr.attachment_kind)
        }
      } catch (e) {
        console.log('[ops-api] intake B1 flag lookup failed:', (e as Error).message)
      }
    }

    // makesafe-inbound-filter — HARD GATE: a GENUINE new work order OR a captured
    // report/re-attend email becomes a draft. Drops photo-evidence / report /
    // invoice / outbound emails. RE/FW work-order evidence is kept with a risk
    // flag. Report-capture emails get kind='report'.
    const woGate = _isGenuineNewWorkOrder(subject, fromEmail, availableWoCount)
    if (!woGate.ok) {
      // Item 2: a CANCELLATION is not a new work order and must never mint a draft.
      // Breadcrumb the referenced ref so a human can flag / void the matching live job
      // (MLB-25769 was the twin-draft incident). Non-destructive: no job/invoice mutation.
      if (woGate.reason === 'cancelled_work_order') {
        cancellationsDetected++
        const refMatch = subject.match(/\b((?:mlb|wb|bw|bwc|bwcwa|kba)-?\s*\d+)/i)
        const cancelledRef = refMatch?.[1] || null
        skippedItems.push({ id: msg.id, subject, external_ref: cancelledRef, reason: woGate.reason })
        try {
          await logBusinessEvent(client, {
            event_type: 'makesafe.intake_cancellation_detected',
            source: 'app/makesafe-intake',
            entity_type: 'makesafe_ref',
            entity_id: cancelledRef || subject,
            body_preview: `Cancellation email detected; no intake draft minted. Flag the matching live job: ${subject}`,
            payload: { subject, from_email: fromEmail, external_ref: cancelledRef, graph_message_id: msg.id },
            metadata: { mission: 'intake/auto-approve-clean-drafts', reason: 'cancelled_work_order' },
          })
        } catch { /* non-blocking breadcrumb */ }
        console.log('[ops-api] intake skip (cancellation — no draft minted):', cancelledRef || subject)
        recordItemLocalTerminalDrop(woGate.reason)
        continue
      }
      console.log('[ops-api] intake skip (not a new work order):', woGate.reason, '|', subject)
      skippedNotWorkOrderGate++
      skippedItems.push({ id: msg.id, subject, reason: woGate.reason })
      recordItemLocalTerminalDrop(woGate.reason)
      continue
    }

    // For report-capture drafts: derive the company slug from the ref prefix if
    // the normal sender-pattern match didn't resolve a company. E.g. an email
    // whose sender is new / not yet seeded but whose subject carries "Our Ref:
    // MLB-25795" can still be attributed to mlb.
    const isReportCapture = woGate.kind === 'report'
    // Codex issue 1: tag report_type whenever the SUBJECT matched a report-capture
    // pattern — even for a kind='work_order' email that rode in with a PDF (e.g. a
    // BWCWA make-safe-AND-report, or a roof report that happened to attach a PDF).
    const tagReportType = isReportCapture || woGate.reportSubjectPattern === true
    if ((isReportCapture || tagReportType) && !matchedCompany?.slug) {
      const refPrefixMatch = subject.match(/\b(mlb|wb|bw|bwc|bwcwa|kba)-?\s*\d+/i)
      const derivedSlug = _slugFromRefPrefix(refPrefixMatch?.[1] ?? null)
      if (derivedSlug) {
        matchedCompany = { slug: derivedSlug, name: derivedSlug }
      }
    }

    // B2 (classification commitment): prefer the model's COMMITTED report_type
    // (body + PDF aware) over the subject/body keyword heuristic; the keyword
    // classifier is the fallback used only when the model abstains, and its
    // unknown_report stays the needs_review safety valve. This is what stops the
    // high-volume MLB "Our Ref:" cards from piling up unclassified.
    let draftReportType: string | null = null
    if (tagReportType) {
      draftReportType = _resolveCommittedReportType(
        extraction.report_type,
        subject,
        builderEmailTextForTrade || bodyPreview,
      )
    }
    const draftJobFamily = _classifyMakeSafeJobFamily(
      subject,
      [builderEmailTextForTrade, bodyPreview, extraction.description].filter(Boolean).join('\n'),
      draftReportType,
    )
    extraction.makesafe_job_family = draftJobFamily
    extraction.makesafe_job_family_label = _makeSafeJobFamilyLabel(draftJobFamily)

    // Item 3 (one email -> two cards): a make-safe WO that ALSO owes a roof/assessment
    // report is recorded as a combined obligation (secondary_obligation + a blocking
    // missing_field) so the single-card draft can never auto-file away the second card.
    flagCombinedIntakeObligation(
      { subject, body_preview: bodyPreview, description: extraction.description },
      extraction,
      attachments,
      missingFields,
      draftReportType,
    )

    // BUG 1 — POST-EXTRACTION CROSS-PATH DEDUP. Now that Haiku has given us the
    // external_ref and we've matched the requesting company, re-run the dedup with
    // those keys. This is what catches the OLD-path draft of the SAME work order
    // whose graph_message_id differs from this group-sync candidate (the BICTON
    // 67998 case): same (normalised ref + company), or a live job already on the ref.
    const extractedRef = extraction.external_ref || null
    const dedupExternalRef = extraction.builder_claim_ref || extractedRef
    const refDup = _isDuplicateIntake(
      {
        graph_message_id: msg.id,
        internet_message_id: msg.internetMessageId || null,
        external_ref: dedupExternalRef,
        builder_work_order_number: extraction.builder_work_order_number || null,
        builder_po_number: extraction.builder_po_number || null,
        requesting_company_slug: matchedCompany?.slug || null,
        requesting_company_name: matchedCompany?.name || null,
        makesafe_job_family: draftJobFamily,
        received_at: msg.receivedDateTime || null,
      },
      dedupIndex,
    )
    if (refDup) {
      // M-A2 / W2-B — TWO-EMAIL LATE WO-PDF LANDING. A builder can announce a WO with
      // no PDF (dirty draft) then send the PDF in a later PO email. That later email
      // dedups here (same ref+company / matching WO identity). If it carries a servable
      // WO PDF and there is exactly ONE existing dirty draft it belongs to, land the
      // PDF on that draft instead of minting a duplicate card (the *_needs_review branch
      // below) or stranding it (the silent-drop else branch). Skip when the email itself
      // carries MULTIPLE work orders (#300 one-WO-one-card stands) — those stay in the
      // existing manual-review path. Fail closed on ambiguity (two dirty drafts match).
      const candidateMultiWo = emailCarriesMultipleWorkOrders(
        { subject, body_preview: bodyPreview, description: extraction.description },
        extraction,
        attachments,
      )
      if (availableWoCount > 0 && !candidateMultiWo) {
        const landing = await landLateWorkOrderPdfOntoDraft(client, {
          candidate: {
            external_ref: dedupExternalRef,
            requesting_company_slug: matchedCompany?.slug || null,
            requesting_company_name: matchedCompany?.name || null,
            makesafe_job_family: draftJobFamily,
            builder_work_order_number: extraction.builder_work_order_number || null,
            builder_po_number: extraction.builder_po_number || null,
            graph_message_id: msg.id,
            confidence,
            attachments,
            extraction,
            missingFields,
          },
          autoFileEnabled,
          extractionDegraded: draftExtractionDegraded,
          subject,
        })
        if (landing.outcome === 'landed') {
          console.log('[ops-api] intake late-pdf landed on existing draft', landing.draft_id, 'ref', extractedRef, 'status', landing.status, landing.auto_filed?.job_id ? 'auto-filed job ' + landing.auto_filed.job_id : '')
          // Register the candidate so a second copy in THIS batch dedups (its WO/PO
          // identity now also lives on the updated draft; next scan skips on identity).
          _registerIntakeDraft(
            {
              graph_message_id: msg.id,
              internet_message_id: msg.internetMessageId || null,
              external_ref: dedupExternalRef,
              builder_work_order_number: extraction.builder_work_order_number || null,
              builder_po_number: extraction.builder_po_number || null,
              requesting_company_slug: matchedCompany?.slug || null,
              requesting_company_name: matchedCompany?.name || null,
              makesafe_job_family: draftJobFamily,
              from_email: fromEmail,
              subject,
              received_at: msg.receivedDateTime || null,
              body: msg.body?.content || msg.bodyPreview || null,
            },
            dedupIndex,
          )
          skippedItems.push({ id: msg.id, subject, external_ref: extractedRef, reason: 'late_pdf_landed' })
          resolveItemLocalTerminalWithDurableDraft()
          if (landing.auto_filed?.job_id) {
            autoApproved.push({ draft_id: landing.draft_id, job_id: landing.auto_filed.job_id, external_ref: extractedRef, reason: 'late_pdf_landed_auto_filed' })
          }
          continue
        }
        if (landing.outcome === 'ambiguous') {
          // Fail closed: more than one dirty draft could receive this PDF. Do NOT guess
          // and do NOT mint a duplicate — leave for human review (breadcrumb written).
          console.log('[ops-api] intake late-pdf ambiguous (multiple dirty drafts); skipped for human review:', extractedRef, landing.candidate_ids.join(','))
          skippedDuplicates++
          skippedItems.push({ id: msg.id, subject, external_ref: extractedRef, reason: 'late_pdf_ambiguous_multiple_targets' })
          recordItemLocalTerminalDrop('late_pdf_ambiguous_multiple_targets')
          continue
        }
        // outcome === 'none': no dirty draft to land on — fall through to the existing
        // dedup handling below (mint a needs_review draft or silent-drop as before).
      }
      // REOPEN-CANDIDATE path: an email matching an existing job's external_ref is
      // NOT silently dropped — it surfaces as a reopen_candidate draft so the human
      // sees "this matches job X — reopen it?". Other dup reasons (same draft already
      // exists, same message id) remain silent drops (the human already has the draft
      // or the email is a re-scan of the same post).
      if (
        refDup === 'unknown_family_needs_review' ||
        refDup === 'job_unknown_family_needs_review' ||
        refDup === 'work_order_identity_needs_review' ||
        refDup === 'job_work_order_identity_needs_review'
      ) {
        // G023: a legacy unknown-family row must not permanently suppress a
        // known-family same-ref variant. Keep this candidate visible as a manual
        // review draft and block auto-approval via missing_fields.
        if (!missingFields.includes(refDup)) missingFields.push(refDup)
        extraction.classification_reason = extraction.classification_reason ||
          'Existing same-ref row lacks the family or builder work-order identity needed to prove this is a duplicate; kept for human review.'
        extraction.dedup_review_reason = refDup
      } else if (refDup === 'job_external_ref' && extractedRef) {
        const normRef = _normaliseDedupRef(extractedRef)
        // Prefer the company-scoped key (ref|slug) to avoid cross-builder collisions.
        // Fall back to the ref-only key when the company slug is absent.
        const companyKey = (matchedCompany?.slug || '').toLowerCase()
        // Only use a company-scoped key for the reopen_candidate lookup. A ref-only
        // (ambiguous) fallback match means two different builders share the same
        // ref number — creating a reopen_candidate against whichever job won the
        // fallback slot would point at the wrong job. Fall through to skippedDuplicates
        // instead (safer: treat it like any other duplicate).
        const familyKey = _normaliseDedupJobFamily(draftJobFamily)
        const companyScopedEntry = normRef && companyKey
          ? refToJobId.get(`${normRef}|${companyKey}|${familyKey}`) ??
            refToJobId.get(`${normRef}|${companyKey}|`) ??
            null
          : null
        const matchedEntry = companyScopedEntry
        const matchedJobId = matchedEntry?.jobId ?? null
        const matchedJobStatus = matchedEntry?.status ?? null
        // Only surface a reopen_candidate when the matched job is actually eligible
        // for reopen (complete/invoiced/archived). Active jobs (scheduled, accepted,
        // processing, in_progress, etc.) stay as silent skips — the email is a re-scan
        // of an original WO or a duplicate for an in-flight job.
        // A null matchedEntry means no company-scoped match was found (ambiguous ref,
        // no company slug) — treated as a safe skip, never points at the wrong job.
        if (!REOPEN_ELIGIBLE_STATUSES.includes(matchedJobStatus ?? '')) {
          // ── M-G WORKSTREAM D-3 — the DROPPED-SECOND-WORK-ORDER fix ──
          // A property whose first deliverable's job is still ACTIVE frequently gets a
          // SECOND separate work order (e.g. a roof report alongside a make-safe). Today
          // that second WO is silently dropped here on the assumption it is "a re-scan of
          // the original WO or a duplicate for an in-flight job" — Marnin's named bug ("we
          // aren't making the second WO"). Before the silent skip, decide if this is a
          // genuinely DISTINCT deliverable rather than a re-scan:
          //   • it carries its OWN servable WO PDF (availableWoCount > 0) that did NOT land
          //     on an existing dirty draft above (the late-pdf block already returned if it
          //     did) — a real second work order, not a nudge/no-WO email; OR
          //   • the matched job(s) under this ref+company are a DIFFERENT family than this
          //     candidate (a family-specific miss but a family-agnostic hit on refToJobId).
          // If DISTINCT, surface it as its OWN needs_review draft (a card a human clears)
          // instead of a silent skip — never a blind live-insert, per the contract. A true
          // re-scan (byte-identical resend) is already caught upstream by the graph-id /
          // internet-id / content-fingerprint dedup, so reaching here is not a byte twin.
          // Nudge / no-WO emails (availableWoCount == 0, same family) keep the silent skip.
          const familySpecificEntry = (normRef && companyKey)
            ? refToJobId.get(`${normRef}|${companyKey}|${familyKey}`) ?? null
            : null
          // Same WO/PO identity as an existing job under this company = a re-send of the
          // SAME work order (not a distinct second deliverable). Keyed on the real WO/PO
          // number only (no external_ref fallback), so a NEW/unparsed WO number never matches.
          const candidateWoKey = _workOrderCompanyKey(
            extraction.builder_work_order_number,
            extraction.builder_po_number,
            matchedCompany?.slug || null,
            matchedCompany?.name || null,
          )
          const sameWoAsActiveJob = !!candidateWoKey && dedupIndex.jobWorkOrderCompany.has(candidateWoKey)
          const distinctSecondDeliverable = isDistinctSecondDeliverable({
            matchedJobId,
            availableWoCount,
            sameWoAsActiveJob,
            candidateFamily: familyKey,
            hasFamilySpecificSibling: familySpecificEntry != null,
            hasFamilyAgnosticSibling: matchedEntry != null,
          })
          if (distinctSecondDeliverable) {
            if (!missingFields.includes('second_deliverable_review')) {
              missingFields.push('second_deliverable_review')
            }
            extraction.dedup_review_reason = 'second_deliverable_review'
            extraction.classification_reason = extraction.classification_reason ||
              `A second work order arrived for property ref ${extractedRef} whose job ${matchedJobId} is still active; surfaced as its own deliverable for review rather than dropped (M-G D-3).`
            const secondDeliverableDraft = {
              org_id: DEFAULT_ORG_ID,
              mailbox: SES_MAILBOX,
              graph_message_id: msg.id,
              internet_message_id: msg.internetMessageId || null,
              conversation_id: msg.conversationId || null,
              received_at: msg.receivedDateTime || null,
              from_email: fromEmail,
              from_name: fromName,
              subject,
              body_preview: bodyPreview,
              requesting_company_slug: matchedCompany?.slug || null,
              requesting_company_name: matchedCompany?.name || null,
              external_ref: extractedRef,
              client_name: extraction.client_name || null,
              client_phone: extraction.client_phone || null,
              client_email: null,
              site_address: extraction.site_address || null,
              site_suburb: extraction.site_suburb || null,
              description: extraction.description || null,
              safety_requirements: extraction.safety_requirements || null,
              special_instructions: null,
              confidence,
              missing_fields: missingFields,
              extraction_json: extraction,
              attachments_json: attachments,
              report_type: draftReportType,
              // Human-review item (its own card), never auto-approved. Not a reopen (the
              // sibling job is active, not closed) so reopen_job_id stays null.
              status: 'needs_review',
            }
            const { error: sdErr } = await client.from('makesafe_intake_drafts')
              .insert(secondDeliverableDraft)
            if (sdErr) {
              // Fail LOUD, not silent: if the review draft can't be written, do NOT fall
              // through to the silent skip (that would re-drop the second WO). Surface it.
              console.error('[ops-api] intake second_deliverable_review insert failed — NOT dropping:', extractedRef, sdErr.message)
              skippedItems.push({ id: msg.id, subject, external_ref: extractedRef, reason: `second_deliverable_review_insert_failed:${sdErr.message}` })
              recordItemLocalTerminalDrop('second_deliverable_review_insert_failed')
            } else {
              console.log('[ops-api] intake second_deliverable_review created for ref', extractedRef, '(sibling active job', matchedJobId + ')')
              _registerIntakeDraft(
                {
                  graph_message_id: msg.id,
                  internet_message_id: msg.internetMessageId || null,
                  external_ref: dedupExternalRef,
                  builder_work_order_number: extraction.builder_work_order_number || null,
                  builder_po_number: extraction.builder_po_number || null,
                  requesting_company_slug: matchedCompany?.slug || null,
                  requesting_company_name: matchedCompany?.name || null,
                  makesafe_job_family: draftJobFamily,
                  from_email: fromEmail,
                  subject,
                  received_at: msg.receivedDateTime || null,
                  body: msg.body?.content || msg.bodyPreview || null,
                },
                dedupIndex,
              )
              secondDeliverableDrafts++
              newDrafts.push({ ...secondDeliverableDraft, _is_second_deliverable: true })
              resolveItemLocalTerminalWithDurableDraft()
            }
            continue
          }
          const skipReason = matchedEntry == null ? 'no company-scoped match (ambiguous ref)' : 'active job, not reopen-eligible'
          // Item 4 (nudge-email pattern): a "please complete the report" nudge for THIS
          // active job carries the report portal link but no new WO. Land it on the
          // existing job's external_links (idempotent) instead of dropping it — the
          // link is why crews couldn't find the portal (SWMS-26632). Only when the ref
          // resolved to a DEFINITE company-scoped job (matchedJobId, not an ambiguous
          // ref-only fallback), so a shared ref number can never patch the wrong job.
          if (matchedJobId) {
            const nudgeLinks = _normalizeReportExternalLinks(extraction)
            if (nudgeLinks.length) {
              try {
                const { added, upgraded } = await _patchExistingJobExternalLinks(client, matchedJobId, nudgeLinks)
                if (added.length || upgraded.length) {
                  if (added.length) nudgeLinksAttached++
                  console.log('[ops-api] intake nudge link attached to job', matchedJobId, 'ref', extractedRef, '+' + added.length + ' new, ' + upgraded.length + ' retyped')
                  try {
                    await logBusinessEvent(client, {
                      event_type: 'makesafe.intake_nudge_link_attached',
                      source: 'app/makesafe-intake',
                      entity_type: 'job',
                      entity_id: matchedJobId,
                      job_id: matchedJobId,
                      body_preview: `Attached ${added.length} + retyped ${upgraded.length} builder portal link(s) from a nudge email to existing job (ref ${extractedRef}); no draft minted.`,
                      payload: { job_id: matchedJobId, external_ref: extractedRef, added_links: added, upgraded_links: upgraded, graph_message_id: msg.id },
                      metadata: { mission: 'intake/nudge-email-links', reason: 'nudge_link_attached' },
                    })
                  } catch { /* non-blocking breadcrumb */ }
                }
              } catch (e) {
                console.log('[ops-api] intake nudge link patch failed (non-blocking):', (e as Error).message)
              }
            }
          }
          console.log('[ops-api] intake skip (' + skipReason + '):', matchedJobStatus, '|', extractedRef, '|', matchedJobId)
          skippedDuplicates++
          skippedItems.push({ id: msg.id, subject, external_ref: extractedRef, reason: `job_external_ref:${skipReason}` })
          recordItemLocalTerminalDrop(`job_external_ref:${skipReason}`)
          continue
        }
        const reopenDraft = {
          org_id: DEFAULT_ORG_ID,
          mailbox: SES_MAILBOX,
          graph_message_id: msg.id,
          internet_message_id: msg.internetMessageId || null,
          conversation_id: msg.conversationId || null,
          received_at: msg.receivedDateTime || null,
          from_email: fromEmail,
          from_name: fromName,
          subject,
          body_preview: bodyPreview,
          requesting_company_slug: matchedCompany?.slug || null,
          requesting_company_name: matchedCompany?.name || null,
          external_ref: extractedRef,
          client_name: extraction.client_name || null,
          client_phone: extraction.client_phone || null,
          client_email: null,
          site_address: extraction.site_address || null,
          site_suburb: extraction.site_suburb || null,
          description: extraction.description || null,
          safety_requirements: null,
          special_instructions: null,
          confidence,
          missing_fields: missingFields,
          extraction_json: extraction,
          attachments_json: attachments,
          report_type: null,
          status: 'reopen_candidate',
          reopen_job_id: matchedJobId,
        }
        const { error: rcErr } = await client.from('makesafe_intake_drafts').insert(reopenDraft)
        if (rcErr) {
          console.log('[ops-api] intake reopen_candidate insert failed:', rcErr.message)
          recordItemLocalTerminalDrop('reopen_candidate_insert_failed')
        } else {
          console.log('[ops-api] intake reopen_candidate created for ref', extractedRef, 'job', matchedJobId)
          // Register in the in-memory index so a second copy of the same email in
          // this batch is also caught (same idempotency contract as normal drafts).
          _registerIntakeDraft(
            {
              graph_message_id: msg.id,
              internet_message_id: msg.internetMessageId || null,
              external_ref: dedupExternalRef,
              builder_work_order_number: extraction.builder_work_order_number || null,
              builder_po_number: extraction.builder_po_number || null,
              requesting_company_slug: matchedCompany?.slug || null,
              requesting_company_name: matchedCompany?.name || null,
              makesafe_job_family: draftJobFamily,
              // M1.5 D0: register the dual-capture fingerprint so the twin capture row
              // of the SAME email later in this batch is caught.
              from_email: fromEmail,
              subject,
              received_at: msg.receivedDateTime || null,
              body: msg.body?.content || msg.bodyPreview || null,
            },
            dedupIndex,
          )
          newDrafts.push({ ...reopenDraft, _is_reopen_candidate: true })
          resolveItemLocalTerminalWithDurableDraft()
        }
        continue
      } else {
        console.log('[ops-api] intake skip (duplicate across paths):', refDup, '|', extractedRef, '|', subject)
        skippedDuplicates++
        skippedItems.push({ id: msg.id, subject, external_ref: extractedRef, reason: refDup })
        recordItemLocalTerminalDrop(refDup)
        continue
      }
    }

    // Report-capture drafts always go to needs_review (they are human-review items,
    // never auto-approved). Normal WO drafts use the existing completeness logic —
    // now the SHARED computeIntakeDraftStatus so the scanner and the admin reextract
    // action can never drift on "draft vs needs_review".
    const draftStatus: string = _computeIntakeDraftStatus({
      extractionDegraded: draftExtractionDegraded,
      isReportCapture,
      hasCompany: !!(matchedCompany?.slug || matchedCompany?.name),
      externalRef: extractedRef,
      clientName: extraction.client_name || null,
      siteAddress: extraction.site_address || null,
      availableWoCount,
    })

    // Create draft
    const draft = {
      org_id: DEFAULT_ORG_ID,
      mailbox: SES_MAILBOX,
      graph_message_id: msg.id,
      internet_message_id: msg.internetMessageId || null,
      conversation_id: msg.conversationId || null,
      received_at: msg.receivedDateTime || null,
      from_email: fromEmail,
      from_name: fromName,
      subject,
      body_preview: bodyPreview,
      requesting_company_slug: matchedCompany?.slug || null,
      requesting_company_name: matchedCompany?.name || null,
      external_ref: extractedRef,
      client_name: extraction.client_name || null,
      client_phone: extraction.client_phone || null,
      client_email: null,
      site_address: extraction.site_address || null,
      site_suburb: extraction.site_suburb || null,
      description: extraction.description || null,
      safety_requirements: extraction.safety_requirements || null,
      special_instructions: null,
      confidence,
      missing_fields: missingFields,
      extraction_json: extraction,
      attachments_json: attachments,
      report_type: draftReportType,
      status: draftStatus,
    }

    const insResult = await client.from('makesafe_intake_drafts')
      .insert(draft).select().single()
    let inserted = insResult.data
    const insErr = insResult.error
    if (insErr) {
      // A2/A3 — no more silent drop. On the (org_id, graph_message_id) unique-key
      // collision, re-populate a non-live shell in place (heal) so a released email
      // recovers into its own slot; a LIVE collision or any other error becomes a loud
      // breadcrumb + alarm signal instead of a swallowed console.log.
      const heal = await _selfHealIntakeInsert(client, {
        draft,
        insErr,
        orgId: DEFAULT_ORG_ID,
        graphMessageId: msg.id,
        externalRef: extractedRef,
        subject,
      })
      if (heal.outcome === 'healed' && heal.row) {
        inserted = heal.row
        insertConflictsHealed++
      } else if (heal.outcome === 'live_collision') {
        insertConflictsLive++
        continue
      } else {
        droppedAfterExtraction++
        lastDroppedRef = extractedRef || msg.id
        continue
      }
    }

    // The durable visible record now exists: this draft carries the source evidence and
    // the typed request_invalid reason. Only now may an item-local permanent failure be
    // marked scanned, so it stops hitting the provider every two minutes while staying
    // manually requeueable through reextract_intake_draft. Nothing is discarded.
    if (
      emailItemLocalTerminal && msg._post_id && _scanMarkEligible({
        templateParsed: emailTemplateParsed,
        modelValidResult: emailModelValidResult,
        authFailed: emailAuthFailed,
        transientFailed: emailTransientFailed,
        terminalQuarantined: emailTerminalFailed,
        itemLocalTerminalRecorded: true,
        keyDegradedOrAbsent: keyDegraded || !ANTHROPIC_API_KEY,
      }) && !scannedEmailIds.includes(msg._post_id)
    ) {
      scannedEmailIds.push(msg._post_id)
    }
    // The draft IS the durable record, so no separate quarantine event is needed.
    if (emailItemLocalTerminal) pendingItemLocalTerminals.delete(msg.id)

    // BUG 1 — register the new draft in the in-memory index so a SECOND copy of the
    // same email later in THIS batch (same ref+company) is also skipped.
    _registerIntakeDraft(
      {
        graph_message_id: msg.id,
        internet_message_id: msg.internetMessageId || null,
        external_ref: dedupExternalRef,
        builder_work_order_number: extraction.builder_work_order_number || null,
        builder_po_number: extraction.builder_po_number || null,
        requesting_company_slug: matchedCompany?.slug || null,
        requesting_company_name: matchedCompany?.name || null,
        makesafe_job_family: draftJobFamily,
        // M1.5 D0: register the dual-capture fingerprint so the twin capture row of the
        // SAME email later in this batch is caught before a second model call.
        from_email: fromEmail,
        subject,
        received_at: msg.receivedDateTime || null,
        body: msg.body?.content || msg.bodyPreview || null,
      },
      dedupIndex,
    )

    // A5 — ARRIVAL TEXT. A genuine NEW work order just landed as a usable card (fresh
    // insert or a healed shell). Text the owner crew ONCE per WO (fire-once via the
    // makesafe_notify_log ledger; twins / re-sends / re-extractions collide and skip).
    // reopen_candidate drafts never reach here (they `continue` earlier); a dead-key
    // degraded draft is skipped (no address to text about, extraction failed).
    const arrivalGate = _shouldSendArrival({
      notifyEnabled: notifySettings.notify_enabled,
      isReopen: false,
      extractionDegraded: draftExtractionDegraded,
      hasDedupKey: !!(extractedRef || msg.id),
    })
    if (arrivalGate.ok) {
      try {
        const arrival = await _sendMakesafeArrivalTexts(
          client,
          notifySettings,
          { sendSms: (phone, message, fromNumber) => sendSmsViaGhl(phone, message, fromNumber), logBusinessEvent },
          {
            orgId: DEFAULT_ORG_ID,
            externalRef: extractedRef,
            graphMessageId: msg.id,
            family: draftJobFamily,
            reportType: draftReportType,
            siteAddress: extraction.site_address || null,
            siteSuburb: extraction.site_suburb || null,
            companyName: matchedCompany?.name || matchedCompany?.slug || null,
          },
        )
        if (arrival.sent) arrivalTextsSent++
      } catch (e) {
        console.warn('[ops-api] arrival text send failed (non-blocking):', (e as Error).message)
      }
    }

    // D-d auto-file gate. THREE independent brakes decide `enabled`:
    //   1. autoApproveCleanIntakeEnabled() — default ON; exact env "false" parks drafts,
    //   2. autoFileEnabled  — the DB kill switch makesafe_cron_settings.auto_file_enabled
    //      (one UPDATE falls back to drafts-only, no redeploy),
    //   3. !draftExtractionDegraded — a dead-key run never auto-files (belt-and-braces
    //      with the forced-low confidence above).
    // The gate itself still requires confidence:high + the SAME required fields as the
    // human approveIntakeDraft (company + ref + client + address + servable WO PDF), and
    // now also rejects cancellations and combined make-safe+report obligations.
    if (draftExtractionDegraded) autoFileSuppressedDrafts++
    else autoFileEligibleDrafts++
    const autoApprovalDecision = shouldAutoApproveCleanIntake({
      enabled: autoFileEnabled && !draftExtractionDegraded && autoApproveCleanIntakeEnabled(),
      isReportCapture,
      tagReportType,
      reportType: draftReportType,
      confidence,
      missingFields,
      matchedCompany,
      externalRef: extractedRef,
      clientName: extraction.client_name || null,
      siteAddress: extraction.site_address || null,
      attachments,
      // Item 2/3 belt-and-braces: a cancellation never reaches here (dropped at the
      // gate). A combined make-safe+report no longer auto-files a single card — an
      // UNAMBIGUOUS one auto-splits into two cards (item 3b); an ambiguous one blocks.
      combinedObligation: !!(extraction?.secondary_obligation),
      combinedSplittable: combinedSplitObligation(extraction) !== null,
    })

    if (autoApprovalDecision.ok) {
      try {
        // Provenance (D-d): approved_by:'auto-intake' distinguishes an auto-filed job
        // from a human tick. This is the gated INTERNAL path — approveIntakeDraft is
        // called at the function level, NOT through the route (the Wave-0 rule that the
        // routine key can't call approve_intake_draft stays intact).
        const approved = await approveIntakeDraft(client, {
          draft_id: inserted.id,
          approved_by: 'auto-intake',
          review_notes: 'Auto-filed clean make-safe intake (Auto-Intake v2): high-confidence extraction, requesting company/ref/client/address present, and servable work-order PDF captured. Draft-only intake promotion; no invoice/send/authorise/close action.',
        })
        // D-d audit row: an explicit, queryable job_events trail for every auto-filed job
        // (createMakesafeJob writes makesafe_created; this adds the auto-file provenance).
        if (approved?.job?.id) {
          try {
            await client.from('job_events').insert({
              job_id: approved.job.id,
              event_type: 'makesafe_auto_filed',
              detail_json: {
                draft_id: inserted.id,
                external_ref: extractedRef || null,
                requesting_company: matchedCompany?.slug || matchedCompany?.name || null,
                confidence,
                gate_reason: autoApprovalDecision.reason,
                // Evidence that made this draft clean (auto-approval audit trail).
                clean_evidence: {
                  confidence,
                  report_type: draftReportType,
                  client_name_present: !!(extraction.client_name),
                  site_address_present: !!(extraction.site_address),
                  work_order_pdf: hasWorkOrderAttachmentEvidence(attachments),
                  combined_obligation: !!(extraction?.secondary_obligation),
                },
                source: 'auto-intake',
              },
            })
          } catch (_) { /* non-blocking audit write */ }
        }
        const autoRow = {
          ...inserted,
          status: 'approved',
          approved_job_id: approved?.job?.id || null,
          auto_approved: true,
          auto_approval_reason: autoApprovalDecision.reason,
        }
        newDrafts.push(autoRow)
        autoApproved.push({
          draft_id: inserted.id,
          job_id: approved?.job?.id || null,
          external_ref: extractedRef,
          reason: autoApprovalDecision.reason,
        })
      } catch (e) {
        const msgText = e instanceof Error ? e.message : String(e)
        console.log('[ops-api] intake auto-approve failed; leaving draft for review:', msgText)
        newDrafts.push({
          ...inserted,
          auto_approved: false,
          auto_approval_reason: autoApprovalDecision.reason,
          auto_approve_error: msgText,
        })
        autoApproveFailed.push({
          draft_id: inserted.id,
          external_ref: extractedRef,
          reason: autoApprovalDecision.reason,
          error: msgText,
        })
      }
    } else {
      newDrafts.push({
        ...inserted,
        auto_approved: false,
        auto_approval_reason: autoApprovalDecision.reason,
      })
    }
  }

  // Every item-local permanent failure still pending here took a gate-drop or
  // insert-failure exit, so no draft carries its evidence. Persist the durable visible
  // record FIRST — idempotently, so a failed scanned-marker write cannot append a
  // duplicate event on the next cycle — and only a confirmed record licenses marking the
  // source scanned. A failed write leaves the source unscanned and is counted, so
  // persistence drift degrades health loudly instead of becoming a silent retry storm.
  const quarantineFlush = await _flushItemLocalQuarantines(client, pendingItemLocalTerminals.values())
  itemLocalQuarantinePersistFailures = quarantineFlush.failed
  for (const postId of quarantineFlush.markable) {
    if (!scannedEmailIds.includes(postId)) scannedEmailIds.push(postId)
  }

  // Cost-leak fix: STAMP makesafe_scanned_at on every email that got a valid extraction
  // this run (draft or not), so it is never re-extracted. Batched + chunked + idempotent
  // + error-checked + pre-migration-safe — see markEmailsScanned.
  const markResult = await _markEmailsScanned(client, scannedEmailIds, {
    columnAvailable: scannedColumnAvailable,
  })
  const scannedMarked = markResult.marked

  // B5 SLA: latency of the drafts created THIS scan (email received_at -> row
  // created_at). Uses the inserted rows accumulated in newDrafts (each carries both
  // timestamps). Pure + deterministic; excludes rows missing a timestamp.
  const scanSla = _computeLatencySla(newDrafts as any[])

  // Health truth: a provider-wide terminal class degrades immediately. Otherwise a
  // cycle is degraded when every provider attempt failed, including retryable 429,
  // network and 5xx failures. Partial success remains healthy.
  const cycleHealth = _extractionCycleHealth({
    attempts: extractionAttempts,
    successes: extractionSuccesses,
    terminalFailures: terminalExtractionFailures,
    retryableFailures: retryableExtractionFailures,
    reasons: extractionFailureReasons,
    providerLaneTerminalReason: providerTerminalClassification?.reason || null,
  })
  // Quarantine persistence drift (RLS change, schema drift) means item-local failures
  // cannot be bounded at all, so it degrades health with its own typed reason rather
  // than retrying silently forever.
  const quarantinePersistenceDegraded = itemLocalQuarantinePersistFailures > 0
  const extractionDegraded = cycleHealth.status === 'degraded' || quarantinePersistenceDegraded
  // A provider reason must never MASK broken quarantine persistence: that is exactly the
  // case where those sources retry the provider unbounded, so both surface together in a
  // stable typed composite that still starts with the provider reason.
  const degradedReason = quarantinePersistenceDegraded
    ? (cycleHealth.reason ? `${cycleHealth.reason}+${INTAKE_QUARANTINE_PERSISTENCE_REASON}` : INTAKE_QUARANTINE_PERSISTENCE_REASON)
    : cycleHealth.reason
  // Persistence health has its own recovery proof: a confirmed durable quarantine write.
  // Provider degradation still clears only on a successful extraction.
  const quarantinePersistenceProven = !quarantinePersistenceDegraded &&
    (quarantineFlush.recorded + quarantineFlush.alreadyRecorded) > 0
  await writeIntakeHealth(client, {
    extractionStatus: extractionDegraded ? 'degraded' : cycleHealth.status,
    degradedReason,
    anyExtractionSucceeded,
    quarantinePersistenceProven,
    draftsCreated: newDrafts.length,
    autoFiled: autoApproved.length,
    // M1.5 cost ledger: this scan's model-call/skip split + token totals.
    cost: scanCostTotals,
    // B5 SLA: this scan's arrival->card latency snapshot + deferred-candidate count.
    sla: scanSla,
    cappedCandidates,
    // A3: dropped-WO breadcrumb (self-heal outcomes this scan) -> feeds the alarm.
    breadcrumb: {
      insertConflictsHealed,
      insertConflictsLive,
      droppedAfterExtraction,
      lastDroppedRef,
    },
    // Empty-feed anomaly: freshest inbound email seen this scan.
    lastInboundEmailAt: mostRecentInboundIso,
  })

  return {
    ok: true,
    // Wave 1: emails READ from the group-sync projection (the candidate window),
    // not a live Graph message count.
    scanned: (emailRows || []).length,
    // D-a fail-loud state: true when the classifier key is dead/unset this run. Every
    // draft made while degraded carries the extraction_down_key_dead marker and is a
    // needs_review docket; nothing is silently empty and nothing is auto-filed.
    extraction_degraded: extractionDegraded,
    extraction_degraded_reason: degradedReason,
    extraction_cycle: {
      attempts: extractionAttempts,
      successes: extractionSuccesses,
      terminal_failures: terminalExtractionFailures,
      retryable_failures: retryableExtractionFailures,
      quarantined: quarantinedItems,
      // Provider-lane quarantine leaves the marker unset and recovers on the next scan.
      // Item-local permanent failures are marked once their draft is durable and recover
      // through an explicit requeue.
      item_local_quarantined: itemLocalQuarantinedItems,
      // Durable-record writes that failed: those sources stay unscanned and retry, and
      // a non-zero count degrades intake health rather than failing quiet.
      item_local_quarantine_record_failures: itemLocalQuarantinePersistFailures,
      quarantine_recovery_action: 'automatic_rescan',
      item_local_recovery_action: 'reextract_intake_draft',
      quarantined_source_ids: quarantinedEmailIds.slice(0, 100),
    },
    // D-d: whether auto-file was permitted this run (DB kill switch AND not degraded),
    // unchanged. Suppression is per draft, so the actual split is reported alongside it.
    auto_file_enabled: autoFileEnabled && !extractionDegraded,
    auto_file_eligible_drafts: autoFileEligibleDrafts,
    auto_file_suppressed_drafts: autoFileSuppressedDrafts,
    makesafe_candidates: processedCandidates,
    matched_candidates: matchedMessages.length,
    processed_candidates: processedCandidates,
    capped_candidates: cappedCandidates,
    // BUG 1: count of candidates skipped because a draft/job already exists for them
    // (across BOTH the old user-mailbox path and the new group-sync path).
    already_processed: skippedDuplicates,
    skipped_ai_only: skippedAiOnly,
    skipped_not_work_order_gate: skippedNotWorkOrderGate,
    // Item 2: cancellation emails recognised and dropped (no draft minted); each is
    // breadcrumbed as a makesafe.intake_cancellation_detected business_event.
    cancellations_detected: cancellationsDetected,
    // Item 4: nudge emails whose portal link was landed on the existing job it
    // references (idempotent add-only), instead of dropping the link / minting.
    nudge_links_attached: nudgeLinksAttached,
    // M-G D-3: distinct second work orders for a property with an active job that were
    // surfaced as needs_review drafts (their own card) instead of being silently dropped.
    second_deliverable_drafts: secondDeliverableDrafts,
    // Cost-leak fix observability: emails skipped because already extracted (marker
    // set), and emails freshly stamped this run. In steady state on a quiet inbox both
    // fall to ~0 new work; a re-extraction leak would show as scanned_marked climbing
    // with new_count flat, which it no longer does.
    skipped_already_scanned: skippedAlreadyScanned,
    scanned_marked: scannedMarked,
    scanned_marker_active: scannedColumnAvailable,
    skipped_items: skippedItems.slice(0, 100),
    scan_order: 'oldest_newest_interleave',
    new_drafts: newDrafts,
    new_count: newDrafts.length,
    auto_approved: autoApproved,
    auto_approved_count: autoApproved.length,
    auto_approve_failed: autoApproveFailed,
    auto_approve_failed_count: autoApproveFailed.length,
    // A2/A3 dropped-WO breadcrumb this scan (>0 live/dropped raises the health alarm).
    insert_conflicts_healed: insertConflictsHealed,
    insert_conflicts_live: insertConflictsLive,
    dropped_after_extraction: droppedAfterExtraction,
    last_dropped_ref: lastDroppedRef,
    // A5 arrival texts fired this scan (fire-once per WO via the notify ledger).
    arrival_texts_sent: arrivalTextsSent,
    // M1.5 cost summary for this scan: how many drafts used a template skip vs a model
    // call, the token totals, and the estimated USD at the Haiku 4.5 rate constants.
    cost: {
      model_calls: scanCostTotals.model_calls,
      model_skips: scanCostTotals.model_skips,
      tokens: scanCostTotals.usage,
      estimated_cost_usd: _usdCost(scanCostTotals.usage),
    },
    // Observability: confirms the redirected source is live (not the old Graph
    // USER-mailbox scan).
    source: 'group_sync_projection',
  }
}
export const _retiredPaidAiIntakeImplementationForManualTest =
  retiredPaidAiIntakeImplementation

async function recordMakesafeAlarmAuthentication(client: any, nowIso = new Date().toISOString()) {
  const { error } = await client.from('makesafe_intake_health').upsert({
    id: true,
    alarm_auth_verified_at: nowIso,
    alarm_auth_action: 'makesafe_email_canary',
    updated_at: nowIso,
  }, { onConflict: 'id' })
  if (error) {
    console.error('[ops-api] authenticated alarm readiness proof could not be persisted:', error.message || error)
    return false
  }
  return true
}

// ── D-a: intake_health — the one-call health check ───────────────────────────
// Read-only. The single call the terminal skill and the morning report make first:
// is the classifier key alive? is the cron on? is auto-file on? how many drafts /
// auto-files in 24h? and the D-e "did we miss anything" unaccounted count (0 = live
// and true). This is what makes a dead key impossible to miss.
async function intakeHealth(client: any) {
  const nowIso = new Date().toISOString()
  const since24h = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()

  const { data: health } = await client.from('makesafe_intake_health')
    .select('*').eq('id', true).maybeSingle()
  const { data: settings, error: settingsError } = await client.from('makesafe_cron_settings')
    .select('cron_enabled, auto_file_enabled, enabled_at, enabled_by, updated_at, intake_mode, deterministic_selection_mode, deterministic_max_cases_per_run, deterministic_source_allowlist, deterministic_instruction_allowlist')
    .eq('id', true).maybeSingle()
  const { data: sync } = await client.from('sync_state')
    .select('last_successful_sync_at, last_attempt_at, mode, pending_attachments, last_error')
    .eq('mailbox', _SES_MAILBOX).maybeSingle()
  const { data: alarmSettings, error: alarmSettingsError } = await client.from('makesafe_notify_settings')
    .select('alarm_enabled, alarm_phones').eq('id', true).maybeSingle()
  // Authentication is proved only by a fresh timestamp written after the protected
  // canary route passed auth. Cron existence and configured recipients cannot make
  // this ready by themselves.
  const alarmReadiness = _alarmReadinessFacts({
    alarmEnabled: alarmSettingsError ? null : (alarmSettings?.alarm_enabled ?? null),
    recipientCount: alarmSettingsError
      ? null
      : (Array.isArray(alarmSettings?.alarm_phones) ? alarmSettings.alarm_phones.filter(Boolean).length : 0),
    latestAuthenticatedAt: health?.alarm_auth_action === 'makesafe_email_canary'
      ? health?.alarm_auth_verified_at || null
      : null,
    nowIso,
    settingsReadError: alarmSettingsError?.message || null,
  })

  const { count: drafts24h } = await client.from('makesafe_intake_drafts')
    .select('id', { count: 'exact', head: true })
    .gte('created_at', since24h)
  // Auto-filed = approved by the internal auto-intake path (new label 'auto-intake';
  // the older 'auto_intake_clean_gate' label is still counted for continuity).
  const { count: autoFiled24h } = await client.from('makesafe_intake_drafts')
    .select('id', { count: 'exact', head: true })
    .in('approved_by', ['auto-intake', 'auto_intake_clean_gate', 'ses-reporting-skill'])
    .gte('approved_at', since24h)

  // M1.5 cost dashboard: read the per-draft cost records for the last 24h and roll them
  // up (model calls, template skips, tokens, and estimated USD at the Haiku 4.5 rates).
  let cost24h: any = null
  try {
    const { data: costDrafts } = await client.from('makesafe_intake_drafts')
      .select('extraction_json')
      .gte('created_at', since24h)
      .limit(3000)
    const costRecords = (costDrafts || []).map((d: any) => {
      const ex = parseJsonObject(d.extraction_json)
      return ex && ex.cost && typeof ex.cost === 'object' ? ex.cost : null
    })
    cost24h = _rollup24h(costRecords)
  } catch (e) {
    cost24h = { error: (e as Error).message }
  }

  // B5 SLA: 24h rolling email-received -> card-created latency, computed on read from
  // the per-draft timestamps (same "24h rollups on read" pattern as the cost ledger).
  // This is the daily-provable statement: "N cards in 24h, p95 arrival->card M sec".
  let sla24h: any = null
  try {
    const { data: slaDrafts } = await client.from('makesafe_intake_drafts')
      .select('received_at, created_at')
      .gte('created_at', since24h)
      .limit(5000)
    sla24h = _computeLatencySla(slaDrafts || [])
  } catch (e) {
    sla24h = { error: (e as Error).message }
  }

  let unaccounted: any = null
  try {
    const inv = await _makesafeIntakeReconcileInvariant(client, { windowDays: 7, limitUnaccounted: 25 })
    unaccounted = {
      count: inv.counts.unaccounted,
      live_and_true: inv.live_and_true,
      window_days: inv.window_days,
      sample: inv.unaccounted.slice(0, 10),
    }
  } catch (e) {
    unaccounted = { error: (e as Error).message }
  }

  const status = String(health?.extraction_status || 'unknown')
  // Application authority is deterministic even while a pre-migration compatibility
  // row still says legacy. A settings read failure remains unknown because bounded
  // selection controls cannot be proved.
  const intakeMode = settingsError ? 'unknown' : 'deterministic'
  return {
    ok: true,
    generated_at: nowIso,
    intake_mode: intakeMode,
    // No false-ready state: extraction, source accounting, effective authority and
    // fresh authenticated alarm delivery readiness must all be proved.
    healthy: status === 'ok' && (unaccounted?.count === 0) &&
      intakeMode !== 'unknown' && alarmReadiness.ready,
    extraction: {
      status,
      degraded_reason: health?.degraded_reason || null,
      degraded_since: health?.degraded_since || null,
      last_scan_at: health?.last_scan_at || null,
      last_successful_extraction_at: health?.last_successful_extraction_at || null,
      last_scan_drafts_created: health?.last_scan_drafts_created ?? null,
      last_scan_auto_filed: health?.last_scan_auto_filed ?? null,
    },
    cron: {
      cron_enabled: settings?.cron_enabled ?? null,
      auto_file_enabled: settings?.auto_file_enabled ?? null,
      enabled_at: settings?.enabled_at || null,
      enabled_by: settings?.enabled_by || null,
      settings_read_error: settingsError?.message || null,
    },
    deterministic_rollout: {
      selection_mode: settings?.deterministic_selection_mode ?? null,
      max_cases_per_run: settings?.deterministic_max_cases_per_run ?? null,
      source_allowlist_count: Array.isArray(settings?.deterministic_source_allowlist)
        ? settings.deterministic_source_allowlist.length
        : null,
      instruction_allowlist_count: Array.isArray(settings?.deterministic_instruction_allowlist)
        ? settings.deterministic_instruction_allowlist.length
        : null,
      exact_allowlist_configured: Array.isArray(settings?.deterministic_source_allowlist) &&
          settings.deterministic_source_allowlist.length > 0 ||
        Array.isArray(settings?.deterministic_instruction_allowlist) &&
          settings.deterministic_instruction_allowlist.length > 0,
    },
    alarm_readiness: alarmReadiness,
    last_poll: {
      mailbox: _SES_MAILBOX,
      last_successful_sync_at: sync?.last_successful_sync_at || null,
      last_attempt_at: sync?.last_attempt_at || null,
      mode: sync?.mode || null,
      pending_attachments: sync?.pending_attachments ?? null,
      last_error: sync?.last_error || null,
    },
    last_24h: {
      drafts_created: drafts24h ?? 0,
      auto_filed: autoFiled24h ?? 0,
    },
    // B5 SLA: the email->card latency proof. `last_scan` is the snapshot written every
    // 2-min run; `last_24h` is the daily-provable rolling percentile over per-draft
    // timestamps. `capped_candidates` on the last scan flags a draining backlog.
    sla: {
      last_scan: {
        latency_p50_sec: health?.last_scan_latency_p50_sec ?? null,
        latency_p95_sec: health?.last_scan_latency_p95_sec ?? null,
        latency_max_sec: health?.last_scan_latency_max_sec ?? null,
        latency_samples: health?.last_scan_latency_samples ?? null,
        capped_candidates: health?.last_scan_capped_candidates ?? null,
      },
      last_24h: sla24h,
      target_sec: 120,
    },
    // M1.5 cost ledger. `last_24h` is the Captain's headline (model calls, the
    // template-skip share, tokens, and estimated USD at the Haiku 4.5 rate constants);
    // `last_scan` + `lifetime` come off the health row's running counters.
    cost: {
      rates: {
        model: _HAIKU_4_5_RATES.model,
        as_of: _HAIKU_4_5_RATES.as_of,
        input_per_mtok: _HAIKU_4_5_RATES.input_per_mtok,
        output_per_mtok: _HAIKU_4_5_RATES.output_per_mtok,
        cache_read_per_mtok: _HAIKU_4_5_RATES.cache_read_per_mtok,
        cache_write_per_mtok: _HAIKU_4_5_RATES.cache_write_per_mtok,
      },
      last_24h: cost24h,
      // Convenience mirrors of the two headline figures the mission calls out.
      model_calls_24h: cost24h?.model_calls_24h ?? null,
      model_skip_rate: cost24h?.model_skip_rate ?? null,
      estimated_cost_usd_24h: cost24h?.estimated_cost_usd_24h ?? null,
      last_scan: {
        model_calls: health?.last_scan_model_calls ?? null,
        model_skips: health?.last_scan_model_skips ?? null,
        input_tokens: health?.last_scan_input_tokens ?? null,
        output_tokens: health?.last_scan_output_tokens ?? null,
        cache_read_tokens: health?.last_scan_cache_read_tokens ?? null,
        cache_write_tokens: health?.last_scan_cache_write_tokens ?? null,
        estimated_cost_usd: health?.last_scan_estimated_cost_usd ?? null,
      },
      lifetime: {
        model_calls: health?.total_model_calls ?? null,
        model_skips: health?.total_model_skips ?? null,
        input_tokens: health?.total_input_tokens ?? null,
        output_tokens: health?.total_output_tokens ?? null,
        cache_read_tokens: health?.total_cache_read_tokens ?? null,
        cache_write_tokens: health?.total_cache_write_tokens ?? null,
      },
    },
    unaccounted,
  }
}

// ── Assignment-mutation authz gate (Manager View) ──────────────────────────
// Shared by the ops-dashboard create/update/delete_assignment actions. Resolves
// the affected job's vertical, then applies _resolveAllocationAuthz. api_key
// (dashboard / service) and dispatchers short-circuit with no DB read; only a
// JWT vertical manager needs the job looked up. Their managed_verticals come
// from the authenticated context the dispatch already read from the server-owned
// users row (never from the request), so no second round trip per mutation.
// Closes the pre-existing hole where ANY logged-in JWT user could mutate
// assignments.
export async function assertAssignmentMutationAuthz(
  client: any,
  authMode: 'api_key' | 'jwt' | 'routine',
  authUser: { id: string; email?: string; role: string; managedVerticals?: unknown } | null,
  ref: { jobId?: string | null; assignmentId?: string | null },
): Promise<void> {
  // Fast paths: no DB read required.
  if (authMode === 'api_key') return
  if (authMode === 'routine') {
    throw new ApiError('forbidden: the make-safe automation routine may not mutate assignments', 403)
  }
  const role = String(authUser?.role || '').toLowerCase()
  if (role === 'admin' || role === 'owner' || role === 'ops_manager') return

  // JWT vertical-manager path: resolve the job's vertical + the caller's list.
  let jobId = ref.jobId || null
  if (!jobId && ref.assignmentId) {
    const { data: a } = await client.from('job_assignments').select('job_id').eq('id', ref.assignmentId).maybeSingle()
    jobId = a?.job_id || null
  }
  let jobVertical: string | null = null
  if (jobId) {
    const { data: job } = await client.from('jobs').select('id, type, job_number').eq('id', jobId).maybeSingle()
    if (job) jobVertical = _jobVertical(job)
  }
  const decision = _resolveAllocationAuthz({
    authMode: 'jwt',
    callerRole: role,
    managedVerticals: authUser?.managedVerticals,
    jobVertical,
  })
  if (!decision.allowed) {
    throw new ApiError('Not authorized: you can only allocate jobs in a vertical you manage', 403)
  }
}

// ── Trade-side manager allocation (Manager View) ───────────────────────────
// A vertical manager (or dispatcher) allocates a job to — or moves it between —
// installers from the trade app. JWT-authed by the caller (case above); gated
// here by _resolveAllocationAuthz on the job's vertical. Wraps the SAME
// createAssignment / updateAssignment primitives the ops dashboard uses, so the
// installer allocation SMS (DA-M3-8), job_events,
// business_events, GHL push, and visible_to_trades all fire identically.
// Idempotent against double-taps and refuses archived / cancelled jobs.
export async function allocateJob(client: any, args: {
  body: any
  callerRole?: string | null
  managedVerticals?: unknown
  // M3b U2c: the authed caller's user id (server-derived at the dispatch, never
  // from the body). Threaded into createAssignment so a self-assign (allocator
  // == assignee) skips the allocation SMS.
  actorUserId?: string | null
}): Promise<any> {
  const { body, callerRole, managedVerticals, actorUserId } = args
  const reassignId = body.assignmentId || body.assignment_id || null

  // Resolve the target job — directly for a new allocation, via the existing
  // assignment for a reassignment.
  let jobId: string | null = body.jobId || body.job_id || null
  let sourceAssignment: any = null
  if (reassignId) {
    const { data: a } = await client.from('job_assignments')
      .select('id, job_id, user_id, scheduled_date, scheduled_end, start_time, end_time, assignment_type, crew_name, role, status')
      .eq('id', reassignId).maybeSingle()
    if (!a) throw new ApiError('assignment not found', 404)
    sourceAssignment = a
    jobId = a.job_id
  }
  if (!jobId) throw new ApiError('jobId (new allocation) or assignmentId (reassignment) required', 400)

  const { data: job } = await client.from('jobs')
    .select('id, type, job_number, status').eq('id', jobId).maybeSingle()
  if (!job) throw new ApiError('job not found', 404)

  // Refuse archived / cancelled / otherwise-terminal jobs (same terminal set the
  // open pool excludes).
  const jobStatus = String(job.status || '').toLowerCase()
  if ((_MAKESAFE_POOL_EXCLUDED_STATUSES as readonly string[]).includes(jobStatus)) {
    throw new ApiError(`cannot allocate a ${jobStatus} job`, 409)
  }

  // Authz: dispatcher OR a manager of this job's vertical.
  const jobVertical = _jobVertical(job)
  const decision = _resolveAllocationAuthz({ authMode: 'jwt', callerRole, managedVerticals, jobVertical })
  if (!decision.allowed) {
    throw new ApiError(`Not authorized to allocate ${jobVertical || 'this'} jobs`, 403)
  }

  // Target installer = any active user (owner's decision). Must exist.
  const targetUserId = body.userId || body.user_id || body.toUserId || body.to_user_id || null
  if (!targetUserId) throw new ApiError('target installer (userId) required', 400)
  const { data: target } = await client.from('users').select('id').eq('id', targetUserId).maybeSingle()
  if (!target) throw new ApiError('target installer not found', 404)

  // ── Reassignment: move the existing assignment to the new installer ──
  // Mirrors ops-side reassignment (updateAssignment can set user_id). Keeps the
  // same row so scheduled_date / times / history are preserved unless overridden.
  if (reassignId) {
    if (sourceAssignment.user_id === targetUserId) {
      return { ok: true, mode: 'reassign', deduped: true, assignment: sourceAssignment } // already on this installer
    }
    const updateBody: any = { assignmentId: reassignId, userId: targetUserId }
    const sDateR = body.scheduledDate || body.scheduled_date || body.date
    if (sDateR) updateBody.scheduledDate = sDateR
    if (body.startTime || body.start_time) updateBody.startTime = body.startTime || body.start_time
    if (body.endTime || body.end_time) updateBody.endTime = body.endTime || body.end_time
    if (body.crewName || body.crew_name) updateBody.crewName = body.crewName || body.crew_name
    if (body.notes !== undefined) updateBody.notes = body.notes
    const res = await updateAssignment(client, updateBody)
    return { ok: true, mode: 'reassign', ...res }
  }

  // ── New allocation ──
  const sDate = body.scheduledDate || body.scheduled_date || body.date || null
  if (!sDate) throw new ApiError('scheduledDate required for a new allocation', 400)

  // Idempotency against double-taps: an existing non-cancelled assignment for the
  // same job + installer + date returns instead of inserting a duplicate.
  const { data: dup } = await client.from('job_assignments')
    .select('id, scheduled_date, user_id, status, assignment_type')
    .eq('job_id', jobId).eq('user_id', targetUserId).eq('scheduled_date', sDate)
    .neq('status', 'cancelled').limit(1)
  if (dup && dup.length > 0) {
    return { ok: true, mode: 'idempotent', deduped: true, assignment: dup[0] }
  }

  // M3b U2c: overwrite any body-supplied value with the SERVER-derived actor
  // (or null when unknown, e.g. tests calling allocateJob directly).
  const created = await createAssignment(client, { ...body, jobId, userId: targetUserId, scheduledDate: sDate, allocated_by_user_id: actorUserId || null })
  return { ok: true, mode: 'create', ...created }
}

async function createAssignment(client: any, body: any) {
  const { jobId, job_id, userId, user_id, scheduledDate, scheduled_date, date,
          scheduledEnd, scheduled_end, startTime, start_time, endTime, end_time,
          assignmentType, assignment_type, crewName, crew_name, role, notes } = body

  const jId = jobId || job_id
  const sDate = scheduledDate || scheduled_date || date
  if (!jId || !sDate) throw new Error('jobId and scheduledDate required')

  const confStatus = body.confirmationStatus || body.confirmation_status || 'tentative'
  const validConfStatuses = ['placeholder', 'tentative', 'confirmed']
  const finalConfStatus = validConfStatuses.includes(confStatus) ? confStatus : 'tentative'

  // Fetch the job up-front: needed for the make-safe trade-visibility trigger AND
  // the legacy accepted->processing auto-advance below (one read instead of two).
  const { data: currentJob } = await client.from('jobs')
    .select('id, type, job_number, status').eq('id', jId).single()

  // M4 allocation truth — defect #2: when a MAKE-SAFE assignment is created
  // (the dispatcher allocates the job to a named crew), expose it to the trade
  // app by setting visible_to_trades=true on this row. Without this, allocated
  // make-safes stay invisible (the column defaults to false in prod) and the
  // crew never sees the job. Scoped to make-safe ONLY — ordinary patio/fencing/
  // decking assignments keep their existing visibility behaviour (we only set the
  // flag for make-safe, never clear it for others). This fires at allocation, not
  // earlier: an open-pool make-safe with no named assignment is unaffected.
  const isMakesafe = isMakesafeAccessJob(currentJob) ||
    (currentJob?.id ? await hasMakesafeDetailForAccess(client, currentJob.id) : false)

  const insertRow: Record<string, any> = {
    job_id: jId,
    user_id: userId || user_id || null,
    scheduled_date: sDate,
    scheduled_end: scheduledEnd || scheduled_end || null,
    start_time: startTime || start_time || null,
    end_time: endTime || end_time || null,
    role: role || 'lead_installer',
    notes: notes || null,
    assignment_type: assignmentType || assignment_type || 'install',
    crew_name: crewName || crew_name || null,
    status: 'scheduled',
    confirmation_status: finalConfStatus,
  }
  if (isMakesafe) insertRow.visible_to_trades = true

  const { data, error } = await client.from('job_assignments').insert(insertRow).select().single()

  if (error) throw error

  // Auto-update job status when crew is assigned
  // processing jobs with crew assigned can auto-advance (kept for backwards compat)
  // Legacy 'accepted' jobs also auto-advance to 'processing'
  if (currentJob?.status === 'accepted') {
    await client.from('jobs').update({ status: 'processing', processing_at: new Date().toISOString() }).eq('id', jId)
  }

  // Log event
  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'assignment_created',
    detail_json: { assignment_id: data.id, date: sDate, operator: body.operator_email || body.user_email || null },
  })

  // ── SMS to assigned installer ──
  // Plain-text SMS via the existing ghl-proxy send_sms path. Non-blocking:
  // a notify failure must never fail or delay the assignment write, exactly like
  // direct message. sendSmsViaGhl swallows its own errors and returns a
  // boolean, so the send can never throw or reject.
  //
  // NOTIFY GATE (ship review FIX 2): ops-calendar planning creates assignments
  // with an EXPLICIT confirmation_status of 'placeholder'/'tentative' — those
  // are schedule drafts and must not text a real installer. The trade-app
  // allocate_job path passes NO confirmation status (finalConfStatus falls back
  // to its 'tentative' default), so the gate keys off the EXPLICIT request
  // value, not the default — otherwise every trade allocation would silently
  // stop texting. suppress_notifications mirrors the make-safe creation path.
  // M3b U2c (D4c): NEVER text on a self-assign — when the allocator IS the
  // assignee (a manager grabbing a job for themselves) the text is noise.
  // allocated_by_user_id is threaded in by allocate_job from the AUTHED trade
  // user (server-derived); when absent (ops-dash api_key path) no skip applies.
  const requestedConfStatus = String(body.confirmationStatus || body.confirmation_status || '').toLowerCase()
  const allocatorUserId = body.allocated_by_user_id || null
  const isSelfAssign = !!allocatorUserId && String(allocatorUserId) === String(userId || user_id || '')
  // U-O2 (M3c): a calendar meeting/reminder is a planning entry, never a job
  // allocation — it must NEVER text an installer, whatever its status. Same
  // skip block as the isSelfAssign guard above.
  const notifyAssignmentType = String(assignmentType || assignment_type || 'install').toLowerCase()
  const isNonNotifyingType = notifyAssignmentType === 'meeting' || notifyAssignmentType === 'reminder'
  const skipAllocationSms = !!body.suppress_notifications ||
    finalConfStatus === 'placeholder' ||
    requestedConfStatus === 'tentative' ||
    isSelfAssign ||
    isNonNotifyingType
  try {
    const assignedUserId = userId || user_id
    if (assignedUserId && !skipAllocationSms) {
      const { data: assignedUser } = await client.from('users')
        .select('name, phone').eq('id', assignedUserId).single()
      if (assignedUser?.phone) {
        const { data: jobData2 } = await client.from('jobs')
          .select('job_number, client_name, site_address, site_suburb').eq('id', jId).single()
        if (jobData2) {
          const site = `${jobData2.site_address || ''}${jobData2.site_suburb ? ', ' + jobData2.site_suburb : ''}`.trim()
          const text = [
            `New job assigned: ${jobData2.job_number || ''} - ${jobData2.client_name || 'Client'}`.trim(),
            site ? `Site: ${site}` : '',
            `Date: ${sDate}`,
            `Open in Trade: https://secureworks-group.github.io/secureworks-ux/trade.html#job/${jId}`,
          ].filter(Boolean).join('\n')
          // FIX 3: a bare un-awaited promise can be torn down with the isolate
          // once the response returns. EdgeRuntime.waitUntil is the sanctioned
          // keep-alive; outside the edge runtime (tests, local) fall back to
          // awaiting — safe either way because sendSmsViaGhl never rejects.
          const smsSend = sendSmsViaGhl(assignedUser.phone, text)
          const edgeRuntime = (globalThis as any).EdgeRuntime
          if (edgeRuntime && typeof edgeRuntime.waitUntil === 'function') {
            edgeRuntime.waitUntil(smsSend)
          } else {
            await smsSend
          }
        }
      }
    }
  } catch (e) { console.log('[ops-api] assignment SMS notification failed:', e) }

  // Push schedule info to GHL custom fields (non-blocking)
  // Also grab job_number for business_events dual-write
  try {
    const { data: jobData } = await client.from('jobs')
      .select('ghl_opportunity_id, job_number').eq('id', jId).single()

    // Dual-write to business_events
    logBusinessEvent(client, {
      event_type: 'schedule.assignment_created',
      entity_type: 'crew_assignment',
      entity_id: data.id,
      job_id: jobData?.job_number || jId,
      correlation_id: jId,
      payload: {
        entity: { id: data.id, name: `${data.crew_name || 'Crew'} on ${sDate}` },
        changes: { status: { from: null, to: 'scheduled' } },
        confirmation_status: finalConfStatus,
        crew_name: data.crew_name || '',
        scheduled_date: sDate,
        related_entities: [
          { type: 'job', id: jId },
          { type: 'crew', id: data.user_id || null, name: data.crew_name || '' },
        ],
      },
      metadata: { operator: body.operator_email || body.user_email || null },
    })
    if (jobData?.ghl_opportunity_id) {
      const ghlUrl = `${SUPABASE_URL}/functions/v1/ghl-proxy?action=update_custom_fields`
      fetch(ghlUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          opportunityId: jobData.ghl_opportunity_id,
          fields: {
            scheduled_date: sDate,
            assigned_crew: body.crewName || body.crew_name || '',
            schedule_status: 'scheduled',
          },
        }),
      }).catch(() => {})
    }
  } catch (e) {
    console.log('[ops-api] GHL custom field push failed (non-blocking):', e)
  }

  // Log to jarvis_event_log (non-blocking, fire-and-forget)
  client.from('jarvis_event_log').insert({
    event_type: 'crew_assigned', job_id: jId,
    channel: 'system', triggered_by: body.created_by || 'jarvis',
    message_content: `Assigned ${body.user_name || body.crew_name || body.crewName || 'crew'} to job on ${sDate}`,
    metadata: { user_id: userId || user_id || null, scheduled_date: sDate },
  }).then(() => {}).catch(() => {})

  // Fire-and-forget: recompute job intelligence after assignment creation
  fetch(`${SUPABASE_URL}/functions/v1/reporting-api?action=job_intelligence&job_id=${jId}`, {
    headers: { 'Authorization': `Bearer ${SUPABASE_SERVICE_KEY}` },
  }).catch(() => {})

  return { assignment: data }
}

async function updateAssignment(client: any, body: any) {
  const id = body.assignmentId || body.assignment_id || body.id
  if (!id) throw new Error('assignmentId required')

  // Capture old state for dual-write
  const { data: oldAssignment } = await client
    .from('job_assignments')
    .select('confirmation_status, scheduled_date, crew_name, job_id')
    .eq('id', id)
    .single()

  const allowed: Record<string, string> = {
    scheduledDate: 'scheduled_date', scheduled_date: 'scheduled_date', date: 'scheduled_date',
    scheduledEnd: 'scheduled_end', scheduled_end: 'scheduled_end',
    startTime: 'start_time', start_time: 'start_time',
    endTime: 'end_time', end_time: 'end_time',
    status: 'status', notes: 'notes',
    crewName: 'crew_name', crew_name: 'crew_name',
    assignmentType: 'assignment_type', assignment_type: 'assignment_type', type: 'assignment_type',
    userId: 'user_id', user_id: 'user_id',
    confirmationStatus: 'confirmation_status', confirmation_status: 'confirmation_status',
  }

  const update: Record<string, unknown> = {}
  for (const [bodyKey, dbKey] of Object.entries(allowed)) {
    if (body[bodyKey] !== undefined) update[dbKey] = body[bodyKey]
  }

  const { data, error } = await client
    .from('job_assignments')
    .update(update)
    .eq('id', id)
    .select()
    .single()

  if (error) throw error

  // Dual-write confirmation_status changes to business_events
  const newConfStatus = update.confirmation_status as string | undefined
  const oldConfStatus = oldAssignment?.confirmation_status
  if (newConfStatus && newConfStatus !== oldConfStatus) {
    let eventType = 'schedule.status_changed'
    if (newConfStatus === 'tentative' && oldConfStatus === 'placeholder') eventType = 'schedule.promoted_tentative'
    else if (newConfStatus === 'confirmed') eventType = 'schedule.locked'
    else if (newConfStatus === 'tentative' && oldConfStatus === 'confirmed') eventType = 'schedule.rescheduled'

    logBusinessEvent(client, {
      event_type: eventType,
      entity_type: 'crew_assignment',
      entity_id: id,
      job_id: data?.job_id || oldAssignment?.job_id,
      payload: {
        old_status: oldConfStatus,
        new_status: newConfStatus,
        crew_name: data?.crew_name,
        scheduled_date: data?.scheduled_date,
        old_date: oldAssignment?.scheduled_date,
        new_date: update.scheduled_date || data?.scheduled_date,
        was_locked: oldConfStatus === 'confirmed',
      },
      metadata: { operator: body.operator_email || body.user_email || null },
    })
  }

  // Feature 6: Assignment cascade — if this assignment was marked complete,
  // check if ALL assignments for this job are now complete
  let allComplete = false
  let suggestStatus: string | null = null
  if (data && update.status === 'complete' && data.job_id) {
    const { data: siblings } = await client
      .from('job_assignments')
      .select('id, status')
      .eq('job_id', data.job_id)
      .neq('status', 'cancelled')

    if (siblings && siblings.length > 0) {
      allComplete = siblings.every((a: any) => a.status === 'complete')
      if (allComplete) {
        // Check current job status — only suggest if still in_progress or scheduled
        const { data: job } = await client
          .from('jobs')
          .select('status')
          .eq('id', data.job_id)
          .single()
        if (job && ['in_progress', 'scheduled', 'processing'].includes(job.status)) {
          suggestStatus = 'complete'
        }
      }
    }
  }

  // Push rescheduled date to GHL custom fields (non-blocking)
  if (data?.job_id && (update.scheduled_date || update.crew_name)) {
    try {
      const { data: jobData } = await client.from('jobs')
        .select('ghl_opportunity_id').eq('id', data.job_id).single()
      if (jobData?.ghl_opportunity_id) {
        const fields: Record<string, string> = {}
        if (update.scheduled_date) fields.scheduled_date = update.scheduled_date as string
        if (update.crew_name) fields.assigned_crew = update.crew_name as string
        const ghlUrl = `${SUPABASE_URL}/functions/v1/ghl-proxy?action=update_custom_fields`
        fetch(ghlUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            opportunityId: jobData.ghl_opportunity_id,
            fields,
          }),
        }).catch(() => {})
      }
    } catch (e) {
      console.log('[ops-api] GHL reschedule push failed (non-blocking):', e)
    }
  }

  return { assignment: data, all_complete: allComplete, suggest_status: suggestStatus, job_id: data?.job_id }
}

async function deleteAssignment(client: any, body: any) {
  const id = body.assignmentId || body.assignment_id || body.id
  if (!id) throw new Error('assignmentId required')

  // Get assignment for event log + dual-write
  const { data: existing } = await client
    .from('job_assignments')
    .select('job_id, user_id, scheduled_date, confirmation_status, crew_name')
    .eq('id', id)
    .single()

  const { error } = await client.from('job_assignments').delete().eq('id', id)
  if (error) throw error

  if (existing) {
    await client.from('job_events').insert({
      job_id: existing.job_id,
      event_type: 'assignment_deleted',
      detail_json: { user_id: existing.user_id, date: existing.scheduled_date },
    })

    // Dual-write to business_events
    logBusinessEvent(client, {
      event_type: 'schedule.assignment_deleted',
      entity_type: 'crew_assignment',
      entity_id: id,
      job_id: existing.job_id,
      payload: {
        crew_name: existing.crew_name,
        scheduled_date: existing.scheduled_date,
        was_locked: existing.confirmation_status === 'confirmed',
      },
      metadata: { operator: body.operator_email || body.user_email || null },
    })
  }

  return { success: true }
}

async function updateJobStatus(client: any, body: any) {
  const jId = body.jobId || body.job_id
  const status = body.status
  if (!jId || !status) throw new Error('jobId and status required')

  // Live trusted baseline 2026-05-18 accepted new stages without an edge
  // redeploy. Preserve that behaviour here and let database constraints /
  // stage-gate shadow observations catch invalid transitions downstream.
  if (!status || typeof status !== 'string' || status.length > 50) throw new Error('Invalid status')

  // Capture old status + job data for business_events dual-write
  const { data: jobBefore } = await client.from('jobs')
    .select('status, type, job_number, client_name, pricing_json')
    .eq('id', jId).single()
  const oldStatus = jobBefore?.status || 'unknown'

  // ════════════════════════════════════════════════════════════════
  // Cap 1C — Shadow-mode evaluation (advisory, NEVER enforces)
  //
  // When STATE_ENGINE_SHADOW=on, evaluate the stage-gate engine
  // BEFORE the existing write logic and append an observation row.
  // Behaviour contract:
  //   • Engine eval runs in a try/catch — any throw is logged as a
  //     shadow_error and control falls through to existing write
  //     logic UNCHANGED.
  //   • Observation insert runs in a try/catch — a missing table or
  //     a perms error is silently swallowed.
  //   • This wrapper NEVER blocks, NEVER alters status writes, and
  //     NEVER calls any external system.
  //   • Default: STATE_ENGINE_SHADOW unset → wrapper is a no-op.
  //
  // Rollback: set STATE_ENGINE_SHADOW=off and redeploy.
  //
  // Authority:
  //   • secureworks-docs/decisions/2026-05-02-cap1c-observations-surface.md
  //   • secureworks-docs/cio/evidence/cap1c-shadow-mode-2026-05-02/
  // ════════════════════════════════════════════════════════════════
  const _capShadowFlag = (Deno.env.get('STATE_ENGINE_SHADOW') || '').toLowerCase()
  const _capShadowEnabled = _capShadowFlag === 'on' || _capShadowFlag === '1' || _capShadowFlag === 'true'
  if (_capShadowEnabled) {
    try {
      const _writerSource = body.source || body.writer_source || 'ops_dashboard'
      const _actorEmail = body.operator_email || body.user_email || null
      const _correlationId = body.correlation_id || jId

      const _miniPacket = {
        revision: null,
        document: null,
        purchase_orders: [],
        work_order: null,
        events: [],
        customer: { name: jobBefore?.client_name, mobile: null, email: null },
        site: { address: null, suburb: null, lat: null, lng: null },
        job: {
          id: jId,
          job_number: jobBefore?.job_number,
          type: jobBefore?.type,
          status: status,
          accepted_at: null,
          completed_at: null,
        },
      }
      const _miniSupplemental = { assignments: [], job_context: [], deposit: null }
      // deno-lint-ignore no-explicit-any
      const _sgr: any = evaluateStageGates(
        { id: jId, type: jobBefore?.type },
        _miniPacket,
        _miniSupplemental,
      )
      // deno-lint-ignore no-explicit-any
      const _blockers = _sgr.blockers.map((b: any) => ({ gate_id: b.gate_id, severity: b.severity, reason: b.reason }))
      // deno-lint-ignore no-explicit-any
      const _warnings = _sgr.warnings.map((w: any) => ({ gate_id: w.gate_id, severity: w.severity, reason: w.reason }))
      // deno-lint-ignore no-explicit-any
      const _overrides = _sgr.overrides.map((o: any) => ({ gate_id: o.gate_id, reason: o.reason }))
      let _verdict: 'allow' | 'block' | 'warn' | 'overridden' = 'allow'
      if (_overrides.length > 0) _verdict = 'overridden'
      else if (_blockers.length > 0) _verdict = 'block'
      else if (_warnings.length > 0) _verdict = 'warn'

      try {
        await client.from('state_engine_observations').insert({
          job_id: jobBefore?.job_number || jId,
          from_status: oldStatus,
          to_status: status,
          writer_source: _writerSource,
          engine_verdict: _verdict,
          hard_blocked: false,
          requires_override: false,
          blockers: _blockers,
          warnings: _warnings,
          overrides: _overrides,
          current_stage: _sgr.current_stage,
          frontend_bucket: _sgr.frontend_bucket,
          evidence_refs: _sgr.evidence_refs,
          engine_version: 'cap1c-shadow-mode-2026-05-02',
          shadow_error: null,
          correlation_id: _correlationId,
          actual_write_succeeded: null,
          actor_email: _actorEmail,
          metadata: { transition_attempt_id: _correlationId, observed_only: true, no_enforcement: true },
        })
      } catch (insertErr) {
        // Table may not exist yet, or RLS may block. Cap 1C NEVER
        // lets observation failures break the transition.
        console.warn('[Cap 1C shadow] observation insert failed:', (insertErr as Error).message)
      }
    } catch (evalErr) {
      // Engine throw OR dynamic import error. Log shadow_error if
      // the observations table exists; otherwise skip silently.
      try {
        await client.from('state_engine_observations').insert({
          job_id: jobBefore?.job_number || jId,
          from_status: oldStatus,
          to_status: status,
          writer_source: body.source || 'ops_dashboard',
          engine_verdict: 'error',
          shadow_error: (evalErr as Error).message,
          engine_version: 'cap1c-shadow-mode-2026-05-02',
          metadata: { observed_only: true, no_enforcement: true, eval_failed: true },
        })
      } catch { /* truly silent — never block transition */ }
    }
  }
  // ════════════════════════════════════════════════════════════════
  // End Cap 1C shadow-mode wrapper. Existing write logic unchanged.
  // ════════════════════════════════════════════════════════════════

  const update: Record<string, unknown> = { status }
  if (status === 'quoted') update.quoted_at = new Date().toISOString()
  if (status === 'accepted') update.accepted_at = new Date().toISOString()
  if (status === 'approvals') update.approvals_at = new Date().toISOString()
  if (status === 'deposit') update.deposit_at = new Date().toISOString()
  if (status === 'processing') update.processing_at = new Date().toISOString()
  if (status === 'scheduled') update.scheduled_at = new Date().toISOString()
  if (status === 'complete') update.completed_at = new Date().toISOString()

  // Accept optional field updates (from acceptance review modal)
  if (body.updates) {
    const allowed = ['client_name', 'client_phone', 'client_email', 'site_address', 'site_suburb']
    for (const key of allowed) {
      if (body.updates[key] !== undefined) update[key] = body.updates[key]
    }
  }

  const { data, error } = await client
    .from('jobs')
    .update(update)
    .eq('id', jId)
    .select()
    .single()

  if (error) throw error

  // ── M3d U2b: a transition INTO a terminal jobs.status closes the job's still-
  // open crew assignments so the trade Board stops classifying finished/dead work
  // as live. Non-terminal statuses map to null and no-op. Non-blocking helper.
  const _jobCloseMode = _closeAsForJobStatus(status)
  if (_jobCloseMode) await closeOpenAssignmentsForJob(client, jId, _jobCloseMode)

  const source = body.source || 'ops_dashboard'
  await client.from('job_events').insert({
    job_id: jId,
    user_id: body.userId || body.user_id || null,
    event_type: 'status_changed',
    detail_json: { new_status: status, source, operator: body.operator_email || body.user_email || null },
  })

  // Log to jarvis_event_log (non-blocking, fire-and-forget)
  client.from('jarvis_event_log').insert({
    event_type: 'status_changed',
    job_id: jId,
    channel: 'system',
    triggered_by: body.operator_email || body.user_email || 'ops_dashboard',
    message_content: `Status changed from ${oldStatus} to ${status}`,
    metadata: { old_status: oldStatus, new_status: status, source },
  }).then(() => {}).catch(() => {})

  // Dual-write to business_events
  logBusinessEvent(client, {
    event_type: 'job.status_changed',
    entity_type: 'job',
    entity_id: jId,
    job_id: jobBefore?.job_number || jId,
    correlation_id: jId,
    payload: {
      entity: { id: jId, name: jobBefore?.client_name || '' },
      changes: { status: { from: oldStatus, to: status } },
      financial: { amount: jobBefore?.pricing_json?.total || jobBefore?.pricing_json?.grandTotal || 0 },
      related_entities: [],
    },
    metadata: { operator: body.operator_email || body.user_email || null },
  })

  // ── M3b U2b (D4b): ready-transition manager text ──
  // When a fencing/patio job TRANSITIONS INTO the crew-ready set (new status in
  // the set, old status NOT in the set), text that vertical's managers — the
  // job just became allocatable on their Board. Fires for every writer through
  // this single choke point (manual ops moves AND the ghl_webhook path — though
  // GHL never sets these tokens, so real volume = manual ops moves). Does NOT
  // fire on a repeat save of the same status or a move WITHIN the set.
  // Make-safe is NOT texted here (creation itself texts, U2a); decking has no
  // manager crew flow yet — fencing/patio only per D4b.
  try {
    const readySet = _CREW_READY_STATUSES as readonly string[]
    const notifyVertical = String(data?.type || jobBefore?.type || '').toLowerCase()
    const enteredReadySet = readySet.includes(status) && !readySet.includes(oldStatus)
    if (enteredReadySet && (notifyVertical === 'fencing' || notifyVertical === 'patio')) {
      const readySite = `${data?.site_address || ''}${data?.site_suburb ? ', ' + data.site_suburb : ''}`.trim()
      const readyText = [
        `Job ready for crew: ${data?.job_number || jobBefore?.job_number || ''} - ${data?.client_name || jobBefore?.client_name || 'Client'}`.trim(),
        readySite ? `Site: ${readySite}` : '',
        `Stage: ${status}`,
        `Open in Trade: https://secureworks-group.github.io/secureworks-ux/trade.html#job/${jId}`,
      ].filter(Boolean).join('\n')
      await notifyVerticalManagersSms(client, notifyVertical, readyText)
    }
  } catch (e) {
    console.log('[ops-api] ready-transition manager notify failed (non-blocking):', (e as Error)?.message)
  }

  // Fire-and-forget: recompute job intelligence after status change
  fetch(`${SUPABASE_URL}/functions/v1/reporting-api?action=job_intelligence&job_id=${jId}`, {
    headers: { 'Authorization': `Bearer ${SUPABASE_SERVICE_KEY}` },
  }).catch(() => {})

  // ── Push status change to GHL (non-blocking) ──
  // Skip if this change originated from a GHL webhook (anti-loop)
  if (source !== 'ghl_webhook' && data.ghl_opportunity_id) {
    try {
      const ghlUrl = `${SUPABASE_URL}/functions/v1/ghl-proxy?action=move_stage`
      const ghlResp = await fetch(ghlUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          opportunityId: data.ghl_opportunity_id,
          status: status,
          jobType: data.type || 'patio',
        }),
      })
      const ghlResult = await ghlResp.json()
      if (ghlResult.success) {
        console.log(`[ops-api] GHL stage synced: ${data.ghl_opportunity_id} → ${status}`)
        await client.from('job_events').insert({
          job_id: jId,
          event_type: 'ghl_stage_synced',
          detail_json: { status, opportunity_id: data.ghl_opportunity_id, stage_id: ghlResult.stageId },
        })
      } else {
        console.log(`[ops-api] GHL stage sync failed (non-blocking): ${ghlResult.error}`)
      }
    } catch (e) {
      console.log('[ops-api] GHL stage push failed (non-blocking):', (e as Error).message)
    }
  }

  // ── Acceptance trigger: auto-approve draft WOs + push labour POs to Xero (non-blocking) ──
  if (status === 'accepted') {
    (async () => {
      try {
        // 1. Approve draft work orders for this job
        const { data: draftWOs } = await client.from('work_orders')
          .select('id, wo_number')
          .eq('job_id', jId)
          .eq('status', 'draft')
        if (draftWOs && draftWOs.length > 0) {
          for (const wo of draftWOs) {
            await client.from('work_orders')
              .update({ status: 'approved', approved_at: new Date().toISOString() })
              .eq('id', wo.id)
            await client.from('job_events').insert({
              job_id: jId,
              event_type: 'work_order_approved',
              detail_json: { wo_number: wo.wo_number, trigger: 'acceptance_auto' },
            })
            console.log(`[ops-api] Auto-approved WO ${wo.wo_number} on job acceptance`)
          }
        }

        // 2. Push draft labour POs to Xero
        const { data: draftPOs } = await client.from('purchase_orders')
          .select('id, po_number')
          .eq('job_id', jId)
          .eq('status', 'draft')
          .is('xero_po_id', null)
        if (draftPOs && draftPOs.length > 0) {
          for (const po of draftPOs) {
            try {
              await pushPOToXero(client, { id: po.id })
              console.log(`[ops-api] Auto-pushed PO ${po.po_number} to Xero on job acceptance`)
            } catch (poErr) {
              console.log(`[ops-api] Auto-push PO ${po.po_number} to Xero failed (non-blocking):`, (poErr as Error).message)
            }
          }
        }
      } catch (e) {
        console.log('[ops-api] Acceptance trigger failed (non-blocking):', (e as Error).message)
      }
    })()
  }

  return { success: true, job_id: jId, new_status: status, job_number: data?.job_number || jobBefore?.job_number }
}
// Test-only export alias (mirrors the `_`-prefixed convention in this file).
export const _updateJobStatus = updateJobStatus

async function createPO(client: any, body: any) {
  const { job_id, jobId, supplier_name, supplierName, xero_contact_id,
          line_items, lineItems, delivery_date, deliveryDate, delivery_address, reference, notes } = body

  const supplier = supplier_name || supplierName
  if (!supplier && body.status !== 'draft') throw new Error('supplier_name required')

  // Generate PO number from timestamp (sequence requires raw SQL RPC)
  const poNum = `PO-${String(Date.now()).slice(-6)}`

  const items = line_items || lineItems || []
  const subtotal = items.reduce((s: number, li: any) => s + ((li.quantity || 0) * (li.unit_price || li.unitPrice || 0)), 0)
  const tax = Math.round(subtotal * 0.1 * 100) / 100 // 10% GST
  const total = subtotal + tax

  const { data, error } = await client
    .from('purchase_orders')
    .insert({
      org_id: DEFAULT_ORG_ID,
      job_id: job_id || jobId || null,
      po_number: poNum,
      supplier_name: supplier,
      xero_contact_id: xero_contact_id || null,
      line_items: items,
      subtotal, tax, total,
      delivery_date: delivery_date || deliveryDate || null,
      reference: reference || null,
      notes: formatPoDeliveryNotes(delivery_address, notes),
      status: body.status || 'draft',
      created_by: body.operator_email || body.user_email || null,
    })
    .select()
    .single()

  if (error) throw error

  const jId = job_id || jobId
  if (jId) {
    await client.from('job_events').insert({
      job_id: jId,
      event_type: 'po_created',
      detail_json: { po_number: poNum, supplier, total },
    })
  }

  // Dual-write to business_events.
  //
  // T7 Loop 5 — closes G2: outbound PO spine rows were 0/16 with
  // job_id because this writer put the wrong field in job_id.
  //   BEFORE: job_id: data.reference || ''         (PO reference, not job)
  //   BEFORE: correlation_id: data.job_id || null  (actual job in wrong field)
  // FIX: use data.job_id directly. correlation_id stays as the UUID
  // group key for the PO lifecycle (po.created → po.sent → po.confirmed).
  //
  // When evidence_capture_v1 is ON, recordEvidence becomes the writer
  // with full envelope (channel='po', direction='outbound'). When OFF,
  // logBusinessEvent runs with the field-swap fix applied (G2 still
  // closes even before the flag flips).
  const t7PoEnabled = await isFlagOn(client, 'evidence_capture_v1', '00000000-0000-0000-0000-000000000001')
  // Legacy logBusinessEvent payload — emitted either by the T7 fallback
  // path OR when the flag is OFF. Defined once so G2's job_id closure
  // applies in both branches.
  const legacyPoEvent = {
    event_type: 'po.created',
    entity_type: 'purchase_order',
    entity_id: data.id,
    job_id: data.job_id || '',                // FIXED: was data.reference
    correlation_id: data.job_id || undefined, // kept as a workflow group
    payload: {
      entity: { id: data.id, name: data.po_number || '' },
      financial: { amount: Number(data.total || 0), currency: 'AUD' },
      related_entities: [
        { type: 'supplier', id: null, name: data.supplier_name || '' },
        { type: 'job', id: data.job_id || null },
      ],
      po_reference: data.reference || null,
    },
    metadata: { operator: body.operator_email || body.user_email || null },
  }
  let t7PoFailed = false
  if (t7PoEnabled) {
    try {
      await recordEvidence(client, {
        event_type: 'po.created',
        source: 'ops-api/create_po',
        channel: 'po',
        direction: 'outbound',
        source_table: 'purchase_orders',
        source_id: String(data.id),
        job_id: data.job_id || null,
        entity_type: 'purchase_order',
        entity_id: data.id,
        match_method: data.job_id ? 'direct_job_id' : 'none',
        body_preview: `PO ${data.po_number || ''} → ${data.supplier_name || 'supplier'}: $${Number(data.total || 0).toFixed(2)}`,
        privacy_classification: 'staff_only',
        retention_class: '7y_audit',
        payload: {
          entity: { id: data.id, name: data.po_number || '' },
          financial: { amount: Number(data.total || 0), currency: 'AUD' },
          related_entities: [
            { type: 'supplier', id: null, name: data.supplier_name || '' },
            { type: 'job', id: data.job_id || null },
          ],
          po_reference: data.reference || null,
        },
        metadata: { operator: body.operator_email || body.user_email || null },
      }, {
        org_id: '00000000-0000-0000-0000-000000000001',
        storage_client: client.storage,
      })
    } catch (e: any) {
      // T7 path failed — fall back to legacy logBusinessEvent below so
      // the canonical PO event still lands on the spine. Without this
      // fallback, an outbound PO could be silently dropped from the
      // canonical event log when evidence_capture_v1 is ON.
      console.error('[ops-api] T7 po.created recordEvidence failed; falling back to legacy:', e?.message)
      t7PoFailed = true
    }
  }
  if (!t7PoEnabled || t7PoFailed) {
    logBusinessEvent(client, legacyPoEvent)
  }

  // Log to jarvis_event_log (non-blocking, fire-and-forget)
  client.from('jarvis_event_log').insert({
    event_type: 'po_created', job_id: job_id || jobId || null,
    channel: 'system', triggered_by: body.created_by || 'jarvis',
    message_content: `PO created for ${supplier}: $${total || 0}`,
    metadata: { supplier_name: supplier, total },
  }).then(() => {}).catch(() => {})

  // Fire-and-forget: recompute job intelligence after PO creation
  if (job_id || jobId) {
    fetch(`${SUPABASE_URL}/functions/v1/reporting-api?action=job_intelligence&job_id=${job_id || jobId}`, {
      headers: { 'Authorization': `Bearer ${SUPABASE_SERVICE_KEY}` },
    }).catch(() => {})
  }

  return { purchase_order: data }
}

async function updatePO(client: any, body: any) {
  const { id, ...updates } = body
  if (!id) throw new Error('id required')

  const allowed = ['supplier_name', 'xero_contact_id', 'line_items', 'delivery_date',
                    'reference', 'notes', 'status',
                    'invoice_received_at', 'paid_at', 'xero_bill_id']
  const filtered: any = {}
  for (const k of allowed) {
    if (updates[k] !== undefined) filtered[k] = updates[k]
  }

  if (filtered.line_items) {
    const items = filtered.line_items
    filtered.subtotal = items.reduce((s: number, li: any) => s + ((li.quantity || 0) * (li.unit_price || 0)), 0)
    filtered.tax = Math.round(filtered.subtotal * 0.1 * 100) / 100
    filtered.total = filtered.subtotal + filtered.tax
  }

  const { data, error } = await client
    .from('purchase_orders')
    .update(filtered)
    .eq('id', id)
    .select()
    .single()

  if (error) throw error
  return { purchase_order: data }
}

async function pushPOToXero(client: any, body: any) {
  const { id, status: requestedStatus } = body
  if (!id) throw new Error('id required')

  const { data: po, error } = await client
    .from('purchase_orders')
    .select('*')
    .eq('id', id)
    .single()

  if (error || !po) throw new Error('PO not found')
  if (po.xero_po_id) throw new Error('PO already synced to Xero')

  // U2 reference discipline — resolve the canonical outbound job ref ONCE so both
  // the Xero Reference field and the DeliveryInstructions quote-back ask carry the
  // exact SW[PFD]-##### form the inbound bill-linker recognises. Prefer the
  // authoritative jobs.job_number; fall back to whatever the PO stored.
  let poJobNumber = ''
  if (po.job_id) {
    const { data: poJob } = await client
      .from('jobs')
      .select('job_number')
      .eq('id', po.job_id)
      .maybeSingle()
    poJobNumber = poJob?.job_number || ''
  }
  const jobRef = _canonicalJobRef(po.reference, poJobNumber)

  const { accessToken, tenantId } = await getToken(client)

  // Resolve supplier contact in Xero — find or create
  let supplierContactId = po.xero_contact_id
  if (!supplierContactId && po.supplier_name) {
    try {
      const searchResult = await xeroGet('/Contacts', accessToken, tenantId, {
        where: `Name=="${(po.supplier_name || '').replace(/"/g, '')}"&&IsSupplier==true`,
      })
      const existing = searchResult?.Contacts?.[0]
      if (existing) {
        supplierContactId = existing.ContactID
      } else {
        // Try without IsSupplier filter (some contacts may not be flagged)
        const searchResult2 = await xeroGet('/Contacts', accessToken, tenantId, {
          where: `Name=="${(po.supplier_name || '').replace(/"/g, '')}"`,
        })
        const existing2 = searchResult2?.Contacts?.[0]
        if (existing2) {
          supplierContactId = existing2.ContactID
        } else {
          // Create new supplier contact
          const newContact = await xeroPost('/Contacts', accessToken, tenantId, {
            Contacts: [{ Name: po.supplier_name, IsSupplier: true }],
          }, 'PUT', `supplier-${(po.supplier_name || '').replace(/\s/g, '-')}`)
          supplierContactId = newContact?.Contacts?.[0]?.ContactID
        }
      }
      // Backfill on the PO record
      if (supplierContactId) {
        client.from('purchase_orders').update({ xero_contact_id: supplierContactId }).eq('id', id).then(() => {}).catch(() => {})
      }
    } catch (e) {
      console.log('[ops-api] Supplier contact resolution failed:', (e as Error).message)
    }
  }

  // Only include tracking if the Xero tracking category exists
  let poTracking: any[] = []
  try {
    const trackingCats = await xeroGet('/TrackingCategories', accessToken, tenantId)
    const divisionCat = (trackingCats?.TrackingCategories || []).find((tc: any) => tc.Name === 'Business Unit' && tc.Status === 'ACTIVE')
    if (divisionCat) {
      const poRef = jobRef || po.reference || ''
      const optionName = trackingCategoryForJob(poRef)
      const validOption = (divisionCat.Options || []).find((o: any) => o.Name === optionName && o.Status === 'ACTIVE')
      if (validOption) poTracking = [{ Name: 'Business Unit', Option: optionName }]
    }
  } catch { /* skip tracking if lookup fails */ }

  const lineItems = (po.line_items || []).map((li: any) => ({
    Description: li.description || li.name || '',
    Quantity: li.quantity || 1,
    UnitAmount: li.unit_price || li.unitPrice || 0,
    AccountCode: li.account_code || '300',
    TaxType: 'INPUT',
    ...(poTracking.length > 0 ? { Tracking: poTracking } : {}),
  }))

  // DRAFT or AUTHORISED based on request
  const xeroStatus = requestedStatus === 'authorised' ? 'AUTHORISED' : 'SUBMITTED'
  const localStatus = requestedStatus === 'authorised' ? 'authorised' : 'submitted'

  // U2 — stamp the canonical job ref in Reference (what the supplier is asked to
  // quote back) and ride the quote-back ask onto Xero's own PO PDF via the
  // DeliveryInstructions free-text field (the only lever we have on Xero's
  // un-templatable PO email; see _shared/po_reference.ts for why not a line item).
  const xeroPO = {
    PurchaseOrders: [{
      Contact: supplierContactId
        ? { ContactID: supplierContactId }
        : { Name: po.supplier_name },
      PurchaseOrderNumber: po.po_number,
      Reference: jobRef || po.reference || '',
      DeliveryDate: po.delivery_date || undefined,
      ...(jobRef ? { DeliveryInstructions: _poDeliveryInstruction(jobRef) } : {}),
      LineAmountTypes: 'Exclusive',
      LineItems: lineItems,
      Status: xeroStatus,
    }],
  }

  // Idempotency key: PO ID is unique, prevents duplicate on retry
  const poIdempotencyKey = `po-${id}-${new Date().toISOString().slice(0, 16)}`
  const result = await xeroPost('/PurchaseOrders', accessToken, tenantId, xeroPO, 'PUT', poIdempotencyKey)
  const xeroPOId = result?.PurchaseOrders?.[0]?.PurchaseOrderID

  if (xeroPOId) {
    await client.from('purchase_orders')
      .update({ xero_po_id: xeroPOId, status: localStatus, synced_at: new Date().toISOString() })
      .eq('id', id)
  }

  return { success: true, xero_po_id: xeroPOId }
}

async function emailPO(client: any, body: any) {
  const id = body.id || body.po_id
  if (!id) throw new Error('id required')

  const { data: po, error } = await client
    .from('purchase_orders')
    .select('xero_po_id, po_number, supplier_name, job_id, total')
    .eq('id', id)
    .single()

  if (error || !po) throw new Error('PO not found')
  if (!po.xero_po_id) throw new Error('PO has not been synced to Xero yet. Call sw_push_po_to_xero first, then sw_email_po.')

  const { accessToken, tenantId } = await getToken(client)
  await xeroPost(`/PurchaseOrders/${po.xero_po_id}/Email`, accessToken, tenantId, {}, 'POST')

  // Log to business_events
  logBusinessEvent(client, {
    event_type: 'po.sent',
    entity_type: 'purchase_order',
    entity_id: id,
    job_id: po.job_id || null,
    correlation_id: po.job_id || null,
    payload: {
      entity: { id, name: po.po_number || '' },
      financial: { amount: Number(po.total || 0), currency: 'AUD' },
      related_entities: [
        { type: 'supplier', id: null, name: po.supplier_name || '' },
      ],
    },
    metadata: { operator: body.operator_email || body.user_email || null },
  })

  return { success: true }
}

// ── Reconcile payment against Xero invoice ──
async function reconcilePayment(client: any, body: any) {
  const { invoice_id, amount, payment_date, reference, account_code } = body

  if (!invoice_id || !amount) throw new Error('invoice_id and amount required')

  const { accessToken, tenantId } = await getToken(client)

  // If no account_code provided, find the main bank account
  let bankAccountCode = account_code
  let bankAccountId: string | null = null
  if (!bankAccountCode) {
    try {
      const accounts = await xeroGet('/Accounts', accessToken, tenantId, {
        where: 'Type=="BANK"&&Status=="ACTIVE"',
      })
      const bankAccount = accounts?.Accounts?.[0]
      bankAccountCode = bankAccount?.Code || null
      bankAccountId = bankAccount?.AccountID || null
    } catch {
      // Will fail below if no account found
    }
  }

  if (!bankAccountCode && !bankAccountId) {
    throw new Error('No bank account found in Xero. Please provide an account_code or set up a bank account in Xero.')
  }

  const paymentPayload = {
    Payments: [{
      Invoice: { InvoiceID: invoice_id },
      Account: bankAccountId ? { AccountID: bankAccountId } : { Code: bankAccountCode },
      Date: payment_date || new Date().toISOString().slice(0, 10),
      Amount: Number(amount),
      Reference: reference || '',
    }],
  }

  const normalizedDate = payment_date || new Date().toISOString().slice(0, 10)
  const idempotencyKey = `payment-${invoice_id}-${amount}-${normalizedDate}`
  const result = await xeroPost('/Payments', accessToken, tenantId, paymentPayload, 'PUT', idempotencyKey)
  const payment = result?.Payments?.[0]

  if (!payment) {
    throw new Error('Xero returned no payment data')
  }

  // Update cached invoice in xero_invoices table if it exists
  try {
    const newAmountPaid = Number(payment.Amount || amount)
    const { data: cachedInv } = await client.from('xero_invoices')
      .select('amount_due, amount_paid')
      .eq('invoice_id', invoice_id)
      .maybeSingle()

    if (cachedInv) {
      await client.from('xero_invoices').update({
        amount_paid: (Number(cachedInv.amount_paid) || 0) + newAmountPaid,
        amount_due: Math.max(0, (Number(cachedInv.amount_due) || 0) - newAmountPaid),
        status: payment.Invoice?.Status || 'PAID',
        updated_at: new Date().toISOString(),
      }).eq('invoice_id', invoice_id)
    }
  } catch (e) {
    console.log('[ops-api] cache update after payment failed:', e)
  }

  // Log the payment event
  try {
    await client.from('job_events').insert({
      event_type: 'payment_recorded',
      detail_json: {
        invoice_id,
        payment_id: payment.PaymentID,
        amount: Number(amount),
        reference,
        account_code: bankAccountCode,
      },
    })
  } catch { /* non-blocking */ }

  return {
    success: true,
    payment_id: payment.PaymentID,
    amount: payment.Amount,
    date: payment.Date,
    status: payment.Status,
    invoice_status: payment.Invoice?.Status,
  }
}

async function createWorkOrder(client: any, body: any) {
  const jId = body.job_id || body.jobId
  if (!jId) throw new Error('job_id required')

  const woNum = `WO-${String(Date.now()).slice(-6)}`

  // Get site address from job if not provided
  let address = body.site_address || body.siteAddress
  if (!address) {
    const { data: job } = await client.from('jobs').select('site_address, site_suburb').eq('id', jId).single()
    if (job) address = [job.site_address, job.site_suburb].filter(Boolean).join(', ')
  }

  const { data, error } = await client
    .from('work_orders')
    .insert({
      org_id: DEFAULT_ORG_ID,
      job_id: jId,
      wo_number: woNum,
      trade_name: body.trade_name || body.tradeName || null,
      trade_phone: body.trade_phone || body.tradePhone || null,
      trade_email: body.trade_email || body.tradeEmail || null,
      assigned_user_id: body.assigned_user_id || body.assignedUserId || null,
      scope_items: body.scope_items || body.scopeItems || [],
      special_instructions: body.special_instructions || body.specialInstructions || null,
      scheduled_date: body.scheduled_date || body.scheduledDate || null,
      site_address: address || null,
      status: 'draft',
      created_by: body.operator_email || body.user_email || null,
    })
    .select()
    .single()

  if (error) throw error

  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'wo_created',
    detail_json: { wo_number: woNum, trade: body.trade_name || body.tradeName },
  })

  // Dual-write to business_events
  logBusinessEvent(client, {
    event_type: 'wo.created',
    entity_type: 'work_order',
    entity_id: data.id,
    job_id: jId,
    correlation_id: jId,
    payload: {
      entity: { id: data.id, name: woNum },
      related_entities: [
        { type: 'job', id: jId },
        { type: 'trade', id: data.assigned_user_id || null, name: body.trade_name || body.tradeName || '' },
      ],
    },
    metadata: { operator: body.operator_email || body.user_email || null },
  })

  // Log to jarvis_event_log (non-blocking, fire-and-forget)
  client.from('jarvis_event_log').insert({
    event_type: 'work_order_created', job_id: jId,
    channel: 'system', triggered_by: 'jarvis',
    message_content: `Work order created`,
    metadata: {},
  }).then(() => {}).catch(() => {})

  return { work_order: data }
}

async function updateWorkOrder(client: any, body: any) {
  const { id, ...updates } = body
  if (!id) throw new Error('id required')

  const allowed = ['trade_name', 'trade_phone', 'trade_email', 'assigned_user_id',
                    'scope_items', 'special_instructions', 'scheduled_date',
                    'site_address', 'status']
  const filtered: any = {}
  for (const k of allowed) {
    if (updates[k] !== undefined) filtered[k] = updates[k]
  }

  if (filtered.status === 'sent') filtered.sent_at = new Date().toISOString()
  if (filtered.status === 'accepted') filtered.accepted_at = new Date().toISOString()
  if (filtered.status === 'complete') filtered.completed_at = new Date().toISOString()

  const { data, error } = await client
    .from('work_orders')
    .update(filtered)
    .eq('id', id)
    .select()
    .single()

  if (error) throw error
  return { work_order: data }
}

async function sendWorkOrder(client: any, body: any) {
  const id = body.id || body.work_order_id
  if (!id) throw new Error('id required')

  const { data: wo, error } = await client
    .from('work_orders')
    .select('*')
    .eq('id', id)
    .single()

  if (error || !wo) throw new Error('Work order not found')

  // Mark as sent
  await client.from('work_orders')
    .update({ status: 'sent', sent_at: new Date().toISOString() })
    .eq('id', id)

  if (wo.job_id) {
    await client.from('job_events').insert({
      job_id: wo.job_id,
      event_type: 'wo_sent',
      detail_json: { wo_number: wo.wo_number, trade_email: wo.trade_email },
    })
  }

  return {
    success: true,
    message: `Work order ${wo.wo_number} marked as sent`,
    share_token: wo.share_token,
  }
}

// Fetch invoice PDF from Xero API and return as base64
async function getInvoicePdf(client: any, params: URLSearchParams) {
  let xeroInvoiceId = params.get('xero_invoice_id')
  const invoiceNumber = params.get('invoice_number')

  if (!xeroInvoiceId && invoiceNumber) {
    const { data } = await client.from('xero_invoices')
      .select('xero_invoice_id, invoice_number')
      .eq('invoice_number', invoiceNumber)
      .maybeSingle()
    if (!data) throw new ApiError(`Invoice ${invoiceNumber} not found`, 404)
    xeroInvoiceId = data.xero_invoice_id
  }
  if (!xeroInvoiceId) throw new ApiError('xero_invoice_id or invoice_number required', 400)

  const { accessToken, tenantId } = await getToken(client)

  // Fetch PDF from Xero — raw binary, not JSON
  let resp: Response | null = null
  for (let attempt = 0; attempt <= 3; attempt++) {
    resp = await fetch(`${XERO_API_BASE}/Invoices/${xeroInvoiceId}`, {
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Xero-tenant-id': tenantId,
        'Accept': 'application/pdf',
      },
    })
    if (resp.status === 429) {
      if (attempt >= 3) throw new ApiError('Xero rate limited after retries', 429)
      const retryAfter = parseInt(resp.headers.get('Retry-After') || '5')
      await new Promise(r => setTimeout(r, retryAfter * 1000))
      continue
    }
    break
  }

  if (!resp || !resp.ok) {
    const errText = resp ? await resp.text() : 'No response'
    if (resp?.status === 404) throw new ApiError('Invoice not found in Xero', 404)
    throw new ApiError(`Failed to fetch PDF from Xero: ${resp?.status} ${errText}`, 502)
  }

  // Convert binary PDF to base64
  const buffer = await resp.arrayBuffer()
  const bytes = new Uint8Array(buffer)
  let binary = ''
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i])
  }
  const pdf_base64 = btoa(binary)

  // Get invoice number for filename
  let filename = `${xeroInvoiceId}.pdf`
  if (invoiceNumber) {
    filename = `${invoiceNumber}.pdf`
  } else {
    const { data: invRecord } = await client.from('xero_invoices')
      .select('invoice_number')
      .eq('xero_invoice_id', xeroInvoiceId)
      .maybeSingle()
    if (invRecord?.invoice_number) filename = `${invRecord.invoice_number}.pdf`
  }

  return { success: true, pdf_base64, filename, content_type: 'application/pdf' }
}

// ── Loop 1B-a-apply: invoice preflight contract ──
//
// Read-only check that gathers the dimensions a "ready to invoice" job must
// carry so the resulting Xero invoice arrives with enough detail for finance
// to reconcile without leaving Xero. Surfaces three things:
//
//   missing_dimensions[] — hard blockers. createInvoice will refuse unless
//                          body.bypass_preflight === true (override is logged
//                          to business_events as an explicit operator action).
//   warnings[]           — soft advisories. Don't block creation; bookkeeper
//                          should be aware (e.g. no frozen quote/scope yet,
//                          payment_terms falling back to division default).
//   context{}            — the resolved trace context. createInvoice reuses
//                          this so we don't re-read the same rows twice.
//
// Per Marnin's 2026-05-06 directive (four-pillars-progress-2026-05-06.md §5):
// "design/implement the preflight contract enough to prevent weak invoice
//  creation paths from shipping bad invoices."
async function preflightInvoiceCreation(client: any, body: any): Promise<{
  ok: boolean,
  missing_dimensions: string[],
  warnings: string[],
  context: {
    job: any,
    job_contact: any | null,
    job_number: string | null,
    customer_name: string | null,
    suburb: string | null,
    division: string | null,
    account_code: string,
    tracking_option: string,
    quote_revision_id: string | null,
    scope_revision_id: string | null,
    payment_terms_text: string,
    payment_terms_source: 'body_override' | 'jobs.payment_terms' | 'pricing_json.payment_terms' | 'division_default',
    due_date: string,
    xero_project_manual_status: string,
  } | null,
}> {
  const jobId = body.job_id || body.jobId
  const jobContactId = body.job_contact_id || null
  const missing: string[] = []
  const warnings: string[] = []

  if (!jobId) {
    // No job context — degraded preflight. Caller is doing ad-hoc invoicing.
    // We still surface the dimension gaps so MCP / ops UI can react, but
    // there is no context to populate.
    missing.push('job_id')
    return { ok: false, missing_dimensions: missing, warnings, context: null }
  }

  // Single round-trip for everything we need.
  const { data: job, error: jobErr } = await client
    .from('jobs')
    .select('id, job_number, type, status, client_name, client_email, client_phone, ' +
            'site_address, site_suburb, xero_contact_id, pricing_json, payment_terms')
    .eq('id', jobId)
    .single()
  if (jobErr || !job) {
    missing.push('job_not_found')
    return { ok: false, missing_dimensions: missing, warnings, context: null }
  }

  let jobContact: any = null
  if (jobContactId) {
    const { data: jc } = await client.from('job_contacts')
      .select('id, client_name, client_email, client_phone, site_address, contact_label, xero_contact_id')
      .eq('id', jobContactId)
      .maybeSingle()
    jobContact = jc || null
    if (!jobContact) warnings.push('job_contact_id_provided_but_not_found')
  }

  // Resolve customer name. Prefer neighbour contact when provided.
  const customerName = (jobContact?.client_name || job.client_name || '').trim() || null
  if (!customerName) missing.push('customer_name')

  // Resolve suburb. job.site_suburb is the canonical source today.
  // job_contacts.site_address is a free-text field; we don't parse a suburb
  // out of it — we rely on the parent job's site_suburb for now.
  const suburb = (job.site_suburb || '').trim() || null
  if (!suburb) missing.push('suburb')

  // Job number — required on every ACCREC invoice for division reporting.
  const jobNumber = (job.job_number || '').trim() || null
  if (!jobNumber) missing.push('job_number')

  // Division — derived from job.type.
  const knownDivisions = new Set(['patio', 'fencing', 'decking', 'roofing', 'insurance', 'renovation', 'combo', 'general', 'makesafe'])
  const divisionRaw = (job.type || '').toLowerCase().trim()
  const division = knownDivisions.has(divisionRaw) ? divisionRaw : null
  if (!division) missing.push('division')

  // Account code — accountCodeForJob always returns a string but we want the
  // mapping to be EXPLICIT not fallback for a known division.
  const accountCode = accountCodeForJob(job.type)

  // Tracking option — derived from job_number prefix.
  const trackingOption = trackingCategoryForJob(jobNumber || '')
  if (!trackingOption && division !== 'general') missing.push('tracking_option_unresolvable')

  // Frozen quote / scope revisions. These are SOFT — invoices for ad-hoc
  // jobs may not have a frozen quote/scope, but the bookkeeper benefits when
  // they do.
  let quoteRevisionId: string | null = null
  let scopeRevisionId: string | null = null
  try {
    // NEEDS A DECISION: quote_revisions has no superseded_at column (verified against live
    // schema), so this .is() filter still 400s the query and quoteRevisionId stays null.
    // There is no equivalent column — supersession may be implicit in `version`/`staged_at`
    // (highest version = current), but that is a guess, so the filter is left as-is pending
    // a product call. Ordering below was corrected created_at → staged_at.
    const { data: qr } = await client.from('quote_revisions')
      .select('id')
      .eq('job_id', jobId)
      .is('superseded_at', null)
      .order('staged_at', { ascending: false })
      .limit(1)
      .maybeSingle()
    quoteRevisionId = qr?.id || null
  } catch { /* table may not exist in some envs */ }
  if (!quoteRevisionId) warnings.push('quote_revision_id_missing')

  try {
    const { data: sr } = await client.from('scope_revisions')
      .select('id')
      .eq('job_id', jobId)
      .is('superseded_at', null)
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle()
    scopeRevisionId = sr?.id || null
  } catch { /* table may not exist in some envs */ }
  if (!scopeRevisionId) warnings.push('scope_revision_id_missing')

  // Payment-terms text. Source priority: body override > job-level > pricing-level > division default.
  const pricing = (typeof job.pricing_json === 'string'
    ? JSON.parse(job.pricing_json || '{}')
    : (job.pricing_json || {})) as Record<string, any>
  const PAYMENT_TERMS_DEFAULTS: Record<string, string> = {
    patio:      'Net 14 days from invoice date. Bank transfer.',
    fencing:    'Net 14 days from invoice date. Bank transfer.',
    decking:    'Net 14 days from invoice date. Bank transfer.',
    roofing:    'Net 14 days from invoice date. Bank transfer.',
    insurance:  'Payable on completion of works per insurance scope. Bank transfer.',
    renovation: 'Net 14 days from invoice date. Bank transfer.',
    combo:      'Net 14 days from invoice date. Bank transfer.',
    general:    'Net 14 days from invoice date. Bank transfer.',
  }
  let paymentTermsText = ''
  let paymentTermsSource: 'body_override' | 'jobs.payment_terms' | 'pricing_json.payment_terms' | 'division_default' = 'division_default'
  if (typeof body.terms_override === 'string' && body.terms_override.trim()) {
    paymentTermsText = body.terms_override.trim()
    paymentTermsSource = 'body_override'
  } else if (typeof job.payment_terms === 'string' && job.payment_terms.trim()) {
    paymentTermsText = job.payment_terms.trim()
    paymentTermsSource = 'jobs.payment_terms'
  } else if (typeof pricing.payment_terms === 'string' && pricing.payment_terms.trim()) {
    paymentTermsText = pricing.payment_terms.trim()
    paymentTermsSource = 'pricing_json.payment_terms'
  } else {
    paymentTermsText = PAYMENT_TERMS_DEFAULTS[division || 'general'] || PAYMENT_TERMS_DEFAULTS.general
    paymentTermsSource = 'division_default'
    warnings.push('payment_terms_using_division_default')
  }

  // Due date. body.due_date wins; otherwise today + 14 days (existing default).
  const dueDate = body.due_date || body.dueDate
    || new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10)

  // Xero Project manual-fill default for new invoices. The 2026-04-09 ADR
  // declared Xero Projects API unreliable; we surface a manual-fill queue.
  const xeroProjectManualStatus = 'needs_manual_fill'

  return {
    ok: missing.length === 0,
    missing_dimensions: missing,
    warnings,
    context: {
      job,
      job_contact: jobContact,
      job_number: jobNumber,
      customer_name: customerName,
      suburb,
      division,
      account_code: accountCode,
      tracking_option: trackingOption,
      quote_revision_id: quoteRevisionId,
      scope_revision_id: scopeRevisionId,
      payment_terms_text: paymentTermsText,
      payment_terms_source: paymentTermsSource,
      due_date: dueDate,
      xero_project_manual_status: xeroProjectManualStatus,
    },
  }
}

// Computes the typed reference suffix for an invoice. Mirrors the createDepositInvoice
// builder shape and the H1 fix family. Used by createInvoice to stamp xero_invoices.reference_suffix.
function computeReferenceSuffix(jobNumber: string, reference: string): string | null {
  if (!reference) return null
  const trimmed = reference.trim()
  if (!trimmed) return null
  const prefix = (jobNumber || '').trim()
  if (prefix && trimmed.toUpperCase().startsWith(prefix.toUpperCase())) {
    const suffix = trimmed.slice(prefix.length).replace(/^[-\s]+/, '').trim()
    return suffix || null
  }
  return trimmed
}

async function createInvoice(client: any, body: any) {
  const { job_id, jobId, contact_name, contactName, xero_contact_id, job_contact_id,
          line_items, lineItems, due_date, dueDate, reference,
          xero_status, send_email } = body

  const items = line_items || lineItems
  if (!items || items.length === 0) throw new Error('line_items required')
  const contact = contact_name || contactName
  if (!contact && !xero_contact_id) throw new Error('contact_name or xero_contact_id required')

  // ── REPORT JOB $0 GATE (generic createInvoice path) ──
  // A report-type makesafe job has no scope_json pricing — a $0 or empty invoice
  // would be silently sent to the builder. Block it here so the generic create_invoice
  // action has the same safety guard as completeAndInvoice + createMakesafeDraftInvoice.
  // Normal (non-makesafe) manual invoicing is unaffected.
  const jIdForGate = job_id || jobId
  if (jIdForGate) {
    const { data: msGateDetail } = await client.from('makesafe_job_details')
      .select('report_type').eq('job_id', jIdForGate).maybeSingle()
    if (msGateDetail?.report_type) {
      const gateTotal = (items as any[]).reduce(
        (sum: number, li: any) => sum + (li.unit_price ?? 0) * (li.quantity ?? 1),
        0,
      )
      if (gateTotal <= 0) {
        throw new Error('report job needs a charge amount before invoicing: supply line_items with the trade/WO charge')
      }
    }
  }

  // ── M-G FIX 1 — REPORT-IN GATE (make-safe premature-invoice kill) ──
  // createInvoice is the reachable choke point (the skill posts create_invoice;
  // completeAndInvoice / createGeneralInvoice / createUnifiedInvoice / createDepositInvoice
  // all delegate here). The portal guard's own invoice chokepoint lives inside
  // createMakesafeDraftInvoice (:22912) which the skill never reaches, so BOTH make-safe
  // types must be gated here:
  //   • report-type card  → a current-cycle portal-locked verification (item-14 twin,
  //     closes the MLB-26183 / MLB-25625 premature-roof-draft class on the skill path).
  //   • physical make-safe → OUR trade report filed in our system this cycle.
  // Both assertions no-op for non-make-safe jobs, so ordinary patio/fence invoicing is
  // untouched. Idempotent when reached via createMakesafeDraftInvoice (which re-checks portal).
  if (jIdForGate) {
    await assertMakesafePortalVerifiedForDraftInvoice(client, jIdForGate)
    await assertMakesafeReportInForInvoice(client, jIdForGate)
  }

  // Loop 1B-a-apply preflight gate. Block creation when required dimensions are
  // missing unless the caller passes bypass_preflight: true. Soft warnings do
  // NOT block. The override is logged to business_events so we have a trail
  // every time someone created an invoice with incomplete trace context.
  const preflight = await preflightInvoiceCreation(client, body)
  if (!preflight.ok && !body.bypass_preflight) {
    const err: any = new Error(
      'Invoice preflight failed: ' + preflight.missing_dimensions.join(', ') +
      '. Set the missing fields on the job, or re-call with bypass_preflight=true to override.'
    )
    err.code = 'PREFLIGHT_FAILED'
    err.missing_dimensions = preflight.missing_dimensions
    err.warnings = preflight.warnings
    throw err
  }
  if (!preflight.ok && body.bypass_preflight) {
    // Override taken — log so we have an audit trail.
    logBusinessEvent(client, {
      event_type: 'invoice.preflight_override',
      entity_type: 'job',
      entity_id: (job_id || jobId || 'unknown'),
      job_id: (job_id || jobId || undefined),
      payload: {
        missing_dimensions: preflight.missing_dimensions,
        warnings: preflight.warnings,
        reason: body.bypass_reason || null,
      },
      metadata: {
        operator: body.operator || null,
        source: 'createInvoice',
      },
    })
  }
  const traceCtx = preflight.context // null only if no job_id provided

  const { accessToken, tenantId } = await getToken(client)

  // Resolve Xero contact — find or create if no xero_contact_id provided
  let resolvedContactId = xero_contact_id
  if (!resolvedContactId && contact) {
    try {
      const jId = job_id || jobId

      // When billing a neighbour, use their email/phone, not the job's primary client.
      let contactEmail: string | undefined
      let contactPhone: string | undefined
      if (job_contact_id) {
        const { data: jcData } = await client.from('job_contacts')
          .select('client_email, client_phone')
          .eq('id', job_contact_id)
          .maybeSingle()
        contactEmail = jcData?.client_email || undefined
        contactPhone = jcData?.client_phone || undefined
      } else {
        const { data: jobData } = jId ? await client.from('jobs')
          .select('client_email, client_phone')
          .eq('id', jId)
          .maybeSingle() : { data: null }
        contactEmail = jobData?.client_email || undefined
        contactPhone = jobData?.client_phone || undefined
      }

      // 1. Search by EMAIL first (most reliable dedup — avoids name variation duplicates)
      let existing: any = null
      if (contactEmail) {
        const emailResult = await xeroGet('/Contacts', accessToken, tenantId, {
          where: `EmailAddress=="${contactEmail.replace(/"/g, '')}"`,
        })
        existing = emailResult?.Contacts?.[0]
        if (existing) console.log(`[ops-api] Xero contact matched by email: ${contactEmail} → ${existing.ContactID}`)
      }

      // 2. Fall back to NAME search if email didn't match
      if (!existing) {
        const nameResult = await xeroGet('/Contacts', accessToken, tenantId, {
          where: `Name=="${contact.replace(/"/g, '')}"`,
        })
        existing = nameResult?.Contacts?.[0]
      }

      if (existing) {
        resolvedContactId = existing.ContactID
      } else {
        // 3. Create new contact in Xero
        const newContact = await xeroPost('/Contacts', accessToken, tenantId, {
          Contacts: [{ Name: contact, EmailAddress: contactEmail || undefined, Phones: contactPhone ? [{ PhoneType: 'DEFAULT', PhoneNumber: contactPhone }] : undefined }],
        }, 'PUT', `contact-${contact.replace(/\s/g, '-')}`)
        resolvedContactId = newContact?.Contacts?.[0]?.ContactID
      }
      // Backfill xero_contact_id so future invoices don't need lookup
      if (resolvedContactId) {
        if (job_contact_id) {
          // Neighbour: write to job_contacts, not jobs
          await client.from('job_contacts').update({ xero_contact_id: resolvedContactId }).eq('id', job_contact_id)
        } else if (jId) {
          await client.from('jobs').update({ xero_contact_id: resolvedContactId }).eq('id', jId)
        }
      }
    } catch (e) {
      console.log('[ops-api] Xero contact lookup/create failed, falling back to Name:', (e as Error).message)
      // Fall through — will use Name-based contact below
    }
  }

  const ref = reference || ''
  // Validate tracking category exists in Xero before including it
  let tracking: any[] = []
  try {
    const trackingCats = await xeroGet('/TrackingCategories', accessToken, tenantId)
    const divisionCat = (trackingCats?.TrackingCategories || []).find((tc: any) => tc.Name === 'Business Unit' && tc.Status === 'ACTIVE')
    if (divisionCat) {
      const optionName = trackingCategoryForJob(ref)
      const validOption = (divisionCat.Options || []).find((o: any) => o.Name === optionName && o.Status === 'ACTIVE')
      if (validOption) tracking = [{ Name: 'Business Unit', Option: optionName }]
    }
  } catch { /* skip tracking if lookup fails */ }

  const xeroLineItems = items.map((li: any) => ({
    Description: li.description || '',
    Quantity: li.quantity || 1,
    UnitAmount: li.unit_price || li.unitPrice || 0,
    AccountCode: li.account_code || '200',
    TaxType: 'OUTPUT',
    ...(tracking.length > 0 ? { Tracking: tracking } : {}),
  }))

  // Use requested status — DRAFT (for bookkeeper review) or AUTHORISED (approve & send)
  const invoiceStatus = xero_status || 'DRAFT'

  // Loop 1B-a-apply: Terms text comes from the preflight context (which
  // already resolved override > jobs.payment_terms > pricing_json.payment_terms
  // > division-default). DueDate prefers preflight context too so the body
  // override flows through one resolution path.
  const xeroTermsText = traceCtx?.payment_terms_text || ''
  const xeroDueDate = traceCtx?.due_date
    || due_date || dueDate
    || new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10)

  const invoice = {
    Invoices: [{
      Type: 'ACCREC',
      Contact: resolvedContactId
        ? { ContactID: resolvedContactId }
        : { Name: contact },
      LineAmountTypes: 'Exclusive',
      LineItems: xeroLineItems,
      Reference: reference || '',
      DueDate: xeroDueDate,
      Status: invoiceStatus,
      ...(xeroTermsText ? { Terms: xeroTermsText } : {}),
    }],
  }

  // Idempotency key. Default: job_id + reference + minute (prevents duplicate on
  // retry/double-click within a minute). The make-safe DRAFT path (and ONLY that
  // internal path) threads an explicit stable key via the INTERNAL-ONLY property
  // `makesafe_idempotency_key`, so the key is STABLE across calls regardless of
  // time (Xero collapses identical keys to one invoice for 12h). We deliberately
  // do NOT read a generic `body.idempotency_key`: the public `create_invoice`
  // route forwards the request body verbatim, so honouring an arbitrary
  // caller-supplied key would let an external caller force key collisions and get
  // back the WRONG existing invoice. `makesafe_idempotency_key` is set only by
  // createMakesafeDraftInvoice (server-side), never by the public route's body.
  // (Adversarial review finding 4.)
  const jIdForKey = job_id || jobId || 'nojob'
  const invIdempotencyKey = body.makesafe_idempotency_key
    ? String(body.makesafe_idempotency_key)
    : `inv-${jIdForKey}-${reference || 'noref'}-${new Date().toISOString().slice(0, 16)}`
  const result = await xeroPost('/Invoices', accessToken, tenantId, invoice, 'PUT', invIdempotencyKey)
  const xeroInv = result?.Invoices?.[0]
  const xeroInvId = xeroInv?.InvoiceID
  const invNumber = xeroInv?.InvoiceNumber

  // If approve & send, email the invoice to the client via Xero
  if (send_email && xeroInvId) {
    try {
      await xeroPost(`/Invoices/${xeroInvId}/Email`, accessToken, tenantId, {}, 'POST')
    } catch (emailErr: any) {
      console.error('Failed to email invoice:', emailErr.message)
      // Non-blocking — invoice was still created
    }
  }

  const jId = job_id || jobId

  // Immediately record in xero_invoices so future queries see it
  // (don't wait for xero-sync which runs every 2 hours)
  const invTotal = xeroInv?.Total ?? items.reduce((s: number, li: any) => s + ((li.quantity || 1) * (li.unit_price || li.unitPrice || 0)), 0) * 1.1
  const invSubTotal = xeroInv?.SubTotal ?? items.reduce((s: number, li: any) => s + ((li.quantity || 1) * (li.unit_price || li.unitPrice || 0)), 0)
  if (xeroInvId) {
    try {
      // Loop 1B-a-apply: stamp the eleven traceability columns added by
      // migration 20260506101511_loop_1b_a_traceability. Eight columns come
      // from the strategy doc's W2 traceability set; two close H1's silent
      // drop (job_contact_id, reference_suffix); one surfaces the Xero
      // Project manual-fill queue per the 2026-04-09 ADR.
      const referenceSuffix = computeReferenceSuffix(traceCtx?.job_number || '', reference || '')
      await client.from('xero_invoices').upsert({
        org_id: DEFAULT_ORG_ID,
        xero_invoice_id: xeroInvId,
        xero_contact_id: xero_contact_id || xeroInv?.Contact?.ContactID || null,
        contact_name: contact || xeroInv?.Contact?.Name || null,
        invoice_number: invNumber,
        invoice_type: 'ACCREC',
        status: xeroInv?.Status || invoiceStatus,
        reference: reference || '',
        sub_total: invSubTotal,
        total_tax: (xeroInv?.TotalTax ?? invTotal - invSubTotal),
        total: invTotal,
        amount_due: invTotal,
        amount_paid: 0,
        invoice_date: new Date().toISOString().slice(0, 10),
        due_date: xeroDueDate,
        job_id: jId || null,
        run_label: body.run_label || null,
        // Loop 1B-a-apply traceability columns (NULL when no job context).
        job_number:                 traceCtx?.job_number || null,
        customer_name:              traceCtx?.customer_name || contact || null,
        suburb:                     traceCtx?.suburb || null,
        division:                   traceCtx?.division || null,
        account_code:               traceCtx?.account_code || null,
        tracking_option:            traceCtx?.tracking_option || null,
        xero_project_manual_status: traceCtx?.xero_project_manual_status || 'needs_manual_fill',
        quote_revision_id:          traceCtx?.quote_revision_id || null,
        scope_revision_id:          traceCtx?.scope_revision_id || null,
        job_contact_id:             job_contact_id || null,
        reference_suffix:           referenceSuffix,
        synced_at: new Date().toISOString(),
      }, { onConflict: 'org_id,xero_invoice_id' })
    } catch (upsertErr: any) {
      console.error('Non-blocking: failed to cache invoice locally:', upsertErr.message)
    }
  }

  if (jId) {
    await client.from('job_events').insert({
      job_id: jId,
      event_type: 'invoice_created',
      detail_json: { xero_invoice_id: xeroInvId, invoice_number: invNumber, status: xeroInv?.Status || invoiceStatus, total: invTotal, emailed: !!send_email },
    })
    // Update job status to invoiced if complete
    await client.from('jobs')
      .update({ status: 'invoiced' })
      .eq('id', jId)
      .eq('status', 'complete')
    // ── M3d U2b: invoicing a job finishes it — close its still-open crew
    // assignments. Also covers complete_and_invoice, which reaches its terminal
    // 'invoiced' state through this createInvoice call. Non-blocking.
    await closeOpenAssignmentsForJob(client, jId, 'complete')
  }

  // Return the status Xero actually assigned (xeroInv.Status), not just what we
  // requested. Callers that gate client-facing payment links (sendAcceptanceInvoice)
  // must verify the invoice really came back AUTHORISED before emailing a Pay Now.
  return { success: true, xero_invoice_id: xeroInvId, invoice_number: invNumber, total: invTotal, status: xeroInv?.Status || invoiceStatus }
}

// ── Sync Job Invoices — pull invoices from Xero for a specific job and link them ──
function _makesafeTrustedInvoiceRefToken(value: any): string | null {
  const raw = String(value ?? '').trim()
  if (!raw) return null
  const norm = _makesafeNormRef(raw)
  // Ref tokens must be structured job/builder refs, not loose numerics,
  // addresses, names, or tiny fragments. This keeps Xero Reference.Contains
  // from broad-linking unrelated invoices on common substrings.
  if (norm.length < 5) return null
  if (!/[a-z]/i.test(norm) || !/\d/.test(norm)) return null
  if (!/^[a-z]{2,8}\d{3,}/i.test(norm)) return null
  return raw
}
export const _makesafeTrustedInvoiceRefTokenForTest = _makesafeTrustedInvoiceRefToken

async function syncJobInvoices(client: any, body: any) {
  const jId = body.job_id || body.jobId
  if (!jId) throw new Error('job_id required')

  const { data: job, error: jobErr } = await client
    .from('jobs')
    .select('id, job_number, client_name, xero_contact_id, metadata')
    .eq('id', jId)
    .single()
  if (jobErr || !job) throw new Error('Job not found')

  const { data: msDetail } = await client.from('makesafe_job_details')
    .select('external_ref')
    .eq('job_id', jId)
    .maybeSingle()

  const refTokens = Array.from(new Set([
    job.job_number,
    msDetail?.external_ref,
    job.metadata?.external_ref,
    body.external_ref || body.externalRef,
  ].map(_makesafeTrustedInvoiceRefToken).filter(Boolean) as string[]))

  if (refTokens.length === 0) {
    return { success: true, synced: 0, job_number: job.job_number, invoices: [], note: 'no job/reference token available; skipped Xero sync to avoid broad contact linking' }
  }

  const { accessToken, tenantId } = await getToken(client)
  let synced = 0
  const syncedInvoices: any[] = []
  const seenInvoiceIds = new Set<string>()
  const tokenKeys = refTokens.map((t) => _makesafeNormRef(t)).filter(Boolean)
  const invoiceMatchesThisJob = (inv: any): boolean => {
    const ref = _makesafeNormRef(inv?.Reference || '')
    if (!ref) return false
    return tokenKeys.some((tok) => tok && (ref === tok || ref.includes(tok)))
  }
  const upsertInvoice = async (inv: any, matchMethod: string) => {
    if (!inv?.InvoiceID || seenInvoiceIds.has(inv.InvoiceID)) return
    if (!invoiceMatchesThisJob(inv)) return
    seenInvoiceIds.add(inv.InvoiceID)
    const record: any = {
      org_id: DEFAULT_ORG_ID,
      xero_invoice_id: inv.InvoiceID,
      xero_contact_id: inv.Contact?.ContactID || null,
      contact_name: canonicalMakesafeInvoiceContactName(inv.Reference || refTokens[0], inv.Contact?.Name || null),
      invoice_number: inv.InvoiceNumber || null,
      invoice_type: inv.Type,
      status: inv.Status,
      reference: inv.Reference || null,
      sub_total: inv.SubTotal || 0,
      total_tax: inv.TotalTax || 0,
      total: inv.Total || 0,
      amount_due: inv.AmountDue || 0,
      amount_paid: inv.AmountPaid || 0,
      invoice_date: inv.DateString || null,
      due_date: inv.DueDateString || null,
      line_items: inv.LineItems || [],
      raw_json: inv,
      job_id: job.id,
      synced_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    }
    const { error } = await client.from('xero_invoices').upsert(record, {
      onConflict: 'org_id,xero_invoice_id',
    })
    if (!error) {
      synced++
      syncedInvoices.push({ invoice_number: inv.InvoiceNumber, total: inv.Total, status: inv.Status, reference: inv.Reference || null, match_method: matchMethod })
    }
  }

  // Money-safety: never sync by broad Xero contact. MLB/Major Loss Builders can
  // have many active invoices on the same contact; linking all of them to one
  // MakeSafe job makes the send pack ambiguous. Search only by job/external refs.
  for (const token of refTokens) {
    const safeToken = token.replace(/"/g, '')
    try {
      const result = await xeroGet('/Invoices', accessToken, tenantId, {
        where: `Reference.Contains("${safeToken}") AND Type=="ACCREC"`,
        Statuses: 'DRAFT,SUBMITTED,AUTHORISED,PAID',
      })
      const invoices = result?.Invoices || []
      for (const inv of invoices) await upsertInvoice(inv, token === job.job_number ? 'job_number_reference' : 'external_reference')
    } catch (e: any) {
      console.log('[sync_job_invoices] Xero reference search failed:', safeToken, e.message)
    }
  }

  return { success: true, synced, job_number: job.job_number, reference_tokens: refTokens, invoices: syncedInvoices }
}

// ── Update Invoice — edit line items on an existing Xero invoice ──
async function updateInvoice(client: any, body: any, adminClientOverride?: any) {
  const { xero_invoice_id, line_items, due_date, resend_email } = body
  if (!xero_invoice_id) throw new ApiError('xero_invoice_id required', 400)
  if (!line_items || !Array.isArray(line_items) || line_items.length === 0) {
    throw new ApiError('line_items required (array of {description, quantity, unit_price})', 400)
  }
  // adminClientOverride is a test-only seam; production callers omit it and get
  // the service-role client (required so the report-job gate reads xero_invoices /
  // makesafe_job_details past RLS — see ea2f778).
  const adminClient = adminClientOverride ?? createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)

  // ── REPORT-JOB $0 GATE ──
  // Mirror the create_invoice / complete_and_invoice guards: a report-type make-safe
  // job must always carry a non-zero charge. An edit that zeroes out the total is
  // rejected here before it reaches Xero. Normal (non-report) jobs are unaffected.
  {
    const { data: invForGate } = await adminClient.from('xero_invoices')
      .select('job_id').eq('xero_invoice_id', xero_invoice_id).maybeSingle()
    const jIdForGate = invForGate?.job_id
    if (jIdForGate) {
      const { data: msGateDetail } = await adminClient.from('makesafe_job_details')
        .select('report_type').eq('job_id', jIdForGate).maybeSingle()
      if (msGateDetail?.report_type) {
        const lineTotal = (line_items as Array<{ quantity?: number; unit_price?: number }>)
          .reduce((sum, li) => sum + ((li.quantity ?? 1) * (li.unit_price ?? 0)), 0)
        if (lineTotal <= 0) {
          throw new ApiError(
            'report job needs a charge amount before invoicing: line items sum to $0 or less',
            400,
          )
        }
      }
    }
  }

  const { accessToken, tenantId } = await getToken(client)

  // H2 (Loop 1B-a): re-derive Tracking from the invoice's reference so edits
  // do not strip the division tag. Xero POST /Invoices/{id} REPLACES the line
  // items array — without an explicit Tracking entry on each line, every edit
  // silently drops the Business Unit option. Pattern mirrors createInvoice's
  // existing fail-soft Tracking lookup (validate against /TrackingCategories,
  // skip if Xero returns nothing or throws).
  let updateTracking: any[] = []
  try {
    const { data: invForTracking } = await adminClient.from('xero_invoices')
      .select('reference')
      .eq('xero_invoice_id', xero_invoice_id)
      .maybeSingle()
    const updateRef = invForTracking?.reference || ''
    if (updateRef) {
      const trackingCats = await xeroGet('/TrackingCategories', accessToken, tenantId)
      const divisionCat = (trackingCats?.TrackingCategories || []).find(
        (tc: any) => tc.Name === 'Business Unit' && tc.Status === 'ACTIVE'
      )
      if (divisionCat) {
        const optionName = trackingCategoryForJob(updateRef)
        const validOption = (divisionCat.Options || []).find(
          (o: any) => o.Name === optionName && o.Status === 'ACTIVE'
        )
        if (validOption) updateTracking = [{ Name: 'Business Unit', Option: optionName }]
      }
    }
  } catch { /* skip Tracking if lookup fails — same fail-soft as createInvoice */ }

  const payload: any = {
    InvoiceID: xero_invoice_id,
    LineItems: line_items.map((li: any) => ({
      Description: li.description || '',
      Quantity: li.quantity || 1,
      UnitAmount: li.unit_price || 0,
      AccountCode: li.account_code || '200',
      TaxType: 'OUTPUT',
      ...(updateTracking.length > 0 ? { Tracking: updateTracking } : {}),
    })),
  }
  if (due_date) payload.DueDate = due_date

  // Xero uses POST for updates
  const result = await xeroPost(`/Invoices/${xero_invoice_id}`, accessToken, tenantId, { Invoices: [payload] }, 'POST')
  const xeroInvoice = result?.Invoices?.[0]
  if (!xeroInvoice) throw new Error('Xero did not return an updated invoice')

  const lineSubtotal = (line_items as Array<{ quantity?: number; unit_price?: number }>).reduce((sum, li) => {
    const qty = Number(li.quantity ?? 1)
    const unit = Number(li.unit_price ?? 0)
    return sum + (Number.isFinite(qty) && Number.isFinite(unit) ? qty * unit : 0)
  }, 0)
  const money = (value: any, fallback: number) => {
    const n = Number(value)
    return Number.isFinite(n) ? n : Math.round(fallback * 100) / 100
  }
  const cacheSubtotal = money(xeroInvoice.SubTotal, lineSubtotal)
  const cacheTax = money(xeroInvoice.TotalTax, cacheSubtotal * 0.1)
  const cacheTotal = money(xeroInvoice.Total, cacheSubtotal + cacheTax)
  const cacheAmountDue = money(xeroInvoice.AmountDue, cacheTotal - money(xeroInvoice.AmountPaid, 0))

  // Update local cache with service-role privileges. API-key/JWT callers can edit
  // Xero, but RLS may block xero_invoices writes; failing silently leaves the
  // board showing a stale amount even though Xero and the attached PDF are fixed.
  const { error: cacheErr } = await adminClient.from('xero_invoices').update({
    line_items: xeroInvoice.LineItems || payload.LineItems,
    sub_total: cacheSubtotal,
    total_tax: cacheTax,
    total: cacheTotal,
    amount_due: cacheAmountDue,
    due_date: xeroInvoice.DueDateString || xeroInvoice.DueDate || due_date || null,
    raw_json: xeroInvoice,
    updated_at: new Date().toISOString(),
  }).eq('xero_invoice_id', xero_invoice_id)
  if (cacheErr) throw new ApiError('update_invoice cache update failed: ' + cacheErr.message, 500)

  // Resend email if requested
  if (resend_email) {
    try {
      await xeroPost(`/Invoices/${xero_invoice_id}/Email`, accessToken, tenantId, {}, 'POST')
    } catch (emailErr: any) {
      console.error('[update_invoice] Failed to resend email:', emailErr.message)
    }
  }

  // Log job event
  const { data: invRecord } = await adminClient.from('xero_invoices')
    .select('job_id, invoice_number')
    .eq('xero_invoice_id', xero_invoice_id)
    .maybeSingle()

  if (invRecord?.job_id) {
    await adminClient.from('job_events').insert({
      job_id: invRecord.job_id,
      event_type: 'invoice_updated',
      detail_json: {
        xero_invoice_id,
        invoice_number: xeroInvoice.InvoiceNumber || invRecord.invoice_number,
        total: xeroInvoice.Total,
        resent: !!resend_email,
      },
    })
  }

  return {
    success: true,
    invoice_number: xeroInvoice.InvoiceNumber || invRecord?.invoice_number,
    total: xeroInvoice.Total,
  }
}

// ── Mark Invoice Paid — local-only override, no Xero payment created ──
async function markInvoicePaid(client: any, body: any) {
  const { xero_invoice_id, payment_date, amount } = body
  if (!xero_invoice_id) throw new ApiError('xero_invoice_id required', 400)
  if (!payment_date) throw new ApiError('payment_date required', 400)
  if (amount === undefined || amount === null) throw new ApiError('amount required', 400)

  // Get invoice details before updating
  const { data: inv } = await client.from('xero_invoices')
    .select('job_id, invoice_number, total')
    .eq('xero_invoice_id', xero_invoice_id)
    .maybeSingle()

  if (!inv) throw new ApiError('Invoice not found in local records', 404)

  // Update local status to PAID
  await client.from('xero_invoices').update({
    status: 'PAID',
    amount_paid: amount,
    amount_due: 0,
    fully_paid_on: payment_date,
    updated_at: new Date().toISOString(),
  }).eq('xero_invoice_id', xero_invoice_id)

  // Log business event
  await client.from('business_events').insert({
    event_type: 'invoice.manually_marked_paid',
    source: 'ops-api/mark_invoice_paid',
    entity_type: 'invoice',
    entity_id: xero_invoice_id,
    payload: { invoice_number: inv.invoice_number, amount, payment_date, manual: true },
  })

  // Create AI annotation on the job
  if (inv.job_id) {
    await client.from('ai_annotations').upsert({
      org_id: DEFAULT_ORG_ID,
      job_id: inv.job_id,
      annotation_type: 'manual_payment',
      severity: 'info',
      title: `${inv.invoice_number} marked as paid manually`,
      body: `$${Number(amount).toLocaleString('en-AU', { minimumFractionDigits: 2 })} marked paid on ${payment_date}. Xero sync will confirm.`,
      ui_location: 'job_money',
      source: 'ops-api/mark_invoice_paid',
      source_ref: `manual_paid_${xero_invoice_id}`,
      priority: 50,
    }, { onConflict: 'source_ref' })
  }

  return { success: true }
}

async function syncSuppliers(client: any) {
  const { accessToken, tenantId } = await getToken(client)

  const result = await xeroGet('/Contacts', accessToken, tenantId, {
    where: 'IsSupplier==true',
    includeArchived: 'false',
  })

  const contacts = result?.Contacts || []
  let upserted = 0

  for (const c of contacts) {
    const { error } = await client.from('suppliers').upsert({
      org_id: DEFAULT_ORG_ID,
      xero_contact_id: c.ContactID,
      name: c.Name || '',
      email: c.EmailAddress || null,
      phone: c.Phones?.find((p: any) => p.PhoneType === 'DEFAULT')?.PhoneNumber || null,
      is_active: c.ContactStatus === 'ACTIVE',
      synced_at: new Date().toISOString(),
    }, { onConflict: 'org_id,xero_contact_id' })

    if (!error) upserted++
  }

  return { success: true, total_contacts: contacts.length, upserted }
}


// ════════════════════════════════════════════════════════════
// AUTOMATION — Complete+Invoice Cascade, Morning Brief,
//              Scope-to-PO Extraction, Assignment Cascade
// ════════════════════════════════════════════════════════════

// Advance the canonical make-safe substatus to 'complete' once an invoice has
// been created. No-op for non-make-safe jobs. Never throws: a substatus write
// failure must not break the (already-completed) invoice flow. Exported for
// tests as `_advanceMakesafeSubstatusOnInvoice`.
async function advanceMakesafeSubstatusOnInvoice(client: any, job: any, jId: string): Promise<boolean> {
  if (String(job?.type || '').toLowerCase() !== 'makesafe') return false
  try {
    await updateMakesafeSubstatus(client, { job_id: jId, substatus: 'complete' })
    return true
  } catch (e) {
    console.log('[completeAndInvoice] makesafe substatus advance failed (non-blocking):', (e as Error).message)
    return false
  }
}
export const _advanceMakesafeSubstatusOnInvoice = advanceMakesafeSubstatusOnInvoice

// Feature 4: Complete a job AND create a Xero invoice in one step.
// 1. Sets job status to "complete" + completed_at
// 2. Reads pricing_json for line items
// 3. Finds/creates Xero contact
// 4. Creates Xero DRAFT invoice with line items + SW reference
// 5. Sets job status to "invoiced"
async function completeAndInvoice(client: any, body: any) {
  const jId = body.job_id || body.jobId
  if (!jId) throw new Error('job_id required')

  // Fetch the job
  const { data: job, error: jobErr } = await client
    .from('jobs')
    .select('id, status, client_name, client_email, job_number, xero_contact_id, pricing_json, scope_json, type, site_address, site_suburb')
    .eq('id', jId)
    .single()
  if (jobErr || !job) throw new Error('Job not found')

  if (!['in_progress', 'complete', 'scheduled', 'processing'].includes(job.status)) {
    throw new Error(`Cannot complete+invoice a job with status "${job.status}". Must be in_progress, processing, scheduled, or complete.`)
  }

  // Use line_items_override if provided (from invoice creation modal),
  // otherwise extract from pricing_json (with fallback to scope_json._pricing_json for fencing jobs)
  let lineItems: any[] = body.line_items_override || []
  // Normalise override items: accept amount_inc_gst as convenience field
  if (lineItems.length > 0) {
    lineItems = lineItems.map((li: any, i: number) => {
      // If caller passed amount_inc_gst (convenience), convert to ex-GST unit_price
      if (li.amount_inc_gst != null && li.unit_price == null) {
        li.unit_price = Math.round((li.amount_inc_gst / 1.1) * 100) / 100
      }
      if (!li.quantity) li.quantity = 1
      if (!li.unit_price || isNaN(li.unit_price)) {
        throw new Error(`line_items_override[${i}] missing unit_price or amount_inc_gst`)
      }
      if (!li.account_code) li.account_code = accountCodeForJob(job.type)
      return li
    })
  }
  if (lineItems.length === 0) {
    // Primary: top-level pricing_json column
    let pricing: any = null
    if (job.pricing_json && Object.keys(job.pricing_json).length > 0) {
      pricing = typeof job.pricing_json === 'string' ? JSON.parse(job.pricing_json) : job.pricing_json
    }
    // Fallback: scope_json.job._pricing_json (fencing scoping tool stores pricing here, not in pricing_json)
    // When using this fallback, always use totalExGST as a single line item — Xero adds 10% GST on top,
    // so we pass the ex-GST amount to arrive at the correct totalIncGST. Individual scope line items
    // are for cost tracking and may not sum exactly to the quoted total due to rounding.
    if (!pricing && job.scope_json) {
      const scope = typeof job.scope_json === 'string' ? JSON.parse(job.scope_json) : job.scope_json
      const jobData = scope.job || scope
      if (jobData._pricing_json) {
        const scopePricing = typeof jobData._pricing_json === 'string' ? JSON.parse(jobData._pricing_json) : jobData._pricing_json
        const exactTotalExGST = scopePricing.totalExGST || scopePricing.subtotal || (scopePricing.totalIncGST ? scopePricing.totalIncGST / 1.1 : 0) || 0
        if (exactTotalExGST > 0) {
          lineItems = [{
            description: buildRichDescription(job, `${trackingCategoryForJob(job.job_number) || 'Construction'} works`),
            quantity: 1,
            unit_price: exactTotalExGST,
            account_code: accountCodeForJob(job.type),
          }]
        }
      }
    }
    if (lineItems.length === 0 && pricing) {
      const itemArray = Array.isArray(pricing.items) ? pricing.items
        : Array.isArray(pricing.line_items) ? pricing.line_items
        : null
      if (itemArray) {
        lineItems = itemArray.map((li: any) => ({
          description: li.description || li.name || 'Line item',
          quantity: li.quantity || li.qty || 1,
          unit_price: li.unit_price || li.unitPrice || li.price || li.amount || 0,
          account_code: li.account_code || '200',
        }))
      } else if (pricing.totalExGST || pricing.totalIncGST || pricing.total || pricing.amount) {
        // GST owner = backend. Xero invoices are LineAmountTypes 'Exclusive' (createInvoice
        // adds 10% GST on top), and the balance maths below also does `total * 1.1`. So the
        // single-line fallback MUST be ex-GST. pricing.totalIncGST / .total / .amount are
        // inc-GST snapshots (e.g. GHL-sourced jobs store { totalIncGST }); divide once here
        // or Xero double-applies GST. Prefer the explicit ex-GST figure when the tool stored it.
        const fallbackExGST = pricing.totalExGST != null
          ? pricing.totalExGST
          : Math.round(((pricing.totalIncGST || pricing.total || pricing.amount || 0) / 1.1) * 100) / 100
        lineItems = [{
          description: buildRichDescription(job, `${trackingCategoryForJob(job.job_number) || 'Construction'} works`),
          quantity: 1,
          unit_price: fallbackExGST,
          account_code: accountCodeForJob(job.type),
        }]
      }
    }
  }

  if (lineItems.length === 0) {
    throw new Error('No pricing data found on this job. Add pricing_json before invoicing.')
  }

  const total = lineItems.reduce((s: number, li: any) => s + ((li.quantity || 0) * (li.unit_price || 0)), 0)
  if (!total || isNaN(total) || total <= 0) {
    throw new Error(`Calculated total is $${total} — line items have invalid or zero pricing. Check unit_price values.`)
  }

  // ── Deposit awareness: check for existing invoices on this job ──
  // Query xero_invoices (includes locally-cached invoices from createInvoice)
  const { data: existingInvoices } = await client.from('xero_invoices')
    .select('xero_invoice_id, invoice_number, total, status')
    .eq('job_id', jId)
    .eq('invoice_type', 'ACCREC')
    .not('status', 'in', '("VOIDED","DELETED")')

  const alreadyInvoiced = (existingInvoices || []).reduce(
    (sum: number, inv: any) => sum + (parseFloat(inv.total) || 0), 0
  )

  // Calculate balance remaining (amounts are inc GST)
  const totalIncGst = total * 1.1
  const balance = totalIncGst - alreadyInvoiced

  if (alreadyInvoiced > 0) {
    console.log(`[completeAndInvoice] Job ${jId}: total=${totalIncGst}, already_invoiced=${alreadyInvoiced}, balance=${balance}`)
  }

  if (balance <= 0) {
    throw new Error(
      `Job already fully invoiced. Total: $${totalIncGst.toFixed(2)}, ` +
      `Already invoiced: $${alreadyInvoiced.toFixed(2)}. ` +
      `No balance remaining. Check existing invoices: ${(existingInvoices || []).map((i: any) => i.invoice_number).join(', ')}`
    )
  }

  // ── REPORT JOB MONEY GATE ──
  // A report-type job has no scope_json/pricing_json. If no line_items_override
  // was supplied, lineItems is empty -> would silently create a $0 Xero draft.
  // Block this hard: the caller must supply explicit line_items_override sourced
  // from the trade's submitted charge / WO billing amount.
  if (job.type === 'makesafe') {
    const { data: msDetail } = await client.from('makesafe_job_details')
      .select('report_type').eq('job_id', jId).maybeSingle()
    if (msDetail?.report_type) {
      if (lineItems.length === 0) {
        throw new Error('report job needs a charge amount before invoicing: supply line_items_override with the trade/WO charge')
      }
      const totalExGst = lineItems.reduce((sum: number, li: any) => sum + (li.unit_price ?? 0) * (li.quantity ?? 1), 0)
      if (totalExGst <= 0) {
        throw new Error('report job needs a charge amount before invoicing: line items sum to $0 or less')
      }
    }
  }

  // If deposits exist, adjust line items to invoice only the balance
  let finalLineItems = lineItems
  if (alreadyInvoiced > 0) {
    // Create a single "balance" line item (ex GST since Xero adds GST)
    const balanceExGst = balance / 1.1
    const balanceLabel = `Balance after $${alreadyInvoiced.toLocaleString('en-AU', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} deposit`
    finalLineItems = [{
      description: buildRichDescription(job, balanceLabel),
      quantity: 1,
      unit_price: Math.round(balanceExGst * 100) / 100,
      account_code: accountCodeForJob(job.type),
    }]
  }

  // Step 1: Mark complete (if not already)
  if (job.status !== 'complete') {
    await client.from('jobs')
      .update({ status: 'complete', completed_at: new Date().toISOString() })
      .eq('id', jId)
    await client.from('job_events').insert({
      job_id: jId,
      event_type: 'status_changed',
      detail_json: { new_status: 'complete', via: 'complete_and_invoice' },
    })
  }

  // Step 2: Create Xero invoice (balance only if deposits exist)
  const reference = (job.job_number || '') + (alreadyInvoiced > 0 ? '-FINBAL' : '')
  const dueDate = body.due_date || undefined
  const invoiceResult = await createInvoice(client, {
    job_id: jId,
    xero_contact_id: job.xero_contact_id || undefined,
    contact_name: job.client_name,
    line_items: finalLineItems,
    reference,
    due_date: dueDate,
    xero_status: body.xero_status || 'DRAFT',
    send_email: body.send_email || false,
    bypass_preflight: body.bypass_preflight || false,
    bypass_reason: body.bypass_reason || undefined,
  })

  // Dual-write to business_events
  logBusinessEvent(client, {
    event_type: 'job.completed_and_invoiced',
    entity_type: 'job',
    entity_id: jId,
    job_id: job?.job_number || jId,
    correlation_id: jId,
    payload: {
      entity: { id: jId, name: job?.client_name || '' },
      changes: { status: { from: job?.status, to: 'invoiced' } },
      financial: { amount: balance || 0, currency: 'AUD' },
    },
  })

  // Log to jarvis_event_log (non-blocking, fire-and-forget)
  client.from('jarvis_event_log').insert({
    event_type: 'job_completed_and_invoiced', job_id: jId,
    channel: 'system', triggered_by: 'jarvis',
    message_content: `Job completed and invoice created`,
    metadata: {},
  }).then(() => {}).catch(() => {})

  // ── Stop the make-safe substatus drift at source ──
  // jobs.status flips to 'invoiced' inside createInvoice, but makesafe_job_details
  // .substatus was never advanced, leaving invoiced make-safes stuck at an early
  // substatus (73/75 jobs). For make-safe jobs only, advance the canonical
  // substatus to 'complete'. Guarded + non-throwing so a substatus write failure
  // never breaks the (already-completed) invoice flow.
  await advanceMakesafeSubstatusOnInvoice(client, job, jId)

  return {
    success: true,
    job_id: jId,
    total_job_value: totalIncGst,
    already_invoiced: alreadyInvoiced,
    balance_invoiced: balance,
    line_items: finalLineItems,
    invoice_number: invoiceResult.invoice_number,
    xero_invoice_id: invoiceResult.xero_invoice_id,
  }
}

// ── Quick Quote: Search GHL Contacts ──
// ── Xero: Get Revenue Accounts ──
let _xeroAccountsCache: any = null
let _xeroAccountsCacheTime = 0
async function getXeroAccounts(client: any) {
  // Cache for 5 minutes
  if (_xeroAccountsCache && Date.now() - _xeroAccountsCacheTime < 300000) return _xeroAccountsCache
  const { accessToken, tenantId } = await getToken(client)
  const data = await xeroGet('/Accounts', accessToken, tenantId, {
    where: 'Type=="REVENUE"&&Status=="ACTIVE"',
  })
  const accounts = (data.Accounts || []).map((a: any) => ({ code: a.Code, name: a.Name, type: a.Type }))
  _xeroAccountsCache = { accounts }
  _xeroAccountsCacheTime = Date.now()
  return { accounts }
}

// ── Xero: Search Contacts ──
async function searchXeroContacts(client: any, params: URLSearchParams) {
  const q = (params.get('q') || '').trim()
  if (!q || q.length < 2) return { contacts: [] }
  const { accessToken, tenantId } = await getToken(client)
  const data = await xeroGet('/Contacts', accessToken, tenantId, {
    where: `Name.Contains("${q.replace(/"/g, '')}")`,
  })
  const contacts = (data.Contacts || []).map((c: any) => ({
    id: c.ContactID, name: c.Name, email: c.EmailAddress || '', phone: c.Phones?.[0]?.PhoneNumber || '',
  }))
  return { contacts }
}

// ── Create General Invoice (rich descriptions for bookkeeper) ──
async function createGeneralInvoice(client: any, body: any) {
  const { job_id, account_code } = body
  if (!job_id) throw new Error('job_id required')

  const { data: job, error: jobErr } = await client.from('jobs')
    .select('id, job_number, client_name, client_email, site_address, site_suburb, pricing_json, xero_contact_id, ghl_contact_id')
    .eq('id', job_id).single()
  if (jobErr || !job) throw new Error('Job not found')

  const pricing = job.pricing_json || {}
  const lineItems = pricing.line_items || []
  if (lineItems.length === 0) throw new Error('No line items on this job')

  const address = [job.site_address, job.site_suburb].filter(Boolean).join(', ')
  const scopeDesc = pricing.job_description || pricing.description || lineItems.map((li: any) => li.description).join('; ')

  // Build rich Xero line items with bookkeeper-friendly descriptions
  const xeroLineItems = lineItems.map((li: any) => ({
    description: `${job.job_number || 'SWG'} - ${job.client_name || ''} - ${address} | ${li.description || ''}`,
    quantity: li.quantity || 1,
    unit_price: li.unit_price || li.sell_price || 0,
    account_code: account_code || '200',
  }))

  // Use existing createInvoice with enhanced parameters
  const invoiceResult = await createInvoice(client, {
    job_id,
    contact_name: job.client_name,
    xero_contact_id: job.xero_contact_id || undefined,
    line_items: xeroLineItems,
    reference: job.job_number || '',
    xero_status: 'DRAFT',
  })

  // Update job status
  await client.from('jobs').update({ status: 'invoiced' }).eq('id', job_id)

  // ── M3d U2b: general-invoice creation finishes the job — close its still-open
  // crew assignments. Non-blocking.
  await closeOpenAssignmentsForJob(client, job_id, 'complete')

  return {
    success: true,
    xero_invoice_id: invoiceResult.xero_invoice_id,
    invoice_number: invoiceResult.invoice_number,
    total: invoiceResult.total,
    job_number: job.job_number,
  }
}

// ── Create GHL Contact (with dedup) ──
async function createGHLContact(client: any, body: any) {
  const { firstName, lastName, email, phone, address, suburb, job_id } = body
  if (!firstName && !lastName) throw new Error('firstName or lastName required')
  if (!GHL_API_TOKEN) throw new Error('GHL API token not configured')

  const name = [firstName, lastName].filter(Boolean).join(' ')
  const headers = { 'Authorization': `Bearer ${GHL_API_TOKEN}`, 'Version': '2021-07-28', 'Content-Type': 'application/json' }

  // Dedup: search by email first, then phone
  let existingId: string | null = null
  if (email) {
    try {
      const dupRes = await fetch(`https://services.leadconnectorhq.com/contacts/search/duplicate`, {
        method: 'POST', headers,
        body: JSON.stringify({ locationId: GHL_LOCATION_ID, email }),
      })
      if (dupRes.ok) {
        const dupData = await dupRes.json()
        if (dupData.contact?.id) existingId = dupData.contact.id
      }
    } catch (e) { /* continue to phone check */ }
  }
  if (!existingId && phone) {
    try {
      const dupRes = await fetch(`https://services.leadconnectorhq.com/contacts/search/duplicate`, {
        method: 'POST', headers,
        body: JSON.stringify({ locationId: GHL_LOCATION_ID, number: phone }),
      })
      if (dupRes.ok) {
        const dupData = await dupRes.json()
        if (dupData.contact?.id) existingId = dupData.contact.id
      }
    } catch (e) { /* continue to create */ }
  }

  let contactId = existingId
  let contactExisted = !!existingId

  if (!contactId) {
    // Create new contact
    const createRes = await fetch(`https://services.leadconnectorhq.com/contacts/`, {
      method: 'POST', headers,
      body: JSON.stringify({
        locationId: GHL_LOCATION_ID,
        firstName: firstName || '',
        lastName: lastName || '',
        email: email || undefined,
        phone: phone || undefined,
        address1: address || undefined,
        city: suburb || undefined,
      }),
    })
    if (!createRes.ok) {
      const errText = await createRes.text()
      throw new Error('GHL contact creation failed (' + createRes.status + '): ' + errText.slice(0, 100))
    }
    const createData = await createRes.json()
    contactId = createData.contact?.id
    if (!contactId) throw new Error('GHL returned no contact ID')
  }

  // Link to job if provided
  if (job_id && contactId) {
    await client.from('jobs').update({ ghl_contact_id: contactId }).eq('id', job_id)
  }

  return { contact_id: contactId, name, email: email || '', phone: phone || '', existed: contactExisted, linked_job_id: job_id || null }
}

async function searchGHLContacts(client: any, params: URLSearchParams) {
  const q = (params.get('q') || '').trim()
  if (!q || q.length < 2) return { contacts: [] }

  if (!GHL_API_TOKEN) throw new Error('GHL API token not configured')

  // Search GHL contacts by name/email/phone using GET /contacts/ endpoint
  const searchParams = new URLSearchParams({
    locationId: GHL_LOCATION_ID,
    query: q,
    limit: '10',
  })
  const res = await fetch(`https://services.leadconnectorhq.com/contacts/?${searchParams.toString()}`, {
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${GHL_API_TOKEN}`,
      'Version': '2021-07-28',
    },
  })
  if (!res.ok) {
    const text = await res.text()
    console.error('[ops-api] GHL contact search failed:', res.status, text.slice(0, 500))
    console.error('[ops-api] GHL search request: locationId=' + GHL_LOCATION_ID + ', query=' + q + ', token=' + (GHL_API_TOKEN ? 'set(' + GHL_API_TOKEN.length + ' chars)' : 'MISSING'))
    throw new Error('GHL search failed (' + res.status + '): ' + text.slice(0, 100))
  }

  const data = await res.json()
  const contacts = (data.contacts || []).map((c: any) => ({
    id: c.id,
    name: [c.firstName, c.lastName].filter(Boolean).join(' '),
    firstName: c.firstName || '',
    lastName: c.lastName || '',
    email: c.email || '',
    phone: c.phone || '',
    address: c.address1 || '',
    city: c.city || '',
  }))

  // For each contact, check for existing jobs in Supabase
  const contactIds = contacts.map((c: any) => c.id).filter(Boolean)
  let existingJobs: any[] = []
  if (contactIds.length > 0) {
    const { data: jobs } = await client.from('jobs')
      .select('id, job_number, type, status, client_name, ghl_contact_id')
      .eq('org_id', DEFAULT_ORG_ID)
      .in('ghl_contact_id', contactIds)
      .order('created_at', { ascending: false })
      .limit(20)
    existingJobs = jobs || []
  }

  // Attach existing jobs to contacts
  contacts.forEach((c: any) => {
    c.existing_jobs = existingJobs.filter((j: any) => j.ghl_contact_id === c.id)
  })

  return { contacts }
}

// ── Quick Quote: Create Miscellaneous Job ──
async function createMiscJob(client: any, body: any) {
  const {
    client_name, client_first_name, client_last_name,
    client_phone, client_email,
    site_address, site_suburb,
    ghl_contact_id,
    job_type_label, description, reference,
    line_items, payment_terms, valid_days,
    client_notes, internal_notes,
    status: reqStatus,
  } = body

  const name = client_name || [client_first_name, client_last_name].filter(Boolean).join(' ')
  if (!name) throw new Error('Client name required')
  if (!line_items || line_items.length === 0) throw new Error('At least one line item required')

  // Cap 0 release-truth: a Quick Quote is created at status='draft' regardless of what the
  // caller asked for. Promotion to 'quoted' only happens when sendQuickQuoteEmail successfully
  // delivers via Resend (mirrors the /send-quote/send and /send-quote/send-runs contract).
  // Pre-patch behaviour honoured caller-supplied status='quoted' here, which let an operator
  // create a row that claimed a quote was sent without anyone ever sending one. Logged when
  // a caller still tries the old shape so we have observability of frontends that need updating.
  if (reqStatus && reqStatus !== 'draft') {
    console.log('[ops-api] createMiscJob ignoring caller-supplied status; forced to draft', JSON.stringify({
      attempted_status: reqStatus,
      reason: 'cap0-release-truth',
    }))
  }

  // Calculate totals
  const totalExGST = line_items.reduce((sum: number, li: any) => sum + (Number(li.total) || 0), 0)
  const gst = Math.round(totalExGST * 0.1 * 100) / 100
  const totalIncGST = Math.round((totalExGST + gst) * 100) / 100

  // Build pricing_json
  const pricing_json = {
    source: 'quick_quote',
    version: '1.0',
    totalExGST,
    totalIncGST,
    gst,
    job_description: description || '',
    job_type_label: job_type_label || 'Miscellaneous',
    payment_terms: payment_terms || '50% deposit + 50% on completion',
    valid_days: valid_days || 30,
    client_notes: client_notes || '',
    internal_notes: internal_notes || '',
    reference: reference || '',
    line_items: line_items.map((li: any) => ({
      description: li.description || '',
      quantity: Number(li.quantity) || 1,
      unit: li.unit || 'ea',
      unit_price: Number(li.unit_price) || 0,
      cost_price: Number(li.cost_price) || 0,
      total: Number(li.total) || 0,
    })),
  }

  // Always 'draft' at creation per Cap 0 release-truth contract (see top of function).
  const finalStatus = 'draft'

  // Generate job number — support 'general' type for SWG- prefix
  const jobType = body.job_type || 'general'
  let jobNumber: string | null = null
  try {
    const { data: jnData } = await client.rpc('next_job_number', { job_type: jobType })
    jobNumber = jnData
  } catch (e) {
    console.error('[ops-api] next_job_number failed:', e)
  }

  // Insert job
  const { data: job, error: jobErr } = await client.from('jobs').insert({
    org_id: DEFAULT_ORG_ID,
    type: jobType,
    status: finalStatus,
    client_name: name,
    client_phone: client_phone || null,
    client_email: client_email || null,
    site_address: site_address || null,
    site_suburb: site_suburb || null,
    ghl_contact_id: ghl_contact_id || null,
    job_number: jobNumber,
    pricing_json,
  }).select().single()

  if (jobErr) throw new Error('Failed to create job: ' + jobErr.message)

  // Insert job event
  await client.from('job_events').insert({
    job_id: job.id,
    event_type: 'status_change',
    detail_json: {
      from: null,
      to: finalStatus,
      job_number: jobNumber,
      source: 'quick_quote',
      job_type_label: job_type_label || 'Miscellaneous',
    },
  })

  return {
    success: true,
    job: {
      id: job.id,
      job_number: jobNumber,
      type: 'miscellaneous',
      status: finalStatus,
      client_name: name,
      totalIncGST,
    },
  }
}

// ── Send Quick Quote Email to Client ──
async function sendQuickQuoteEmail(client: any, body: any) {
  const { job_id, pdf_url } = body
  if (!job_id) throw new Error('job_id required')

  const { data: job, error: jobErr } = await client.from('jobs')
    .select('id, job_number, type, client_name, client_email, client_phone, site_address, site_suburb, pricing_json')
    .eq('id', job_id)
    .single()
  if (jobErr || !job) throw new Error('Job not found')
  if (!job.client_email) throw new Error('No client email on this job')

  const RESEND_API_KEY = Deno.env.get('RESEND_API_KEY') || ''
  if (!RESEND_API_KEY) throw new Error('RESEND_API_KEY not configured')

  const pricing = typeof job.pricing_json === 'string' ? JSON.parse(job.pricing_json || '{}') : (job.pricing_json || {})

  // ── Server-side pricing gate (mirrors send-quote quotePricingGateError) ──
  // Refuse to send a quote the scoping tool flagged as failing validation, or one
  // with no/zero price. Strict === false so quotes that never set the flag
  // (fence/legacy) are not blocked — only an explicit validation failure blocks.
  if (pricing.pricing_validation_passed === false) {
    throw new Error('Quote failed pricing validation in the scoping tool and cannot be sent. Fix the flagged pricing issues, re-save, and try again.')
  }
  // Same total fallback chain as send-quote so legacy quotes carrying only
  // `total`/`grandTotal` (not `totalIncGST`) are not falsely blocked.
  const totalIncGST = Number(pricing.totalIncGST ?? pricing.total ?? pricing.grandTotal ?? 0)
  if (!(totalIncGST > 0)) {
    throw new Error('Quote total is zero or missing. Set pricing on the job in the scoping tool before sending.')
  }
  const paymentTerms = pricing.payment_terms || '50/50 split'
  const validDays = pricing.valid_days || 30
  const validUntil = new Date(Date.now() + validDays * 86400000).toLocaleDateString('en-AU', { day: 'numeric', month: 'long', year: 'numeric' })
  const firstName = (job.client_name || '').split(' ')[0] || 'there'

  // Build HTML email
  const emailHtml = `
<div style="font-family:Helvetica,Arial,sans-serif;max-width:600px;margin:0 auto;">
  <div style="background:#293C46;padding:20px 24px;border-radius:8px 8px 0 0;">
    <h1 style="color:#fff;margin:0;font-size:20px;">SecureWorks Group</h1>
    <p style="color:#8FA4B2;margin:4px 0 0;font-size:12px;">Your Quote</p>
  </div>
  <div style="padding:24px;border:1px solid #e0e0e0;border-top:none;border-radius:0 0 8px 8px;">
    <p>Hi ${firstName},</p>
    <p>Thank you for your enquiry. Please find attached your quote for the following works:</p>
    <div style="background:#f8f6f3;padding:16px;border-radius:6px;margin:16px 0;">
      <p style="margin:0 0 8px;font-weight:600;color:#293C46;">Quote ${job.job_number || ''}</p>
      <p style="margin:0;font-size:14px;color:#4C6A7C;">${job.site_address || ''} ${job.site_suburb || ''}</p>
      <p style="margin:12px 0 0;font-size:24px;font-weight:700;color:#293C46;">$${Number(totalIncGST).toLocaleString('en-AU', { minimumFractionDigits: 2 })} <span style="font-size:12px;font-weight:400;color:#4C6A7C;">inc GST</span></p>
    </div>
    <p style="font-size:13px;color:#4C6A7C;">Payment terms: ${paymentTerms}<br>Valid until: ${validUntil}</p>
    <p>If you'd like to proceed, simply reply to this email or give us a call.</p>
    <p>Thanks,<br><strong>SecureWorks Group</strong><br>
    <span style="font-size:12px;color:#4C6A7C;">Patios | Fencing | Decking | Screening</span></p>
  </div>
</div>`

  // Build Resend payload
  const emailPayload: any = {
    from: 'SecureWorks Group <orders@secureworksgroup.app>',
    reply_to: getClientReplyTo(job.type, job.job_number),
    to: [job.client_email],
    subject: `Your Quote — ${job.job_number || 'SecureWorks Group'}`,
    html: emailHtml,
  }

  // Attach PDF if URL provided
  if (pdf_url) {
    try {
      const pdfResp = await fetch(pdf_url)
      if (pdfResp.ok) {
        const pdfBuffer = new Uint8Array(await pdfResp.arrayBuffer())
        let b64 = ''
        const chunkSize = 8192
        for (let i = 0; i < pdfBuffer.length; i += chunkSize) {
          b64 += String.fromCharCode(...pdfBuffer.slice(i, i + chunkSize))
        }
        emailPayload.attachments = [{
          filename: `${job.job_number || 'Quote'}.pdf`,
          content: btoa(b64),
        }]
      }
    } catch (e) {
      console.log('[ops-api] PDF attachment failed (non-blocking):', (e as Error).message)
    }
  }

  const resendResp = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${RESEND_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(emailPayload),
  })
  const resendResult = await resendResp.json()
  if (!resendResp.ok) throw new Error('Email send failed: ' + (resendResult.message || JSON.stringify(resendResult)))

  // ── Cap 0 release-truth: atomic draft → quoted transition + canonical events ──
  // Mirrors /send-quote/send (post-`350e943`) so Quick Quote inherits the same exactly-once
  // guarantee on the actual transition. The conditional UPDATE returns affected rows; canonical
  // events fire only when this call's UPDATE flipped the row. Resends on already-quoted jobs
  // no-op the UPDATE and emit nothing canonical (idempotence).
  //
  // CAP0-QUICKQUOTE-FRESH-SELECT-RACE-SAFETY (2026-05-01): the conditional UPDATE
  // also returns the post-UPDATE row state via .select(...). Canonical event
  // payloads use those FRESH values for job_number, type, client_name, and
  // pricing_json — NOT the function-entry SELECT at line ~6058 — so an edit to
  // the row between entry and UPDATE (e.g. a parallel writer changing type)
  // can't poison the canonical bus with stale state. `sent_to` and the email
  // body still reflect entry-time values because that's what was actually
  // dispatched to Resend.
  const nowIso = new Date().toISOString()
  const { data: updatedRows } = await client.from('jobs')
    .update({ status: 'quoted', quoted_at: nowIso })
    .eq('id', job_id)
    .eq('status', 'draft')
    .select('id, job_number, type, client_name, pricing_json')
  const transitioned = Array.isArray(updatedRows) && updatedRows.length > 0

  // Legacy event (mirrors /send-quote/send: written whenever a job_id exists, regardless of
  // transition, so daily-digest and other legacy readers see the send signal on every send).
  await client.from('job_events').insert({
    job_id,
    event_type: 'quote_sent',
    detail_json: { sent_to: job.client_email, source: 'quick_quote' },
  })

  // Canonical release events — only on actual draft → quoted transition.
  // Awaited via the existing logBusinessEvent helper so a transient Supabase failure is logged
  // (`[ops-api] business_events write failed`) rather than silently dropped.
  if (transitioned) {
    const fresh = updatedRows[0] as {
      id: string
      job_number: string | null
      type: string | null
      client_name: string | null
      pricing_json: Record<string, unknown> | null
    }
    const freshPricing = (fresh.pricing_json ?? {}) as Record<string, unknown>
    const freshTotalIncGSTRaw = freshPricing.totalIncGST ?? freshPricing.total ?? freshPricing.grandTotal
    const totalIncGSTNum = typeof freshTotalIncGSTRaw === 'number' && Number.isFinite(freshTotalIncGSTRaw)
      ? freshTotalIncGSTRaw
      : (Number(totalIncGST) || 0)

    // CAP0-QUOTE-REVISION-QUICKQUOTE: record the immutable revision row at the
    // release moment. job_document_id is null because Quick Quote doesn't have
    // a job_documents row (FK relaxed in migration 20260501130000). build_kind
    // derives from the post-UPDATE type so a Quick Quote that the user
    // re-classified before send carries the correct kind in its manifest.
    const buildKind: 'patio' | 'fence' | 'misc' =
      fresh.type === 'fencing' ? 'fence' :
      fresh.type === 'patio' ? 'patio' : 'misc'

    // ── Loop 3 / P2 V2 augmentation prep (Quick Quote) ──
    let v2InputsQq: Omit<V2AugmentationInput, 'release_id'> | null = null
    try {
      const [{ data: contactRows }, { data: mediaRows }] = await Promise.all([
        client.from('job_contacts')
          .select('id, contact_type, is_primary, contact_label, client_name, client_email, client_phone, assigned_runs, share_percentage')
          .eq('job_id', job_id),
        client.from('job_media')
          .select('id, type, phase, storage_url, label, taken_at, lat, lng')
          .eq('job_id', job_id),
      ])
      v2InputsQq = {
        job_id,
        version: 1,
        released_via: 'ops-api/send_quick_quote_email',
        released_at: nowIso,
        released_by_user_id: null,
        job_row: {
          id: job_id,
          type: fresh.type ?? job.type ?? 'general',
          org_id: DEFAULT_ORG_ID,
          client_name: fresh.client_name ?? job.client_name ?? null,
          client_email: job.client_email ?? null,
          client_phone: job.client_phone ?? null,
          site_address: job.site_address ?? null,
          site_suburb: job.site_suburb ?? null,
          site_lat: null,
          site_lng: null,
          job_number: fresh.job_number ?? job.job_number ?? null,
          ghl_contact_id: null,
          xero_contact_id: null,
          scope_json: null,
          pricing_json: (fresh.pricing_json ?? job.pricing_json) as Record<string, unknown> | null,
          notes: null,
        },
        contacts: contactRows ?? [],
        media: mediaRows ?? [],
        quote_pdf_url: pdf_url || '',
        quote_pdf_size_bytes: null,
        email_subject: emailPayload.subject,
        email_custom_message: '',
        email_template_version: 'v1',
        scoper_name: 'SecureWorks Group',
        resend_message_id: resendResult.id ?? null,
        primary_recipient_email: job.client_email,
        per_contact_pdfs: [],
        terms_valid_days: validDays,
        terms_payment_terms: paymentTerms,
        terms_deposit_pct: 50,
        scoper_user_id: null,
        scoper_user_name: null,
        scoped_at: null,
        override_operator_allowlist: [],
        pdf_sha256: '',
        email_html_sha256: '',
      }
    } catch (e: any) {
      console.error('[v2-augmentation-prefetch-fail]', JSON.stringify({
        job_id,
        handler: 'ops-api/send_quick_quote_email',
        error: e?.message ?? String(e),
        note: 'V2 columns left NULL; V1 release-truth path proceeds',
      }))
    }

    const releasedRevisionId = await recordReleasedQuoteRevision(client, {
      job_id,
      job_document_id: null,
      version: 1,
      recipient_email: job.client_email,
      recipient_label: null,
      build_kind: buildKind,
      scope: {
        client_name: fresh.client_name,
        site_address: job.site_address || null,
        site_suburb: job.site_suburb || null,
        job_type: fresh.type,
        job_number: fresh.job_number,
      },
      pricing_json: fresh.pricing_json ?? null,
      pdf_url: pdf_url || '',
      released_via: 'ops-api/send_quick_quote_email',
      org_id: DEFAULT_ORG_ID,
      v2_inputs: v2InputsQq,
    }, { handler: 'ops-api/send_quick_quote_email', job_id })

    // N2 — see send-quote handlers. Structured body_preview so the extractor
    // pre-filter doesn't skip with the auto-generated "quote quote.sent <UUID>".
    const qsBodyPreviewQuick = [
      `Quote ${fresh.job_number || ''} → ${fresh.client_name || ''} (${fresh.type || ''})`.replace(/\s+\(\)$/, '').trim(),
      totalIncGSTNum ? `$${Number(totalIncGSTNum).toFixed(2)} inc GST` : '',
      job.site_address ? `at ${job.site_address}` : '',
      job.site_suburb || '',
    ].filter(Boolean).join(' · ').slice(0, 400)
    await logBusinessEvent(client, {
      event_type: 'quote.sent',
      source: 'send-quick-quote-email',
      entity_type: 'job',
      entity_id: job_id,
      correlation_id: job_id,
      job_id,
      body_preview: qsBodyPreviewQuick,
      payload: {
        // Race-safety: fresh post-UPDATE values, not entry-time ones. See
        // CAP0-QUICKQUOTE-FRESH-SELECT-RACE-SAFETY note above.
        quote_revision_id: releasedRevisionId,
        job_number: fresh.job_number || null,
        job_type: fresh.type || null,
        sent_to: job.client_email,
        total_inc_gst: totalIncGSTNum,
      },
      metadata: { handler: 'ops-api/send_quick_quote_email' },
    })

    await logBusinessEvent(client, {
      event_type: 'job.status_changed',
      source: 'send-quick-quote-email',
      entity_type: 'job',
      entity_id: job_id,
      correlation_id: job_id,
      job_id,
      payload: {
        entity: { id: job_id, name: fresh.job_number || fresh.client_name || '' },
        changes: { status: { from: 'draft', to: 'quoted' } },
        financial: { amount: totalIncGSTNum },
        related_entities: releasedRevisionId
          ? [{ type: 'quote_revision', id: releasedRevisionId }]
          : [],
      },
      metadata: { reason: 'quote_sent', handler: 'ops-api/send_quick_quote_email' },
    })
  }

  // Log email event (existing behaviour, preserved)
  await client.from('email_events').insert({
    email_type: 'quote',
    entity_type: 'job',
    entity_id: job_id,
    job_id,
    recipient: job.client_email,
    sender: 'orders@secureworksgroup.app',
    subject: emailPayload.subject,
    resend_message_id: resendResult.id || null,
    status: 'sent',
    sent_at: new Date().toISOString(),
  })

  return { success: true, resend_id: resendResult.id, sent_to: job.client_email, released: transitioned }
}

// ── Delete PO ──
async function deletePO(client: any, body: any) {
  const { id } = body
  if (!id) throw new Error('id required')

  // Only allow deletion of draft/quote_requested POs
  const { data: po, error: fetchErr } = await client.from('purchase_orders')
    .select('id, status, po_number, supplier_name')
    .eq('id', id).single()
  if (fetchErr) throw new Error('PO not found')

  const deletable = ['draft', 'quote_requested']
  if (!deletable.includes(po.status)) {
    throw new Error('Cannot delete — PO status is "' + po.status + '". Cancel it instead.')
  }

  const { error } = await client.from('purchase_orders').delete().eq('id', id)
  if (error) throw new Error('Failed to delete PO: ' + error.message)

  return { success: true, deleted: po.po_number }
}

// ── PO Email Log ──
async function addPOEvent(client: any, body: any) {
  const { po_id, event_type, supplier, summary, direction, job_id } = body
  if (!po_id) throw new Error('po_id required')
  if (!event_type) throw new Error('event_type required')

  const eventData: any = {
    event_type: event_type,
    detail_json: {
      po_id,
      supplier: supplier || '',
      summary: summary || '',
      direction: direction || 'sent',
    },
  }

  // If job_id provided, store as job_event for timeline display
  if (job_id) {
    eventData.job_id = job_id
  }

  const { data, error } = await client.from('job_events').insert(eventData).select().single()
  if (error) throw new Error('Failed to log event: ' + error.message)

  return { success: true, event: data }
}

// ── Tracking category helper ──
// Maps job number prefix to Xero tracking category option name
function trackingCategoryForJob(jobNumber: string): string {
  if (!jobNumber) return ''
  const upper = jobNumber.toUpperCase()
  if (upper.startsWith('SWMS-') || upper.startsWith('AJBR') || upper.startsWith('MS1') || upper.startsWith('BWCWA') || upper.startsWith('WB6')) return 'SW - MAKESAFE'
  const prefix = upper.slice(0, 3)
  if (prefix === 'SWP') return 'SW - PATIOS'
  if (prefix === 'SWF') return 'SW - FENCING'
  if (prefix === 'SWD') return 'SW - DECKING'
  if (prefix === 'SWR') return 'SW - PRIVATE ROOFING'
  if (prefix === 'SWI') return 'SW - INSURANCE WORK'
  return ''
}

// Builds Xero Tracking array for a line item
function xeroTracking(jobNumber: string): any[] {
  const option = trackingCategoryForJob(jobNumber)
  if (!option) return []
  return [{ Name: 'Business Unit', Option: option }]
}

// ── Account code by job type ──
// Default sales account codes per division — override in job settings if needed
function accountCodeForJob(jobType: string, fallback = '200'): string {
  // All map to 200 by default. If the bookkeeper creates separate revenue
  // accounts later (e.g. 201 Patios, 202 Fencing), change these values.
  const map: Record<string, string> = {
    patio: '208',
    fencing: '207',
    decking: '205',
    roofing: '209',
    insurance: '210',
    makesafe: '210',
    renovation: '201',
    combo: '200',
  }
  return map[(jobType || '').toLowerCase()] || fallback
}

// ── Rich line item description builder ──
// Bakes job number, type, scope summary, client, and address into every
// line item so bookkeepers never have to cross-reference.
function buildRichDescription(job: any, prefix: string): string {
  const lines: string[] = []

  // Line 1: Prefix (e.g. "25% Deposit ($1,711 of $8,555 inc GST)")
  if (prefix) lines.push(prefix)

  // Line 2: Job number + type label
  const typeParts: string[] = []
  if (job.job_number) typeParts.push(job.job_number)
  const typeLabel = (job.type || '').toLowerCase()
  if (typeLabel === 'fencing') typeParts.push('Colorbond Fencing Installation')
  else if (typeLabel === 'decking') typeParts.push('Composite Decking Installation')
  else if (typeLabel === 'makesafe') typeParts.push('Make-Safe Works')
  else typeParts.push('Insulated Patio Installation')
  lines.push(typeParts.join(' | '))

  // Line 3: Scope summary from scope_json (metres, colour, type, dimensions)
  const scopeLine = buildScopeSummaryLine(job)
  if (scopeLine) lines.push(scopeLine)

  // Line 4: Client + address
  const clientParts: string[] = []
  if (job.client_name) clientParts.push(job.client_name)
  const addr = [job.site_address, job.site_suburb].filter(Boolean).join(', ')
  if (addr) clientParts.push(addr)
  if (clientParts.length) lines.push(clientParts.join(' | '))

  return lines.join('\n')
}

function buildScopeSummaryLine(job: any): string {
  try {
    const scope = typeof job.scope_json === 'string'
      ? JSON.parse(job.scope_json || '{}') : (job.scope_json || {})
    const type = (job.type || '').toLowerCase()
    const parts: string[] = []

    if (type === 'fencing') {
      // Fencing: sum runs for total metres
      const jobData = scope.job || scope.config || scope
      const runs = jobData.runs || []
      const totalM = runs.reduce((s: number, r: any) => s + (Number(r.lengthM) || Number(r.totalLength) || Number(r.length) || 0), 0)
      if (totalM > 0) parts.push(Math.round(totalM) + 'm')
      const mat = jobData.material || jobData.profile || 'Colorbond'
      parts.push(mat)
      const colour = jobData.colour || jobData.color || scope.config?.colour || ''
      if (colour) parts.push(colour)
      const height = jobData.sheetHeight || jobData.height || scope.config?.height || ''
      if (height) parts.push(height + 'mm high')
      const gates = jobData.gates || []
      if (Array.isArray(gates) && gates.length > 0) parts.push(gates.length + ' gate' + (gates.length > 1 ? 's' : ''))
      else if (typeof jobData.gateCount === 'number' && jobData.gateCount > 0) parts.push(jobData.gateCount + ' gate' + (jobData.gateCount > 1 ? 's' : ''))
    } else {
      // Patio / decking
      const cfg = scope.config || scope
      const l = cfg.length || cfg.L || ''
      const p = cfg.projection || cfg.W || cfg.width || ''
      if (l && p) parts.push(l + 'm x ' + p + 'm')
      if (cfg.roofStyle) parts.push(cfg.roofStyle)
      const roofing = cfg.roofing || cfg.sheetType || cfg.panelType || ''
      if (roofing) {
        const roofLabel = roofing.replace(/solarspan75/i, 'SolarSpan 75mm').replace(/solarspan100/i, 'SolarSpan 100mm')
          .replace(/solarspan50/i, 'SolarSpan 50mm').replace(/trimdek/i, 'Trimdek').replace(/corrugated/i, 'Corrugated')
          .replace(/spandek/i, 'SpanDek')
        parts.push(roofLabel)
      }
      const colour = cfg.sheetColor || cfg.sheetColour || cfg.colour || ''
      if (colour) parts.push(colour)
      const posts = cfg.posts || cfg.postCount || ''
      const postSize = cfg.postSize || ''
      if (posts) parts.push(posts + ' x ' + (postSize || '100x100 SHS') + ' posts')
      if (cfg.connection) parts.push(cfg.connection)
    }

    if (parts.length > 0) return parts.join(', ')

    // Fallback to pricing_json.job_description
    const pricing = typeof job.pricing_json === 'string'
      ? JSON.parse(job.pricing_json || '{}') : (job.pricing_json || {})
    return pricing.job_description || pricing.description || ''
  } catch {
    return ''
  }
}

// Feature 5: Create a deposit invoice for an accepted job
// Creates a Xero ACCREC invoice for a configurable % of the quoted total,
// with rich description, tracking category, and SWP-25042-DEP reference.
// Sends via Xero email. Saves deposit_invoice_id + deposit_amount on jobs.
// xero_status defaults to DRAFT (drafts-for-review for make-safe / manual / MCP
// callers — do not change); sendAcceptanceInvoice defaults it to AUTHORISED.
// Returns xero_status (the status Xero actually assigned) so callers can gate
// client-facing payment links. See "Acceptance Deposit Invoice Invariant" in AGENTS.md.
async function createDepositInvoice(client: any, body: any) {
  const jId = body.job_id || body.jobId
  if (!jId) throw new Error('job_id required')

  const depositPercent = body.deposit_percent ?? 50

  // Fetch the job
  const { data: job, error: jobErr } = await client
    .from('jobs')
    .select('id, status, client_name, client_email, job_number, xero_contact_id, pricing_json, scope_json, type, site_address, site_suburb')
    .eq('id', jId)
    .single()
  if (jobErr || !job) throw new Error('Job not found')

  // Resolve neighbour contact details if job_contact_id provided
  const job_contact_id = body.job_contact_id || null
  // Do not default to the job's Xero contact when billing a neighbour.
  let invoiceContactId = job_contact_id ? undefined : (job.xero_contact_id || undefined)
  let invoiceContactName = job.client_name
  let contactLabel = '' // A, B, C, D — used for reference suffix
  if (job_contact_id) {
    const { data: jc } = await client.from('job_contacts')
      .select('client_name, xero_contact_id, contact_label')
      .eq('id', job_contact_id).single()
    if (jc?.xero_contact_id) invoiceContactId = jc.xero_contact_id
    if (jc?.client_name) invoiceContactName = jc.client_name
    if (jc?.contact_label) contactLabel = jc.contact_label
    console.log('[createDepositInvoice] Neighbour contact resolved:', invoiceContactName, contactLabel, invoiceContactId)
  }

  // Per-run label (for multi-neighbour fencing)
  const runLabel = body.run_label || null

  // Check for existing deposit invoice (neighbour + run aware)
  let depRefPattern = '%DEP%'
  if (runLabel && contactLabel) depRefPattern = `%${runLabel}-${contactLabel}-DEP%`
  else if (contactLabel) depRefPattern = `%${contactLabel}-DEP%`
  else if (runLabel) depRefPattern = `%${runLabel}%DEP%`

  const existingDepQuery = client.from('xero_invoices')
    .select('xero_invoice_id, invoice_number, total')
    .eq('job_id', jId)
    .eq('invoice_type', 'ACCREC')
    .not('status', 'in', '("VOIDED","DELETED")')
    .ilike('reference', depRefPattern)
    .limit(1)
  if (job_contact_id) existingDepQuery.eq('job_contact_id', job_contact_id)
  if (runLabel) existingDepQuery.eq('run_label', runLabel)
  const { data: existingDep } = await existingDepQuery
  if (existingDep && existingDep.length > 0) {
    throw new Error(`Deposit invoice already exists: ${existingDep[0].invoice_number} ($${existingDep[0].total}). Void it in Xero before creating a new one.`)
  }

  // Extract total from pricing_json (with fallback to scope_json._pricing_json for fencing jobs)
  let quotedTotal = 0
  let jobDescription = ''
  let pricingDep: any = null
  if (job.pricing_json && Object.keys(job.pricing_json).length > 0) {
    pricingDep = typeof job.pricing_json === 'string' ? JSON.parse(job.pricing_json) : job.pricing_json
  }
  if (!pricingDep && job.scope_json) {
    const scope = typeof job.scope_json === 'string' ? JSON.parse(job.scope_json) : job.scope_json
    const jobData = scope.job || scope
    if (jobData._pricing_json) {
      pricingDep = typeof jobData._pricing_json === 'string' ? JSON.parse(jobData._pricing_json) : jobData._pricing_json
    }
  }
  if (pricingDep) {
    quotedTotal = pricingDep.totalIncGST || pricingDep.total || pricingDep.amount || 0
    jobDescription = pricingDep.description || pricingDep.jobDescription || ''
  }

  // Allow override from body
  const depositAmountOverride = body.deposit_amount
  const depositAmountIncGst = depositAmountOverride || Math.round(quotedTotal * (depositPercent / 100) * 100) / 100

  if (depositAmountIncGst <= 0) {
    throw new Error('Cannot create a $0 deposit invoice. Set pricing_json on the job first.')
  }

  // Build rich description with all job metadata baked in
  const depositLabel = `Deposit (${depositPercent}% of $${quotedTotal.toLocaleString('en-AU', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} inc GST)`
  const description = buildRichDescription(job, depositLabel)

  // Reference: SWP-25042-DEP50 (single), SWF-25030-A-DEP50 (neighbour A), SWF-25030-REAR-A-DEP50 (per-run)
  const refParts = [job.job_number || '']
  if (runLabel) refParts.push(runLabel)
  if (contactLabel) refParts.push(contactLabel)
  refParts.push(`DEP${depositPercent}`)
  const reference = refParts.join('-')

  // Deposit is inc GST — Xero adds GST, so we need ex GST amount
  const depositExGst = Math.round((depositAmountIncGst / 1.1) * 100) / 100

  const lineItems: any[] = [{
    description,
    quantity: 1,
    unit_price: depositExGst,
    account_code: accountCodeForJob(job.type),
  }]

  // Extra line items (council fees, etc.) — each has amount_inc_gst
  const extras = body.extra_line_items || []
  for (const extra of extras) {
    if (extra.amount_inc_gst > 0 && extra.description) {
      lineItems.push({
        description: extra.description,
        quantity: 1,
        unit_price: Math.round((extra.amount_inc_gst / 1.1) * 100) / 100,
        account_code: accountCodeForJob(job.type),
      })
    }
  }

  // Create Xero invoice as a draft by default so Shaun can review before sending.
  const invoiceResult = await createInvoice(client, {
    job_id: jId,
    xero_contact_id: invoiceContactId,
    contact_name: invoiceContactName,
    line_items: lineItems,
    reference,
    xero_status: body.xero_status || 'DRAFT',
    send_email: body.send_email !== false, // default: send
    job_contact_id: job_contact_id,
    run_label: runLabel,
  })

  // Total invoice amount = deposit + extras
  const extrasTotal = extras.reduce((s: number, e: any) => s + (e.amount_inc_gst || 0), 0)
  const totalInvoiceAmount = depositAmountIncGst + extrasTotal

  // Save deposit info on jobs table
  await client.from('jobs')
    .update({
      deposit_invoice_id: invoiceResult.xero_invoice_id,
      deposit_amount: totalInvoiceAmount,
    })
    .eq('id', jId)

  // Log event
  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'deposit_invoice_created',
    detail_json: {
      xero_invoice_id: invoiceResult.xero_invoice_id,
      invoice_number: invoiceResult.invoice_number,
      deposit_amount: totalInvoiceAmount,
      deposit_percent: depositPercent,
      quoted_total: quotedTotal,
      extra_line_items: extras,
    },
  })

  // Dual-write to business_events
  logBusinessEvent(client, {
    event_type: 'invoice.created',
    entity_type: 'invoice',
    entity_id: invoiceResult.xero_invoice_id || jId,
    job_id: job.job_number || jId,
    correlation_id: jId,
    payload: {
      entity: { id: invoiceResult.xero_invoice_id, name: invoiceResult.invoice_number || '' },
      financial: { amount: totalInvoiceAmount, currency: 'AUD' },
      invoice_type: 'deposit',
      deposit_percent: depositPercent,
      quoted_total: quotedTotal,
      related_entities: [{ type: 'job', id: jId, name: job.client_name || '' }],
    },
    metadata: { operator: body.operator_email || body.user_email || null },
  })

  return {
    success: true,
    job_id: jId,
    xero_invoice_id: invoiceResult.xero_invoice_id,
    invoice_number: invoiceResult.invoice_number,
    deposit_amount: depositAmountIncGst,
    deposit_percent: depositPercent,
    quoted_total: quotedTotal,
    reference,
    description,
    // Surface the Xero status so acceptance callers can gate the Pay Now email.
    xero_status: invoiceResult.status,
  }
}

// ── Unified Invoice — single flow for deposits, progress claims, finals, extras ──
async function createUnifiedInvoice(client: any, body: any) {
  const jId = body.job_id || body.jobId
  if (!jId) throw new Error('job_id required')

  const items = body.line_items || body.lineItems
  if (!items || items.length === 0) throw new Error('line_items required')

  // Fetch job
  const { data: job, error: jobErr } = await client
    .from('jobs')
    .select('id, status, client_name, client_email, job_number, xero_contact_id, pricing_json, type, site_address, site_suburb')
    .eq('id', jId)
    .single()
  if (jobErr || !job) throw new Error('Job not found')

  // Calculate quoted total
  const pricing = typeof job.pricing_json === 'string' ? JSON.parse(job.pricing_json || '{}') : (job.pricing_json || {})
  const quotedTotal = pricing.totalIncGST || pricing.total || 0

  // Sum existing active invoices for this job
  const { data: existingInvs } = await client.from('xero_invoices')
    .select('total')
    .eq('job_id', jId)
    .eq('invoice_type', 'ACCREC')
    .not('status', 'in', '("VOIDED","DELETED")')
  const existingTotal = (existingInvs || []).reduce((s: number, inv: any) => s + (inv.total || 0), 0)

  // Build line items — each item has amount inc GST, convert to ex GST for Xero
  const lineItems = items.map((li: any) => {
    const unitPrice = li.unit_price_ex_gst != null
      ? li.unit_price_ex_gst
      : (li.unit_price || li.unitPrice || 0)
    return {
      description: li.description || '',
      quantity: li.quantity || 1,
      unit_price: unitPrice,
      account_code: accountCodeForJob(job.type),
    }
  })

  // Calculate new invoice total (inc GST)
  const newTotal = lineItems.reduce((s: number, li: any) => s + ((li.quantity || 1) * (li.unit_price || 0) * 1.1), 0)

  // Warn if over-invoicing (but don't block — variations happen)
  const overInvoiceWarning = quotedTotal > 0 && (existingTotal + newTotal) > quotedTotal * 1.05
    ? `Warning: total invoiced ($${(existingTotal + newTotal).toFixed(2)}) exceeds quoted total ($${quotedTotal.toFixed(2)})`
    : null

  // Reference — use frontend suffix if provided (e.g. 'COUNCIL', 'VARIATION1')
  const referenceSuffix = body.reference_suffix || ''
  const reference = (job.job_number || '') + (referenceSuffix ? `-${referenceSuffix}` : '')

  // Duplicate prevention: warn if creating invoice for same reference
  if (reference && reference !== job.job_number) {
    const { data: dupeCheck } = await client.from('xero_invoices')
      .select('invoice_number')
      .eq('job_id', jId)
      .eq('reference', reference)
      .not('status', 'in', '("VOIDED","DELETED")')
      .limit(1)
    if (dupeCheck && dupeCheck.length > 0) {
      throw new Error(`Invoice with reference ${reference} already exists (${dupeCheck[0].invoice_number}). Void it first if you need to recreate.`)
    }
  }

  // When using branded email, suppress Xero's plain email — we'll send our own
  const useBrandedEmail = body.use_branded_email === true && (body.send_email === true || body.send_email)
  const xeroSendEmail = useBrandedEmail ? false : (body.send_email || false)

  // Create invoice via existing function
  const invoiceResult = await createInvoice(client, {
    job_id: jId,
    xero_contact_id: job.xero_contact_id || undefined,
    contact_name: job.client_name,
    line_items: lineItems,
    reference,
    xero_status: body.xero_status || 'DRAFT',
    send_email: xeroSendEmail,
  })

  // Store quote_document_ids on the xero_invoices record if provided
  const quoteDocIds = body.quote_document_ids
  if (quoteDocIds && quoteDocIds.length > 0 && invoiceResult.xero_invoice_id) {
    await client.from('xero_invoices')
      .update({ quote_document_ids: quoteDocIds })
      .eq('xero_invoice_id', invoiceResult.xero_invoice_id)
  }

  // Branded email: get online invoice URL and send via send-quote/send-invoice
  let brandedEmailSent = false
  if (useBrandedEmail && invoiceResult.xero_invoice_id) {
    // Determine recipient — email_override takes precedence, then job client_email
    const invoiceClientEmail = body.email_override || job.client_email

    // Get Xero online invoice URL for payment
    let paymentUrl = ''
    try {
      const { accessToken, tenantId } = await getToken(client)
      const onlineResult = await xeroGet(
        `/Invoices/${invoiceResult.xero_invoice_id}/OnlineInvoice`,
        accessToken, tenantId
      )
      paymentUrl = onlineResult?.OnlineInvoices?.[0]?.OnlineInvoiceUrl || ''
    } catch (e) {
      console.log('Could not get online invoice URL:', (e as Error).message)
    }

    // Send branded invoice email
    if (invoiceClientEmail) {
      try {
        const address = [job.site_address, job.site_suburb].filter(Boolean).join(', ')
        const emailRes = await fetch(`${SUPABASE_URL}/functions/v1/send-quote/send-invoice`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${SUPABASE_SERVICE_KEY}`,
          },
          body: JSON.stringify({
            xero_invoice_id: invoiceResult.xero_invoice_id,
            job_id: jId,
            payment_url: paymentUrl,
            invoice_number: invoiceResult.invoice_number,
            deposit_amount: invoiceResult.total,
            client_name: job.client_name,
            client_email: invoiceClientEmail,
            job_type: job.type,
            address,
          }),
        })
        const emailResult = await emailRes.json()
        brandedEmailSent = emailResult.success || false
      } catch (e) {
        console.log('Branded email call failed (non-blocking):', (e as Error).message)
      }
    }
  }

  // Log event
  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'unified_invoice_created',
    detail_json: {
      xero_invoice_id: invoiceResult.xero_invoice_id,
      invoice_number: invoiceResult.invoice_number,
      total: invoiceResult.total,
      quote_document_ids: quoteDocIds || [],
      line_items: items,
      over_invoice_warning: overInvoiceWarning,
      branded_email_sent: brandedEmailSent,
    },
  })

  return {
    success: true,
    job_id: jId,
    xero_invoice_id: invoiceResult.xero_invoice_id,
    invoice_number: invoiceResult.invoice_number,
    total: invoiceResult.total,
    quoted_total: quotedTotal,
    invoiced_total: existingTotal + (invoiceResult.total || 0),
    remaining_to_invoice: Math.max(0, quotedTotal - existingTotal - (invoiceResult.total || 0)),
    warning: overInvoiceWarning,
    branded_email_sent: brandedEmailSent,
  }
}

// Feature 2: Morning brief — structured summary for AI to narrate
async function morningBrief(client: any) {
  const summary = await opsSummary(client)

  // Enrich with extra context for the brief
  const completeNotInvoiced = await client
    .from('jobs')
    .select('id, client_name, job_number, site_suburb, pricing_json, completed_at')
    .eq('org_id', DEFAULT_ORG_ID)
    .not('legacy', 'is', true)
    .eq('status', 'complete')
    .order('completed_at', { ascending: true })
    .limit(10)

  const briefData = {
    ...summary,
    complete_not_invoiced: (completeNotInvoiced.data || []).map((j: any) => {
      let value = 0
      if (j.pricing_json) {
        const p = typeof j.pricing_json === 'string' ? JSON.parse(j.pricing_json) : j.pricing_json
        value = parseFloat(p.totalIncGST || p.totalExGST || p.total || p.grandTotal || p.amount || p.subtotal || 0) || 0
      }
      return { id: j.id, client: j.client_name, job_number: j.job_number, suburb: j.site_suburb, value, completed: j.completed_at }
    }),
  }
  return briefData
}

// Feature 5: Extract materials from scope_json for PO auto-population
function extractMaterialsFromScope(scope_json: any, pricing_json: any): any[] {
  if (!scope_json) return []
  const scope = typeof scope_json === 'string' ? JSON.parse(scope_json) : scope_json
  const config = scope.config || scope

  const items: any[] = []

  // Roofing panels — calculate from dimensions
  // Patio tool stores as config.length (mm string), config.projection (mm string)
  // or config.roofing (string like 'solarspan75')
  if (config.roofing || config.panels || config.length) {
    // Length/projection may be mm strings from patio tool — convert to metres
    let rawLen = config.length || config.roofing?.length || 0
    let rawProj = config.projection || config.roofing?.projection || 0
    let length = typeof rawLen === 'string' ? parseFloat(rawLen) : rawLen
    let projection = typeof rawProj === 'string' ? parseFloat(rawProj) : rawProj
    // If values are > 100, assume mm and convert to metres
    if (length > 100) length = length / 1000
    if (projection > 100) projection = projection / 1000
    if (length > 0 && projection > 0) {
      const m2 = length * projection
      const panelCount = Math.ceil(length)
      // Map roofing code to readable name
      const roofingMap: Record<string, string> = {
        solarspan75: 'SolarSpan 75mm', solarspan100: 'SolarSpan 100mm',
        trimdek: 'Trimdek', corrugated: 'Corrugated', spandek: 'Spandek',
        spanplus330: 'SpanPlus 330',
      }
      const roofCode = typeof config.roofing === 'string' ? config.roofing : ''
      const panelType = config.panel_type || roofingMap[roofCode] || roofCode || 'Roofing panels'
      items.push({
        description: `${panelType} — ${projection.toFixed(1)}m projection × ${panelCount} panels`,
        quantity: panelCount,
        unit_price: 0,
        notes: `${m2.toFixed(1)}m² total area, ${length.toFixed(1)}m span`,
      })
    }
  }

  // Posts — handle both camelCase (patio tool) and snake_case
  const postCountRaw = config.post_count || config.postQtyOverride || config.posts?.count || config.posts || 0
  const postCount = typeof postCountRaw === 'number' ? postCountRaw : parseInt(postCountRaw) || 0
  if (postCount > 0) {
    const postSize = config.post_size || config.postSize || config.posts?.size || '100x100 SHS'
    items.push({
      description: `${postSize} posts`,
      quantity: postCount,
      unit_price: 0,
    })
  }

  // Beams — handle both camelCase and snake_case
  if (config.beams || config.beam_count || config.beamSize) {
    const beamCount = config.beam_count || config.beams?.count || 1
    const beamSize = config.beam_size || config.beamSize || config.beams?.size || 'Steel beam'
    let beamLenRaw = config.beam_length || config.beams?.length || config.length || 0
    let beamLength = typeof beamLenRaw === 'string' ? parseFloat(beamLenRaw) : beamLenRaw
    if (beamLength > 100) beamLength = beamLength / 1000
    items.push({
      description: `${beamSize}${beamLength ? ` — ${beamLength.toFixed(1)}m` : ''}`,
      quantity: beamCount,
      unit_price: 0,
    })
  }

  // Footings — 1 per post
  if (postCount > 0) {
    items.push({
      description: 'Concrete footings (400x400x500mm)',
      quantity: postCount,
      unit_price: 0,
    })
  }

  // ── Fencing materials (detailed extraction from scoping tool) ──
  const sections = scope.sections || []
  if (sections.length > 0) {
    // Group panels by sheet height
    const panelsByHeight: Record<number, number> = {}
    const postsByHeight: Record<string, number> = { end: 0, corner: 0, intermediate: 0 }
    let totalPlinths = 0
    let totalSleepers = 0
    let totalMetres = 0

    for (const sec of sections) {
      const panels = sec.panels || []
      const height = sec.sheetHeight || 1800
      panelsByHeight[height] = (panelsByHeight[height] || 0) + panels.length
      totalMetres += sec.length || 0

      // Count posts by type
      for (const panel of panels) {
        if (panel.leftPost) postsByHeight[panel.leftPost] = (postsByHeight[panel.leftPost] || 0) + 1
      }
      // Last panel's right post
      if (panels.length > 0 && panels[panels.length - 1].rightPost) {
        postsByHeight[panels[panels.length - 1].rightPost] = (postsByHeight[panels[panels.length - 1].rightPost] || 0) + 1
      }

      // Plinths and sleepers
      if (sec.retaining) {
        const plinthCount = panels.length
        totalPlinths += plinthCount
        const sleeperRows = sec.retainingHeight ? Math.ceil(sec.retainingHeight / 200) : 1
        totalSleepers += plinthCount * sleeperRows
      }
    }

    // Panels by height
    for (const [height, count] of Object.entries(panelsByHeight)) {
      items.push({
        description: `Colorbond fence sheets — ${height}mm high`,
        quantity: count,
        unit: 'sheets',
        unit_price: 0,
      })
    }

    // Posts (total count)
    const totalPosts = Object.values(postsByHeight).reduce((s, n) => s + n, 0)
    if (totalPosts > 0) {
      items.push({
        description: 'Fence posts (C-section)',
        quantity: totalPosts,
        unit: 'ea',
        unit_price: 0,
        notes: `End: ${postsByHeight.end || 0}, Corner: ${postsByHeight.corner || 0}, Intermediate: ${postsByHeight.intermediate || 0}`,
      })
    }

    // Plinths
    if (totalPlinths > 0) {
      items.push({
        description: 'Concrete plinths',
        quantity: totalPlinths,
        unit: 'ea',
        unit_price: 0,
      })
    }

    // Retaining sleepers
    if (totalSleepers > 0) {
      items.push({
        description: 'Retaining sleepers',
        quantity: totalSleepers,
        unit: 'ea',
        unit_price: 0,
      })
    }

    // Patio tubes (if 3+ plinths per section, need patio tube support)
    for (const sec of sections) {
      if (sec.retaining && (sec.panels || []).length >= 3) {
        items.push({
          description: `Patio tube support — Section (${sec.length || 0}m)`,
          quantity: Math.ceil((sec.panels || []).length / 3),
          unit: 'ea',
          unit_price: 0,
        })
      }
    }

    // Gates
    const gates = scope.gates || []
    for (const gate of gates) {
      const gateType = gate.type || 'pedestrian'
      const gateWidth = gate.width || 900
      items.push({
        description: `${gateType.charAt(0).toUpperCase() + gateType.slice(1)} gate — ${gateWidth}mm`,
        quantity: 1,
        unit: 'ea',
        unit_price: 0,
      })
    }

    // Concrete bags (1 per post, 60kg bags)
    if (totalPosts > 0) {
      items.push({
        description: 'Concrete bags (20kg)',
        quantity: totalPosts * 3, // ~3 bags per post
        unit: 'bags',
        unit_price: 0,
      })
    }

    // Tek screws (4 per panel)
    const totalPanels = Object.values(panelsByHeight).reduce((s, n) => s + n, 0)
    if (totalPanels > 0) {
      items.push({
        description: 'Tek screws (12-14 x 20)',
        quantity: totalPanels * 4,
        unit: 'ea',
        unit_price: 0,
      })
    }

    // Removal line items
    const removal = scope.removal
    if (removal && (removal.totalMetres > 0 || removal.length > 0)) {
      items.push({
        description: 'Old fence removal',
        quantity: removal.totalMetres || removal.length || 0,
        unit: 'm',
        unit_price: 0,
      })
    }
  } else if (config.fence_length || config.fencing) {
    // Fallback: simple fencing dimensions
    const fenceLen = config.fence_length || config.fencing?.length || 0
    const fenceHeight = config.fence_height || config.fencing?.height || 1.8
    if (fenceLen > 0) {
      const fencePosts = Math.ceil(fenceLen / 2.4) + 1
      items.push(
        { description: `Colorbond fence sheets — ${fenceHeight}m high`, quantity: Math.ceil(fenceLen), unit_price: 0, notes: `${fenceLen}m total` },
        { description: 'Fence posts (C-section)', quantity: fencePosts, unit_price: 0 },
        { description: 'Concrete bags (20kg)', quantity: fencePosts * 3, unit_price: 0 },
        { description: 'Tek screws (12-14 x 20)', quantity: Math.ceil(fenceLen) * 4, unit_price: 0 },
      )
    }
  }

  // If scope had nothing recognisable but pricing has items, fall back to pricing
  if (items.length === 0 && pricing_json) {
    const pricing = typeof pricing_json === 'string' ? JSON.parse(pricing_json) : pricing_json
    if (Array.isArray(pricing.items)) {
      return pricing.items
        .filter((li: any) => li.description && /material|panel|post|beam|steel|concrete|colorbond/i.test(li.description))
        .map((li: any) => ({
          description: li.description,
          quantity: li.quantity || 1,
          unit_price: li.unit_price || 0,
        }))
    }
  }

  return items
}

// Exposed as API action for PO auto-population
async function scopeToPO(client: any, params: URLSearchParams) {
  const jobId = params.get('jobId') || params.get('job_id')
  if (!jobId) throw new Error('jobId required')

  const { data: job, error } = await client
    .from('jobs')
    .select('id, scope_json, pricing_json, client_name, site_suburb, type')
    .eq('id', jobId)
    .single()
  if (error || !job) throw new Error('Job not found')

  const materials = extractMaterialsFromScope(job.scope_json, job.pricing_json)
  return { job_id: jobId, client: job.client_name, type: job.type, materials }
}

// ── Scheduling Capacity Endpoint ──
// Returns weekly capacity data for upcoming weeks.
// Used by scoping tools' future calendar preview widget.
async function schedulingCapacity(client: any, params: URLSearchParams) {
  const weeksCount = parseInt(params.get('weeks') || '6')
  const crewCount = parseInt(params.get('crew_count') || '3') // Default 3 crews

  const now = new Date()
  // Start from next Monday
  const dayOfWeek = now.getDay() || 7
  const nextMonday = new Date(now)
  nextMonday.setDate(now.getDate() - dayOfWeek + 8) // Next Monday
  nextMonday.setHours(0, 0, 0, 0)

  const weeks: any[] = []
  for (let i = 0; i < weeksCount; i++) {
    const weekStart = new Date(nextMonday)
    weekStart.setDate(nextMonday.getDate() + i * 7)
    const weekEnd = new Date(weekStart)
    weekEnd.setDate(weekStart.getDate() + 4) // Friday

    const startStr = weekStart.toISOString().slice(0, 10)
    const endStr = weekEnd.toISOString().slice(0, 10)

    // Count assignments in this week
    const { data: assignments } = await client
      .from('job_assignments')
      .select('id')
      .eq('org_id', DEFAULT_ORG_ID)
      .gte('scheduled_date', startStr)
      .lte('scheduled_date', endStr)
      .neq('status', 'cancelled')
      .limit(200)

    const assignmentCount = (assignments || []).length
    const maxCapacity = crewCount * 5 // 5 weekdays per crew
    const capacityPct = maxCapacity > 0 ? Math.round(assignmentCount / maxCapacity * 100) : 0

    weeks.push({
      start: startStr,
      end: endStr,
      assignments: assignmentCount,
      crew_count: crewCount,
      capacity_pct: capacityPct,
    })
  }

  return { weeks }
}


// Bulk-move legacy GHL imports from "complete" to "invoiced"
// These are jobs that were invoiced through Tradify/old Xero and have no ops activity.
// Pass ?dry_run=true to preview without changing.
async function bulkLegacyToInvoiced(client: any, params: URLSearchParams) {
  const dryRun = params.get('dry_run') !== 'false'

  // Find complete jobs with no assignments, no POs, no job_number (= never managed through ops)
  const { data: candidates, error } = await client
    .from('jobs')
    .select('id, client_name, type, status, job_number, completed_at')
    .eq('org_id', DEFAULT_ORG_ID)
    .eq('status', 'complete')
    .is('job_number', null)

  if (error) throw error
  if (!candidates || candidates.length === 0) return { message: 'No legacy jobs found', updated: 0 }

  // Double-check: exclude any with assignments
  const candidateIds = candidates.map((j: any) => j.id)
  const { data: withAssignments } = await client
    .from('job_assignments')
    .select('job_id')
    .in('job_id', candidateIds)
  const hasAssignment = new Set((withAssignments || []).map((a: any) => a.job_id))

  const toUpdate = candidates.filter((j: any) => !hasAssignment.has(j.id))

  if (dryRun) {
    return {
      dry_run: true,
      message: `Would update ${toUpdate.length} legacy jobs from "complete" to "invoiced"`,
      count: toUpdate.length,
      sample: toUpdate.slice(0, 10).map((j: any) => ({ id: j.id, client: j.client_name, type: j.type, completed: j.completed_at })),
    }
  }

  // Execute the bulk update
  const updateIds = toUpdate.map((j: any) => j.id)
  const { error: updateErr } = await client
    .from('jobs')
    .update({ status: 'invoiced', updated_at: new Date().toISOString() })
    .in('id', updateIds)

  if (updateErr) throw updateErr

  return {
    dry_run: false,
    message: `Updated ${updateIds.length} legacy jobs to "invoiced"`,
    count: updateIds.length,
  }
}


// ════════════════════════════════════════════════════════════
// TRADE ENDPOINTS (mobile) — JWT auth required
// ════════════════════════════════════════════════════════════

// Verify trade user is assigned to a job before allowing access.
// Admin users bypass this check. MakeSafe field-report jobs are a special
// dispatch flow: any logged-in trade may read/upload/report them, but this
// exception must not loosen ordinary patio/fencing/decking job access.
async function assertAssigned(client: any, jobId: string, userId: string, isAdmin = false) {
  if (isAdmin) return // Admins can view any job
  const { data } = await client
    .from('job_assignments')
    .select('id')
    .eq('job_id', jobId)
    .eq('user_id', userId)
    .neq('status', 'cancelled')
    .limit(1)
    .maybeSingle()
  if (!data) throw new Error('You are not assigned to this job')
}

function isMakesafeAccessJob(job: any): boolean {
  if (!job) return false
  const type = String(job.type || '').toLowerCase().replace(/[\s_-]+/g, '')
  if (type === 'makesafe') return true
  // Some imported MakeSafes are identifiable by their SWMS job number even if
  // the legacy/placeholder job type has not been normalised to `makesafe` yet.
  if (/^SWMS-/i.test(String(job.job_number || ''))) return true
  return false
}

async function hasMakesafeDetailForAccess(client: any, jobId: string): Promise<boolean> {
  const { data, error } = await client
    .from('makesafe_job_details')
    .select('job_id')
    .eq('job_id', jobId)
    .limit(1)
    .maybeSingle()
  if (error) throw error
  return !!data
}

async function isMakesafeAccessJobForClient(client: any, job: any): Promise<boolean> {
  if (isMakesafeAccessJob(job)) return true
  if (!job?.id) return false
  return hasMakesafeDetailForAccess(client, job.id)
}

function isOpenTradeMakesafeDetail(detail: any): boolean {
  if (!detail) return true
  const sub = String(detail.substatus || '').toLowerCase()
  if (['admin_to_send_report', 'ready_to_invoice', 'complete', 'completed', 'report_ready', 'to_invoice', 'invoiced'].includes(sub)) return false
  if (detail.report_received_at || detail.report_sent_at || detail.invoice_ready_at) return false
  return true
}

// ── M3d U2c — trade make-safe OPEN POOL = allocatable only (G2) ─────────────
// The trade make-safe "New" column shows jobs ops has cleared for crew
// allocation. A job still at substatus 'company_contact_required' is ops's own
// admin queue (New = "ops still owns it"), not yet allocatable, so it drops off
// the trade pool. This is POOL VISIBILITY ONLY: report access
// (assertAssignedOrMakesafeAccess -> isMakesafeAccessJobForClient) is a SEPARATE
// predicate and is deliberately left unchanged, so any trade can still open and
// REPORT on such a job. A job with NO detail row stays visible (null ->
// allocatable), preserving today's behaviour.
function isAllocatableMakesafePoolDetail(detail: any): boolean {
  if (!isOpenTradeMakesafeDetail(detail)) return false
  const sub = String(detail?.substatus || '').toLowerCase()
  if (sub === 'company_contact_required') return false
  return true
}
export function _isAllocatableMakesafePoolDetailForTest(detail: any): boolean {
  return isAllocatableMakesafePoolDetail(detail)
}

// ── M3d U2a/U2b — auto-close stale crew assignments on terminal transitions ──
// The trade Board classifies a card purely from its ASSIGNMENT status, so a job
// (or make-safe) that reaches a terminal state must close its still-open crew
// assignments or the Board keeps showing finished/dead work as live. These
// vocabularies were verified live 2026-07-08 and mirror the U1 reconcile script
// (scripts/reconcile-stale-assignments.sh) exactly: dead -> assignment cancelled,
// finished -> assignment complete.
export const _JOB_STATUS_DEAD = [
  'cancelled', 'canceled', 'lost', 'deleted', 'duplicate', 'duplicated', 'void', 'voided',
] as const
export const _JOB_STATUS_FINISHED = [
  'complete', 'completed', 'invoiced', 'paid', 'closed', 'archived',
] as const
export const _MAKESAFE_SUBSTATUS_FINISHED = [
  'complete', 'completed', 'ready_to_invoice', 'admin_to_send_report', 'invoiced',
] as const
// Assignment statuses treated as OPEN (eligible to be auto-closed). Mirrors the
// board's open columns and the U1 script's OPEN set.
export const _OPEN_ASSIGNMENT_STATUSES = ['scheduled', 'confirmed', 'draft'] as const

// Which assignment statuses RELEASE a job back to an open pool by status ALONE.
// Only 'cancelled', in BOTH pools: a dead allocation never holds a job, but a
// FINISHED one still does. Status cannot distinguish a finished visit from a
// re-opened one — clock_event('clock_off') writes job_assignments.status =
// 'complete' (and the trade app's updateMyAssignment / updateJobPhase do the
// same) without touching jobs.status or makesafe_job_details. Releasing on
// status would re-offer work a crew has just done to a second crew, and render
// it twice, since the windowed feed still carries that 'complete' card.
export const _POOL_RELEASING_STATUSES = ['cancelled'] as const

export function _poolReleasingStatusFilter(): string {
  return '(' + _POOL_RELEASING_STATUSES.map((s) => `"${s}"`).join(',') + ')'
}

export type PoolOccupancyKind = 'makesafe' | 'vertical'

// The ONE durable proof that a finished make-safe visit was deliberately sent
// back to the pool: reattendMakesafe stamps makesafe_job_details.last_reattend_at
// (nothing else writes that column) and deliberately creates no assignment, so
// the card must become tap-to-allocate again. A completed visit therefore
// releases only when it finished BEFORE that stamp — the re-attend crew's own
// later completion holds the job again. No stamp, or timestamps we cannot read,
// means still occupied: unfinished work is never re-offered.
//
// "When it finished" is answered ONLY by the two stamps that record finishing
// the work — completed_at and clocked_off_at, both written by the trade clock
// path and by nothing else. updated_at is deliberately NOT consulted: the
// trg_job_assignments_updated trigger bumps it on every write to the row, so
// stamping invoiced_in (submit_trade_invoice), acknowledged_at, a confirmation
// change or any dashboard edit would silently re-date a long-finished visit past
// the re-attend and strand the card as occupied forever. Rows closed without
// either stamp (closeOpenAssignmentsForJob, a dashboard status edit) carry no
// evidence of when the work finished, so they keep holding the job.
export function _assignmentFinishedAt(assignment: any): number | null {
  let latest: number | null = null
  for (const raw of [assignment?.completed_at, assignment?.clocked_off_at]) {
    const parsed = Date.parse(String(raw ?? ''))
    if (Number.isFinite(parsed) && (latest === null || parsed > latest)) latest = parsed
  }
  return latest
}

export function _makesafeReattendReleases(assignment: any, reattendAt: unknown): boolean {
  if (String(assignment?.status || '').toLowerCase() !== 'complete') return false
  const reopenedAt = Date.parse(String(reattendAt ?? ''))
  if (!Number.isFinite(reopenedAt)) return false
  const finishedAt = _assignmentFinishedAt(assignment)
  if (finishedAt === null) return false
  return reopenedAt > finishedAt
}

// Does this assignment still HOLD its job for this pool's semantics? Both the
// de-dupe seed and the DB occupancy probe route through this one predicate; if
// they ever answered differently the pool would re-emit an occupied job as an
// 'available' card while the feed still showed the crew's own card.
export function _assignmentHoldsPoolJob(
  assignment: any,
  pool: PoolOccupancyKind,
  reattendAtByJobId: Record<string, unknown> = {},
): boolean {
  const status = String(assignment?.status || '').toLowerCase()
  if ((_POOL_RELEASING_STATUSES as readonly string[]).includes(status)) return false
  if (pool !== 'makesafe') return true
  const jobId = String(assignment?.jobs?.id || assignment?.job_id || '')
  return !_makesafeReattendReleases(assignment, reattendAtByJobId[jobId])
}

// The windowed assignment feed is NOT status-filtered beyond 'cancelled', so it
// still carries finished visits. A pool's de-duplication seed must therefore ask
// the same question its occupancy probe does: does a row that still HOLDS this
// job (for this pool's semantics) exist in the feed?
export function _activeAssignedJobIds(
  assignments: any[],
  pool: PoolOccupancyKind,
  reattendAtByJobId: Record<string, unknown> = {},
): Set<string> {
  const ids = new Set<string>()
  for (const assignment of (assignments || [])) {
    const jobId = assignment?.jobs?.id
    if (!jobId) continue
    if (!_assignmentHoldsPoolJob(assignment, pool, reattendAtByJobId)) continue
    ids.add(jobId)
  }
  return ids
}

// Map a jobs.status to the assignment close mode, or null when not terminal.
export function _closeAsForJobStatus(status: string | null | undefined): 'complete' | 'cancelled' | null {
  const s = String(status || '').toLowerCase()
  if ((_JOB_STATUS_DEAD as readonly string[]).includes(s)) return 'cancelled'
  if ((_JOB_STATUS_FINISHED as readonly string[]).includes(s)) return 'complete'
  return null
}
// Map a make-safe substatus to the assignment close mode, or null when the
// substatus is not a finished one. Finished make-safe work is always 'complete'.
export function _closeAsForMakesafeSubstatus(substatus: string | null | undefined): 'complete' | null {
  const s = String(substatus || '').toLowerCase()
  if ((_MAKESAFE_SUBSTATUS_FINISHED as readonly string[]).includes(s)) return 'complete'
  return null
}

// U2a: close every still-open crew assignment for a job when the job/make-safe
// reaches a terminal state. NON-BLOCKING by contract — the caller has already
// committed the real status write, so a failure here (or a missing row) must
// never surface as a failed transition. Idempotent: a repeat call finds no open
// rows and no-ops. Never texts / notifies (M3b: updates are silent). Returns the
// number of assignments closed (0 on failure or when there was nothing to close).
//
// Date belt split by close mode (FM review, PR #319):
//  - closeAs 'cancelled' (dead job — cancelled/lost/deleted/…): close ALL open
//    rows, INCLUDING strictly-future bookings. A dead job's future visits are
//    genuinely dead.
//  - closeAs 'complete' (finished job — invoiced/complete/archived/…): close
//    every open row EXCEPT a strictly-future dated one. A STRICTLY-FUTURE row
//    survives, so a make-safe RE-ATTEND still booked when an earlier attendance
//    is invoiced stays on the run sheet / calendar (the unconditional close would
//    otherwise silently kill it). A null-dated open row on a finished job IS
//    closed — an undated open assignment on finished work is stale by definition
//    (a deliberate future booking always carries a date). All 510 verified stale
//    rows are past-dated, so the belt costs nothing on the existing backlog.
async function closeOpenAssignmentsForJob(
  client: any,
  jobId: string,
  closeAs: 'complete' | 'cancelled',
): Promise<number> {
  try {
    if (!jobId) return 0
    let query = client
      .from('job_assignments')
      .update({ status: closeAs, updated_at: new Date().toISOString() })
      .eq('job_id', jobId)
      .in('status', _OPEN_ASSIGNMENT_STATUSES as unknown as string[])
    if (closeAs === 'complete') {
      // Survive strictly-future dated rows only; null-dated + today + past close.
      query = query.or(`scheduled_date.is.null,scheduled_date.lte.${getAWSTDate()}`)
    }
    const { data, error } = await query.select('id')
    if (error) throw error
    const closed = (data || []).length
    if (closed > 0) {
      console.log(`[ops-api] closeOpenAssignmentsForJob: closed ${closed} open assignment(s) on job ${jobId} as ${closeAs}`)
    }
    return closed
  } catch (e) {
    console.log('[ops-api] closeOpenAssignmentsForJob failed (non-blocking):', (e as Error)?.message)
    return 0
  }
}
export const _closeOpenAssignmentsForJobForTest = closeOpenAssignmentsForJob

async function getTradeJobForAccess(client: any, jobId: string): Promise<any> {
  const { data, error } = await client
    .from('jobs')
    .select('id, org_id, type, job_number, status')
    .eq('id', jobId)
    .maybeSingle()
  if (error) throw error
  if (!data) throw new Error('Job not found')
  return data
}

export type TradeJobAccessContext = {
  orgId: string
  managedVerticals?: unknown
}

async function assertAssignedOrMakesafeAccess(
  client: any,
  jobId: string,
  userId: string,
  isAdmin = false,
  access?: TradeJobAccessContext,
) {
  let job: any = null
  if (access?.orgId) {
    job = await getTradeJobForAccess(client, jobId)
    if (String(job.org_id || '') !== access.orgId) {
      throw new Error('You are not authorized to access this job')
    }
  }
  if (isAdmin) return
  try {
    await assertAssigned(client, jobId, userId, isAdmin)
    return
  } catch (err) {
    if (!job) job = await getTradeJobForAccess(client, jobId)
    const managedVerticals = _normalizeManagedVerticals(access?.managedVerticals)
    if (managedVerticals.includes(_jobVertical(job))) return
    // MakeSafe report fallback: any logged-in trade may open/report an open
    // MakeSafe even before ops has created a named assignment. This keeps the
    // field-report flow moving when the board/admin upload step is behind, while
    // ordinary patio/fencing/decking jobs remain allocation-gated below.
    if (await isMakesafeAccessJobForClient(client, job)) return
    throw err
  }
}
export const _assertAssignedOrMakesafeAccessForTest = assertAssignedOrMakesafeAccess

async function assertMakesafeJob(client: any, jobId: string) {
  const job = await getTradeJobForAccess(client, jobId)
  if (!(await isMakesafeAccessJobForClient(client, job))) throw new Error('MakeSafe job required')
}

export function _isMakesafeAccessJobForTest(job: any): boolean {
  return isMakesafeAccessJob(job)
}

export function _isOpenTradeMakesafeDetailForTest(detail: any): boolean {
  return isOpenTradeMakesafeDetail(detail)
}

export function _backfillOpenMakesafeContactsForTest(openMakesafes: any[], contacts: any[]) {
  const contactByJob: Record<string, any> = {}
  for (const c of (contacts || [])) {
    if (!c?.job_id || !c.client_phone) continue
    const existing = contactByJob[c.job_id]
    if (!existing || c.is_primary || (!existing.is_primary && String(c.contact_label || '').localeCompare(String(existing.contact_label || '')) < 0)) {
      contactByJob[c.job_id] = c
    }
  }
  for (const job of (openMakesafes || []) as any[]) {
    const c = contactByJob[job.id]
    if (!c) continue
    job.client_phone = job.client_phone || c.client_phone || null
    job.client_email = job.client_email || c.client_email || null
    job.contact_phone = c.client_phone || null
    job.contact_name = c.client_name || null
  }
  return openMakesafes
}

async function enrichTradeMakesafeJobs(client: any, jobs: any[]) {
  const list = (jobs || []).filter(Boolean)
  const jobIds = list.map((job: any) => job?.id).filter(Boolean)
  if (jobIds.length === 0) return list

  const detailByJobId: Record<string, any> = {}
  try {
    const { data: details } = await client.from('makesafe_job_details')
      .select('*, makesafe_companies:requesting_company_id(slug, name)')
      .in('job_id', jobIds)
    for (const row of (details || [])) if (row?.job_id) detailByJobId[String(row.job_id)] = row
    for (const job of list) {
      if (job?.id && detailByJobId[job.id]) job.makesafe_details = detailByJobId[job.id]
    }
  } catch (e: any) {
    console.log('[ops-api] trade MakeSafe detail enrichment skipped:', e?.message)
  }

  const phoneMissingJobIds = list
    .filter((job: any) => job?.id && (isMakesafeAccessJob(job) || detailByJobId[job.id]) && !job.client_phone)
    .map((job: any) => job.id)
  if (phoneMissingJobIds.length > 0) {
    try {
      const { data: contacts, error: contactErr } = await client.from('job_contacts')
        .select('job_id, client_name, client_email, client_phone, is_primary, contact_label, status')
        .in('job_id', phoneMissingJobIds)
        .eq('status', 'active')
      if (contactErr) throw contactErr
      _backfillOpenMakesafeContactsForTest(list as any[], contacts || [])
    } catch (e: any) {
      console.log('[ops-api] trade MakeSafe contact enrichment skipped:', e?.message)
    }
  }

  return list
}

export function _groupTradeAssignmentsForTest(assignments: any[], today: string, weekEnd: string) {
  const grouped: any = {
    today: [] as any[],
    thisWeek: [] as any[],
    upcoming: [] as any[],
    recent: [] as any[],
    unscheduled: [] as any[],
    makesafePool: [] as any[],
  }
  for (const a of (assignments || [])) {
    // Open-pool cards (make-safe OR any managed vertical: fencing_open /
    // patio_open / decking_open) go to the pool bucket, never the dated
    // today/thisWeek buckets. The bucket key stays `makesafePool` for client
    // compatibility; it is the generic open-pool lane.
    const openType = String(a?.assignment_type || '')
    const openRole = String(a?.role || '')
    if (openType.endsWith('_open') || openRole.endsWith('_open')) {
      grouped.makesafePool.push(a)
      continue
    }
    const d = a?.scheduled_date || ''
    if (!d) {
      grouped.unscheduled.push(a)
      continue
    }
    if (d < today) grouped.recent.push(a)
    else if (d === today) grouped.today.push(a)
    else if (d <= weekEnd) grouped.thisWeek.push(a)
    else grouped.upcoming.push(a)
  }
  return grouped
}

// ── Make-safe pool visibility (trade app) ──────────────────────────────────
// Statuses that EXCLUDE a make-safe job from the open trade pool. Extracted to a
// single constant so the two queries that build the pool cannot drift and so the
// exclusion contract (notably 'archived') can be unit-tested. Rendered into a
// PostgREST `not in (...)` filter via _makesafePoolExcludedStatusFilter().
export const _MAKESAFE_POOL_EXCLUDED_STATUSES = [
  'cancelled', 'archived', 'lost', 'deleted', 'complete', 'completed',
  'invoiced', 'paid', 'closed', 'duplicate', 'duplicated', 'void', 'voided',
] as const

export function _makesafePoolExcludedStatusFilter(): string {
  return '(' + _MAKESAFE_POOL_EXCLUDED_STATUSES.map((s) => `"${s}"`).join(',') + ')'
}

// Pure resolver for trade-app make-safe visibility. Single source of truth used
// by the route and unit tests.
//  - Dispatcher (admin / ops_manager): see-all view of every job PLUS the full
//    open make-safe pool. Runs with showAll=true.
//  - Make-safe manager (users.makesafe_manager = true, e.g. Hugo + Nithin): NOT a
//    dispatcher. Gets the SAME full open make-safe pool UNIONED with only their
//    own assignments. showAll stays false so the per-user assignment query runs.
export function _resolveMakesafeVisibility(
  input: { role?: string | null; makesafeManager?: boolean | null },
): { isAdmin: boolean; isDispatcher: boolean; isMakesafeManager: boolean; canSeeMakesafePool: boolean } {
  const role = String(input?.role || '').toLowerCase()
  const isAdmin = role === 'admin'
  const isDispatcher = isAdmin || role === 'ops_manager'
  const isMakesafeManager = input?.makesafeManager === true
  return { isAdmin, isDispatcher, isMakesafeManager, canSeeMakesafePool: isDispatcher || isMakesafeManager }
}

// Gate used inside myJobs: a flagged make-safe manager gets the same full
// non-archived make-safe pool a dispatcher gets.
export function _canSeeFullMakesafePool(isDispatcher: boolean, isMakesafeManager: boolean): boolean {
  return isDispatcher === true || isMakesafeManager === true
}

// ── Manager View — per-vertical manager visibility + allocation ────────────
// Marnin's locked model (2026-07-05): manager rights are ONE list per user
// (users.managed_verticals), NOT three bespoke per-vertical booleans. A managed
// vertical grants (a) the full open pool of that vertical in the trade app and
// (b) allocation rights over that vertical. Values align to jobs.type. This
// generalises the make-safe-only flag (users.makesafe_manager, now backfilled
// into managed_verticals) to fencing / patio / decking with one mechanism.
export const _MANAGED_VERTICALS = ['makesafe', 'fencing', 'patio', 'decking'] as const

// Normalise a raw managed_verticals value (DB array, possibly null / mixed-case
// / unknown entries) into a clean, de-duplicated list of valid verticals.
export function _normalizeManagedVerticals(input: unknown): string[] {
  if (!Array.isArray(input)) return []
  const valid = _MANAGED_VERTICALS as readonly string[]
  const out: string[] = []
  for (const raw of input) {
    const v = String(raw ?? '').trim().toLowerCase()
    if (valid.includes(v) && !out.includes(v)) out.push(v)
  }
  return out
}

// Pure resolver for trade-app manager visibility, generalised from
// _resolveMakesafeVisibility to every vertical. Single source of truth used by
// the trade route + unit tests.
//  - Dispatcher (admin / ops_manager): unchanged see-all behaviour + make-safe
//    pool. isMakesafeManager / canSeeMakesafePool preserve the exact make-safe
//    semantics the live flag gave (Hugo keeps the pool via the backfill).
//  - Vertical manager (managed_verticals contains the vertical): gets that
//    vertical's open pool unioned with their own assignments, WITHOUT dispatcher
//    see-all.
//  - poolVerticals: the set of verticals whose open pool myJobs should union in
//    — every managed vertical, PLUS 'makesafe' for any dispatcher (so the
//    dispatcher make-safe pool survives even with an empty managed list).
export function _resolveManagerVisibility(
  input: { role?: string | null; managedVerticals?: unknown },
): {
  isAdmin: boolean
  isDispatcher: boolean
  managedVerticals: string[]
  poolVerticals: string[]
  isMakesafeManager: boolean
  canSeeMakesafePool: boolean
} {
  const role = String(input?.role || '').toLowerCase()
  const isAdmin = role === 'admin'
  const isDispatcher = isAdmin || role === 'ops_manager'
  const managedVerticals = _normalizeManagedVerticals(input?.managedVerticals)
  const isMakesafeManager = managedVerticals.includes('makesafe')
  const canSeeMakesafePool = isDispatcher || isMakesafeManager
  const poolSet = new Set<string>(managedVerticals)
  if (canSeeMakesafePool) poolSet.add('makesafe')
  // Deterministic order (matches _MANAGED_VERTICALS) so tests + payloads are stable.
  const poolVerticals = (_MANAGED_VERTICALS as readonly string[]).filter((v) => poolSet.has(v))
  return { isAdmin, isDispatcher, managedVerticals, poolVerticals, isMakesafeManager, canSeeMakesafePool }
}

// U2b (manager's Board accuracy): the verticals whose WHOLE board a vertical
// manager may see via my_jobs(mode:'all'). A dispatcher already gets global
// showAll, so this is empty for them; a non-dispatcher with managed_verticals
// viewing the board (mode:'all') gets exactly their managed verticals — the
// SAME set allocate_job authorises (no new global exposure). Any other mode
// (personal 'mine' / default) returns [] so the personal Jobs view is untouched.
export function _managerBoardVerticals(
  input: { isDispatcher: boolean; mode?: string | null; managedVerticals?: unknown },
): string[] {
  if (input.isDispatcher) return []
  if (String(input.mode || '') !== 'all') return []
  return _normalizeManagedVerticals(input.managedVerticals)
}

// The vertical a job belongs to, for allocation-authz + pool purposes. Make-safe
// wins on either jobs.type='makesafe' OR an SWMS- job_number (mirrors
// isMakesafeAccessJob); otherwise the plain jobs.type (lower-cased).
export function _jobVertical(job: any): string {
  if (isMakesafeAccessJob(job)) return 'makesafe'
  return String(job?.type || '').trim().toLowerCase()
}

// Pure resolver for who may create / move / delete a job_assignment. The ops
// dashboard's create/update/delete_assignment path and the trade-side
// allocate_job path share it. Marnin's rule: a privileged server key (ops
// dashboard SW_API_KEY / service role, authMode='api_key') or a dispatcher
// (admin / owner / ops_manager JWT) may allocate ANY job; a vertical manager may
// allocate ONLY jobs of a vertical they manage; anyone else (a plain installer
// JWT) is refused. The scoped make-safe routine may never mutate assignments
// (also blocked upstream by the default-deny allow-list; refused here too).
export function _resolveAllocationAuthz(input: {
  authMode: 'api_key' | 'jwt' | 'routine'
  callerRole?: string | null
  managedVerticals?: unknown
  jobVertical?: string | null
}): { allowed: boolean; reason: string } {
  if (input.authMode === 'api_key') return { allowed: true, reason: 'api_key' }
  if (input.authMode === 'routine') return { allowed: false, reason: 'routine_forbidden' }
  const role = String(input.callerRole || '').toLowerCase()
  if (role === 'admin' || role === 'owner' || role === 'ops_manager') {
    return { allowed: true, reason: 'dispatcher' }
  }
  const managed = _normalizeManagedVerticals(input.managedVerticals)
  const vertical = String(input.jobVertical || '').trim().toLowerCase()
  if (vertical && managed.includes(vertical)) {
    return { allowed: true, reason: 'vertical_manager' }
  }
  return { allowed: false, reason: 'not_authorized' }
}

// Availability is an identity fact, not a display-window fact: a pool job is
// "available" only when it has NO active assignment at ANY date, including rows
// whose scheduled_date is NULL or older than the feed's display window. Every
// open pool must answer that question the same way, so both the make-safe and
// the generic per-vertical pool route through this probe.
//
// "Active" here means STILL HOLDING (_assignmentHoldsPoolJob): a 'cancelled' row
// has released the job, and a make-safe's 'complete' row releases only once a
// re-attend stamp proves the card was deliberately reopened — so the re-attend
// flow pools again without a plain clock-off re-offering unfinished work.
//
// It returns the OCCUPYING ASSIGNMENT, not just the id, because a pool job that
// is occupied outside the display window must still render — as an assigned card
// with crew attribution. Dropping it would trade a wrongly-clickable card for an
// invisible one, against the B2 rationale above ("never drop off the trade's
// list silently").
//
// The probe is chunked AND paged: job_assignments holds one row per crew per
// date, so an 80-job pool of long multi-day jobs can blow past PostgREST's
// 1000-row cap. A silently truncated probe would re-introduce exactly the false
// "available" card it exists to prevent, so never issue it as one unbounded read.
// Chunking is only a URL-length guard and the chunks are independent, so they run
// concurrently; the page loop inside each chunk is what guarantees completeness.
// Paging also demands a TOTAL order: job_id is highly non-unique here (that is the
// very reason paging exists), and Postgres may return rows tied on it in a
// different order per LIMIT/OFFSET query, silently skipping a row on a page
// boundary. The unique id tiebreak below closes that seam.
const OCCUPANCY_PROBE_CHUNK = 25
const OCCUPANCY_PROBE_PAGE = 1000
const OCCUPANCY_PROBE_SELECT = `
        job_id, id, scheduled_date, scheduled_end, start_time, status, role, notes, assignment_type, crew_name,
        started_at, completed_at, clocked_on_at, clocked_off_at, travel_started_at, arrived_at, break_minutes, job_phase,
        user:user_id ( id, name )
      `

// Deterministic pick when a job carries several active assignments: on the
// personal lens the viewer's OWN row wins (it is the only one they may recover),
// then the latest scheduled row (NULL dates sort lowest), id as the tiebreak.
function occupancyOutranks(candidate: any, current: any, preferUserId = ''): boolean {
  if (preferUserId) {
    const candidateIsViewer = String(candidate?.user?.id || '') === preferUserId
    const currentIsViewer = String(current?.user?.id || '') === preferUserId
    if (candidateIsViewer !== currentIsViewer) return candidateIsViewer
  }
  const candidateDate = String(candidate?.scheduled_date || '')
  const currentDate = String(current?.scheduled_date || '')
  if (candidateDate !== currentDate) return candidateDate > currentDate
  return String(candidate?.id || '') > String(current?.id || '')
}

async function fetchOccupyingAssignments(
  client: any,
  jobIds: string[],
  preferUserId = '',
  pool: PoolOccupancyKind = 'vertical',
  reattendAtByJobId: Record<string, unknown> = {},
): Promise<Map<string, any>> {
  const byJobId = new Map<string, any>()
  const ids = Array.from(new Set((jobIds || []).filter(Boolean).map((id: any) => String(id))))
  const chunks: string[][] = []
  for (let i = 0; i < ids.length; i += OCCUPANCY_PROBE_CHUNK) {
    chunks.push(ids.slice(i, i + OCCUPANCY_PROBE_CHUNK))
  }
  const chunkRows = await Promise.all(chunks.map(async (chunk) => {
    const rows: any[] = []
    let offset = 0
    while (true) {
      const { data, error } = await client
        .from('job_assignments')
        .select(OCCUPANCY_PROBE_SELECT)
        .in('job_id', chunk)
        .not('status', 'in', _poolReleasingStatusFilter())
        .order('job_id', { ascending: true })
        .order('id', { ascending: true })
        .range(offset, offset + OCCUPANCY_PROBE_PAGE - 1)
      if (error) throw error
      const page = data || []
      rows.push(...page)
      if (page.length < OCCUPANCY_PROBE_PAGE) break
      offset += OCCUPANCY_PROBE_PAGE
    }
    return rows
  }))
  for (const row of chunkRows.flat()) {
    const jobId = row?.job_id ? String(row.job_id) : ''
    if (!jobId) continue
    if (!_assignmentHoldsPoolJob(row, pool, reattendAtByJobId)) continue
    const current = byJobId.get(jobId)
    if (!current || occupancyOutranks(row, current, preferUserId)) byJobId.set(jobId, row)
  }
  return byJobId
}
export const _fetchOccupyingAssignmentsForTest = fetchOccupyingAssignments

// The re-attend stamps for exactly the pool ids being resolved. This is the only
// signal that ever hands a finished make-safe back to the pool, so it must be
// COMPLETE for every id asked about: a stamp missing because a capped, unordered
// scan happened not to return that job's row would strand a genuinely re-attended
// card as permanently occupied (reattendMakesafe creates no assignment, so
// tap-to-allocate would never come back). Keyed by job_id, which is the table's
// primary key, and chunked + paged on the same guards as the occupancy probe.
async function fetchMakesafeReattendStamps(client: any, jobIds: string[]): Promise<Record<string, unknown>> {
  const stamps: Record<string, unknown> = {}
  const ids = Array.from(new Set((jobIds || []).filter(Boolean).map((id: any) => String(id))))
  const chunks: string[][] = []
  for (let i = 0; i < ids.length; i += OCCUPANCY_PROBE_CHUNK) {
    chunks.push(ids.slice(i, i + OCCUPANCY_PROBE_CHUNK))
  }
  const chunkRows = await Promise.all(chunks.map(async (chunk) => {
    const rows: any[] = []
    let offset = 0
    while (true) {
      const { data, error } = await client
        .from('makesafe_job_details')
        .select('job_id, last_reattend_at')
        .in('job_id', chunk)
        .order('job_id', { ascending: true })
        .range(offset, offset + OCCUPANCY_PROBE_PAGE - 1)
      if (error) throw error
      const page = data || []
      rows.push(...page)
      if (page.length < OCCUPANCY_PROBE_PAGE) break
      offset += OCCUPANCY_PROBE_PAGE
    }
    return rows
  }))
  for (const row of chunkRows.flat()) {
    const jobId = row?.job_id ? String(row.job_id) : ''
    if (!jobId || !row?.last_reattend_at) continue
    stamps[jobId] = row.last_reattend_at
  }
  return stamps
}
export const _fetchMakesafeReattendStampsForTest = fetchMakesafeReattendStamps

// An occupied pool job is NEVER emitted as available. Whether it is additionally
// recovered as an assigned card depends on the lens. Callers only reach this for
// a job ALREADY absent from the emitted assignment set — the pool loops skip
// anything the feed carried — so this deliberately does not second-guess the
// feed's window. The make-safe pool's legacy `detailJobIds` backstop surfaces
// jobs the feed's `type.eq.makesafe,job_number.ilike.SWMS-%` filter can never
// match at ANY date, and those must still render as the crew's card.
//  - 'everyone' (dispatcher showAll / vertical manager on mode:'all'): recover
//    the allocation; the pool query already bounded it to same-tenant
//    managed-vertical work.
//  - 'mine' (personal view): the feed is own-only, so recover only the viewer's
//    OWN allocation. Another crew's work stays out of the personal dated lanes;
//    the manager sees it on the Board (mode:'all').
export function _shouldRecoverOccupiedPoolJob(input: {
  occupying: any
  lens: 'everyone' | 'mine'
  userId: string
}): boolean {
  if (!input.occupying) return false
  if (input.lens === 'everyone') return true
  return String(input.occupying?.user?.id || '') === String(input.userId || '')
}

// An occupied pool job rendered honestly: the real assignment (crew, dates,
// clock state) carried on the already tenant+vertical-authorized pool job. Never
// an `_open` assignment_type/role, so the grouper keeps it out of the pool lane.
function occupiedPoolAssignmentCard(assignment: any, job: any) {
  return {
    id: assignment?.id,
    scheduled_date: assignment?.scheduled_date ?? null,
    scheduled_end: assignment?.scheduled_end ?? null,
    start_time: assignment?.start_time ?? null,
    status: assignment?.status ?? 'scheduled',
    role: assignment?.role ?? null,
    notes: assignment?.notes ?? null,
    assignment_type: assignment?.assignment_type ?? null,
    crew_name: assignment?.crew_name ?? null,
    started_at: assignment?.started_at ?? null,
    completed_at: assignment?.completed_at ?? null,
    clocked_on_at: assignment?.clocked_on_at ?? null,
    clocked_off_at: assignment?.clocked_off_at ?? null,
    travel_started_at: assignment?.travel_started_at ?? null,
    arrived_at: assignment?.arrived_at ?? null,
    break_minutes: assignment?.break_minutes ?? null,
    job_phase: assignment?.job_phase ?? null,
    user: assignment?.user ?? null,
    jobs: job,
  }
}

export async function myJobs(
  client: any,
  userId: string,
  showAll = false,
  isDispatcher = false,
  isMakesafeManager = false,
  poolVerticals: string[] = [],
  managerScopeVerticals: string[] = [],
  orgId = DEFAULT_ORG_ID,
) {
  // U2b: manager's-Board widening. When set (non-dispatcher manager on
  // mode:'all'), the assignment query returns ALL in-vertical assignments across
  // every crew, not just this user's — scoped strictly to these verticals. Never
  // set for a dispatcher (they use showAll) or the personal view.
  const managerScope = !showAll ? _normalizeManagedVerticals(managerScopeVerticals) : []
  const today = getAWSTDate()
  const thirtyDaysAgo = new Date(Date.now() + AWST_OFFSET_MS)
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30)
  // B2: make-safe assignments can be allocated weeks before the scheduled date or
  // span insurance processing windows longer than 30 days. Use a 180-day backstop
  // so allocated make-safe jobs never drop off the trade's list silently.
  // Non-make-safe assignments keep the original 30-day window.
  const makesafeSixMonthsAgo = new Date(Date.now() + AWST_OFFSET_MS)
  makesafeSixMonthsAgo.setDate(makesafeSixMonthsAgo.getDate() - 180)
  // Which allocations the open pools are entitled to re-surface as assigned cards.
  const poolLens: 'everyone' | 'mine' = showAll || managerScope.length > 0 ? 'everyone' : 'mine'
  const poolRecoveryUserId = poolLens === 'mine' ? userId : ''

  const ASSIGNMENT_SELECT_ADMIN = `
        id, scheduled_date, scheduled_end, start_time, status, role, notes, assignment_type, crew_name, started_at, completed_at,
        clocked_on_at, clocked_off_at, travel_started_at, arrived_at, break_minutes, job_phase,
        user:user_id ( id, name ),
        jobs:job_id (
          id, type, status, client_name, client_phone, client_email,
          site_address, site_suburb, notes, job_number
        )
      `
  const ASSIGNMENT_SELECT_USER = `
        id, scheduled_date, scheduled_end, start_time, status, role, notes, assignment_type, crew_name, started_at, completed_at,
        clocked_on_at, clocked_off_at, travel_started_at, arrived_at, break_minutes, job_phase,
        jobs:job_id (
          id, type, status, client_name, client_phone, client_email,
          site_address, site_suburb, notes, job_number
        )
      `
  // Same columns as the admin select but with an INNER join on jobs so a
  // referenced-table filter on jobs.type actually CONSTRAINS the parent rows
  // (PostgREST semantics — see the make-safe backstop note below). Used only by
  // the U2b manager's-Board query.
  const ASSIGNMENT_SELECT_ADMIN_INNER = ASSIGNMENT_SELECT_ADMIN.replace('jobs:job_id (', 'jobs:job_id!inner (')
  // Guard the string-derivation: if the admin select's embed spelling ever
  // changes, replace() silently no-ops and the manager query would stop
  // constraining by vertical. Fail loudly instead.
  if (ASSIGNMENT_SELECT_ADMIN_INNER === ASSIGNMENT_SELECT_ADMIN) {
    throw new Error('ASSIGNMENT_SELECT_ADMIN_INNER inner-join derivation failed — embed spelling changed')
  }

  let assignments: any[]
  let error: any

  if (showAll) {
    // ── Admin mode: show ALL assignments across all users, ONE tenant ──
    // "See everything" is bounded by the dispatcher's own org: tenant is a
    // boundary, not a display preference, and every pool below is already
    // org-scoped. Uses the INNER select so the jobs.org_id filter constrains the
    // parent job_assignments rows (PostgREST semantics — see the note below).
    const res = await client
      .from('job_assignments')
      .select(ASSIGNMENT_SELECT_ADMIN_INNER)
      .neq('status', 'cancelled')
      .gte('scheduled_date', thirtyDaysAgo.toISOString().slice(0, 10))
      .eq('jobs.org_id', orgId)
      .order('scheduled_date', { ascending: true })
    assignments = res.data
    error = res.error
  } else if (managerScope.length > 0) {
    // ── Manager's Board (U2b): all in-vertical assignments across every crew ──
    // A vertical manager (non-dispatcher) on mode:'all' sees the WHOLE vertical,
    // so widen past this user's own rows to every assignment whose job's vertical
    // is one they manage — regardless of user_id — using the admin select (which
    // carries the crew user, needed for the board's lanes). Scope is strictly
    // managerScope (their managed_verticals), matching allocate_job authz: a
    // fencing manager gets fencing only, etc. Make-safe is matched by type OR an
    // SWMS- job_number, mirroring _jobVertical + the open-pool query.
    //
    // Fencing is the planning range: managers need every historic, future, and
    // unscheduled allocation. Other verticals retain the existing rolling
    // window/backstop behavior. Splitting the query preserves the conservative
    // MakeSafe model while allowing mixed-vertical managers a complete fencing
    // lane without widening their other lanes.
    //
    // Because the open pools below de-dupe
    // against this same (now vertical-wide) `assignments` set, jobs already
    // assigned to OTHER crew can no longer show as false "available" cards.
    const verticalFilter = (verticals: string[]) => verticals.flatMap((v) =>
      v === 'makesafe' ? ['type.eq.makesafe', 'job_number.ilike.SWMS-%'] : [`type.eq.${v}`]
    ).join(',')
    const rollingVerticals = managerScope.filter((vertical) => vertical !== 'fencing')
    assignments = []
    error = null

    if (rollingVerticals.length > 0) {
      const rolling = await client
        .from('job_assignments')
        .select(ASSIGNMENT_SELECT_ADMIN_INNER)
        .neq('status', 'cancelled')
        .gte('scheduled_date', thirtyDaysAgo.toISOString().slice(0, 10))
        .eq('jobs.org_id', orgId)
        .or(verticalFilter(rollingVerticals), { referencedTable: 'jobs' })
        .order('scheduled_date', { ascending: true })
      assignments.push(...(rolling.data || []))
      error = rolling.error
    }

    if (!error && managerScope.includes('fencing')) {
      const FENCING_ASSIGNMENT_PAGE = 1000
      let offset = 0
      while (true) {
        const pageResult = await client
          .from('job_assignments')
          .select(ASSIGNMENT_SELECT_ADMIN_INNER)
          .neq('status', 'cancelled')
          .eq('jobs.org_id', orgId)
          .or(verticalFilter(['fencing']), { referencedTable: 'jobs' })
          .order('scheduled_date', { ascending: true })
          .order('id', { ascending: true })
          .range(offset, offset + FENCING_ASSIGNMENT_PAGE - 1)
        if (pageResult.error) {
          error = pageResult.error
          break
        }
        const pageRows = pageResult.data || []
        assignments.push(...pageRows)
        if (pageRows.length < FENCING_ASSIGNMENT_PAGE) break
        offset += FENCING_ASSIGNMENT_PAGE
      }
    }

    // Mixed scopes can overlap only through malformed data, but de-duplicating
    // by the canonical assignment id also makes retries/page boundaries safe.
    assignments = [...new Map(assignments.map((row: any) => [row.id, row])).values()]
  } else {
    // ── Normal mode: only this user's assignments ──
    const res = await client
      .from('job_assignments')
      .select(ASSIGNMENT_SELECT_USER)
      .eq('user_id', userId)
      .neq('status', 'cancelled')
      .gte('scheduled_date', thirtyDaysAgo.toISOString().slice(0, 10))
      .order('scheduled_date', { ascending: true })
    assignments = res.data
    error = res.error
  }

  if (error) throw error

  // B2: Backstop for make-safe assignments older than 30 days. A second query
  // fetches make-safe jobs (by jobs.type or job_number prefix) that were allocated
  // to this trade but fall outside the standard 30-day window. Results are
  // de-duplicated by assignment ID so there is no double-counting.
  //
  // PostgREST semantics (supabase-js v2): to make an embedded-table filter actually
  // CONSTRAIN the parent job_assignments rows (not just shape the embedded payload),
  // the embed MUST be an INNER join (`jobs:job_id!inner(...)`) AND the filter must be
  // applied with `{ referencedTable: 'jobs' }` using column names relative to jobs.
  // A plain embed + top-level `jobs.type` filter does NOT constrain the parent and
  // would either error or return ALL of the trade's old assignments — both wrong.
  const ASSIGNMENT_SELECT_USER_MAKESAFE = `
        id, scheduled_date, scheduled_end, start_time, status, role, notes, assignment_type, crew_name, started_at, completed_at,
        clocked_on_at, clocked_off_at, travel_started_at, arrived_at, break_minutes, job_phase,
        jobs:job_id!inner (
          id, type, status, client_name, client_phone, client_email,
          site_address, site_suburb, notes, job_number
        )
      `
  // U2b + ship-review FIX 1: the personal path runs this backstop per-user; the
  // manager's-Board path MUST run it too when the scope includes make-safe —
  // pre-U2b a make-safe manager's mode:'all' took the personal path (backstop
  // included), so skipping it here silently dropped >30-day make-safe
  // assignments from `assignments` AND let the open pool below re-surface those
  // jobs as false "available" cards (double-allocation risk). For a make-safe
  // manager the SAME 180-day window runs VERTICAL-WIDE (no user_id filter,
  // admin select so board lanes keep the crew user). Managers without
  // 'makesafe' in scope (e.g. fencing) are unaffected — the backstop is
  // make-safe-only by its jobs filter. Dispatchers (showAll) unchanged.
  const runManagerMakesafeBackstop = managerScope.includes('makesafe')
  if (!showAll && (managerScope.length === 0 || runManagerMakesafeBackstop)) {
    try {
      const existing30DayIds = new Set((assignments || []).map((a: any) => a.id))
      let backstopQuery = client
        .from('job_assignments')
        .select(runManagerMakesafeBackstop ? ASSIGNMENT_SELECT_ADMIN_INNER : ASSIGNMENT_SELECT_USER_MAKESAFE)
      // Personal path stays scoped to this user; the manager path is vertical-wide.
      if (!runManagerMakesafeBackstop) backstopQuery = backstopQuery.eq('user_id', userId)
      const resMakesafe = await backstopQuery
        .neq('status', 'cancelled')
        .gte('scheduled_date', makesafeSixMonthsAgo.toISOString().slice(0, 10))
        .lt('scheduled_date', thirtyDaysAgo.toISOString().slice(0, 10))
        .eq('jobs.org_id', orgId)
        // Filter on the EMBEDDED jobs relation (inner join) so only assignments whose
        // job is a make-safe come back. Column names are relative to `jobs`.
        .or('type.eq.makesafe,job_number.ilike.SWMS-%', { referencedTable: 'jobs' })
        .order('scheduled_date', { ascending: true })
      if (resMakesafe.error) throw resMakesafe.error
      const msAssignments: any[] = resMakesafe.data || []
      for (const a of msAssignments) {
        if (a?.id && !existing30DayIds.has(a.id)) {
          assignments = [...(assignments || []), a]
        }
      }
    } catch (msErr: any) {
      // Non-blocking: if the backstop query fails, the primary 30-day list still shows.
      console.log('[ops-api] myJobs makesafe backstop query failed (non-blocking):', msErr?.message)
    }
  }

  // MakeSafe dispatch flow: the full open MakeSafe pool is visible to the
  // dispatcher (ops manager / admin) AND to a flagged make-safe manager
  // (users.makesafe_manager, e.g. Hugo + Nithin) as open field-report cards,
  // even before a named assignment exists. Other trades see a MakeSafe only once
  // it is allocated to them (their named assignment). A manager is not a
  // dispatcher, so showAll stays false: their own assignments (fetched above)
  // are unioned with this pool, and pool cards already assigned to them are
  // de-duplicated via assignedJobIds below. Keep this specific to MakeSafe and
  // expose only the same slim job fields the mobile job list already uses.
  if (_canSeeFullMakesafePool(isDispatcher, isMakesafeManager)) {
    const { data: openMakesafesByShape, error: msErr } = await client
      .from('jobs')
      .select('id, type, status, client_name, client_phone, client_email, site_address, site_suburb, notes, job_number, metadata, created_at')
      .eq('org_id', orgId)
      .or('type.eq.makesafe,job_number.ilike.SWMS-%')
      .not('status', 'in', _makesafePoolExcludedStatusFilter())
      .order('created_at', { ascending: false })
      .limit(80)
    if (msErr) throw msErr

    const openMakesafeById: Record<string, any> = {}
    for (const job of (openMakesafesByShape || [])) if (job?.id) openMakesafeById[job.id] = job

    // Backstop for legacy imports: if a job has a makesafe_job_details row but
    // its jobs.type/job_number has not been normalised, still expose it to the
    // open MakeSafe pool instead of requiring a named assignment.
    const { data: detailRows, error: detailErr } = await client
      .from('makesafe_job_details')
      .select('*, makesafe_companies:requesting_company_id(slug, name)')
      .limit(120)
    if (detailErr) throw detailErr
    const detailByJobId: Record<string, any> = {}
    for (const row of (detailRows || [])) if (row?.job_id) detailByJobId[String(row.job_id)] = row
    for (const id of Object.keys(openMakesafeById)) {
      // U2c: pool = allocatable only. Excludes finished substatuses (as before)
      // AND company_contact_required (ops's admin queue). Report access is a
      // separate predicate and unchanged.
      if (!isAllocatableMakesafePoolDetail(detailByJobId[id])) delete openMakesafeById[id]
    }
    const detailJobIds = Array.from(new Set<string>((detailRows || [])
      .filter((r: any) => isAllocatableMakesafePoolDetail(r))
      .map((r: any) => String(r.job_id || '')).filter(Boolean)))
      .filter((id: string) => !openMakesafeById[id])
    if (detailJobIds.length > 0) {
      const { data: detailJobs, error: detailJobsErr } = await client
        .from('jobs')
        .select('id, type, status, client_name, client_phone, client_email, site_address, site_suburb, notes, job_number, metadata, created_at')
        .eq('org_id', orgId)
        .in('id', detailJobIds)
        .not('status', 'in', _makesafePoolExcludedStatusFilter())
        .order('created_at', { ascending: false })
        .limit(80)
      if (detailJobsErr) throw detailJobsErr
      for (const job of (detailJobs || [])) if (job?.id) openMakesafeById[job.id] = job
    }

    for (const id of Object.keys(openMakesafeById)) {
      if (detailByJobId[id]) openMakesafeById[id].makesafe_details = detailByJobId[id]
    }

    const openMakesafes = Object.values(openMakesafeById)
      .sort((a: any, b: any) => String(b.created_at || '').localeCompare(String(a.created_at || '')))
      .slice(0, 80)

    // Open MakeSafe cards are synthetic pool cards, not normal assigned cards.
    // Some imported MakeSafes have the client phone in job_contacts rather than
    // jobs.client_phone, which made the trade app show Navigate only. Backfill
    // the slim phone/contact fields before handing the pool cards to trade.html.
    const phoneMissingJobIds = openMakesafes
      .filter((job: any) => job?.id && !job.client_phone)
      .map((job: any) => job.id)
    if (phoneMissingJobIds.length > 0) {
      try {
        const { data: contacts, error: contactErr } = await client.from('job_contacts')
          .select('job_id, client_name, client_email, client_phone, is_primary, contact_label, status')
          .in('job_id', phoneMissingJobIds)
          .eq('status', 'active')
        if (contactErr) throw contactErr
        _backfillOpenMakesafeContactsForTest(openMakesafes as any[], contacts || [])
      } catch (e: any) {
        console.log('[ops-api] open MakeSafe contact backfill skipped:', e?.message)
      }
    }

    // Whether a finished make-safe visit still holds its job is a question about
    // that job's re-attend history, not about status alone — so resolve the
    // stamps for exactly this pool's ids before either the de-dupe seed or the
    // probe answers it. A failed read degrades to "no stamp", which holds every
    // finished visit: a card that stays occupied for one load is recoverable, a
    // job re-offered to a second crew is not.
    const poolJobIdsForStamps = openMakesafes.map((job: any) => job?.id).filter(Boolean)
    let reattendAtByJobId: Record<string, unknown> = {}
    try {
      reattendAtByJobId = await fetchMakesafeReattendStamps(client, poolJobIdsForStamps)
    } catch (stampErr: any) {
      console.log('[ops-api] myJobs make-safe re-attend stamp read failed (non-blocking, work stays occupied):', stampErr?.message)
    }
    const assignedJobIds = _activeAssignedJobIds(assignments, 'makesafe', reattendAtByJobId)

    // Same all-date occupancy rule as the generic pool below: the assignment
    // feed above is windowed (30-day, plus the 180-day make-safe backstop) and
    // both windows drop NULL-dated rows, so de-duping against it alone still
    // lets an already-allocated make-safe reappear as a synthetic "available"
    // card — the double-allocation risk. Ask job_assignments directly.
    let makesafeOccupancy = new Map<string, any>()
    try {
      makesafeOccupancy = await fetchOccupyingAssignments(
        client,
        openMakesafes.map((job: any) => job?.id),
        poolRecoveryUserId,
        'makesafe',
        reattendAtByJobId,
      )
    } catch (occErr: any) {
      // Non-blocking: a failed probe must not take the make-safe board down. The
      // windowed de-dupe below still applies.
      console.log('[ops-api] myJobs make-safe occupancy probe failed (non-blocking):', occErr?.message)
    }

    for (const job of openMakesafes) {
      if (!job?.id || assignedJobIds.has(job.id)) continue
      // Held by a live allocation: never open work anyone may take. Recovered as
      // that crew's real card only when this lens is entitled to show it.
      const occupying = makesafeOccupancy.get(job.id)
      if (occupying) {
        assignedJobIds.add(job.id)
        if (_shouldRecoverOccupiedPoolJob({ occupying, lens: poolLens, userId })) {
          assignments.push(occupiedPoolAssignmentCard(occupying, job))
        }
        continue
      }
      assignments.push({
        id: `makesafe-open-${job.id}`,
        scheduled_date: today,
        scheduled_end: null,
        start_time: null,
        status: 'available',
        role: 'makesafe_open',
        notes: null,
        assignment_type: 'makesafe_open',
        crew_name: null,
        started_at: null,
        completed_at: null,
        clocked_on_at: null,
        clocked_off_at: null,
        travel_started_at: null,
        arrived_at: null,
        break_minutes: null,
        job_phase: null,
        jobs: job,
      })
    }
  }

  // ── M-F W2-A: windowed CANCELLED make-safe feed (trade Cancelled column) ──
  // The make-safe pool above EXCLUDES cancelled (_MAKESAFE_POOL_EXCLUDED_STATUSES)
  // and the named-assignment feed drops it (cancel closed the assignment to
  // 'cancelled') — so WITHOUT this a cancelled make-safe vanishes from trade
  // entirely, leaving the (already-built) trade Cancelled column + Reopen button
  // inert. Feed recently-cancelled make-safes (last 90 days) as synthetic cards so
  // the trade board classifier — which keys off job.status='cancelled' — routes
  // them into the Cancelled column, carrying the cancel_* attribution via
  // job.makesafe_details. Manager/dispatcher-gated (same gate as the pool above).
  // Appended in-memory AFTER the DB queries, so no .neq('status','cancelled')
  // filter can drop them.
  if (_canSeeFullMakesafePool(isDispatcher, isMakesafeManager)) {
    const cancelledSinceIso = new Date(Date.now() - 90 * 86_400_000).toISOString()
    const { data: cancelledMakesafes, error: cancelErr } = await client
      .from('jobs')
      .select('id, type, status, client_name, client_phone, client_email, site_address, site_suburb, notes, job_number, metadata, created_at')
      .eq('org_id', orgId)
      .eq('type', 'makesafe')
      .eq('status', 'cancelled')
      .gte('updated_at', cancelledSinceIso)
      .order('updated_at', { ascending: false })
      .limit(80)
    if (cancelErr) throw cancelErr

    const cancelledJobs = cancelledMakesafes || []
    if (cancelledJobs.length > 0) {
      const cancelledIds = cancelledJobs.map((j: any) => j.id).filter(Boolean)
      const { data: cancelledDetails, error: cancelledDetailErr } = await client
        .from('makesafe_job_details')
        .select('*, makesafe_companies:requesting_company_id(slug, name)')
        .in('job_id', cancelledIds)
      if (cancelledDetailErr) throw cancelledDetailErr
      const cancelledDetailByJobId: Record<string, any> = {}
      for (const row of (cancelledDetails || [])) {
        if (row?.job_id) cancelledDetailByJobId[String(row.job_id)] = row
      }

      // Dedup against every card already emitted — the classifier routes on
      // job.status='cancelled', so a job that reached the board by ANY route is
      // already in the Cancelled column and a synthetic card would double it.
      // cancelMakesafe only closes rows in _OPEN_ASSIGNMENT_STATUSES, so a
      // worked-then-cancelled make-safe still rides the feed on its 'complete'
      // row; what that card lacks is the cancel_* attribution, so hand it the
      // details instead of appending a second card.
      const emittedCardsByJobId = new Map<string, any[]>()
      for (const emitted of (assignments || [])) {
        const emittedJobId = emitted?.jobs?.id
        if (!emittedJobId) continue
        const bucket = emittedCardsByJobId.get(emittedJobId)
        if (bucket) bucket.push(emitted)
        else emittedCardsByJobId.set(emittedJobId, [emitted])
      }
      const cancelledHandled = new Set<string>()
      for (const job of cancelledJobs) {
        if (!job?.id || cancelledHandled.has(job.id)) continue
        cancelledHandled.add(job.id)
        const cancelDetail = cancelledDetailByJobId[job.id]
        const alreadyEmitted = emittedCardsByJobId.get(job.id)
        if (alreadyEmitted && alreadyEmitted.length > 0) {
          if (cancelDetail) {
            for (const card of alreadyEmitted) {
              if (card?.jobs) card.jobs.makesafe_details = cancelDetail
            }
          }
          continue
        }
        if (cancelDetail) job.makesafe_details = cancelDetail
        assignments.push({
          id: `makesafe-cancelled-${job.id}`,
          scheduled_date: today,
          scheduled_end: null,
          start_time: null,
          status: 'cancelled',
          role: 'makesafe_cancelled',
          notes: null,
          assignment_type: 'makesafe_cancelled',
          crew_name: null,
          started_at: null,
          completed_at: null,
          clocked_on_at: null,
          clocked_off_at: null,
          travel_started_at: null,
          arrived_at: null,
          break_minutes: null,
          job_phase: null,
          jobs: job,
        })
      }
    }
  }

  // ── Generic per-vertical open pool (fencing / patio / decking) ──
  // Manager View: a vertical manager sees the full open pool of every vertical
  // in their managed_verticals — active, non-archived jobs of that jobs.type —
  // as synthetic 'available' cards, exactly like the make-safe pool above (which
  // keeps its bespoke make-safe_job_details enrichment). Make-safe is handled
  // above and excluded here. Cards are de-duped against the user's own
  // assignments (and against each other). Same terminal-status exclusion as the
  // make-safe pool via _makesafePoolExcludedStatusFilter().
  const genericPoolVerticals = (poolVerticals || []).filter((v) => v !== 'makesafe')
  if (genericPoolVerticals.length > 0) {
    const assignedJobIdsPool = _activeAssignedJobIds(assignments, 'vertical')
    for (const vertical of genericPoolVerticals) {
      try {
        // M3b U1 (D1+G1): INCLUDE filter — the fencing/patio/decking pool shows
        // ONLY jobs at a crew-ready stage (order_confirmed / schedule_install /
        // crewless scheduled). The old exclude-only filter surfaced the whole
        // pipeline (quoted, awaiting_deposit, order_materials, ...) as fake
        // "available" cards — the 72/76 counts Marnin called out. The make-safe
        // pool above keeps its exclude filter untouched (its "New" = intake-
        // complete jobs, already honest). Assigned-job dedupe below unchanged.
        const { data: openJobs, error: poolErr } = await client
          .from('jobs')
          .select('id, type, status, client_name, client_phone, client_email, site_address, site_suburb, notes, job_number, created_at')
          .eq('org_id', orgId)
          .eq('type', vertical)
          .in('status', _CREW_READY_STATUSES as unknown as string[])
          .order('created_at', { ascending: false })
          .limit(80)
        if (poolErr) throw poolErr
        // The manager assignment feed intentionally remains 30-day windowed, so
        // ask job_assignments directly whether these already tenant+vertical-
        // authorized pool ids are occupied at any date.
        const poolJobIds = (openJobs || []).map((job: any) => job?.id).filter(Boolean)
        const occupancy = await fetchOccupyingAssignments(client, poolJobIds, poolRecoveryUserId, 'vertical')
        for (const job of (openJobs || [])) {
          if (!job?.id || assignedJobIdsPool.has(job.id)) continue
          assignedJobIdsPool.add(job.id)
          // Held by a live allocation: never open work anyone may take. Recovered
          // as that crew's real card only when this lens is entitled to show it.
          const occupying = occupancy.get(job.id)
          if (occupying) {
            if (_shouldRecoverOccupiedPoolJob({ occupying, lens: poolLens, userId })) {
              assignments.push(occupiedPoolAssignmentCard(occupying, job))
            }
            continue
          }
          assignments.push({
            id: `${vertical}-open-${job.id}`,
            scheduled_date: today,
            scheduled_end: null,
            start_time: null,
            status: 'available',
            role: `${vertical}_open`,
            notes: null,
            assignment_type: `${vertical}_open`,
            crew_name: null,
            started_at: null,
            completed_at: null,
            clocked_on_at: null,
            clocked_off_at: null,
            travel_started_at: null,
            arrived_at: null,
            break_minutes: null,
            job_phase: null,
            jobs: job,
          })
        }
      } catch (poolErr: any) {
        // Non-blocking: a failed vertical pool query must not break the trade's
        // own assignment list.
        console.log(`[ops-api] myJobs ${vertical} pool query failed (non-blocking):`, poolErr?.message)
      }
    }
  }

  const weekEnd = getAWSTWeekEnd()

  // Enrich with PO delivery info (pickup vs delivery badge)
  const jobIds = (assignments || []).map((a: any) => a.jobs?.id).filter(Boolean)
  let poMap: Record<string, any> = {}
  if (jobIds.length > 0) {
    const { data: pos } = await client.from('purchase_orders')
      .select('job_id, delivery_date, notes, status')
      .in('job_id', jobIds)
      .neq('status', 'deleted')
      .order('created_at', { ascending: false })
    for (const po of (pos || [])) {
      if (!poMap[po.job_id]) {
        // purchase_orders has no delivery_address column — the address is encoded
        // into notes at PO creation; _shared/po_reference.ts owns both sides.
        const deliverTo = parsePoDeliveryAddress(po.notes)
        const isPickup = isPoPickup(po.notes)
        poMap[po.job_id] = {
          delivery_method: isPickup ? 'pickup' : 'delivery',
          delivery_date: po.delivery_date,
          delivery_address: deliverTo,
          pickup_location: isPickup ? (deliverTo || 'R&R Wangara') : null,
          po_status: po.status,
          materials_confirmed: ['confirmed', 'delivered', 'billed', 'authorised'].includes(po.status),
        }
      }
    }
  }

  // Attach PO info + scope_summary to each assignment (keep payload slim)
  for (const a of (assignments || [])) {
    if (a.jobs) {
      if (a.jobs.id && poMap[a.jobs.id]) {
        a.jobs.po_info = poMap[a.jobs.id]
      }
      // Compute scope_summary from pricing_json.job_description (replaces sending full scope_json)
      const pj = a.jobs.pricing_json
      a.jobs.scope_summary = pj?.job_description || ''
      delete a.jobs.pricing_json // don't send pricing data to trades
    }
  }

  const grouped: any = _groupTradeAssignmentsForTest(assignments || [], today, weekEnd)

  // Flag so frontend knows this is admin/all-jobs view
  if (showAll) grouped._adminView = true

  return grouped
}

// ── Scope Photo Extraction ──────────────────────────────────────────────
// Fencing scope tool captures photos as BASE64 inside scope_json.scopeMedia.photos.
// This extracts them to Supabase Storage + job_media so the trade app can display them.
async function extractScopePhotos(client: any, jobId: string, scopeJson: any): Promise<number> {
  // Guard: nothing to extract
  const photos = scopeJson?.scopeMedia?.photos
  if (!Array.isArray(photos) || photos.length === 0) return 0

  // Check if already extracted
  const { data: existing } = await client.from('job_media')
    .select('id')
    .eq('job_id', jobId)
    .eq('phase', 'scope')
    .limit(1)
  if (existing && existing.length > 0) return 0

  // Ensure bucket exists (idempotent)
  try { await client.storage.createBucket('job-photos', { public: true }) } catch { /* exists */ }

  let count = 0
  for (let i = 0; i < photos.length; i++) {
    const photo = photos[i]
    if (!photo?.dataUrl || typeof photo.dataUrl !== 'string') continue

    try {
      // Strip data URL prefix — handle jpeg, png, webp etc
      const base64 = photo.dataUrl.split(',')[1]
      if (!base64) continue

      const mimeMatch = photo.dataUrl.match(/data:([^;]+);/)
      const mime = mimeMatch ? mimeMatch[1] : 'image/jpeg'
      const ext = mime.includes('png') ? 'png' : 'jpg'
      const bytes = Uint8Array.from(atob(base64), (c: string) => c.charCodeAt(0))

      const path = `${DEFAULT_ORG_ID}/${jobId}/scope/${i}.${ext}`

      const { error: uploadError } = await client.storage
        .from('job-photos')
        .upload(path, bytes, { contentType: mime, upsert: true })
      if (uploadError) { console.log(`[ops-api] scope photo ${i} upload failed:`, uploadError.message); continue }

      const { data: urlData } = client.storage.from('job-photos').getPublicUrl(path)

      const { error: insertError } = await client.from('job_media').insert({
        job_id: jobId,
        phase: 'scope',
        type: 'photo',
        storage_url: urlData.publicUrl,
        label: photo.label || `Scope photo ${i + 1}`,
        created_at: new Date().toISOString(),
      })
      if (insertError) { console.log(`[ops-api] scope photo ${i} insert failed:`, insertError.message); continue }

      count++
    } catch (err: any) {
      console.log(`[ops-api] scope photo ${i} error:`, err?.message)
    }
  }

  console.log(`[ops-api] extracted ${count} scope photos for job ${jobId}`)
  return count
}

async function tradeJobDetail(
  client: any,
  params: URLSearchParams,
  viewer: TradeAuthContext,
  isAdmin = false,
) {
  const jobId = params.get('jobId')
  if (!jobId) throw new Error('jobId required')

  // Verify the job belongs to the viewer's tenant, then allow an assignment,
  // dispatcher access, the existing MakeSafe exception, or explicit
  // managed-vertical authority.
  await assertAssignedOrMakesafeAccess(client, jobId, viewer.id, isAdmin, {
    orgId: viewer.orgId,
    managedVerticals: viewer.managedVerticals,
  })

  const [jobRes, docsRes, mediaRes, eventsRes, reportRes, woRes, crewRes, posRes] = await Promise.all([
    client.from('jobs')
      .select('id, type, status, client_name, client_phone, client_email, site_address, site_suburb, site_lat, site_lng, notes, job_number, scope_json, ghl_opportunity_id, ghl_contact_id, metadata')
      .eq('id', jobId).eq('org_id', viewer.orgId).single(),
    client.from('job_documents')
      .select('id, type, pdf_url, storage_url, file_name, visible_to_trades, version, quote_number, created_at')
      .eq('job_id', jobId).order('created_at', { ascending: false }),
    client.from('job_media')
      .select('id, phase, type, storage_url, thumbnail_url, label, notes, po_id, created_at')
      .eq('job_id', jobId).order('created_at').limit(200),
    client.from('job_events')
      .select('id, event_type, detail_json, created_at, users:user_id(name)')
      .eq('job_id', jobId).eq('event_type', 'note').order('created_at', { ascending: false }).limit(50),
    client.from('job_service_reports')
      .select('*').eq('job_id', jobId).order('created_at', { ascending: false }).limit(20),
    // Work order data (scope items, instructions)
    client.from('work_orders')
      .select('id, wo_number, scope_items, special_instructions, scheduled_date, status')
      .eq('job_id', jobId).neq('status', 'cancelled').order('created_at', { ascending: false }).limit(1),
    // All crew assignments for this job (not filtered by date — user explicitly opened this job)
    client.from('job_assignments')
      .select('id, user_id, scheduled_date, start_time, role, crew_name, status, started_at, completed_at, acknowledged_at, clocked_on_at, clocked_off_at, travel_started_at, arrived_at, break_minutes, job_phase, hours_worked, users:user_id(name, phone)')
      .eq('job_id', jobId).neq('status', 'cancelled')
      .order('scheduled_date', { ascending: true }),
    // Purchase orders — materials for this job (trade-safe fields only)
    client.from('purchase_orders')
      .select('id, po_number, supplier_name, status, delivery_date, line_items')
      .eq('job_id', jobId).neq('status', 'deleted')
      .order('delivery_date', { ascending: true }),
  ])

  if (jobRes.error) throw jobRes.error

  // Strip pricing from PO line items — trades only see descriptions and quantities
  const safePOs = (posRes.data || []).map((po: any) => ({
    ...po,
    line_items: (po.line_items || []).map((li: any) => ({
      description: li.description || li.Description || '',
      quantity: li.quantity || li.Quantity || 0,
      unit: li.unit || li.UnitAmount ? undefined : undefined,
    })),
  }))

  // Fire-and-forget: extract scope photos if not already done
  if (jobRes.data?.scope_json?.scopeMedia?.photos?.length > 0) {
    extractScopePhotos(client, jobId, jobRes.data.scope_json)
      .catch(e => console.log('[ops-api] scope photo extraction failed:', e?.message))
  }

  // Make-safe overlay details for trade view
  let makesafeDetails: any = null
  if (await isMakesafeAccessJobForClient(client, jobRes.data)) {
    try {
      const { data: ms } = await client.from('makesafe_job_details')
        .select('*, makesafe_companies:requesting_company_id(*)')
        .eq('job_id', jobId)
        .maybeSingle()
      const jobMetadata = parseJsonObject(jobRes.data?.metadata)
      makesafeDetails = ms ? {
        ...ms,
        builder_email_text_for_trade: jobMetadata.builder_email_text_for_trade || null,
        builder_email_subject: jobMetadata.builder_email_subject || null,
        builder_email_received_at: jobMetadata.builder_email_received_at || null,
      } : null
    } catch (e) {
      console.log('[ops-api] trade makesafe details fetch skipped:', (e as Error).message)
    }
  }

  const { metadata: _tradeJobMetadata, ...tradeSafeJob } = jobRes.data || {}

  return {
    job: tradeSafeJob,
    documents: docsRes.data || [],
    media: mediaRes.data || [],
    // Human comms thread only: strip system/audit markers (MAKESAFE_PACK_SENT,
    // MAKESAFE_AGENT_REPLY) so the trade never sees internal breadcrumbs in the
    // notes thread. The markers stay in job_events untouched.
    notes: (eventsRes.data || []).filter((n: any) => !noteIsSystemMarker(n?.detail_json?.text ?? n?.detail_json?.note ?? '')),
    serviceReport: (reportRes.data || [])[0] || null,
    // Re-attendance (M-C): all reports (latest first) so a re-attended job shows
    // every visit's report, not just the latest. serviceReport stays the latest
    // for existing single-report callers. reattend_count lives on makesafe_details.
    serviceReports: reportRes.data || [],
    workOrder: (woRes.data || [])[0] || null,
    crew: crewRes.data || [],
    purchaseOrders: safePOs,
    makesafe_details: makesafeDetails,
  }
}

async function addNote(client: any, body: any, isAdmin = false) {
  const { jobId, job_id, userId, user_id, text, sync_to_ghl, visibility, from_ops } = body
  const jId = jobId || job_id
  const uId = userId || user_id
  if (!jId || !text) throw new Error('jobId and text required')

  // Verify user is assigned to this job (admins bypass). Open MakeSafe field-report jobs
  // may receive trade admin notes before a named assignment exists.
  if (uId) await assertAssignedOrMakesafeAccess(client, jId, uId, isAdmin)

  // Sales cockpit notes are staff-only by default. GHL contact notes are CRM
  // notes, not customer messages; when explicitly requested, mirror there too
  // so the salesmen see the same context in LeadConnector/GHL.
  //
  // Item 10 — a caller-stated visibility ALWAYS wins (backward compatible). When
  // it is unspecified, a system/audit marker body (a MAKESAFE_PACK_SENT send
  // breadcrumb, an agent-reply marker) DEFAULTS to internal_only so it never
  // syncs to a client-facing GHL note. Before this, a marker written via
  // sw_add_note (which passes no visibility) defaulted to client_visible +
  // sync_to_ghl — the 2026-07-07 SWMS-26832 marker backfill hit exactly this,
  // one GHL-linked job away from leaking an internal audit breadcrumb to a
  // client. Ordinary notes are unchanged: unspecified => client_visible.
  const noteVisibility = resolveNoteVisibility(visibility, text)
  const shouldSyncToGhl = sync_to_ghl === true || (sync_to_ghl !== false && noteVisibility === 'client_visible')

  // from_ops flags a note authored by the office/ops side of the trade<->ops
  // comms thread so both UIs can label it "Office" vs a trade's own note. Only
  // persisted when explicitly true; ordinary notes are unchanged.
  const noteDetail: Record<string, any> = { text, visibility: noteVisibility, sync_to_ghl: shouldSyncToGhl }
  if (from_ops === true) noteDetail.from_ops = true

  const { data, error } = await client.from('job_events').insert({
    job_id: jId,
    user_id: userId || user_id || null,
    event_type: 'note',
    detail_json: noteDetail,
  }).select().single()

  if (error) throw error

  // Dual-write to business_events.
  //
  // T7 Loop 6 — long-note pointer. Note bodies up to 500c stay inline as
  // body_preview. Notes longer than that get persisted to
  // evidence-bodies/{org}/note/{job_events.id}.txt with body_pointer +
  // body_hash. The legacy `note_text` payload field is preserved when T7
  // OFF for backward compatibility (the existing extractor reads it).
  const noteText = String(text || '')
  const isLongNote = noteText.length > 500
  const t7NoteEnabled = await isFlagOn(client, 'evidence_capture_v1', DEFAULT_ORG_ID)
  // Legacy logBusinessEvent payload — emitted either by the T7 fallback
  // path OR when the flag is OFF. Defined once so a T7 failure cannot
  // silently drop the canonical note.added row.
  const legacyNoteEvent = {
    event_type: 'note.added',
    source: 'app/field',
    entity_type: 'job',
    entity_id: jId,
    job_id: jId,
    correlation_id: jId,
    payload: {
      entity: { id: jId },
      related_entities: [{ type: 'user', id: uId || null }],
      note_text: noteText,
      note_preview: noteText.slice(0, 500),
      visibility: noteVisibility,
      sync_to_ghl: shouldSyncToGhl,
      source_job_event_id: data?.id || null,
    },
  }
  let t7NoteFailed = false
  if (t7NoteEnabled) {
    try {
      await recordEvidence(client, {
        event_type: 'note.added',
        source: 'ops-api/add_note',
        channel: 'note',
        direction: 'internal',
        source_table: 'job_events',
        source_id: String(data?.id || crypto.randomUUID()),
        job_id: jId,
        entity_type: 'job',
        entity_id: jId,
        match_method: 'direct_job_id',
        body_preview: noteText.slice(0, 500),
        body_full: isLongNote ? noteText : undefined,
        body_filename: isLongNote ? `note-${data?.id || 'untitled'}.txt` : undefined,
        body_mime: isLongNote ? 'text/plain; charset=utf-8' : undefined,
        privacy_classification: 'staff_only',
        retention_class: '7y_audit',
        payload: {
          entity: { id: jId },
          related_entities: [{ type: 'user', id: uId || null }],
          note_text: noteText,                  // preserved for backward-compat
          note_preview: noteText.slice(0, 500),
          source_job_event_id: data?.id || null,
        },
      }, {
        org_id: DEFAULT_ORG_ID,
        storage_client: client.storage,
      })
    } catch (e: any) {
      console.error('[ops-api] T7 note.added recordEvidence failed; falling back to legacy:', e?.message)
      t7NoteFailed = true
    }
  }
  if (!t7NoteEnabled || t7NoteFailed) {
    logBusinessEvent(client, legacyNoteEvent)
  }

  // Push to GHL contact-note (closes the GHL→Supabase note-loop gap by
  // making the loop bidirectional). Best-effort — don't block the note
  // save on GHL connectivity.
  let ghl_note_id: string | null = null
  let ghl_push_error: string | null = null
  if (shouldSyncToGhl) {
    try {
      // Resolve ghl_contact_id from the job
      const { data: jobRow } = await client.from('jobs')
        .select('ghl_contact_id')
        .eq('id', jId)
        .maybeSingle()
      const contactId = jobRow?.ghl_contact_id
      if (contactId) {
        const ghlBase = (Deno.env.get('SUPABASE_URL') || '').replace('/rest/v1', '') + '/functions/v1/ghl-proxy'
        const ghlKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
        const noteResp = await fetch(`${ghlBase}?action=add_note`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-api-key': ghlKey,
          },
          body: JSON.stringify({
            contactId,
            body: noteText,
            jobId: jId,
          }),
        })
        if (noteResp.ok) {
          const noteData = await noteResp.json().catch(() => ({}))
          ghl_note_id = noteData.note_id || noteData.id || null
        } else {
          ghl_push_error = `ghl-proxy add_note returned ${noteResp.status}`
        }
      } else {
        ghl_push_error = 'job has no ghl_contact_id; cannot push note'
      }
    } catch (e) {
      ghl_push_error = (e as Error).message
    }
  }

  return {
    note: data,
    visibility: noteVisibility,
    ghl_synced: !!ghl_note_id,
    ghl_note_id,
    ghl_push_error,
  }
}

// T7 Loop 9 — Controlled transcript ingest handler.
// Caller has already passed the admin/owner role check at the dispatch
// site. This handler validates input, computes the envelope, calls
// recordEvidence with bypass_feature_flag=true, and returns the spine
// event id + extraction job id for downstream verification.
async function ingestTranscript(
  client: any,
  body: any,
  caller: { user_id: string; role: string },
): Promise<any> {
  const job_id = String(body?.job_id || '').trim()
  const transcript_text = String(body?.transcript_text || '')
  const source_label = String(body?.source_label || 'whisperflow').slice(0, 64)
  const occurred_at = (body?.occurred_at && typeof body.occurred_at === 'string')
    ? body.occurred_at
    : new Date().toISOString()
  const consent_confirmed = body?.consent_confirmed === true
  const call_direction = (body?.call_direction === 'inbound' || body?.call_direction === 'outbound')
    ? body.call_direction
    : 'internal'

  if (!job_id) return { ok: false, reason: 'job_id required' }
  if (transcript_text.trim().length === 0) return { ok: false, reason: 'transcript_text required (non-empty)' }
  if (!consent_confirmed) return { ok: false, reason: 'consent_confirmed must be explicitly true' }

  // Confirm the job exists. Avoids creating spine rows pointing at junk ids.
  const { data: jobRow, error: jobErr } = await client
    .from('jobs')
    .select('id, job_number')
    .eq('id', job_id)
    .limit(1)
  if (jobErr) return { ok: false, reason: `job lookup failed: ${jobErr.message}` }
  if (!jobRow || jobRow.length === 0) return { ok: false, reason: `job_id '${job_id}' not found` }

  // Build a deterministic-ish source id so reruns dedupe at the
  // (source_table, source_id) level rather than minting a new spine row
  // every paste. Hash of (job_id, occurred_at, first 64 chars).
  const source_id = `transcript-${job_id}-${occurred_at}-${transcript_text.slice(0, 64).replace(/\s+/g, '_').slice(0, 32)}`

  const safe_summary = transcript_text.slice(0, 280).replace(/\s+/g, ' ').trim()
  const body_filename = `transcript-${job_id}-${Date.now()}.txt`

  try {
    const result = await recordEvidence(
      client,
      {
        event_type: 'call.transcript_ingested',
        source: 'ops-api/ingest_transcript',
        channel: 'call',
        direction: call_direction as any,
        occurred_at,
        source_table: 'admin_transcript',
        source_id,
        job_id,
        entity_type: 'job',
        entity_id: job_id,
        match_method: 'manual',
        match_confidence: 1.0,
        body_preview: transcript_text.slice(0, 500),
        body_full: transcript_text,
        body_filename,
        body_mime: 'text/plain; charset=utf-8',
        safe_summary,
        privacy_classification: 'staff_only',
        retention_class: '7y_audit',
        payload: {
          source_label,
          call_direction,
          ingested_by: { user_id: caller.user_id, role: caller.role },
          ingested_at: new Date().toISOString(),
          char_count: transcript_text.length,
          consent_confirmed: true,
        },
        metadata: {
          ingest_action: 'ingest_transcript',
        },
      },
      {
        org_id: DEFAULT_ORG_ID,
        bypass_feature_flag: true,                       // structurally controlled (admin only)
        extractor_eligible_channels: ['email', 'note', 'call'],   // local override; lets transcripts flow to extractor
        storage_client: client.storage,
      },
    )
    return {
      ok: true,
      spine_event_id: result.spine_event_id,
      extraction_job_id: result.extraction_job_id ?? null,
      body_pointer: result.body_pointer ?? null,
      match_status: result.spine_row.match_status,
      job_number: jobRow[0].job_number,
      source_id,
      warnings: result.warnings,
    }
  } catch (e: any) {
    return { ok: false, reason: `ingestTranscript: recordEvidence failed: ${e?.message ?? e}` }
  }
}

async function uploadPhoto(client: any, body: any) {
  const { jobId, job_id, dataUrl, label, phase, userId, user_id, po_id } = body
  const jId = jobId || job_id
  const uId = userId || user_id
  if (!jId || !dataUrl) throw new Error('jobId and dataUrl required')

  // Verify user is assigned, or this is a MakeSafe field-report job.
  if (uId) await assertAssignedOrMakesafeAccess(client, jId, uId)

  const base64 = dataUrl.split(',')[1]
  const mimeMatch = dataUrl.match(/data:([^;]+);/)
  const mime = mimeMatch ? mimeMatch[1] : 'image/jpeg'
  const ext = mime.includes('png') ? 'png' : 'jpg'
  const bytes = Uint8Array.from(atob(base64), (c: string) => c.charCodeAt(0))

  const photoId = crypto.randomUUID()
  const path = `${DEFAULT_ORG_ID}/${jId}/photos/${photoId}.${ext}`

  try { await client.storage.createBucket('job-photos', { public: true }) } catch { /* exists */ }

  const { error: uploadError } = await client.storage
    .from('job-photos')
    .upload(path, bytes, { contentType: mime, upsert: false })

  if (uploadError) throw uploadError

  const { data: urlData } = client.storage.from('job-photos').getPublicUrl(path)

  const mediaInsert: any = {
    job_id: jId,
    type: 'photo',
    storage_url: urlData.publicUrl,
    label: label || '',
    phase: phase || 'completion',
    uploaded_by: userId || user_id || null,
  }
  if (po_id) mediaInsert.po_id = po_id

  const { data: mediaRecord, error: mediaError } = await client.from('job_media').insert(mediaInsert).select().single()

  if (mediaError) throw mediaError

  await client.from('job_events').insert({
    job_id: jId,
    user_id: userId || user_id || null,
    event_type: phase === 'receipt' ? 'receipt_added' : 'photo_added',
    detail_json: { media_id: mediaRecord.id, phase: phase || 'completion', po_id: po_id || null },
  })

  return { id: mediaRecord.id, url: urlData.publicUrl }
}

function normaliseOpsAttachJobPhotoInput(body: any) {
  const jId = body?.jobId || body?.job_id
  const dataUrl = String(body?.dataUrl || body?.data_url || '')
  if (!jId || !dataUrl) throw new ApiError('job_id and dataUrl required', 400)
  if (!String(jId).match(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i)) {
    throw new ApiError('job_id must be a valid UUID', 400)
  }

  const phase = String(body?.phase || 'completion').trim().toLowerCase()
  if (phase !== 'completion') {
    throw new ApiError('ops_attach_job_photo only attaches completion photos for reporting recovery', 400)
  }

  const match = dataUrl.match(/^data:(image\/(?:jpeg|jpg|png|webp));base64,([A-Za-z0-9+/=\s]+)$/i)
  if (!match) throw new ApiError('dataUrl must be a base64 jpeg, png, or webp image data URL', 400)

  const mime = match[1].toLowerCase().replace('image/jpg', 'image/jpeg')
  const ext = mime.includes('png') ? 'png' : mime.includes('webp') ? 'webp' : 'jpg'
  const base64 = match[2].replace(/\s/g, '')
  let bytes: Uint8Array
  try {
    bytes = Uint8Array.from(atob(base64), (c: string) => c.charCodeAt(0))
  } catch {
    throw new ApiError('dataUrl base64 payload is invalid', 400)
  }
  if (!bytes.byteLength) throw new ApiError('dataUrl image payload is empty', 400)
  if (bytes.byteLength > 12 * 1024 * 1024) throw new ApiError('image payload exceeds 12MB limit', 413)

  const label = String(body?.label || 'Recovered completion photo').trim().slice(0, 160) || 'Recovered completion photo'
  const sourceNote = String(body?.source_note || body?.sourceNote || 'Recovered by Ops for MakeSafe reporting').trim().slice(0, 500)
  return { jId, phase, dataUrl, mime, ext, bytes, label, sourceNote }
}

async function opsAttachJobPhoto(client: any, body: any) {
  const parsed = normaliseOpsAttachJobPhotoInput(body)
  const { data: job, error: jobErr } = await client.from('jobs')
    .select('id, job_number')
    .eq('id', parsed.jId)
    .maybeSingle()
  if (jobErr) throw jobErr
  if (!job) throw new ApiError('Job not found', 404)

  const photoId = crypto.randomUUID()
  const path = `${DEFAULT_ORG_ID}/${parsed.jId}/photos/${photoId}.${parsed.ext}`

  try { await client.storage.createBucket('job-photos', { public: true }) } catch { /* exists */ }

  const { error: uploadError } = await client.storage
    .from('job-photos')
    .upload(path, parsed.bytes, { contentType: parsed.mime, upsert: false })
  if (uploadError) throw uploadError

  const { data: urlData } = client.storage.from('job-photos').getPublicUrl(path)
  const mediaInsert: any = {
    job_id: parsed.jId,
    type: 'photo',
    storage_url: urlData.publicUrl,
    thumbnail_url: urlData.publicUrl,
    label: parsed.label,
    phase: parsed.phase,
    uploaded_by: null,
    notes: parsed.sourceNote,
  }

  const { data: mediaRecord, error: mediaError } = await client.from('job_media').insert(mediaInsert).select().single()
  if (mediaError) throw mediaError

  await client.from('job_events').insert({
    job_id: parsed.jId,
    user_id: null,
    event_type: 'photo_added',
    detail_json: {
      media_id: mediaRecord.id,
      phase: parsed.phase,
      source: 'ops_attach_job_photo',
      label: parsed.label,
    },
  })

  return { ok: true, job_id: parsed.jId, job_number: job.job_number, media_id: mediaRecord.id, url: urlData.publicUrl }
}

export const _normaliseOpsAttachJobPhotoInputForTest = normaliseOpsAttachJobPhotoInput

async function submitServiceReport(client: any, body: any) {
  const { jobId, job_id, userId, user_id, checklist, notes, signatureData, signatureName, status, weather, start_time, end_time, variations } = body
  const jId = jobId || job_id
  if (!jId) throw new Error('jobId required')

  const reportStatus = status || 'submitted'
  const uId = userId || user_id || null

  // Verify user is assigned, or this is a MakeSafe/SWMS field-report job.
  if (uId) await assertAssignedOrMakesafeAccess(client, jId, uId)

  // Upload signature to storage if provided (instead of storing base64 in DB)
  let signatureUrl: string | null = null
  if (signatureData && signatureData.startsWith('data:')) {
    const base64 = signatureData.split(',')[1]
    const bytes = Uint8Array.from(atob(base64), (c: string) => c.charCodeAt(0))
    const sigId = crypto.randomUUID()
    const path = `${DEFAULT_ORG_ID}/${jId}/signatures/${sigId}.png`

    try { await client.storage.createBucket('job-photos', { public: true }) } catch { /* exists */ }

    const { error: uploadErr } = await client.storage
      .from('job-photos')
      .upload(path, bytes, { contentType: 'image/png', upsert: false })

    if (!uploadErr) {
      const { data: urlData } = client.storage.from('job-photos').getPublicUrl(path)
      signatureUrl = urlData.publicUrl
    }
  } else if (signatureData) {
    // Already a URL (re-submission of existing report)
    signatureUrl = signatureData
  }

  // Prevent overwriting an approved report
  const { data: existing } = await client
    .from('job_service_reports')
    .select('id, status')
    .eq('job_id', jId)
    .limit(1)
    .maybeSingle()

  if (existing?.status === 'approved' && reportStatus !== 'approved') {
    throw new Error('This report has been approved and cannot be modified')
  }

  let report
  const reportFields: Record<string, any> = {
    checklist_json: checklist || [],
    notes: notes || null,
    signature_data: signatureUrl,
    signature_name: signatureName || null,
    status: reportStatus,
    submitted_by: uId,
    submitted_at: reportStatus === 'submitted' ? new Date().toISOString() : null,
    weather: weather || null,
    start_time: start_time || null,
    end_time: end_time || null,
    variations: variations || null,
  }

  if (existing) {
    const { data, error } = await client
      .from('job_service_reports')
      .update(reportFields)
      .eq('id', existing.id)
      .select().single()

    if (error) throw error
    report = data
  } else {
    const { data, error } = await client
      .from('job_service_reports')
      .insert({ job_id: jId, ...reportFields })
      .select().single()

    if (error) throw error
    report = data
  }

  if (reportStatus === 'submitted') {
    await client.from('job_events').insert({
      job_id: jId,
      user_id: uId,
      event_type: 'service_report_submitted',
      detail_json: { report_id: report.id },
    })

    // Move GHL opportunity to "Job Complete" stage (non-blocking)
    try {
      const { data: jobData } = await client.from('jobs')
        .select('ghl_opportunity_id, type, id')
        .eq('id', jId).single()

      if (jobData?.ghl_opportunity_id) {
        const ghlProxyUrl = `${SUPABASE_URL}/functions/v1/ghl-proxy?action=move_to_complete`
        fetch(ghlProxyUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            opportunityId: jobData.ghl_opportunity_id,
            jobType: jobData.type || 'patio',
            jobId: jId,
          }),
        }).catch((e: any) => console.log('[ops-api] GHL move_to_complete fire-and-forget error:', e))
      }
    } catch (e) {
      console.log('[ops-api] GHL stage move lookup failed (non-blocking):', e)
    }
  }

  return { report }
}

async function getServiceReport(client: any, params: URLSearchParams, userId: string) {
  const jobId = params.get('jobId')
  if (!jobId) throw new Error('jobId required')

  // Verify user is assigned, or this is a MakeSafe/SWMS field-report job.
  await assertAssignedOrMakesafeAccess(client, jobId, userId)

  const { data: report } = await client
    .from('job_service_reports')
    .select('*')
    .eq('job_id', jobId)
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle()

  const { data: job } = await client.from('jobs').select('type').eq('id', jobId).maybeSingle()
  const configKey = job?.type === 'fencing' ? 'service_checklist_fencing' : 'service_checklist_patio'
  const { data: config } = await client
    .from('org_config')
    .select('config_value')
    .eq('org_id', DEFAULT_ORG_ID)
    .eq('config_key', configKey)
    .maybeSingle()

  return {
    report: report || null,
    checklistTemplate: config?.config_value?.items || [],
  }
}

// ── Shared Report (public, no auth) — returns branded HTML page ──
async function viewSharedReport(client: any, params: URLSearchParams) {
  const token = params.get('token')
  if (!token) return json({ error: 'token required' }, 400)

  // Look up report by share_token
  const { data: report } = await client
    .from('job_service_reports')
    .select('*, jobs!inner(client_name, site_address, site_suburb, type)')
    .eq('share_token', token)
    .maybeSingle()

  if (!report) {
    return new Response('<html><body style="font-family:sans-serif;text-align:center;padding:60px"><h2>Report not found</h2><p>This link may have expired or is invalid.</p></body></html>', {
      status: 404,
      headers: { 'Content-Type': 'text/html; charset=utf-8', ...CORS },
    })
  }

  // Only show submitted/approved reports (not drafts)
  if (report.status === 'draft') {
    return new Response('<html><body style="font-family:sans-serif;text-align:center;padding:60px"><h2>Report not ready</h2><p>This report has not been submitted yet.</p></body></html>', {
      status: 403,
      headers: { 'Content-Type': 'text/html; charset=utf-8', ...CORS },
    })
  }

  // Get completion photos for this job
  const { data: photos } = await client
    .from('job_media')
    .select('url, caption')
    .eq('job_id', report.job_id)
    .eq('phase', 'completion')
    .order('uploaded_at', { ascending: false })

  const job = report.jobs
  const checklist: Array<{ label: string; checked: boolean }> = report.checklist_json || []
  const photoList: Array<{ url: string; caption: string }> = photos || []
  const esc = (s: string) => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

  // Build branded HTML page
  let html = `<!DOCTYPE html><html lang="en"><head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Service Report — ${esc(job.client_name || '')}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1A2332;background:#f5f6f8;line-height:1.6}
.wrap{max-width:600px;margin:0 auto;background:#fff;min-height:100vh}
.header{background:#293C46;color:#fff;padding:20px 24px;display:flex;justify-content:space-between;align-items:center}
.header h1{font-size:18px;font-weight:700}.header .brand{font-size:12px;opacity:.7}
.accent{height:4px;background:#F15A29}
.badge{display:inline-block;padding:3px 10px;border-radius:12px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px}
.badge-submitted{background:#E8F4FD;color:#2980B9}.badge-approved{background:#E8F8E8;color:#27AE60}
.section{padding:16px 24px;border-bottom:1px solid #eee}
.section h3{font-size:11px;text-transform:uppercase;letter-spacing:.8px;color:#4C6A7C;margin-bottom:10px;font-weight:700}
.info-row{display:flex;gap:12px;font-size:14px;margin:4px 0}
.info-label{font-weight:700;min-width:70px;color:#4C6A7C;flex-shrink:0}
.checklist{list-style:none}
.checklist li{padding:8px 0;border-bottom:1px solid #f0f0f0;font-size:14px;display:flex;align-items:center;gap:8px}
.checklist li:last-child{border-bottom:none}
.check-icon{width:20px;height:20px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:12px}
.check-yes{background:#E8F8E8;color:#27AE60}.check-no{background:#FDE8E8;color:#E74C3C}
.notes{font-size:14px;white-space:pre-wrap;background:#f7f8fa;padding:12px 16px;border-radius:8px}
.photos{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px}
.photos img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:8px;cursor:pointer}
.sig-block{text-align:center;padding:16px;background:#f7f8fa;border-radius:8px}
.sig-block img{max-width:280px;width:100%}
.sig-name{font-size:14px;color:#4C6A7C;margin-top:6px}
.footer{padding:24px;text-align:center;font-size:11px;color:#7C8898;border-top:1px solid #eee}
@media print{body{background:#fff}.wrap{max-width:100%}.photos img{max-height:200px}}
</style></head><body>
<div class="wrap">
<div class="header">
<div><h1>Service Report</h1><div class="brand">SecureWorks Group</div></div>
<span class="badge badge-${report.status}">${report.status}</span>
</div>
<div class="accent"></div>

<div class="section">
<h3>Job Details</h3>
<div class="info-row"><span class="info-label">Client</span><span>${esc(job.client_name || '')}</span></div>
<div class="info-row"><span class="info-label">Address</span><span>${esc((job.site_address || '') + (job.site_suburb ? ', ' + job.site_suburb : ''))}</span></div>
<div class="info-row"><span class="info-label">Type</span><span style="text-transform:capitalize">${esc(job.type || 'patio')}</span></div>`

  if (report.submitted_at) {
    const d = new Date(report.submitted_at)
    const dateStr = d.toLocaleDateString('en-AU', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Australia/Perth' })
    html += `\n<div class="info-row"><span class="info-label">Completed</span><span>${dateStr}</span></div>`
  }

  html += `</div>`

  // Checklist
  if (checklist.length > 0) {
    html += `<div class="section"><h3>Completion Checklist</h3><ul class="checklist">`
    for (const item of checklist) {
      const icon = item.checked
        ? '<span class="check-icon check-yes">&#10003;</span>'
        : '<span class="check-icon check-no">&#10007;</span>'
      html += `<li>${icon}${esc(item.label)}</li>`
    }
    html += `</ul></div>`
  }

  // Notes
  if (report.notes) {
    html += `<div class="section"><h3>Notes</h3><div class="notes">${esc(report.notes)}</div></div>`
  }

  // Completion photos
  if (photoList.length > 0) {
    html += `<div class="section"><h3>Completion Photos</h3><div class="photos">`
    for (const p of photoList) {
      html += `<img src="${esc(p.url)}" alt="${esc(p.caption || 'Completion photo')}" loading="lazy">`
    }
    html += `</div></div>`
  }

  // Signature
  if (report.signature_data) {
    html += `<div class="section"><h3>Homeowner Sign-Off</h3>
<div class="sig-block"><img src="${report.signature_data}" alt="Signature">`
    if (report.signature_name) html += `<div class="sig-name">${esc(report.signature_name)}</div>`
    html += `</div></div>`
  }

  html += `<div class="footer">SecureWorks Group Pty Ltd &mdash; ABN 64689223416 &mdash; Perth, Western Australia</div>
</div></body></html>`

  return new Response(html, {
    headers: { 'Content-Type': 'text/html; charset=utf-8', ...CORS },
  })
}

// ── Document Upload Management ──
async function uploadDocument(client: any, body: any) {
  const { jobId, job_id, fileName, file_name, contentType, content_type, type, visible_to_trades } = body
  const jId = jobId || job_id
  const fName = fileName || file_name
  if (!jId || !fName) throw new Error('jobId and fileName required')

  const allowedTypes = ['work_order', 'supplier_work_order', 'quote', 'approval', 'site_photo', 'general', 'supplier_quote', 'council_plans', 'engineering', 'client_reference', 'asbestos', 'makesafe_report', 'invoice', 'swms', 'other']
  const docType = allowedTypes.includes(type) ? type : 'general'

  const bucket = 'job-documents'
  try { await client.storage.createBucket(bucket, { public: true }) } catch { /* exists */ }

  const path = `${jId}/${Date.now()}-${fName.replace(/[^a-zA-Z0-9._-]/g, '_')}`
  const { data: signedData, error: signError } = await client.storage
    .from(bucket)
    .createSignedUploadUrl(path)

  if (signError) throw signError

  const { data: urlData } = client.storage.from(bucket).getPublicUrl(path)

  return {
    uploadUrl: signedData.signedUrl,
    token: signedData.token,
    path: path,
    publicUrl: urlData.publicUrl,
    docType: docType,
  }
}

async function confirmDocumentUpload(client: any, body: any) {
  const { jobId, job_id, publicUrl, path, fileName, type, visible_to_trades, uploaded_by } = body
  const jId = jobId || job_id
  if (!jId || !publicUrl) throw new Error('jobId and publicUrl required')

  // Default visibility: on for field/useful trade docs. Off for quote/client-only docs.
  // makesafe_report + swms are operational docs trades/ops view on site (close-out
  // contract surfaces them on the Ops Dash MakeSafe card); invoice is client/admin
  // only so it defaults trades-hidden.
  const defaultVisible = ['site_photo', 'council_plans', 'engineering', 'work_order', 'supplier_work_order', 'supplier_quote', 'approval', 'makesafe_report', 'swms'].includes(type)
  const isVisible = visible_to_trades != null ? visible_to_trades : defaultVisible

  const allowedTypes = ['work_order', 'supplier_work_order', 'quote', 'approval', 'site_photo', 'general', 'supplier_quote', 'council_plans', 'engineering', 'client_reference', 'asbestos', 'makesafe_report', 'invoice', 'swms', 'other']
  const docType = allowedTypes.includes(type) ? type : 'general'

  const insertData: any = {
    job_id: jId,
    type: docType,
    storage_url: publicUrl,
    file_name: fileName || path,
    visible_to_trades: isVisible,
    version: 1,
    // uploaded_by is a UUID column (FK to users). opsPost injects operator_email
    // on every dashboard call, so this value is usually an email, not a UUID.
    // Coerce any non-UUID value to NULL so the insert never throws "invalid input
    // syntax for type uuid". The operator identity is still preserved in the
    // job_events / business_events rows below for the audit trail.
    uploaded_by: ((v: any) => (typeof v === 'string' && /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(v) ? v : null))(uploaded_by || body.operator_email),
  }

  // Set pdf_url for PDF files so existing code can find them
  if (fileName && /\.pdf$/i.test(fileName)) {
    insertData.pdf_url = publicUrl
  }

  const { data: doc, error } = await client.from('job_documents')
    .insert(insertData).select('id').single()

  if (error) throw error

  // Log event
  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'document_uploaded',
    detail_json: { document_id: doc?.id, type: docType, file_name: fileName, visible_to_trades: isVisible, uploaded_by: uploaded_by || body.operator_email || null },
  })

  // Dual-write to business_events
  logBusinessEvent(client, {
    event_type: 'document.uploaded',
    entity_type: 'job_document',
    entity_id: doc?.id || '',
    job_id: jId,
    payload: { type: docType, file_name: fileName, visible_to_trades: isVisible },
    metadata: { operator: uploaded_by || body.operator_email || null },
  })

  return { success: true, document_id: doc?.id, url: publicUrl }
}

// ── attach_email_attachment_to_job ──────────────────────────────────────────
// Copy a work-order PDF that already lives in the PRIVATE `makesafe-emails`
// bucket (referenced by an `email_attachments` row) onto a live make-safe job's
// document list in the PUBLIC `job-documents` bucket, so the WO PDF renders on
// the board card.
//
// WHY THIS EXISTS: the email sync drops the builder WO PDF into the private
// `makesafe-emails` bucket and records it in `email_attachments` (status
// 'uploaded'). The board reads documents from the public `job-documents`
// bucket. The manual terminal intake skill can READ the PDF (ms365) but cannot
// fetch the private bucket bytes to re-host them — that needs the service-role
// key, which the terminal must not hold. This action does the byte-copy
// SERVER-SIDE with the service key, then delegates to attachMakesafeDocument so
// the job_documents row, idempotency, visibility and ledger logic are identical
// to every other typed attach.
//
// Accepts: job_id, and EITHER email_attachment_id (preferred) OR
// (email_id [+ optional sha256 / file_name]) to resolve the row. Optional:
// type (default 'work_order'), file_name override, visible_to_trades,
// operator_email. Read of the private bytes + upload of the public copy run on
// the admin (service-role) client; the job_documents write reuses the caller's
// client via attachMakesafeDocument. Does NOT change job status or send.
// ── item 11: live-Graph fallback helpers (pure + testable) ───────────────────

// A Graph message attachment (fileAttachment) as returned by
// GET /users/{mailbox}/messages/{id}/attachments.
interface GraphMessageAttachment {
  id?: string
  name?: string
  contentType?: string
  size?: number
  contentBytes?: string // base64
}

// Choose which attachment to attach from a live Graph attachments list. Only file
// attachments that carry inline base64 bytes are eligible (item/reference stubs
// and empty ones are skipped). Priority: explicit graph attachment id, then exact
// file name (case-insensitive), then the first PDF, then the first eligible file.
// Returns null when nothing qualifies. Pure — the handler owns the Graph I/O.
function pickGraphAttachment(
  attachments: GraphMessageAttachment[] | null | undefined,
  pick: { attachmentId?: string | null; fileName?: string | null } = {},
): GraphMessageAttachment | null {
  const eligible = (attachments || []).filter(
    (a) => a && typeof a.contentBytes === 'string' && a.contentBytes.length > 0,
  )
  if (!eligible.length) return null
  const wantId = String(pick.attachmentId || '').trim()
  if (wantId) {
    const byId = eligible.find((a) => a.id === wantId)
    if (byId) return byId
  }
  const wantName = String(pick.fileName || '').trim().toLowerCase()
  if (wantName) {
    const byName = eligible.find((a) => String(a.name || '').trim().toLowerCase() === wantName)
    if (byName) return byName
  }
  const isPdf = (a: GraphMessageAttachment) =>
    String(a.contentType || '').toLowerCase().includes('pdf') ||
    String(a.name || '').toLowerCase().endsWith('.pdf')
  return eligible.find(isPdf) || eligible[0]
}

// The ordered, de-duplicated set of mailboxes to try a live Graph message read
// against when the email_attachments intake table has no synced bytes. A
// caller-supplied mailbox wins; then the mailbox the emails projection recorded
// for this message; then the documented default set (ses@ group + admin@) — where
// both inbound WOs and our own OUTBOUND sent packs live.
const MAKESAFE_MAILBOX_FALLBACKS = [
  'ses@secureworkswa.com.au',
  'admin@secureworkswa.com.au',
]
function resolveMailboxCandidates(
  bodyMailbox: string | null | undefined,
  emailRowMailbox: string | null | undefined,
  defaults: readonly string[] = MAKESAFE_MAILBOX_FALLBACKS,
): string[] {
  const out: string[] = []
  const add = (m: string | null | undefined) => {
    const v = String(m || '').trim().toLowerCase()
    if (v && !out.includes(v)) out.push(v)
  }
  add(bodyMailbox)
  add(emailRowMailbox)
  for (const d of defaults) add(d)
  return out
}

type GraphAttachmentsResult =
  | { ok: true; attachments: GraphMessageAttachment[] }
  | { ok: false; status: number; error: string }

// Live-read a mailbox message's attachments via Graph (token self-heal on a 401
// expired-token via the shared graphFetch refresh path — intake item 12).
async function fetchGraphMessageAttachments(
  mailbox: string,
  messageId: string,
): Promise<GraphAttachmentsResult> {
  const token = await _getGraphToken()
  const url = `https://graph.microsoft.com/v1.0/users/${encodeURIComponent(mailbox)}/messages/${encodeURIComponent(messageId)}/attachments`
  const resp = await _graphFetch(url, token, { refresh: () => _getGraphToken({ forceRefresh: true }) })
  if (!resp.ok) {
    const error = await resp.text().catch(() => '')
    return { ok: false, status: resp.status, error: String(error).slice(0, 300) }
  }
  const data = await resp.json().catch(() => ({}))
  return { ok: true, attachments: (data?.value || []) as GraphMessageAttachment[] }
}

// Copy a work-order (or other typed) PDF onto a live make-safe job's document list.
//
// PRIMARY path: resolve the synced email_attachments row (private makesafe-emails
// bucket) and re-host it — unchanged.
//
// FALLBACK (item 11): when the intake table has no synced bytes, live-read the
// mailbox message via Graph and attach the chosen attachment. This covers the two
// real 2026-07-07 gaps that used to 500: (a) our own OUTBOUND sent packs (Admin
// Sent Items are never in the inbound intake table) and (b) inbound WOs from
// senders not in the intake watch set (e.g. Prime Notification Centre). The typed,
// idempotent delegation to attachMakesafeDocument is identical on both paths.
//
// `deps.fetchGraphAttachments` is injectable for tests; production uses the live
// Graph fetch above.
async function attachEmailAttachmentToJob(
  client: any,
  body: any,
  deps: {
    fetchGraphAttachments?: (mailbox: string, messageId: string) => Promise<GraphAttachmentsResult>
    adminClient?: any
  } = {},
) {
  const jId = body.job_id || body.jobId
  if (!jId) throw new Error('job_id required')
  const type = body.type || 'work_order'

  // ── PRIMARY: resolve a synced email_attachments row. A miss no longer throws —
  //    it falls through to the live-Graph fallback below.
  const adminClient = deps.adminClient || createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)
  let att: any = null
  if (body.email_attachment_id || body.attachment_id) {
    const { data, error } = await adminClient.from('email_attachments')
      .select('id, name, content_type, storage_path, status, sha256, size_bytes')
      .eq('id', body.email_attachment_id || body.attachment_id).maybeSingle()
    if (error) throw new Error('email_attachments lookup failed: ' + error.message)
    att = data
  } else if (body.email_id) {
    let q = adminClient.from('email_attachments')
      .select('id, name, content_type, storage_path, status, sha256, size_bytes')
      .eq('email_id', body.email_id).eq('status', 'uploaded')
    if (body.sha256) q = q.eq('sha256', body.sha256)
    if (body.file_name || body.name) q = q.eq('name', body.file_name || body.name)
    const { data, error } = await q.order('created_at', { ascending: true })
    if (error) throw new Error('email_attachments lookup failed: ' + error.message)
    // Prefer a PDF when multiple match and no exact name was given.
    const rows = data || []
    att = rows.find((r: any) => (r.content_type || '').includes('pdf') || (r.name || '').toLowerCase().endsWith('.pdf')) || rows[0]
  }

  if (att && att.storage_path) {
    // Download the private bytes (service role) and re-host — the proven path.
    const { data: blob, error: dlErr } = await adminClient.storage
      .from('makesafe-emails')
      .download(att.storage_path)
    if (dlErr || !blob) throw new Error('private bucket download failed: ' + (dlErr?.message || 'no blob') + ` (path=${att.storage_path})`)
    const fileBuffer = new Uint8Array(await blob.arrayBuffer())
    const fileName = body.file_name || body.name || att.name || `work-order-${jId}.pdf`
    const result = await attachMakesafeDocument(client, {
      job_id: jId,
      type,
      pdf_base64: bytesToBase64(fileBuffer),
      file_name: fileName,
      visible_to_trades: body.visible_to_trades,
      operator_email: body.operator_email || body.uploaded_by,
    })
    return {
      ...result,
      source: 'email_attachment',
      email_attachment_id: att.id,
      source_storage_path: att.storage_path,
      bytes: fileBuffer.length,
    }
  }

  // ── FALLBACK (item 11): live Graph fetch for ANY mailbox message. ──
  const messageId = String(body.message_id || body.email_id || body.graph_message_id || '').trim()
  if (!messageId) {
    // No synced row AND nothing to fetch live — a clear 400, not an opaque 500.
    throw new ApiError(
      'attach failed: no synced email_attachments bytes and no message_id/email_id to fetch the attachment live from the mailbox' +
        (att ? ` (email_attachments ${att.id} status='${att.status}' has no storage_path)` : ''),
      400,
    )
  }
  // Best-effort mailbox hint from the emails projection (post_id == Graph msg id).
  let emailRowMailbox: string | null = null
  try {
    const { data: emailRow } = await adminClient.from('emails')
      .select('mailbox').eq('post_id', messageId).maybeSingle()
    emailRowMailbox = emailRow?.mailbox || null
  } catch (_) { /* projection is optional — defaults still cover it */ }

  const candidates = resolveMailboxCandidates(body.mailbox, emailRowMailbox)
  const fetchGraph = deps.fetchGraphAttachments || fetchGraphMessageAttachments
  const pick = {
    attachmentId: body.graph_attachment_id || body.attachment_id || null,
    fileName: body.file_name || body.name || null,
  }
  let chosen: GraphMessageAttachment | null = null
  let lastError = ''
  for (const mailbox of candidates) {
    const r = await fetchGraph(mailbox, messageId)
    if (!r.ok) { lastError = `${mailbox}: ${r.status} ${r.error}`; continue }
    const picked = pickGraphAttachment(r.attachments, pick)
    if (picked) { chosen = picked; break }
    lastError = `${mailbox}: message has no eligible (inline-bytes) attachment`
  }
  if (!chosen) {
    throw new ApiError(
      `attach failed: could not resolve a mailbox attachment for message ${messageId} ` +
        `(tried ${candidates.join(', ')}; ${lastError})`,
      404,
    )
  }

  const fileName = body.file_name || body.name || chosen.name || `work-order-${jId}.pdf`
  const result = await attachMakesafeDocument(client, {
    job_id: jId,
    type,
    pdf_base64: chosen.contentBytes,
    file_name: fileName,
    visible_to_trades: body.visible_to_trades,
    operator_email: body.operator_email || body.uploaded_by,
  })
  return {
    ...result,
    source: 'mailbox_graph',
    message_id: messageId,
    graph_attachment_id: chosen.id || null,
    mailbox_tried: candidates,
  }
}

// ── Make-Safe close-out doc attach (typed + idempotent) ──
// Closes the gap the close-out contract requires: the completion report,
// authorised invoice and SWMS are emailed by the wiki Python skill but no
// job_documents row is ever created, so the Ops Dash MakeSafe card only ever
// shows the work order. This action writes the typed job_documents row so the
// board/contract can verify the evidence. It does NOT change job status, send
// anything or mutate live business state.
//
// Accepts: job_id, type (makesafe_report|invoice|swms|work_order), and EITHER a
// public/storage `url` already in the bucket OR `pdf_base64` bytes to upload to
// the `job-documents` bucket. Idempotent on (job_id, type, file_name): an
// existing row of the same type+file_name is updated (version bumped) instead of
// inserting a duplicate — mirrors the work-order attach pattern.
async function attachMakesafeDocument(client: any, body: any) {
  const jId = body.job_id || body.jobId
  const type = body.type
  // 'roof_report' is the SecureWorks own-letterhead roof inspection report. Unlike
  // 'makesafe_report' (blocked on report-type jobs below), the roof report is
  // DELIBERATELY produced for report-type jobs -- generating our own letterhead
  // report is the whole point of the roof-report flow -- so it is not subject to
  // the report-type gate.
  const allowedTypes = ['work_order', 'makesafe_report', 'roof_report', 'invoice', 'swms']
  if (!jId) throw new Error('job_id required')
  if (!allowedTypes.includes(type)) {
    throw new Error('type must be one of ' + allowedTypes.join(', '))
  }

  // ── REPORT-JOB REPORT-DOC GATE ──
  // A report-type job (report_type IS NOT NULL in makesafe_job_details) never gets a
  // SecureWorks-authored makesafe_report document — the completion report is owned by
  // the builder and lives on the builder portal, not in the job folder. Allowing it
  // would create a confusing duplicate of the builder-side PDF in the ops doc list.
  // Other doc types (invoice, work_order, swms) on report jobs are unaffected.
  if (type === 'makesafe_report') {
    const { data: reportJobDetail } = await client.from('makesafe_job_details')
      .select('report_type').eq('job_id', jId).maybeSingle()
    if (reportJobDetail?.report_type != null) {
      throw new ApiError(
        `attachMakesafeDocument: type 'makesafe_report' is not allowed on a report-type job (report_type='${reportJobDetail.report_type}'); ` +
        'the completion report lives on the builder portal, not in the job folder',
        400,
      )
    }
  }

  const url: string | undefined = body.url || body.public_url || body.publicUrl || body.storage_url
  const pdfBase64: string | undefined = body.pdf_base64 || body.pdfBase64
  if (!url && !pdfBase64) throw new Error('url or pdf_base64 required')

  // Resolve a stable file name. Caller may pass one; otherwise derive from the
  // type so idempotency stays deterministic per job+type.
  const rawName: string = body.file_name || body.fileName ||
    (url ? decodeURIComponent(url.split('/').pop()?.split('?')[0] || '') : '') ||
    `${type}-${jId}.pdf`
  const fileName = rawName || `${type}-${jId}.pdf`

  const bucket = 'job-documents'
  let publicUrl: string
  let storagePath: string

  if (pdfBase64) {
    // Upload bytes — mirrors the create_makesafe_job PDF upload path.
    const pdfBuffer = Uint8Array.from(atob(pdfBase64), (c) => c.charCodeAt(0))
    storagePath = `${jId}/${fileName.replace(/[^a-zA-Z0-9._-]/g, '_')}`
    const adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)
    try { await adminClient.storage.createBucket(bucket, { public: true }) } catch { /* exists */ }
    const { error: upErr } = await adminClient.storage
      .from(bucket)
      .upload(storagePath, pdfBuffer, { contentType: 'application/pdf', upsert: true })
    if (upErr) throw new Error('Storage upload failed: ' + upErr.message)
    const { data: urlData } = adminClient.storage.from(bucket).getPublicUrl(storagePath)
    publicUrl = urlData?.publicUrl || ''
  } else {
    // Already-in-storage URL path.
    publicUrl = url as string
    storagePath = body.path || body.storage_path || publicUrl
  }

  // Visibility: report + swms are operational docs trades/ops view on site;
  // invoice is client/admin only; work_order stays trade-visible. Caller may
  // override with visible_to_trades.
  const defaultVisible = ['work_order', 'makesafe_report', 'roof_report', 'swms'].includes(type)
  const isVisible = body.visible_to_trades != null ? body.visible_to_trades : defaultVisible
  const isPdf = /\.pdf$/i.test(fileName)

  // Idempotency: same job + type + file_name → update (bump version), else insert.
  const { data: existing } = await client.from('job_documents')
    .select('id, version').eq('job_id', jId).eq('type', type).eq('file_name', fileName).limit(1)

  let docId: string
  if (existing && existing.length > 0) {
    const nextVersion = (existing[0].version || 1) + 1
    const updateData: any = {
      storage_url: publicUrl,
      visible_to_trades: isVisible,
      version: nextVersion,
    }
    if (isPdf) updateData.pdf_url = publicUrl
    const { error: updErr } = await client.from('job_documents')
      .update(updateData).eq('id', existing[0].id)
    if (updErr) throw updErr
    docId = existing[0].id
  } else {
    const insertData: any = {
      job_id: jId,
      type: type,
      file_name: fileName,
      storage_url: publicUrl,
      visible_to_trades: isVisible,
      version: 1,
      // uploaded_by is a UUID column (FK to users). Callers sometimes pass an
      // operator label or email (the dashboard api_key path has no user UUID,
      // only a fallback label like "makesafe reporting autopilot"). Coerce any
      // non-UUID value to NULL so the insert never throws "invalid input syntax
      // for type uuid". The human-readable operator label is still preserved in
      // the job_events / business_events JSON below for the audit trail.
      uploaded_by: ((v: any) => (typeof v === 'string' && /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(v) ? v : null))(body.uploaded_by || body.operator_email),
    }
    if (isPdf) insertData.pdf_url = publicUrl
    const { data: newDoc, error: insErr } = await client.from('job_documents')
      .insert(insertData).select('id').single()
    if (insErr) throw insErr
    docId = newDoc?.id
  }

  // Job event ledger row.
  await client.from('job_events').insert({
    job_id: jId,
    event_type: 'makesafe_document_attached',
    detail_json: {
      document_id: docId,
      type: type,
      file_name: fileName,
      visible_to_trades: isVisible,
      uploaded_by: body.uploaded_by || body.operator_email || null,
    },
  })

  // Dual-write to business_events (best-effort, mirrors confirmDocumentUpload).
  logBusinessEvent(client, {
    event_type: 'document.uploaded',
    entity_type: 'job_document',
    entity_id: docId || '',
    job_id: jId,
    payload: { type: type, file_name: fileName, visible_to_trades: isVisible, source: 'makesafe_closeout' },
    metadata: { operator: body.uploaded_by || body.operator_email || null },
  })

  return { success: true, document_id: docId, type: type, url: publicUrl }
}

// ════════════════════════════════════════════════════════════════════════════
// MakeSafe Reporting Autopilot (Wave 2) — draft invoice, render report, send pack
// ════════════════════════════════════════════════════════════════════════════

type MakesafeReportPhotoCandidate = {
  url?: string | null
  storage_url?: string | null
  thumbnail_url?: string | null
  label?: string | null
  taken_at?: string | null
  created_at?: string | null
}

function selectMakesafeReportPhotosForReport<T extends MakesafeReportPhotoCandidate>(
  photos: T[],
  limit = 8,
): T[] {
  const clean = (photos || []).filter((p: any) => p?.url || p?.storage_url || p?.thumbnail_url)
  const cap = Math.max(0, Math.min(8, Math.floor(Number(limit) || 8)))
  if (cap === 0) return []
  if (clean.length <= cap) return clean.slice(0, cap)

  // Field uploads are chronological: early shots carry address/damage context,
  // late shots usually prove the completed make-safe. The old first-8 cap dropped
  // photo 9 on 7 Broughton St, which was the clearest temporary fence/star-picket
  // evidence. Preserve both ends and drop the middle duplicate/materials shots.
  const headCount = Math.ceil(cap / 2)
  const tailCount = cap - headCount
  const out: T[] = []
  const seen = new Set<string>()
  const push = (photo: T) => {
    const key = String(photo.url || photo.storage_url || photo.thumbnail_url || '')
    if (!key || seen.has(key)) return
    seen.add(key)
    out.push(photo)
  }
  clean.slice(0, headCount).forEach(push)
  clean.slice(clean.length - tailCount).forEach(push)
  return out.slice(0, cap)
}

export const _selectMakesafeReportPhotosForTest = selectMakesafeReportPhotosForReport

// (3d) makesafe_report_drafts — READ-ONLY feed for the report-draft cockpit.
// Returns every report-draft-ready job (makesafe_job_details.substatus =
// 'admin_to_send_report') with the full informed-approve content set: invoice
// line items + totals, signed/public PDF urls (report + invoice), evidence
// photos, the builder recipient email, a gate-passing default subject + html
// body, and the send-pack status if a pack row exists. No writes, no Xero, no
// send. The cockpit shows all of this so a human can make an informed decision
// before the approve button fires makesafe_send_pack.
//
// NOTE on invoice line items: createInvoice does NOT write line_items into the
// local xero_invoices row — only the 2-hourly xero-sync does. So a freshly
// drafted make-safe invoice can have NULL/[] lines locally. When that happens we
// return lines:[] + lines_unavailable:true + a note; the inline invoice PDF in
// the cockpit still satisfies the informed-approve gate (the amount + the PDF
// are enough to decide).
async function makesafeReportDrafts(client: any, params: URLSearchParams) {
  const limit = Math.min(parseInt(params.get('limit') || '50', 10) || 50, 200)
  const SIGNED_TTL = 600 // 10 min, short-lived signed urls for any private docs

  const DETAIL_SELECT = 'job_id, requesting_company_id, requesting_company_slug, requesting_company_name, external_ref, substatus, report_received_at, report_sent_at, invoice_notes, reattend_count, last_reattend_at, last_reattend_reason, cycle_number, makesafe_companies(slug, name, invoice_email, report_recipient)'

  // 1) The report-draft-ready make-safe details. report_sent_at is loaded so the
  // shared surfacing predicate can exclude an already-sent-but-stale job (the
  // substatus alone is NOT enough — see T3). The outer substatus filter is KEPT
  // intact (it is the primary feed source).
  const { data: details, error: detErr } = await client
    .from('makesafe_job_details')
    .select(DETAIL_SELECT)
    .eq('substatus', REPORT_DRAFT_READY_SUBSTATUS)
    .limit(limit)
  if (detErr) throw new ApiError('makesafe_report_drafts: details read failed: ' + detErr.message, 500)
  const detailRows: any[] = (details || []).slice()
  const detailJobIdSet = new Set<string>(detailRows.map((d: any) => d.job_id).filter(Boolean))

  // 1b) RESUME-AWARE UNION (TASK A — the Ferndale bug). A resume can move the
  // substatus OFF admin_to_send_report (e.g. an authorised_not_sent pack whose
  // job advanced), so the substatus filter alone EXCLUDES those resumable packs.
  // Also query makesafe_report_packs for the in-progress statuses and union any
  // job_ids NOT already in the detail set into the feed's detail fetch, so a
  // half-sent pack still surfaces for the operator to finish.
  const { data: resumablePacks, error: rpErr } = await client
    .from('makesafe_report_packs')
    .select('job_id, pack_kind, status, failed_step')
    .in('status', RESUMABLE_PACK_STATUSES)
    .limit(limit)
  if (rpErr) throw new ApiError('makesafe_report_drafts: resumable packs read failed: ' + rpErr.message, 500)
  const extraJobIds = Array.from(new Set(
    (resumablePacks || [])
      .filter((p: any) =>
        (p.pack_kind || 'main') === 'main' &&
        p.job_id &&
        !detailJobIdSet.has(p.job_id) &&
        !(p.status === 'sending' && p.failed_step === 'draft_pack')
      )
      .map((p: any) => p.job_id),
  )) as string[]
  if (extraJobIds.length > 0) {
    const { data: extraDetails, error: edErr } = await client
      .from('makesafe_job_details')
      .select(DETAIL_SELECT)
      .in('job_id', extraJobIds)
    if (edErr) throw new ApiError('makesafe_report_drafts: resumable details read failed: ' + edErr.message, 500)
    for (const d of (extraDetails || [])) {
      if (d?.job_id && !detailJobIdSet.has(d.job_id)) {
        detailRows.push(d)
        detailJobIdSet.add(d.job_id)
      }
    }
  }

  if (detailRows.length === 0) return { drafts: [], count: 0 }

  const jobIds: string[] = detailRows.map((d: any) => d.job_id).filter(Boolean)

  // 2) Bulk-load the related rows for those jobs (each a single .in() read).
  const [jobsRes, invoicesRes, docsRes, mediaRes, packsRes, serviceReportsRes] = await Promise.all([
    client.from('jobs')
      .select('id, job_number, client_name, client_email, client_phone, site_address, site_suburb, status, type, created_at')
      .in('id', jobIds),
    client.from('xero_invoices')
      .select('xero_invoice_id, invoice_number, status, reference, sub_total, total, total_tax, line_items, job_id, invoice_date')
      .in('job_id', jobIds)
      .order('invoice_date', { ascending: false }),
    client.from('job_documents')
      .select('id, job_id, type, file_name, storage_url, pdf_url, version, created_at')
      .in('job_id', jobIds),
    client.from('job_media')
      .select('id, job_id, phase, type, storage_url, thumbnail_url, label, taken_at, created_at')
      .in('job_id', jobIds)
      .eq('phase', 'completion')
      .order('created_at', { ascending: true }),
    client.from('makesafe_report_packs')
      // B1 (Wave 0): last_render_hash feeds the versioned report doc URL (?v={hash})
      // below — without it pack?.last_render_hash is always undefined and the
      // cache-bust never appends, leaving the stale-doc fix inert.
      .select('job_id, pack_kind, status, report_doc_id, invoice_doc_id, swms_doc_id, xero_invoice_id, invoice_status, sent_at, send_started_at, failed_step, error_detail, last_render_hash')
      .in('job_id', jobIds),
    client.from('job_service_reports')
      .select('id, job_id, status, checklist_json, notes, signature_name, submitted_at, submitted_by, created_at, updated_at, cycle_number')
      .in('job_id', jobIds)
      .order('created_at', { ascending: false }),
  ])

  // T3 (adversarial review #1) — load the MAKESAFE_PACK_SENT | main marker map so
  // the feed excludes a LEGACY marker-only sent job (sent via the pre-pack-table
  // path: a marker note exists but there is no durable pack row and no
  // report_sent_at). Without this, such a job with a lingering DRAFT invoice +
  // admin_to_send_report substatus could slip into the cockpit and be re-sent.
  // The board already loads this map; the feed must too (single source of truth).
  const packSentMap = await buildPackSentMap(client, jobIds)

  const jobsById: Record<string, any> = {}
  for (const j of (jobsRes.data || [])) jobsById[j.id] = j

  const invoicesByJob: Record<string, any[]> = {}
  for (const inv of (invoicesRes.data || [])) {
    (invoicesByJob[inv.job_id] ||= []).push(inv)
  }
  const docsByJob: Record<string, any[]> = {}
  for (const d of (docsRes.data || [])) (docsByJob[d.job_id] ||= []).push(d)
  const mediaByJob: Record<string, any[]> = {}
  for (const m of (mediaRes.data || [])) (mediaByJob[m.job_id] ||= []).push(m)
  const packByJob: Record<string, any> = {}
  for (const p of (packsRes.data || [])) {
    if ((p.pack_kind || 'main') === 'main') packByJob[p.job_id] = p
  }
  // Re-attendance (M-C): retain EVERY report per job (not just the latest) so a
  // re-attended job's earlier visit report is never hidden from the reporting
  // skill. serviceReportByJob stays the latest (back-compat single-report reads);
  // serviceReportsByJob holds all reports, oldest→newest, for the multi-report
  // source-doc list below.
  const serviceReportByJob: Record<string, any> = {}
  const serviceReportsByJob: Record<string, any[]> = {}
  for (const r of (serviceReportsRes.data || [])) {
    if (!r?.job_id) continue
    if (!serviceReportByJob[r.job_id]) serviceReportByJob[r.job_id] = r // query is created_at desc → first is latest
    ;(serviceReportsByJob[r.job_id] ||= []).push(r)
  }
  for (const jobId of Object.keys(serviceReportsByJob)) {
    // Oldest → newest: cycle_number asc (first attendance first), created_at asc as tiebreak.
    serviceReportsByJob[jobId].sort((a, b) =>
      ((a.cycle_number ?? 1) - (b.cycle_number ?? 1)) ||
      String(a.created_at || '').localeCompare(String(b.created_at || '')))
  }

  // Mint a short-lived signed url for a job_documents storage path. The
  // job-documents bucket is public so pdf_url/storage_url is usually a full
  // public url already; we sign only when the stored value looks like a bare
  // storage path (no scheme). Falls back to the stored value on any failure.
  //
  // B1 (Wave 0 versioned URLs): an optional `versionHash` (the doc/render hash
  // from `makesafe_report_packs.last_render_hash`) is appended as `?v=<hash>` so
  // that a re-rendered document always produces a NEW URL the browser/CDN cannot
  // serve from cache. The stable filename + (job_id,type,file_name) idempotency key
  // are UNCHANGED — the cache-bust lives only in the returned URL, not in storage.
  // A re-render writes a new hash -> the next feed call returns a changed URL.
  const signDocUrl = async (stored: string | null | undefined, versionHash?: string | null): Promise<string | null> => {
    const raw = stored || null
    if (!raw) return null
    const appendVersion = (url: string): string => {
      if (!versionHash) return url
      const sep = url.includes('?') ? '&' : '?'
      return `${url}${sep}v=${versionHash}`
    }
    if (/^https?:\/\//i.test(raw)) return appendVersion(raw) // already a full (public) url
    try {
      const { data: signed } = await client.storage
        .from('job-documents')
        .createSignedUrl(raw, SIGNED_TTL)
      const signedUrl = signed?.signedUrl || signed?.signedURL || raw
      return appendVersion(signedUrl)
    } catch (_) {
      return appendVersion(raw)
    }
  }

  // 3) Assemble one cockpit row per report-draft-ready job.
  const drafts = await Promise.all(detailRows.map(async (d: any) => {
    const job = jobsById[d.job_id] || {}
    const company = d.makesafe_companies || {}
    const jobInvoices = invoicesByJob[d.job_id] || []
    // The live (non-void) invoice — same posture as makesafe_send_pack preflight.
    const liveInvoice = jobInvoices.find((inv: any) =>
      !['VOIDED', 'DELETED'].includes(String(inv?.status || '').toUpperCase())) || jobInvoices[0] || null
    // N-1 (money-safety) — surface AMBIGUITY (>1 non-void invoice maps to the job)
    // rather than display a wrong amount. The cockpit shows the ambiguity card;
    // makesafe_send_pack fails closed (412) on the same condition.
    const invoiceAmbiguous = isInvoiceAmbiguous(jobInvoices)

    const lines = normaliseLineItems(liveInvoice?.line_items)
    const linesUnavailable = !!liveInvoice && lines.length === 0
    const totals = computeInvoiceTotals({
      subTotal: liveInvoice?.sub_total ?? null,
      total: liveInvoice?.total ?? null,
      lines,
    })

    const docs = docsByJob[d.job_id] || []
    // B1 (Wave 0): read the pack row early so last_render_hash is available for
    // versioned URL minting below. The pack row is also used downstream for surface
    // derivation and pack_status — the value is the same object reference.
    const pack = packByJob[d.job_id] || null
    if (pack?.status === 'sending' && pack?.failed_step === 'draft_pack') return null
    const {
      reportDoc,
      invoiceDoc,
      swmsDoc,
      workOrderDoc,
      serviceReportDoc,
    } = selectMakesafePackDocs(docs, pack)
    const renderHash = pack?.last_render_hash || null
    const [reportPdfUrl, invoicePdfUrl, swmsPdfUrl, workOrderPdfUrl, serviceReportPdfUrl] = await Promise.all([
      // B1: the report URL carries the render hash so a re-render always yields a new URL.
      signDocUrl(reportDoc?.pdf_url || reportDoc?.storage_url, renderHash),
      signDocUrl(
        invoiceDoc?.pdf_url || invoiceDoc?.storage_url,
        invoiceDoc?.version ? `invoice-v${invoiceDoc.version}` : renderHash,
      ),
      signDocUrl(swmsDoc?.pdf_url || swmsDoc?.storage_url),
      signDocUrl(workOrderDoc?.pdf_url || workOrderDoc?.storage_url),
      signDocUrl(serviceReportDoc?.pdf_url || serviceReportDoc?.storage_url),
    ])

    // T3 — SHARED surfacing predicate. The feed must only return genuinely
    // drafted-not-sent jobs. The substatus filter alone (admin_to_send_report)
    // would still include a job whose pack was already sent (e.g. the close
    // failed and the substatus never advanced). Exclude anything sentClosed and
    // require a real readyForReview draft (report artifact + DRAFT invoice).
    // docFlags is built from the TYPED doc picks (not filename matching) so the
    // report-doc presence signal agrees with what the carousel actually shows.
    const feedDocFlags = {
      has_invoice_doc: !!invoiceDoc,
      has_report_doc: !!reportDoc,
      has_swms_doc: !!swmsDoc,
    }
    const markerPresent = packSentMap[d.job_id] === true
    const surf = _deriveMakesafeSurfacing(d, d, true /* report received via substatus */, liveInvoice, feedDocFlags, markerPresent, pack)

    // RESUME-AWARE action mapping (TASK A). Reuse the deployed surfacing predicates
    // (NEVER relax sentClosed) and the marker map (#193). deriveResumeAction is the
    // SINGLE source of truth: it returns the one safe operation for this state, or
    // null to EXCLUDE a genuinely terminal / unrecoverable job (as before). This
    // widens the feed past the old `if (!surf.readyForReview) return null`, which
    // dropped authorised_not_sent packs (the Ferndale bug).
    const resumeAction = deriveResumeAction({
      readyForReview: surf.readyForReview,
      invoiceAuthorisedLive: surf.invoiceAuthorisedLive,
      packStatus: pack?.status,
      failedStep: pack?.failed_step,
      markerPresent,
    })
    if (resumeAction === null) return null

    const photos = (mediaByJob[d.job_id] || []).map((m: any) => ({
      url: m.storage_url || null,
      thumbnail_url: m.thumbnail_url || m.storage_url || null,
      label: m.label || null,
      taken_at: m.taken_at || null,
      created_at: m.created_at || null,
      received_at: m.taken_at || m.created_at || null,
    })).filter((p: any) => p.url)
    const reportPhotoLimit = 8
    // The photo follow-up must default to the same photo set the report PDF uses,
    // not every raw/source photo. Persisted selected_photo_urls can be added later;
    // until then the report renderer's deterministic cap is mirrored here.
    const reportPhotos = selectMakesafeReportPhotosForReport(photos, reportPhotoLimit)

    // D3 — carousel doc arrays. draft_docs: the artifacts WE produced for this
    // close-out (rendered report PDF, draft invoice PDF, attached SWMS if any).
    // source_docs: the inputs (original trade/service report, work order, photos).
    // Each object keeps the legacy {label,url,kind} contract and adds optional
    // timestamp metadata so the cockpit can prove WHEN each source/draft arrived.
    // SWMS is surfaced ONLY when one is attached (we do NOT generate one). Reuses
    // the same signed-url mechanism as report/invoice.
    type MakesafeCockpitDoc = {
      label: string
      url: string
      kind: 'pdf' | 'image' | 'html'
      created_at?: string | null
      received_at?: string | null
      source_type?: string | null
      raw_report?: any
    }
    const docMeta = (doc: any, receivedAt?: string | null, sourceType?: string | null) => ({
      created_at: doc?.created_at || null,
      received_at: receivedAt || doc?.created_at || null,
      source_type: sourceType || doc?.type || null,
    })
    const draftDocs: MakesafeCockpitDoc[] = []
    const invoiceDocLabel = ['AUTHORISED', 'SUBMITTED', 'PAID'].includes(
      String(liveInvoice?.status || pack?.invoice_status || '').toUpperCase(),
    )
      ? 'Xero Invoice'
      : 'Draft Invoice'
    if (reportPdfUrl) draftDocs.push({ label: 'Make Safe Report', url: reportPdfUrl, kind: 'pdf', ...docMeta(reportDoc, reportDoc?.created_at || null, 'makesafe_report') })
    if (invoicePdfUrl) draftDocs.push({ label: invoiceDocLabel, url: invoicePdfUrl, kind: 'pdf', ...docMeta(invoiceDoc, invoiceDoc?.created_at || null, 'invoice') })
    if (swmsPdfUrl) draftDocs.push({ label: 'SWMS', url: swmsPdfUrl, kind: 'pdf', ...docMeta(swmsDoc, swmsDoc?.created_at || null, 'swms') })

    const rawServiceReport = serviceReportByJob[d.job_id] || null
    // Re-attendance (M-C): ALL reports for this job, oldest→newest. A single-visit
    // job keeps exactly one "Raw Trade Report" source doc (unchanged); a re-attended
    // job surfaces one per visit so the reporting skill sees every visit's report.
    // The renderer already iterates sourceDocs, so multi-report jobs do not break it.
    const allReports = serviceReportsByJob[d.job_id] || (rawServiceReport ? [rawServiceReport] : [])
    const multiVisit = allReports.length > 1

    const sourceDocs: MakesafeCockpitDoc[] = []
    for (const r of allReports) {
      const cyc = Number(r.cycle_number || 1)
      sourceDocs.push({
        label: multiVisit ? `Raw Trade Report — Visit ${cyc}` : 'Raw Trade Report',
        url: '',
        kind: 'html',
        created_at: r.created_at || null,
        received_at: (r === rawServiceReport ? d.report_received_at : null) || r.submitted_at || r.created_at || null,
        source_type: 'trade_report',
        raw_report: {
          id: r.id,
          cycle_number: cyc,
          status: r.status || null,
          checklist_json: r.checklist_json || null,
          notes: r.notes || null,
          signature_name: r.signature_name || null,
          submitted_at: r.submitted_at || null,
          created_at: r.created_at || null,
          updated_at: r.updated_at || null,
          submitted_by: r.submitted_by || null,
        },
      })
    }
    if (serviceReportPdfUrl) sourceDocs.push({
      label: rawServiceReport ? 'Trade Report PDF' : 'Trade Report',
      url: serviceReportPdfUrl,
      kind: 'pdf',
      ...docMeta(serviceReportDoc, d.report_received_at || serviceReportDoc?.created_at || null, 'trade_report'),
    })
    if (workOrderPdfUrl) sourceDocs.push({
      label: 'Work Order',
      url: workOrderPdfUrl,
      kind: 'pdf',
      ...docMeta(workOrderDoc, workOrderDoc?.created_at || job.created_at || null, 'work_order'),
    })
    for (const p of photos) {
      if (p.url) sourceDocs.push({
        label: p.label || 'Site Photo',
        url: p.url,
        kind: 'image',
        created_at: p.created_at || null,
        received_at: p.received_at || p.taken_at || p.created_at || null,
        source_type: 'photo',
      })
    }

    // BLOCKER C — the To is the builder's WORK-ORDERS inbox (report_recipient),
    // NEVER the billing contact (invoice_email = vanessa@ajs.build for AJS). When
    // report_recipient is unset the recipient is null and the cockpit shows the
    // "no work-order recipient configured" warning, except for vetted
    // known-builder backstops such as MLB. Never fall back to invoice_email.
    const recipientEmail = resolveMakesafeReportRecipient({
      companyReportRecipient: company.report_recipient,
      companyInvoiceEmail: company.invoice_email, // accepted for back-compat; never used as To
      detailInvoiceEmail: null, // no per-job recipient column on makesafe_job_details
      companySlug: company.slug || d.requesting_company_slug,
      companyName: company.name || d.requesting_company_name,
      externalRef: d.external_ref,
    })

    const builderName = canonicalMakesafeBuilderDisplayName(d.external_ref, d.requesting_company_name, company.name)
    const siteAddress = job.site_address || null
    const subject = composeDefaultSubject({
      externalRef: d.external_ref,
      siteAddress,
      siteSuburb: job.site_suburb,
    })
    const htmlBody = composeDefaultHtmlBody({
      builderName,
      externalRef: d.external_ref,
      clientName: job.client_name,
      siteAddress,
      invoiceNumber: liveInvoice?.invoice_number || null,
      totalIncGst: totals.total_inc_gst,
    })
    const positiveInvoiceFailures = liveInvoice ? checkPositiveInvoiceTotalGate(liveInvoice) : []
    const zeroPriceLines = lines.filter((line: any) =>
      Number(line?.line_total || 0) <= 0 || Number(line?.unit_price || 0) <= 0
    )
    const moneyReview = positiveInvoiceFailures.length > 0 || zeroPriceLines.length > 0
      ? {
        needs_money_review: true,
        reason: positiveInvoiceFailures[0] ||
          'one or more invoice lines have $0 pricing and need review before send',
        flagged_lines: (zeroPriceLines.length ? zeroPriceLines : lines).map((line: any, index: number) => ({
          line_index: index,
          description: line.description || 'Invoice line',
          amount: Number(line.line_total || 0),
          flag: Number(line.line_total || 0) <= 0
            ? 'zero_line_total'
            : 'zero_unit_price',
        })),
      }
      : null

    return {
      job_id: d.job_id,
      job_number: job.job_number || null,
      builder: builderName,
      requesting_company_name: builderName,
      external_ref: d.external_ref || null,
      // Re-attendance (M-C): the visit marker + report count so the reporting-skill
      // renderer (M-D) can badge a re-attend and knows there are multiple reports.
      // raw_reports is oldest→newest; source_docs already carries each per visit.
      reattend_count: Number(d.reattend_count || 0),
      is_reattend: Number(d.reattend_count || 0) > 0,
      last_reattend_at: d.last_reattend_at || null,
      last_reattend_reason: d.last_reattend_reason || null,
      report_count: allReports.length,
      raw_reports: allReports.map((r: any) => ({
        id: r.id,
        cycle_number: Number(r.cycle_number || 1),
        status: r.status || null,
        submitted_at: r.submitted_at || null,
        created_at: r.created_at || null,
      })),
      client_name: job.client_name || null,
      client_email: job.client_email || null,
      client_phone: job.client_phone || null,
      site_address: siteAddress,
      site_suburb: job.site_suburb || null,
      recipient_email: recipientEmail, // null -> cockpit shows a warning
      // TASK A — the EXPLICIT per-state resume_action the cockpit drives off:
      //   'send'             -> a fresh ready-to-review draft (authorise + send)
      //   'finish_send'      -> authorised, not sent, NO marker (re-email ONCE)
      //   'finish_close_out' -> marker present, only the close remains (NO email)
      //   'resolve_send_state' -> 'sending', NO marker (operator must confirm)
      // deriveResumeAction is the single source of truth; a terminal job is
      // excluded above (resumeAction === null), never surfaced as sendable.
      resume_action: resumeAction,
      // BLOCKER C — the EXACT (and only) cc set for a make-safe report send. The
      // cockpit/send carries this so the To = work-orders inbox + CC = ses@ only
      // (vanessa@ajs.build is never a recipient or cc). send_pack re-derives +
      // enforces this server-side too (checkExactRecipientGate).
      cc: [MAKESAFE_CC],
      // N-1: when true, MORE THAN ONE non-void invoice maps to this job. The
      // cockpit must show the ambiguity (not a single amount) and block sending;
      // makesafe_send_pack returns 412 on the same condition.
      invoice_ambiguous: invoiceAmbiguous,
      invoice: liveInvoice ? {
        invoice_number: liveInvoice.invoice_number || null,
        status: liveInvoice.status || null,
        reference: liveInvoice.reference || null,
        total_ex_gst: totals.total_ex_gst,
        total_inc_gst: totals.total_inc_gst,
        totals_source: totals.source,
        lines,
        lines_unavailable: linesUnavailable,
        lines_note: linesUnavailable
          ? 'line detail not yet synced locally; see the invoice PDF below for the full breakdown'
          : null,
        // N-1: echoed inside the invoice block too so a consumer reading only the
        // invoice object still sees the ambiguity warning.
        ambiguous: invoiceAmbiguous,
      } : null,
      report_pdf_url: reportPdfUrl,
      invoice_pdf_url: invoicePdfUrl,
      photos,
      report_photo_limit: reportPhotoLimit,
      report_photos: reportPhotos,
      report_photo_urls: reportPhotos.map((p: any) => p.url).filter(Boolean),
      // D3 — carousel arrays for the cockpit (existing fields above unchanged for
      // backward compat). draft_docs = artifacts we produced; source_docs = inputs.
      draft_docs: draftDocs,
      source_docs: sourceDocs,
      // Defaults the human sees + can edit. Composed to pass the client-send gate.
      default_subject: subject,
      default_html_body: htmlBody,
      pack_status: pack ? {
        status: pack.status || null,
        invoice_status: pack.invoice_status || null,
        sent_at: pack.sent_at || null,
        // P-1: the hard-crash 'sending' window. in_flight_stale is true when the
        // pack is 'sending' and send_started_at is older than ~2 minutes -> the
        // cockpit renders an "IN-FLIGHT — VERIFY SENT ITEMS" attention card and
        // the operator resubmits makesafe_send_pack with body.sending_resolution.
        send_started_at: pack.send_started_at || null,
        in_flight_stale: isSendingStale(pack.status, pack.send_started_at, Date.now()),
        failed_step: pack.failed_step || null,
        error_detail: pack.error_detail || null,
      } : null,
      // B2 (Wave 0 money-review schema): the money_review block surfaces when the
      // invoice needs human sign-off before sending. W0 builds the schema + the
      // send-block only; the flag EMISSION (deciding when to flag) is Wave 2 (pricing
      // engine). Default is unset (null) — no flag, no block. When Wave 2 populates
      // it, the cockpit shows a CHECK PRICING amber banner and the send button is
      // disabled until money_review_confirmed=true is passed in the send body.
      //
      // Schema:
      //   needs_money_review: boolean
      //   reason: string           — human-readable explanation
      //   flagged_lines: Array<{ description, amount, flag }> — per-line flags
      money_review: moneyReview as (null | {
        needs_money_review: boolean
        reason: string
        flagged_lines: Array<{ line_index: number; description: string; amount: number; flag: string }>
      }),
      needs_money_review: moneyReview?.needs_money_review === true,
    }
  }))

  // T3 — drop the rows the shared predicate rejected (sent-but-stale / not yet a
  // real draft). Only genuinely drafted-not-sent jobs reach the cockpit.
  const filtered = drafts.filter((row: any) => row !== null)
  return { drafts: filtered, count: filtered.length }
}
// Test-only export alias (mirrors the `_`-prefixed convention) so the T3 feed
// gating + D3 doc-array shape can be exercised with a fake client.
export const _makesafeReportDraftsForTest = makesafeReportDrafts

// Fetch the FULL live ACCREC invoice set, paginating list_invoices' source so the
// dup-guard scans every invoice (not a recent window). Mirrors the python
// fetch_all_invoices but reads the xero_invoices projection directly (the same
// table list_invoices serves) with PostgREST .range() chunking under the 1000 cap.
async function _fetchAllAccrecInvoices(client: any): Promise<any[]> {
  const rows: any[] = []
  const page = 500
  let offset = 0
  // Bounded loop — never spin forever even if the table is huge.
  for (let guard = 0; guard < 40; guard++) {
    const { data, error } = await client.from('xero_invoices')
      .select('xero_invoice_id, invoice_number, reference, status, job_id, invoice_type, invoice_date, sub_total, total, total_tax, line_items')
      .eq('invoice_type', 'ACCREC')
      .order('invoice_date', { ascending: false })
      .range(offset, offset + page - 1)
    if (error) throw new Error('dup-guard: xero_invoices scan failed: ' + error.message)
    const batch = data || []
    rows.push(...batch)
    if (batch.length < page) break
    offset += page
  }
  return rows
}

// D2 — deterministic make-safe DRAFT idempotency key. STABLE per (job, reference)
// with NO time component, so two sequential create calls collapse to one invoice
// at the Xero layer (12h idempotency window). Pure + exported for testing.
export function _makesafeDraftIdempotencyKey(jobId: string | null | undefined, reference: any): string {
  return `msafe-draft-${jobId || 'nojob'}-${_makesafeNormRef(reference)}`.slice(0, 120)
}

// MLB/Prime jobs must bill through the canonical Xero contact. Intake/board
// labels may say "ML Builders", but Xero should use "Major Loss Builders" so
// draft invoices do not create/use the wrong duplicate contact.
function canonicalMakesafeInvoiceContactName(reference: any, contact: any): string {
  const raw = String(contact || '').trim()
  const ref = String(reference || '').trim().toUpperCase()
  const norm = raw.toLowerCase().replace(/[^a-z0-9]+/g, '')
  const hasMlbRef = /(^|[^A-Z0-9])MLB([^A-Z0-9]|$)/.test(ref) || /(^|[^A-Z0-9])MLB[-\s]*\d+/.test(ref) || ref.startsWith('MLB')
  if (hasMlbRef || norm === 'mlbuilders' || norm === 'mlbuilder' || norm === 'majorlossbuilder' || norm === 'majorlossbuilders') {
    return 'Major Loss Builders'
  }
  return raw
}
export const _canonicalMakesafeInvoiceContactNameForTest = canonicalMakesafeInvoiceContactName

function canonicalMakesafeBuilderDisplayName(reference: any, requestedName: any, companyName: any): string {
  return canonicalMakesafeInvoiceContactName(reference, requestedName || companyName || '')
}
export const _canonicalMakesafeBuilderDisplayNameForTest = canonicalMakesafeBuilderDisplayName

interface CreateMakesafeDraftInvoiceDeps {
  fetchAllAccrecInvoices?: (client: any) => Promise<any[]>
  updateExistingDraftInvoice?: (client: any, args: {
    existing: any
    jobId: string | null
    reference: string
    contact: string
    lineItems: any[]
    dueDate?: string | null
    operator?: string | null
  }) => Promise<any>
  deleteExistingDraftInvoice?: (client: any, args: {
    existing: any
    jobId: string | null
    operator?: string | null
    reason?: string | null
  }) => Promise<any>
  createInvoiceFn?: (client: any, body: any) => Promise<any>
  // W2-C item-14 portal-truth guard (default: assertMakesafePortalVerifiedForDraftInvoice).
  // Overridable so pricing/dup-guard unit tests with a stub client can opt out.
  assertPortalVerified?: (client: any, jobId: string | null) => Promise<void>
}

function makesafeDraftLinesForXero(lines: any[]): any[] {
  return lines.map((li: any) => ({
    description: li.description || '',
    quantity: li.quantity ?? 1,
    unit_price: li.unit_price ?? li.unitPrice ?? 0,
    account_code: li.account_code || li.accountCode || '210',
  }))
}

function evaluateMakesafeDraftInvoicePricing(lines: any[], opts: { allowZeroPricing?: boolean; noChargeReason?: string | null } = {}): string[] {
  const failures: string[] = []
  if (!Array.isArray(lines) || lines.length === 0) return ['line_items required']
  const allowZeroPricing = opts.allowZeroPricing === true && String(opts.noChargeReason || '').trim().length > 0
  const draftLines = makesafeDraftLinesForXero(lines)
  const totalExGst = draftLines.reduce((sum: number, li: any) => {
    const quantity = Number(li.quantity ?? 1)
    const unit = Number(li.unit_price ?? 0)
    return sum + ((Number.isFinite(quantity) ? quantity : 1) * (Number.isFinite(unit) ? unit : 0))
  }, 0)
  if (!allowZeroPricing && (!Number.isFinite(totalExGst) || totalExGst <= 0)) {
    failures.push('invoice total must be greater than $0 before a make-safe draft invoice can be created or revised')
  }
  draftLines.forEach((li: any, idx: number) => {
    const quantity = Number(li.quantity ?? 1)
    const unit = Number(li.unit_price ?? 0)
    const desc = String(li.description || `line ${idx + 1}`).trim()
    if (!Number.isFinite(quantity) || quantity <= 0) {
      failures.push(`invoice line ${idx + 1} has invalid quantity: ${desc}`.slice(0, 220))
      return
    }
    if (!allowZeroPricing && (!Number.isFinite(unit) || unit <= 0)) {
      failures.push(`invoice line ${idx + 1} has $0/invalid unit price: ${desc}`.slice(0, 220))
    }
  })
  return failures
}
export const _evaluateMakesafeDraftInvoicePricingForTest = evaluateMakesafeDraftInvoicePricing

function existingDraftInvoiceHasUsablePricing(existing: any): boolean {
  const existingLines = normaliseLineItems(existing?.line_items)
  const existingTotals = computeInvoiceTotals({
    subTotal: existing?.sub_total ?? null,
    total: existing?.total ?? null,
    lines: existingLines,
  })
  const existingLineFailures = existingLines.length > 0
    ? evaluateMakesafeDraftInvoicePricing(existingLines)
    : []
  return existingTotals.total_inc_gst > 0 && existingLineFailures.length === 0
}

function isXeroProjectLineUpdateError(err: any): boolean {
  const msg = String(err?.message || err || '')
  return /Project/i.test(msg) && /LineItemID|LineItemIDs|associated/i.test(msg)
}

function makesafeDraftInvoicePayloadLinesForXeroUpdate(lineItems: any[], liveInvoice: any): any[] {
  const existingLines = Array.isArray(liveInvoice?.LineItems) ? liveInvoice.LineItems : []
  return lineItems.map((line: any, index: number) => {
    const existing = existingLines[index] || {}
    const lineItemId = existing.LineItemID || existing.LineItemId || existing.lineItemID || existing.line_item_id
    return lineItemId ? { ...line, LineItemID: lineItemId } : line
  })
}
export const _makesafeDraftInvoicePayloadLinesForXeroUpdateForTest = makesafeDraftInvoicePayloadLinesForXeroUpdate

function normaliseXeroNameForCompare(value: any): string {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '')
}

async function resolveXeroContactByExactName(accessToken: string, tenantId: string, contactName: string): Promise<any> {
  const clean = String(contactName || '').trim()
  if (!clean) return null
  try {
    const result = await xeroGet('/Contacts', accessToken, tenantId, {
      where: `Name=="${clean.replace(/"/g, '')}"`,
    })
    return result?.Contacts?.[0] || null
  } catch (e) {
    console.log('[makesafe_draft_invoice] Xero contact name lookup failed:', (e as Error).message)
    return null
  }
}

async function updateMakesafeExistingDraftInvoice(client: any, args: {
  existing: any
  jobId: string | null
  reference: string
  contact: string
  lineItems: any[]
  dueDate?: string | null
  operator?: string | null
}): Promise<any> {
  const xeroInvoiceId = args.existing?.xero_invoice_id || args.existing?.id || args.existing?.InvoiceID
  if (!xeroInvoiceId) throw new ApiError('existing draft invoice missing xero_invoice_id; cannot revise safely', 409)

  const { accessToken, tenantId } = await getToken(client)
  const live = await xeroGet(`/Invoices/${xeroInvoiceId}`, accessToken, tenantId)
  const liveInvoice = live?.Invoices?.[0] || null
  const liveStatus = String(liveInvoice?.Status || args.existing?.status || '').toUpperCase()
  if (liveStatus !== 'DRAFT') {
    throw new ApiError(
      `existing invoice ${args.existing?.invoice_number || xeroInvoiceId} is ${liveStatus || 'not DRAFT'}; Revise Pack cannot rewrite a non-DRAFT invoice`,
      409,
    )
  }

  const pricingFailures = evaluateMakesafeDraftInvoicePricing(args.lineItems)
  if (pricingFailures.length > 0) {
    throw new ApiError('existing draft invoice update refused: ' + pricingFailures.join('; '), 400)
  }

  const lineItems = makesafeDraftLinesForXero(args.lineItems)
  const expectedExGst = lineItems.reduce((sum: number, li: any) => {
    return sum + Number(li.quantity ?? 1) * Number(li.unit_price ?? 0)
  }, 0)
  if (expectedExGst <= 0) {
    throw new ApiError('existing draft invoice update refused: revised line items sum to $0 or less', 400)
  }

  const contactName = canonicalMakesafeInvoiceContactName(args.reference, args.contact)
  const matchedContact = await resolveXeroContactByExactName(accessToken, tenantId, contactName)
  const draftPayloadLines = lineItems.map((li: any) => ({
    Description: li.description || '',
    Quantity: li.quantity ?? 1,
    UnitAmount: li.unit_price ?? 0,
    AccountCode: li.account_code || '210',
    TaxType: 'OUTPUT',
  }))
  const payload: any = {
    InvoiceID: xeroInvoiceId,
    Type: 'ACCREC',
    Contact: matchedContact?.ContactID
      ? { ContactID: matchedContact.ContactID }
      : { Name: contactName },
    LineAmountTypes: 'Exclusive',
    LineItems: makesafeDraftInvoicePayloadLinesForXeroUpdate(draftPayloadLines, liveInvoice),
    Reference: args.reference || liveInvoice?.Reference || '',
    Status: 'DRAFT',
  }
  if (args.dueDate) payload.DueDate = args.dueDate

  const updateResult = await xeroPost(`/Invoices/${xeroInvoiceId}`, accessToken, tenantId, { Invoices: [payload] }, 'POST')
  const updated = updateResult?.Invoices?.[0]
  if (!updated) throw new ApiError('Xero did not return the revised DRAFT invoice', 502)
  const updatedStatus = String(updated.Status || '').toUpperCase()
  if (updatedStatus !== 'DRAFT') {
    throw new ApiError(`Xero returned invoice status ${updatedStatus || 'unknown'} after draft revision; expected DRAFT`, 502)
  }

  const actualContact = updated.Contact?.Name || contactName
  if (normaliseXeroNameForCompare(actualContact) !== normaliseXeroNameForCompare(contactName)) {
    throw new ApiError(`Xero returned contact '${actualContact}' after draft revision; expected '${contactName}'`, 502)
  }

  const subTotal = Number(updated.SubTotal ?? expectedExGst)
  const total = Number(updated.Total ?? expectedExGst * 1.1)
  if (!Number.isFinite(subTotal) || subTotal <= 0 || !Number.isFinite(total) || total <= 0) {
    throw new ApiError('Xero returned a zero/invalid total after draft invoice revision', 502)
  }

  const cachePatch: any = {
    xero_contact_id: updated.Contact?.ContactID || matchedContact?.ContactID || args.existing?.xero_contact_id || null,
    contact_name: contactName,
    invoice_number: updated.InvoiceNumber || args.existing?.invoice_number || null,
    invoice_type: updated.Type || 'ACCREC',
    status: updated.Status || 'DRAFT',
    reference: updated.Reference || args.reference || null,
    sub_total: subTotal,
    total_tax: Number(updated.TotalTax ?? total - subTotal),
    total,
    amount_due: Number(updated.AmountDue ?? total),
    due_date: updated.DueDateString || updated.DueDate || args.dueDate || null,
    line_items: updated.LineItems || payload.LineItems,
    raw_json: updated,
    job_id: args.jobId || args.existing?.job_id || null,
    synced_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  }
  const { data: cacheRows, error: cacheErr } = await client.from('xero_invoices')
    .update(cachePatch)
    .eq('xero_invoice_id', xeroInvoiceId)
    .select('xero_invoice_id')
  if (cacheErr) {
    throw new ApiError(`local invoice cache update failed after Xero draft revision: ${cacheErr.message}`, 500)
  }
  if (!cacheRows || cacheRows.length === 0) {
    throw new ApiError('local invoice cache update affected 0 rows after Xero draft revision', 500)
  }
  if (args.jobId) {
    try {
      await client.from('job_events').insert({
        job_id: args.jobId,
        event_type: 'invoice_updated',
        detail_json: {
          source: 'makesafe_revise_pack',
          xero_invoice_id: xeroInvoiceId,
          invoice_number: updated.InvoiceNumber || args.existing?.invoice_number || null,
          total,
          contact_name: contactName,
          line_count: payload.LineItems.length,
        },
      })
    } catch (e) {
      console.log('[makesafe_draft_invoice] invoice_updated event insert failed:', (e as Error).message)
    }
  }

  return {
    success: true,
    skipped: false,
    updated_existing: true,
    xero_invoice_id: xeroInvoiceId,
    invoice_number: updated.InvoiceNumber || args.existing?.invoice_number || null,
    status: updated.Status || 'DRAFT',
    total,
    reference: updated.Reference || args.reference,
  }
}

async function deleteMakesafeExistingDraftInvoice(client: any, args: {
  existing: any
  jobId: string | null
  operator?: string | null
  reason?: string | null
}): Promise<any> {
  const xeroInvoiceId = args.existing?.xero_invoice_id || args.existing?.id || args.existing?.InvoiceID
  if (!xeroInvoiceId) throw new ApiError('existing draft invoice missing xero_invoice_id; cannot replace safely', 409)
  const existingStatus = String(args.existing?.status || '').toUpperCase()
  if (existingStatus && existingStatus !== 'DRAFT') {
    throw new ApiError(
      `existing invoice ${args.existing?.invoice_number || xeroInvoiceId} is ${existingStatus}; cannot delete/replace a non-DRAFT invoice`,
      409,
    )
  }

  const { accessToken, tenantId } = await getToken(client)
  const deleted = await xeroPost(
    `/Invoices/${xeroInvoiceId}`,
    accessToken,
    tenantId,
    { Invoices: [{ InvoiceID: xeroInvoiceId, Status: 'DELETED' }] },
    'POST',
  )
  const deletedInvoice = deleted?.Invoices?.[0] || null

  const { error: cacheErr } = await client.from('xero_invoices')
    .update({
      status: 'DELETED',
      raw_json: deletedInvoice || args.existing?.raw_json || null,
      updated_at: new Date().toISOString(),
      synced_at: new Date().toISOString(),
    })
    .eq('xero_invoice_id', xeroInvoiceId)
  if (cacheErr) {
    throw new ApiError(`local invoice cache update failed after Xero draft delete: ${cacheErr.message}`, 500)
  }

  if (args.jobId) {
    try {
      await client.from('job_events').insert({
        job_id: args.jobId,
        event_type: 'invoice_deleted',
        detail_json: {
          source: 'makesafe_revise_pack',
          xero_invoice_id: xeroInvoiceId,
          invoice_number: args.existing?.invoice_number || deletedInvoice?.InvoiceNumber || null,
          reason: args.reason || 'replace_project_linked_draft',
          operator: args.operator || null,
        },
      })
    } catch (e) {
      console.log('[makesafe_draft_invoice] invoice_deleted event insert failed:', (e as Error).message)
    }
  }

  return {
    success: true,
    deleted_existing_draft: true,
    xero_invoice_id: xeroInvoiceId,
    invoice_number: args.existing?.invoice_number || deletedInvoice?.InvoiceNumber || null,
    status: 'DELETED',
  }
}

// (3a) create_makesafe_draft_invoice — DRAFT only, never authorise/send. Runs the
// full-ACCREC-scan 3-tier dup guard FIRST. If a DRAFT invoice already maps to
// the job, revise that DRAFT in place from the latest Claude JSON; if a non-DRAFT
// invoice maps to the job, skip or fail per caller policy. Routine-safe
// (drafts only) — NO human-only gate.
async function createMakesafeDraftInvoice(client: any, body: any, deps: CreateMakesafeDraftInvoiceDeps = {}) {
  const jobId = body.job_id || body.jobId || null
  const reference = body.reference
  const contact = canonicalMakesafeInvoiceContactName(reference, body.contact_name || body.contactName)
  const lines = body.line_items || body.lineItems || body.lines
  if (!reference) throw new ApiError('reference required', 400)
  if (!contact) throw new ApiError('contact_name required', 400)
  if (!Array.isArray(lines) || lines.length === 0) throw new ApiError('line_items required', 400)
  // W2-C (item 14): PORTAL-TRUTH GUARD FIRST, before any Xero read. A report-type
  // card may not have a DRAFT invoice cut until a portal-locked verification is
  // recorded for its current cycle — the direct kill for the "graf" class (DRAFT
  // invoices minted before the builder portal report was ever submitted). No-op
  // for normal make-safes and for job-less draft calls.
  await (deps.assertPortalVerified || assertMakesafePortalVerifiedForDraftInvoice)(client, jobId)
  // DUPLICATE-INVOICE GUARD (mandatory, cannot be skipped). external_ref defaults
  // to the make-safe reference. A VOIDED/DELETED invoice never blocks. We run
  // this before the pricing refusal so a renderer-only repair can preserve an
  // already-priced DRAFT invoice when Claude emits zero-priced placeholder lines.
  const externalRef = body.external_ref || reference
  const _fetchInvoices = deps.fetchAllAccrecInvoices || _fetchAllAccrecInvoices
  const _updateExistingDraft = deps.updateExistingDraftInvoice || updateMakesafeExistingDraftInvoice
  const _deleteExistingDraft = deps.deleteExistingDraftInvoice || deleteMakesafeExistingDraftInvoice
  const _createInvoice = deps.createInvoiceFn || createInvoice
  const allInvoices = await _fetchInvoices(client)
  const existing = resolveExistingInvoice(allInvoices, jobId, externalRef)

  // All MakeSafe draft invoices must carry real pricing before Xero is touched.
  // Claude may draft the commercial intent, but the backend is the money-safety
  // boundary: a normal make-safe pack cannot create/revise a $0 invoice unless a
  // future explicit no-charge operator path supplies both allow_zero_pricing=true
  // and a no_charge_reason.
  const pricingFailures = evaluateMakesafeDraftInvoicePricing(lines, {
    allowZeroPricing: body.allow_zero_pricing === true || body.allowZeroPricing === true,
    noChargeReason: body.no_charge_reason || body.noChargeReason || null,
  })
  if (pricingFailures.length > 0) {
    const preserveExistingDraft = body.preserve_existing_draft_on_invalid_pricing === true ||
      body.preserveExistingDraftOnInvalidPricing === true
    const existingStatus = String(existing?.status || '').toUpperCase()
    if (preserveExistingDraft && existing && existingStatus === 'DRAFT') {
      const existingLines = normaliseLineItems((existing as any).line_items)
      const existingTotals = computeInvoiceTotals({
        subTotal: (existing as any).sub_total ?? null,
        total: (existing as any).total ?? null,
        lines: existingLines,
      })
      const existingLineFailures = existingLines.length > 0
        ? evaluateMakesafeDraftInvoicePricing(existingLines)
        : []
      if (existingTotals.total_inc_gst > 0 && existingLineFailures.length === 0) {
        return {
          skipped: true,
          pricing_preserved_from_existing: true,
          pricing_failures: pricingFailures,
          reference,
          existing_invoice: existing,
          scanned: allInvoices.length,
          note: `Claude returned invalid draft pricing, so renderer repair preserved existing DRAFT invoice ${existing.invoice_number || existing.xero_invoice_id}`,
        }
      }
    }
    throw new ApiError('draft invoice pricing review required: ' + pricingFailures.join('; '), 400)
  }

  if (existing) {
    const existingStatus = String(existing.status || '').toUpperCase()
    if (existingStatus === 'DRAFT' && body.update_existing_draft !== false) {
      try {
        return await _updateExistingDraft(client, {
          existing,
          jobId,
          reference,
          contact,
          lineItems: lines,
          dueDate: body.due_date || body.dueDate || null,
          operator: body.operator || null,
        })
      } catch (e) {
        const replaceProjectLinkedDraft = body.replace_project_linked_draft_on_project_line_error === true ||
          body.replaceProjectLinkedDraftOnProjectLineError === true
        if (replaceProjectLinkedDraft && isXeroProjectLineUpdateError(e)) {
          const deleted = await _deleteExistingDraft(client, {
            existing,
            jobId,
            operator: body.operator || null,
            reason: 'xero_project_line_rewrite_replacement',
          })
          const created = await _createInvoice(client, {
            job_id: jobId,
            reference,
            contact_name: contact,
            due_date: body.due_date || body.dueDate || null,
            line_items: lines,
            operator: body.operator || null,
          })
          return {
            ...created,
            replaced_project_linked_draft: true,
            deleted_existing_draft: deleted,
            update_error: String((e as Error)?.message || e).slice(0, 500),
            reference,
            scanned: allInvoices.length,
            note: `Xero refused draft invoice rewrite because existing lines are linked to a Project, so Draft Pack deleted DRAFT invoice ${existing.invoice_number || existing.xero_invoice_id} and created a clean replacement draft`,
          }
        }
        const preserveExistingDraft = body.preserve_existing_draft_on_project_line_error === true ||
          body.preserveExistingDraftOnProjectLineError === true
        if (preserveExistingDraft && isXeroProjectLineUpdateError(e) && existingDraftInvoiceHasUsablePricing(existing)) {
          return {
            skipped: true,
            project_line_pricing_preserved: true,
            reference,
            existing_invoice: existing,
            scanned: allInvoices.length,
            update_error: String((e as Error)?.message || e).slice(0, 500),
            note: `Xero refused draft invoice rewrite because existing lines are linked to a Project, so Draft Pack preserved existing DRAFT invoice ${existing.invoice_number || existing.xero_invoice_id}`,
          }
        }
        throw e
      }
    }
    if (body.fail_on_existing_non_draft === true) {
      throw new ApiError(
        `existing invoice ${existing.invoice_number || existing.xero_invoice_id || ''} is ${existingStatus || 'not DRAFT'}; Revise Pack cannot rewrite a non-DRAFT invoice`,
        409,
      )
    }
    return {
      skipped: true,
      reference,
      existing_invoice: existing,
      scanned: allInvoices.length,
      note: `live invoice ${existing.invoice_number} (${existing.status}) already maps to this job via ${existing.match_method}; no new invoice created`,
    }
  }

  // Safe to create the single DRAFT. Hardcoded guardrails: DRAFT + no send.
  // account_code default 210 (per the make-safe draft spec), not createInvoice's
  // default of 200 — stamp it onto every line that did not specify one.
  const draftLines = makesafeDraftLinesForXero(lines)
  // D2 — STABLE Xero idempotency key per (job, reference), NO time component.
  // The old key baked the current minute, so a retry a minute later created a
  // second DRAFT. A stable key makes Xero collapse identical create calls to one
  // invoice (12h window), so this path is idempotent even when the non-atomic
  // pre-read dup-guard above races. Kept short (Xero caps the header) and
  // namespaced to the make-safe draft path.
  const stableIdempotencyKey = _makesafeDraftIdempotencyKey(jobId, reference)
  const created = await _createInvoice(client, {
    job_id: jobId || undefined,
    contact_name: contact,
    line_items: draftLines,
    due_date: body.due_date || body.dueDate,
    reference,
    xero_status: 'DRAFT', // guardrail
    send_email: false,    // guardrail
    // D2 — deterministic per (job, reference). INTERNAL-ONLY property name so the
    // public create_invoice route can never inject it (adversarial review #4).
    makesafe_idempotency_key: stableIdempotencyKey,
    operator: body.operator || 'makesafe reporting autopilot (draft-only)',
  })
  return {
    success: true,
    skipped: false,
    xero_invoice_id: created.xero_invoice_id,
    invoice_number: created.invoice_number,
    total: created.total,
    reference,
  }
}
// Test-only export alias for the DRAFT-invoice dup-guard skip path.
export const _createMakesafeDraftInvoiceForTest = createMakesafeDraftInvoice

// (3b) makesafe_render_report — render the report PDF (server jsPDF) and attach it
// via attachMakesafeDocument as type 'makesafe_report'. Routine-safe (no send).
async function makesafeRenderReport(client: any, body: any) {
  const jobId = body.job_id || body.jobId
  if (!jobId) throw new ApiError('job_id required', 400)

  // ── REPORT-TYPE GUARD ──
  // A report-type job (report_type IS NOT NULL in makesafe_job_details) is a
  // builder-portal report: the report lives on the builder side, not in our PDF.
  // Producing and attaching a SecureWorks makesafe_report PDF is a mistake —
  // refuse here rather than silently creating the wrong document.
  const { data: renderDetail } = await client.from('makesafe_job_details')
    .select('report_type').eq('job_id', jobId).maybeSingle()
  if (renderDetail?.report_type) {
    return {
      success: false,
      skipped: true,
      reason: 'report-type job: no SecureWorks report is generated; report lives on the builder portal',
      document_id: null,
      file_name: null,
    }
  }

  const job = body.job || body.report_job
  if (!job || typeof job !== 'object') throw new ApiError('job (render payload) required', 400)

  const rendered = await renderMakesafeReportPdf(job)
  // base64 the bytes for attachMakesafeDocument's pdf_base64 path.
  let bin = ''
  for (let i = 0; i < rendered.bytes.length; i++) bin += String.fromCharCode(rendered.bytes[i])
  const pdfBase64 = btoa(bin)

  const attached = await attachMakesafeDocument(client, {
    job_id: jobId,
    type: 'makesafe_report',
    file_name: rendered.fileName,
    pdf_base64: pdfBase64,
    uploaded_by: body.operator || 'makesafe reporting autopilot',
  })

  // Record the render hash onto the pack row (upsert a 'drafted' row if absent).
  try {
    await client.from('makesafe_report_packs').upsert({
      org_id: DEFAULT_ORG_ID,
      job_id: jobId,
      pack_kind: body.pack_kind || 'main',
      report_doc_id: attached.document_id || null,
      last_render_hash: rendered.renderHash,
      updated_at: new Date().toISOString(),
    }, { onConflict: 'job_id,pack_kind' })
  } catch (e) {
    console.log('[makesafe_render_report] pack upsert non-blocking:', (e as Error).message)
  }

  return {
    success: true,
    document_id: attached.document_id,
    file_name: rendered.fileName,
    render_hash: rendered.renderHash,
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// Wave 3 -- SecureWorks own-letterhead Roof Report (trade-filled -> our PDF).
//
// Flow the trade app binds to:
//   1. roof_report_template  (READ)   -- schema + job header + any existing draft
//   2. save_roof_report      (WRITE)  -- draft-safe, idempotent upsert of the fill
//   3. submit_roof_report    (WRITE)  -- final fill + render OUR PDF + advance the
//                                        reporting checklist (substatus)
//   4. render_roof_report    (WRITE)  -- routine-safe re-render/preview (ops)
//
// Persistence: makesafe_roof_report_drafts (one row per job, pack_kind='roof').
// The rendered PDF attaches as job_documents type 'roof_report'. Every write
// records a job_events audit row. RLS-safe: all writes go through this edge
// function's service client.
// ══════════════════════════════════════════════════════════════════════════════

const UUID_RE =
  /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/
function roofUuidOrNull(v: unknown): string | null {
  return typeof v === 'string' && UUID_RE.test(v) ? v : null
}

// Read the job identity the renderer needs (ref/address/contact) from the live
// job + make-safe detail rows. The report ref is the builder external ref joined
// with our SWMS job number; the address is site_address + suburb.
// The make-safe cycle a roof-report write is scoped to. Defaults to 1 when the
// detail row carries no cycle_number.
async function loadMakesafeCycleNumber(client: any, jobId: string): Promise<number> {
  const { data } = await client.from('makesafe_job_details')
    .select('cycle_number').eq('job_id', jobId).maybeSingle()
  return Number(data?.cycle_number ?? 1)
}

async function loadRoofReportJobMeta(client: any, jobId: string) {
  const { data: job } = await client.from('jobs')
    .select('id, job_number, client_name, site_address, site_suburb, metadata')
    .eq('id', jobId).maybeSingle()
  if (!job) throw new ApiError('job not found', 404)
  const { data: detail } = await client.from('makesafe_job_details')
    .select('external_ref').eq('job_id', jobId).maybeSingle()
  const metaExternalRef = parseJsonObject(job.metadata)?.external_ref || null
  const externalRef = detail?.external_ref || metaExternalRef || null
  const ref = [externalRef, job.job_number].filter(Boolean).join(' / ') ||
    job.job_number || jobId
  const address = [job.site_address, job.site_suburb].filter(Boolean).join(', ') ||
    job.site_address || ''
  return {
    ref,
    address,
    contact: job.client_name || '',
    client: job.client_name || '',
    job_number: job.job_number || '',
  }
}

// Resolve the photos to render: explicit body.photos wins (may carry base64 for
// an immediate render), then the persisted draft photo meta (URL + label), then a
// fall back to the job's completion/scope photos in job_media (labels included).
// The renderer fetches any URL bytes itself at render time.
async function resolveRoofReportPhotos(
  client: any,
  jobId: string,
  bodyPhotos: unknown,
  draftPhotos: unknown,
): Promise<Array<{ url?: string; bytesBase64?: string; contentType?: string; label?: string }>> {
  if (Array.isArray(bodyPhotos) && bodyPhotos.length) {
    return (bodyPhotos as any[]).map((p) => ({
      url: typeof p?.url === 'string' ? p.url : undefined,
      bytesBase64: typeof p?.bytesBase64 === 'string' ? p.bytesBase64 : undefined,
      contentType: typeof p?.contentType === 'string' ? p.contentType : undefined,
      label: typeof p?.label === 'string' ? p.label : undefined,
    })).filter((p) => p.url || p.bytesBase64)
  }
  if (Array.isArray(draftPhotos) && draftPhotos.length) {
    return (draftPhotos as any[]).map((p) => ({
      url: typeof p?.url === 'string' ? p.url : undefined,
      contentType: typeof p?.contentType === 'string' ? p.contentType : undefined,
      label: typeof p?.label === 'string' ? p.label : undefined,
    })).filter((p) => p.url)
  }
  const { data: media } = await client.from('job_media')
    .select('storage_url, label, type, phase').eq('job_id', jobId).eq('type', 'photo').limit(20)
  return ((media as any[]) || [])
    .filter((m) => m?.storage_url)
    .map((m) => ({ url: m.storage_url as string, label: (m.label as string) || undefined }))
}

// Render OUR letterhead roof-report PDF and attach it as a 'roof_report' document.
// Shared by submit_roof_report and render_roof_report. attachMakesafeDocument
// writes the makesafe_document_attached audit row.
async function renderAndAttachRoofReport(
  client: any,
  jobId: string,
  renderJob: Record<string, unknown>,
  operator: string,
) {
  const rendered = await renderRoofReportPdf(renderJob as any)
  let bin = ''
  for (let i = 0; i < rendered.bytes.length; i++) bin += String.fromCharCode(rendered.bytes[i])
  const pdfBase64 = btoa(bin)
  const attached = await attachMakesafeDocument(client, {
    job_id: jobId,
    type: 'roof_report',
    file_name: rendered.fileName,
    pdf_base64: pdfBase64,
    uploaded_by: operator,
  })
  return {
    document_id: attached.document_id,
    file_name: rendered.fileName,
    render_hash: rendered.renderHash,
  }
}

// (Wave 3a) roof_report_template -- READ. Returns the field schema, the job
// header the form shows, and any existing draft for resume.
async function getRoofReportTemplateForJob(client: any, jobId: string | null) {
  if (!jobId) throw new ApiError('job_id required', 400)
  await assertMakesafeJob(client, jobId)
  const meta = await loadRoofReportJobMeta(client, jobId)
  const { data: existing } = await client.from('makesafe_roof_report_drafts')
    .select('fields_json, storey, status, report_doc_id, submitted_at, template_version, updated_at')
    .eq('job_id', jobId).eq('pack_kind', ROOF_REPORT_PACK_KIND).maybeSingle()
  return { template: getRoofReportTemplate(), job: meta, draft: existing || null }
}

// (Wave 3b) save_roof_report -- WRITE. Draft-safe, idempotent upsert of the fill.
// Never renders, never advances the board. A save on an already-submitted fill is
// a no-op (the submitted report is terminal).
async function saveRoofReport(client: any, body: any) {
  const jobId = body.job_id || body.jobId
  if (!jobId) throw new ApiError('job_id required', 400)
  await assertMakesafeJob(client, jobId)

  const nowIso = new Date().toISOString()
  const uId = roofUuidOrNull(body.userId || body.user_id)

  const { data: existing } = await client.from('makesafe_roof_report_drafts')
    .select('id, status, fields_json, submitted_cycle').eq('job_id', jobId).eq('pack_kind', ROOF_REPORT_PACK_KIND).maybeSingle()
  // Cycle-scope the terminal 'submitted' state. A submitted row is terminal only
  // WITHIN its own make-safe cycle. If the job has since been reopened
  // (cycle_number bumped past submitted_cycle), that submitted state belongs to an
  // older cycle and must not block a fresh roof report for the new one — the row
  // is reset to a fresh draft below.
  let staleSubmitted = false
  if (existing?.status === 'submitted') {
    const currentCycle = await loadMakesafeCycleNumber(client, jobId)
    const submittedCycle = existing.submitted_cycle == null ? null : Number(existing.submitted_cycle)
    staleSubmitted = submittedCycle !== null && currentCycle > submittedCycle
    if (!staleSubmitted) {
      return { ok: true, status: 'submitted', already_submitted: true, saved: false, draft_id: existing.id }
    }
  }

  // Merge this (possibly partial) save over the existing draft so an autosave
  // that omits fields never wipes previously-entered ones — consistent with
  // submit_roof_report's draft+request merge. A stale prior-cycle fill is NOT a
  // merge base: the new cycle starts from a clean slate.
  const existingFields = (existing?.fields_json && typeof existing.fields_json === 'object' && !staleSubmitted)
    ? existing.fields_json : {}
  const existingText = sanitiseRoofReportFields(existingFields as any)
  const existingPhotos = Array.isArray((existingFields as any).photos)
    ? (existingFields as any).photos : []

  const rawFields = (body.fields && typeof body.fields === 'object') ? body.fields : {}
  const reqText = sanitiseRoofReportFields(rawFields)
  const textFields = { ...existingText, ...reqText }
  // A save that carries no photos keeps the previously-saved photo meta; an
  // explicit photos array (even empty) replaces it.
  const hasReqPhotos = body.photos !== undefined || (rawFields as any).photos !== undefined
  const photosMeta = hasReqPhotos
    ? sanitiseRoofPhotosMeta(body.photos ?? (rawFields as any).photos)
    : sanitiseRoofPhotosMeta(existingPhotos)
  const storey = normaliseStorey((textFields as any).storeys)
  const fieldsJson = { ...textFields, photos: photosMeta }

  let draft: any
  if (existing) {
    const updatePayload: any = {
      fields_json: fieldsJson,
      storey,
      template_version: ROOF_REPORT_TEMPLATE_VERSION,
      updated_at: nowIso,
    }
    // Reopened cycle: clear the prior cycle's submit state so the row is once
    // again a plain draft the trade can fill and submit for the new cycle. The
    // old cycle's attached roof_report document is left untouched.
    if (staleSubmitted) {
      updatePayload.status = 'draft'
      updatePayload.report_doc_id = null
      updatePayload.last_render_hash = null
      updatePayload.submitted_cycle = null
      updatePayload.submitted_at = null
      updatePayload.submitted_by = null
    }
    const { data, error } = await client.from('makesafe_roof_report_drafts')
      .update(updatePayload)
      .eq('id', existing.id).select().single()
    if (error) throw error
    draft = data
  } else {
    // Upsert on the UNIQUE (job_id, pack_kind) key rather than a bare insert so
    // two concurrent first-time writes (a trailing autosave racing another save)
    // can't collide on the constraint and 500 — the loser updates instead.
    const { data, error } = await client.from('makesafe_roof_report_drafts')
      .upsert({
        org_id: DEFAULT_ORG_ID,
        job_id: jobId,
        pack_kind: ROOF_REPORT_PACK_KIND,
        template_version: ROOF_REPORT_TEMPLATE_VERSION,
        fields_json: fieldsJson,
        storey,
        status: 'draft',
        created_by: uId,
        updated_at: nowIso,
      }, { onConflict: 'job_id,pack_kind' }).select().single()
    if (error) throw error
    draft = data
  }

  // Audit (non-blocking: a draft save must still succeed if the ledger insert fails).
  try {
    await client.from('job_events').insert({
      job_id: jobId,
      user_id: uId,
      event_type: 'roof_report_saved',
      detail_json: {
        draft_id: draft.id,
        status: 'draft',
        storey,
        field_keys: Object.keys(reqText),
        photo_count: photosMeta.length,
        template_version: ROOF_REPORT_TEMPLATE_VERSION,
      },
    })
  } catch (_e) { /* non-blocking */ }

  let price: any = null
  try { price = roofReportPrice(storey) } catch { price = null }
  return { ok: true, status: 'draft', saved: true, draft_id: draft.id, storey, price }
}

// (Wave 3c) submit_roof_report -- WRITE. Validates the merged fill, renders OUR
// letterhead PDF, persists the final fill, and advances the reporting checklist
// (substatus admin_to_send_report + cycle-scoped verification, sourced from our
// rendered report). Idempotent: a re-submit of an already-submitted fill returns
// the existing report without re-rendering or re-advancing.
interface RoofRenderDeps {
  renderAndAttach?: (
    client: any,
    jobId: string,
    renderJob: Record<string, unknown>,
    operator: string,
  ) => Promise<{ document_id: string; file_name: string; render_hash: string }>
}

// Report-type gate — mirrors mark_makesafe_portal_report_done EXACTLY. A roof
// report is a report-type deliverable and advances the same reporting checklist,
// so it must never be accepted on an ordinary make-safe: that would mark the
// reporting checklist satisfied and let the job proceed toward invoicing while
// bypassing the real make-safe report. Two PERSISTED server-read sources qualify:
//   1. makesafe_job_details.report_type (intake approval writes this), or
//   2. jobs.metadata.makesafe_job_family being a report family.
// Body-supplied report_type / is_report_type flags are IGNORED either way.
async function assertRoofReportIsReportTypeJob(client: any, jobId: string) {
  const { data: detail } = await client.from('makesafe_job_details')
    .select('report_type').eq('job_id', jobId).maybeSingle()
  let reportType = String(detail?.report_type || '').trim() || null
  if (!reportType) {
    const { data: jobRow } = await client.from('jobs')
      .select('id, metadata').eq('id', jobId).maybeSingle()
    const persistedFamily = parseJsonObject(jobRow?.metadata)?.makesafe_job_family || null
    reportType = _reportTypeForJobFamily(persistedFamily) || null
  }
  if (!reportType) {
    throw new ApiError('roof report is restricted to report-type jobs: neither makesafe_job_details.report_type nor a report-family jobs.metadata.makesafe_job_family is set for this job. A normal make-safe must submit its real make-safe report.', 409)
  }
}

async function submitRoofReport(client: any, body: any, deps: RoofRenderDeps = {}) {
  const renderAndAttach = deps.renderAndAttach || renderAndAttachRoofReport
  const jobId = body.job_id || body.jobId
  if (!jobId) throw new ApiError('job_id required', 400)
  await assertMakesafeJob(client, jobId)
  await assertRoofReportIsReportTypeJob(client, jobId)

  const { data: existing } = await client.from('makesafe_roof_report_drafts')
    .select('*').eq('job_id', jobId).eq('pack_kind', ROOF_REPORT_PACK_KIND).maybeSingle()

  // A submitted row is terminal only within its own make-safe cycle. When the job
  // has been reopened (cycle_number bumped past submitted_cycle) the stored fill
  // belongs to an OLDER cycle and must NOT seed the new cycle's report — mirrors
  // saveRoofReport's staleSubmitted clean-slate handling.
  let staleSubmitted = false

  if (existing?.status === 'submitted') {
    // A prior submit persisted the fill but its board advance may have failed
    // transiently, leaving the board un-advanced. Re-run the (idempotent)
    // checklist advance so a retry completes the board sync — but ONLY within the
    // same make-safe cycle this report was submitted for. If the job was reopened
    // (cycle_number bumped past submitted_cycle), this terminal draft is a stale
    // prior-cycle report: we do NOT treat it as terminal, and fall through below
    // to render+advance a FRESH report for the new cycle. Never re-renders on the
    // same-cycle retry. Still throws loudly on a genuinely missing detail.
    const { data: detail } = await client.from('makesafe_job_details')
      .select('job_id, substatus, cycle_number, report_received_at')
      .eq('job_id', jobId).maybeSingle()
    if (!detail) {
      throw new ApiError('roof report saved but board sync failed: makesafe detail row missing', 500)
    }
    const currentCycle = Number(detail.cycle_number ?? 1)
    const submittedCycle = existing.submitted_cycle == null ? null : Number(existing.submitted_cycle)
    const reopenedNewerCycle = submittedCycle !== null && currentCycle > submittedCycle
    staleSubmitted = reopenedNewerCycle
    if (!reopenedNewerCycle) {
      const boardSubstatus = normalizeMakesafeSubstatus(detail.substatus)
      const boardAdvanced = !!detail.report_received_at ||
        (!!boardSubstatus && _PORTAL_DONE_ALREADY_SUBSTATUSES.includes(boardSubstatus))
      const sameCycle = submittedCycle !== null && submittedCycle === currentCycle
      let boardSync: any
      if (sameCycle && !boardAdvanced) {
        boardSync = await advanceRoofReportChecklist(
          client,
          jobId,
          new Date().toISOString(),
          body,
        )
      } else {
        boardSync = {
          ok: true,
          skipped: true,
          already_advanced: boardAdvanced,
          substatus: boardSubstatus,
          report_received_at: detail.report_received_at || null,
          reason: !sameCycle ? 'cycle_advanced' : 'board_already_advanced',
          submitted_cycle: submittedCycle,
          current_cycle: currentCycle,
        }
      }
      return {
        ok: true,
        already_submitted: true,
        status: 'submitted',
        draft_id: existing.id,
        report_doc_id: existing.report_doc_id,
        render_hash: existing.last_render_hash,
        board_sync: boardSync,
      }
    }
    // reopenedNewerCycle: fall through to a fresh submit for the new cycle.
  }

  // A stale prior-cycle fill is NOT a merge base: the reopened cycle's report is
  // built only from this submit request, so last cycle's data never leaks into the
  // new-cycle letterhead deliverable. A same-cycle draft still merges draft+request.
  const draftFields = (existing?.fields_json && typeof existing.fields_json === 'object' && !staleSubmitted)
    ? existing.fields_json : {}
  const reqFields = (body.fields && typeof body.fields === 'object') ? body.fields : {}
  const mergedText = sanitiseRoofReportFields({ ...draftFields, ...reqFields })

  const validation = validateRoofReportForSubmit(mergedText as any)
  if (!validation.ok) {
    throw new ApiError('Roof report incomplete: ' + validation.errors.join('; '), 400)
  }
  // storeys is validated above, so this cannot throw.
  const price = roofReportPrice((mergedText as any).storeys)

  const draftPhotos = Array.isArray((draftFields as any).photos) ? (draftFields as any).photos : []
  const photosMeta = sanitiseRoofPhotosMeta(body.photos ?? (reqFields as any).photos ?? draftPhotos)
  const photosForRender = await resolveRoofReportPhotos(
    client,
    jobId,
    body.photos ?? (reqFields as any).photos,
    draftPhotos,
  )
  const fieldsJson = { ...mergedText, photos: photosMeta }

  // Render + attach OUR letterhead PDF.
  const meta = await loadRoofReportJobMeta(client, jobId)
  const renderJob = buildRoofReportJob(fieldsJson, meta, photosForRender)
  const attached = await renderAndAttach(
    client,
    jobId,
    renderJob,
    body.operator || body.operator_email || 'roof report (trade)',
  )

  const nowIso = new Date().toISOString()
  const uId = roofUuidOrNull(body.userId || body.user_id)
  // Stamp the make-safe cycle this fill is submitted for, so a later retry can
  // cycle-scope its board re-advance (see the already_submitted branch above).
  // Persisted BEFORE the board advance so a transient advance failure leaves the
  // draft correctly cycle-tagged and the retry stays within the same cycle.
  const { data: submitCycleDetail } = await client.from('makesafe_job_details')
    .select('cycle_number').eq('job_id', jobId).maybeSingle()
  const submittedCycle = Number(submitCycleDetail?.cycle_number ?? 1)
  const finalRow = {
    org_id: DEFAULT_ORG_ID,
    job_id: jobId,
    pack_kind: ROOF_REPORT_PACK_KIND,
    template_version: ROOF_REPORT_TEMPLATE_VERSION,
    fields_json: fieldsJson,
    storey: price.storey,
    status: 'submitted',
    report_doc_id: roofUuidOrNull(attached.document_id),
    last_render_hash: attached.render_hash,
    submitted_cycle: submittedCycle,
    submitted_by: uId,
    submitted_at: nowIso,
    updated_at: nowIso,
  }
  let draft: any
  if (existing) {
    const { data, error } = await client.from('makesafe_roof_report_drafts')
      .update(finalRow).eq('id', existing.id).select().single()
    if (error) throw error
    draft = data
  } else {
    // Upsert on the UNIQUE (job_id, pack_kind) key rather than a bare insert so a
    // first-time submit racing a trailing autosave can't collide on the constraint
    // and 500 — the loser updates the same row.
    const { data, error } = await client.from('makesafe_roof_report_drafts')
      .upsert(finalRow, { onConflict: 'job_id,pack_kind' }).select().single()
    if (error) throw error
    draft = data
  }

  // Advance the reporting checklist. Mirrors mark_makesafe_portal_report_done:
  // our submitted+rendered roof report IS the verified deliverable for this cycle.
  const boardSync = await advanceRoofReportChecklist(client, jobId, nowIso, body)

  // Audit event (non-blocking after the board sync succeeded).
  let eventSync: any = { ok: true }
  try {
    await client.from('job_events').insert({
      job_id: jobId,
      user_id: uId,
      event_type: 'roof_report_submitted',
      detail_json: {
        draft_id: draft.id,
        report_doc_id: attached.document_id,
        storey: price.storey,
        price_ex_gst: price.ex_gst,
        price_inc_gst: price.inc_gst,
        render_hash: attached.render_hash,
        photo_count: photosForRender.length,
        template_version: ROOF_REPORT_TEMPLATE_VERSION,
      },
    })
  } catch (e) {
    eventSync = { ok: false, error: e instanceof Error ? e.message : String(e) }
  }

  return {
    ok: true,
    status: 'submitted',
    draft_id: draft.id,
    report_doc_id: attached.document_id,
    file_name: attached.file_name,
    render_hash: attached.render_hash,
    price,
    board_sync: boardSync,
    event_sync: eventSync,
  }
}

// Advance the make-safe reporting checklist for a roof-report submit. Sets the
// board to admin_to_send_report + report_received_at and records a cycle-scoped
// verification stamp (our rendered report is the verified deliverable, exactly as
// mark_makesafe_portal_report_done stamps a portal-locked verification). Throws
// loudly if the detail row is missing or the update fails, so a submit never
// silently leaves the board un-advanced.
async function advanceRoofReportChecklist(
  client: any,
  jobId: string,
  nowIso: string,
  body: any,
) {
  const { data: detail } = await client.from('makesafe_job_details')
    .select('job_id, substatus, cycle_number, report_received_at, portal_verified_at, portal_verified_cycle')
    .eq('job_id', jobId).maybeSingle()
  if (!detail) {
    throw new ApiError('roof report saved but board sync failed: makesafe detail row missing', 500)
  }
  const currentCycle = Number(detail.cycle_number ?? 1)
  const verifyActor = body.operator_email || body.user_email || body.operator || 'roof_report_submit'
  const verificationStamp = {
    portal_verified_at: nowIso,
    portal_verified_cycle: currentCycle,
    portal_verified_signal: 'secureworks roof report submitted',
    portal_verified_by: verifyActor,
  }
  const alreadyVerifiedThisCycle = !!detail.portal_verified_at &&
    Number(detail.portal_verified_cycle) === currentCycle
  const currentSubstatus = normalizeMakesafeSubstatus(detail.substatus)

  // Idempotent / already-advanced guard — mirrors mark_makesafe_portal_report_done.
  // If the board is already at or beyond admin_to_send_report, NEVER regress the
  // substatus or re-stamp report_received_at; still record this cycle's
  // verification if it is missing (our rendered report is the deliverable).
  if (currentSubstatus && _PORTAL_DONE_ALREADY_SUBSTATUSES.includes(currentSubstatus)) {
    let verificationRecorded = false
    if (!alreadyVerifiedThisCycle) {
      const { error: verifyErr } = await client.from('makesafe_job_details')
        .update({ ...verificationStamp, updated_at: nowIso })
        .eq('job_id', jobId)
      if (verifyErr) {
        throw new ApiError('roof report saved but board sync failed: ' + (verifyErr.message || verifyErr), 500)
      }
      verificationRecorded = true
    }
    return {
      ok: true,
      already_advanced: true,
      substatus: currentSubstatus,
      report_received_at: detail.report_received_at || null,
      verification_recorded: verificationRecorded,
    }
  }

  const { data: updated, error } = await client.from('makesafe_job_details')
    .update({
      substatus: 'admin_to_send_report',
      report_received_at: nowIso,
      ...verificationStamp,
      updated_at: nowIso,
    })
    .eq('job_id', jobId)
    .select('substatus, report_received_at')
    .maybeSingle()
  if (error) {
    throw new ApiError('roof report saved but board sync failed: ' + (error.message || error), 500)
  }
  // Advancing to a finished substatus closes any still-open crew assignments.
  await closeOpenAssignmentsForJob(client, jobId, 'complete')
  return {
    ok: true,
    already_advanced: false,
    substatus: updated?.substatus || 'admin_to_send_report',
    report_received_at: updated?.report_received_at || nowIso,
    verification_recorded: true,
  }
}

// (Wave 3d) render_roof_report -- WRITE (routine-safe). Renders OUR letterhead PDF
// from the current draft (merged with any body.fields) and attaches it, WITHOUT
// submitting or advancing the board. For ops re-render / preview.
async function renderRoofReportAction(client: any, body: any, deps: RoofRenderDeps = {}) {
  const renderAndAttach = deps.renderAndAttach || renderAndAttachRoofReport
  const jobId = body.job_id || body.jobId
  if (!jobId) throw new ApiError('job_id required', 400)
  await assertMakesafeJob(client, jobId)
  await assertRoofReportIsReportTypeJob(client, jobId)
  const { data: existing } = await client.from('makesafe_roof_report_drafts')
    .select('fields_json').eq('job_id', jobId).eq('pack_kind', ROOF_REPORT_PACK_KIND).maybeSingle()
  const draftFields = (existing?.fields_json && typeof existing.fields_json === 'object')
    ? existing.fields_json : {}
  const reqFields = (body.fields && typeof body.fields === 'object') ? body.fields : {}
  const mergedText = sanitiseRoofReportFields({ ...draftFields, ...reqFields })
  const draftPhotos = Array.isArray((draftFields as any).photos) ? (draftFields as any).photos : []
  const photosForRender = await resolveRoofReportPhotos(
    client,
    jobId,
    body.photos ?? (reqFields as any).photos,
    draftPhotos,
  )
  const meta = await loadRoofReportJobMeta(client, jobId)
  const renderJob = buildRoofReportJob({ ...mergedText, photos: [] }, meta, photosForRender)
  const attached = await renderAndAttach(
    client,
    jobId,
    renderJob,
    body.operator || 'roof report render',
  )
  return {
    success: true,
    document_id: attached.document_id,
    file_name: attached.file_name,
    render_hash: attached.render_hash,
  }
}

